window.PA_INSIGHTS_DATA = {"insights": [{"id": "INS-001", "kind": "insight", "title": "End-to-end card transaction flow", "topic": "End-to-end card transaction flow", "theme": "Payment lifecycle", "text": "Explain authorisation, clearing, settlement and reconciliation across issuer, acquirer, network and merchant.", "domain": "Cards & Merchant Payments", "area": "Cards & Merchant Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch21s6", "title": "Settlement Between Issuer, Acquirer and Scheme", "url": "lessons/ch21s6"}}, {"id": "INS-002", "kind": "insight", "title": "Debit versus credit card transaction behaviour", "topic": "Debit versus credit card transaction behaviour", "theme": "Payment lifecycle", "text": "Compare the account and settlement implications of debit and credit card flows.", "domain": "Cards & Merchant Payments", "area": "Cards & Merchant Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch21s1", "title": "The Four Parties and the Card Transaction", "url": "lessons/ch21s1"}}, {"id": "INS-003", "kind": "insight", "title": "Card authorisation decision", "topic": "Card authorisation decision", "theme": "Payment lifecycle", "text": "Identify the issuer-side checks and response outcomes during authorisation.", "domain": "Cards & Merchant Payments", "area": "Cards & Merchant Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch63s6", "title": "Payment Processors, Fees and How They Are Shared", "url": "lessons/ch63s6"}}, {"id": "INS-004", "kind": "insight", "title": "Card settlement and reconciliation", "topic": "Card settlement and reconciliation", "theme": "Payment lifecycle", "text": "Explain how clearing records, settlement positions and ledger postings are reconciled.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch18s1", "title": "What Settlement Means After Clearing", "url": "lessons/ch18s1"}}, {"id": "INS-005", "kind": "insight", "title": "Chargeback lifecycle and reason for disputes", "topic": "Chargeback lifecycle and reason for disputes", "theme": "Disputes", "text": "Map dispute initiation, representment evidence, scheme timelines and financial impact.", "domain": "Cards & Disputes", "area": "Cards & Disputes", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch78s5", "title": "The chargeback chain: representment, pre-arbitration and arbitration", "url": "lessons/ch78s5"}}, {"id": "INS-006", "kind": "insight", "title": "Payment failed but customer account debited", "topic": "Payment failed but customer account debited", "theme": "Payment exceptions", "text": "Investigate uncertain status, downstream confirmation, reversal and reconciliation before retry.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s5", "title": "Unknown Payment Status, Failed Beneficiary Credit and Clearing System Outage", "url": "lessons/ch41s5"}, "case": {"status": "authored", "business_problem": "Meridian Bank offers instant domestic payments through its mobile app. On a busy morning, a retail customer sends EUR 850 to a supplier and the app shows the payment as failed, yet the customer's account statement shows the EUR 850 debit. The customer calls the contact centre, worried the money is lost, and asks the bank to send the payment again straight away.\n\nThe operations team faces an uncertain status. The debit may mean the payment reached the clearing system and is still processing, or it may mean the ledger posted while the payment status update failed. A blind retry could create a duplicate payment of EUR 850, while doing nothing could leave a genuine payment stuck. The team must establish the true state of the payment, protect the customer from a duplicate debit, and give a clear, honest update before deciding on reversal or reprocessing.", "decision_exercise": {"scenario": "A customer reports a failed payment of EUR 850, but the account shows the debit. The payment status in the platform is unclear and no clearing acknowledgement has been seen yet. What should the operations analyst do first?", "options": [{"id": "A", "text": "Place the payment in an investigation state, verify the ledger posting, the payment engine state and any clearing acknowledgement using the original references, and do not retry until the true status is known."}, {"id": "B", "text": "Reverse the debit at once and tell the customer to submit a new payment."}, {"id": "C", "text": "Send the payment again immediately so the supplier is paid without delay."}, {"id": "D", "text": "Close the case as a display error because the app message and the statement disagree."}], "correct_option": "A", "why": "Option A is correct because an uncertain status must be resolved from authoritative evidence before any money moves again. Option C risks a duplicate EUR 850 payment if the original payment is still processing. Option B is wrong because a reversal is only safe once the team knows the payment did not reach the beneficiary, and a premature reversal can conflict with a payment that later settles. Option D is wrong because a disagreement between screens is a real control signal, not proof that nothing happened."}, "recommended_solution": "Treat the payment as one transaction with one identity across every system. Use the original instruction ID, end-to-end ID and ledger posting reference to trace the payment through the channel, the payment engine, the clearing adapter and the core ledger, and record each finding against the same case record. Keep the customer instruction status separate from the clearing status, so a channel failure message is never read as proof that no money moved.\n\nIf the ledger debit exists but no clearing submission can be found, hold the payment in a controlled investigation state and reconcile the ledger against the payment status store. Replay a missing status event idempotently using the original posting reference, never by reposting the debit. If the clearing system confirms the payment was accepted, let it complete and confirm the outcome to the customer. If the clearing system confirms rejection, or no submission exists and the debit is an orphan posting, reverse the debit once, with a clear reason code and audit trail.\n\nCommunicate in plain language at each stage: what is known, what is still being checked, and when the next update will arrive. Do not promise a time the team cannot meet, and do not ask the customer to retry the payment while the investigation is open.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits a EUR 850 payment in the mobile app and receives a failure message", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction and creates the payment with instruction ID and end-to-end ID", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Sends the debit instruction to the core ledger", "system": "Ledger adapter"}, {"step": 4, "actor": "Core ledger", "action": "Posts the EUR 850 debit and returns a posting reference", "system": "Core banking"}, {"step": 5, "actor": "Payment engine", "action": "Submits the payment to the clearing system and awaits acknowledgement", "system": "Clearing adapter"}, {"step": 6, "actor": "Clearing system", "action": "Returns an acknowledgement or rejection correlated by message reference", "system": "Clearing system"}, {"step": 7, "actor": "Operations analyst", "action": "Investigates the ledger posting, engine state and clearing response under one case record", "system": "Operations workbench"}, {"step": 8, "actor": "Payment engine", "action": "Updates the payment to its true final state, reverses the debit once if the payment did not proceed, and notifies the customer", "system": "Payment engine and notification service"}], "happy_path": "The analyst traces the original references and finds the clearing system accepted the payment after a delayed acknowledgement. The ledger debit and the payment status converge on the same completed payment, the supplier is credited, and the customer receives a confirmation showing the payment reference, the amount and the completion time. No duplicate payment and no reversal are needed.", "negative_paths": [{"path": "Duplicate retry", "trigger": "The customer or an agent resubmits the payment before the first payment is resolved.", "handling": "Block retries while the payment is in investigation state. Use the idempotency key and original instruction ID to return the existing payment reference instead of creating a second debit."}, {"path": "Ledger posted but status event lost", "trigger": "The debit posts but the status update from the ledger to the payment platform fails.", "handling": "Reconcile ledger postings against payment states daily. Replay the missing event idempotently from the outbox using the original posting reference and alert on aged inconsistencies."}, {"path": "Clearing rejects after debit", "trigger": "The clearing participant rejects the payment after the customer account has been debited.", "handling": "Translate the external rejection into a controlled internal reason code, move the payment to a rejected state, reverse the debit once, and notify the channel and the customer."}, {"path": "Cover leg returned, customer leg unclear", "trigger": "In a cross-border case the cover leg is returned while the customer leg status is unknown.", "handling": "Track the cover leg and the customer leg separately using linked references. Investigate both legs before posting any customer adjustment, and never assume one leg defines the other."}], "technical_data": "Use one canonical payment record with stable identifiers: instruction ID, end-to-end ID, transaction ID, UETR where applicable, ledger posting reference and clearing message reference. Persist the idempotency key and payload hash at intake so retries return the original reference. Publish status changes through a durable outbox so a failed event can be replayed without reposting the debit. Make status consumers idempotent and version events so an older event cannot regress a newer state. Validate state transitions explicitly, log every transition with actor and timestamp, and keep the original instruction and all acknowledgements for audit. Reconcile the payment status store against the ledger and clearing acknowledgements on a scheduled cycle, with ageing thresholds that raise an alert before a case goes stale.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation from the channel to the payment engine.", "key_fields": ["Instruction ID, the unique instruction reference", "End-to-end ID, carried through to the beneficiary bank", "Debtor account and creditor account", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer payment sent to the clearing system or beneficiary bank.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency", "Remittance information"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection by the clearing system.", "key_fields": ["Original instruction ID and message reference", "Status code, accepted or rejected", "Reason code where rejected", "Status timestamp"]}, {"message": "pacs.004", "purpose": "Payment return used when a payment that was sent must be returned.", "key_fields": ["Original instruction ID and end-to-end ID", "Return reason code", "Returned amount", "Return identification"]}, {"message": "camt.053", "purpose": "Bank-to-customer statement used as external evidence for the debit and for reconciliation.", "key_fields": ["Account identification", "Entry amount, currency and value date", "Posting reference", "Balance after the entry"]}], "accounting_operational": "Debit the customer account once for EUR 850 and credit the internal settlement or clearing account. If the payment is rejected or never submitted, reverse the debit once with a matching credit to the customer account, using the original posting reference and a documented reason code. Never post a second debit for the same instruction. Place unresolved debits on an operations worklist with an owner and a service level for investigation, and age them so nothing sits unowned. Reconcile the settlement account against clearing reports daily, and treat any unmatched debit as a break to be investigated, not written off. Notify the customer of the outcome and keep the full audit trail of postings, reversals and status changes.", "gherkin": ["Given a ledger posting exists but the status event is missing, When recovery runs, Then the payment state is updated using the original posting reference without reposting the debit.", "Given a clearing rejection correlated to a payment, When the response is received, Then the payment is moved to the appropriate rejected state and any related accounting reservation is handled once.", "Given a payment is in investigation state, When a retry arrives with the same idempotency key, Then the platform returns the original payment reference and does not create a second debit."], "assessment": [{"question": "A customer payment shows as failed in the app but the account is debited. What is the first safe step?", "options": ["Retry the payment immediately.", "Investigate the ledger posting, payment state and clearing acknowledgement using the original references before any retry.", "Tell the customer the debit will disappear on its own.", "Reverse the debit at once."], "answer": 1, "explanation": "The true status must be established from authoritative evidence first, because a blind retry can duplicate the payment and a blind reversal can conflict with a payment that later settles."}, {"question": "Why must the customer instruction status and the clearing status be kept separate?", "options": ["Because customers only see the channel status.", "Because the ledger does not record clearing outcomes.", "Because the two statuses are always identical.", "Because channel acceptance does not prove clearing acceptance, and each stage has its own authoritative source."], "answer": 3, "explanation": "Channel acceptance, engine processing and clearing acceptance are different stages. Conflating them hides the real state and leads to wrong retry or reversal decisions."}, {"question": "How should a missing status event be recovered?", "options": ["By replaying the event idempotently from the outbox using the original posting reference.", "By reposting the debit.", "By deleting the payment record.", "By asking the customer to submit a new payment."], "answer": 0, "explanation": "Idempotent replay updates the status without creating a second financial effect."}, {"question": "In a cross-border payment, the cover leg is returned. What should the bank do about the customer leg?", "options": ["Reverse the customer debit immediately.", "Investigate the customer leg separately before deciding any customer impact.", "Assume the customer leg also failed.", "Ignore the cover return."], "answer": 1, "explanation": "Cover and customer legs have separate states. Only evidence about the customer leg can decide the customer outcome."}]}}, {"id": "INS-007", "kind": "insight", "title": "Handling ambiguous business requirements", "topic": "Handling ambiguous business requirements", "theme": "BA fundamentals", "text": "Use discovery questions, examples, process observation and playback to convert ambiguity into testable requirements.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s2", "title": "Business Process Modelling: As-Is and To-Be Flows", "url": "lessons/ch28s2"}}, {"id": "INS-008", "kind": "insight", "title": "Making requirements testable", "topic": "Making requirements testable", "theme": "BA fundamentals", "text": "Define observable outcomes, boundary conditions, negative cases and acceptance criteria.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-009", "kind": "insight", "title": "Resolving conflicting stakeholder requirements", "topic": "Resolving conflicting stakeholder requirements", "theme": "Stakeholders", "text": "Compare value, risk, urgency, customer impact and dependencies; facilitate a documented decision.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-010", "kind": "insight", "title": "Managing requirement change mid-sprint", "topic": "Managing requirement change mid-sprint", "theme": "Agile delivery", "text": "Assess scope, sprint goal, effort and dependency impact before agreeing a change.", "domain": "Agile Delivery", "area": "Agile Delivery", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-011", "kind": "insight", "title": "First response to a production issue", "topic": "First response to a production issue", "theme": "Production support", "text": "Establish impact, affected population, containment, ownership, evidence and update cadence.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s8", "title": "Incident communication: who is told, what they are told, and when", "url": "lessons/ch68s8"}, "case": {"status": "authored", "business_problem": "At Meridian Bank, the monitoring dashboard shows a sharp rise in failed instant payments just after 09:00. Customers report payments stuck in pending, and the contact centre queue is growing. The on-call payments analyst is the first responder and must decide what to do in the first thirty minutes, before the cause is known.\n\nThe risk is that well-meant early actions make things worse: restarting a service could duplicate payments, retrying stuck items could double debit customers, and silence from the bank lets rumours fill the gap. The analyst must establish how many customers are affected, which rails and channels are involved, whether money has moved, and who owns the fix, while keeping customers and internal stakeholders updated on a steady cadence.", "decision_exercise": {"scenario": "Instant payments are failing and customers report stuck payments. You are the first responder and the cause is not yet known. What is the best first response?", "options": [{"id": "A", "text": "Retry all stuck payments in bulk so customers are paid quickly."}, {"id": "B", "text": "Restart the payment service immediately to clear the problem."}, {"id": "C", "text": "Wait until the cause is fully understood before telling anyone."}, {"id": "D", "text": "Declare the incident, establish impact and affected population, contain the issue by pausing new submissions on the affected rail if needed, assign an owner, preserve evidence, and start regular updates."}], "correct_option": "D", "why": "Option D is correct because it establishes facts, limits further harm and keeps ownership and communication clear while diagnosis continues. Option B risks duplicate processing and destroys evidence about the failure. Option A risks duplicate debits on payments whose true status is unknown. Option C leaves customers and stakeholders without information while the impact grows."}, "recommended_solution": "Follow a fixed first-response sequence and do not improvise the order. First, confirm the incident is real using monitoring, error rates and customer reports, and declare it through the agreed channel with a severity based on customer impact, not on the suspected cause. Second, scope the impact: which rails, channels, customer segments and time window are affected, how many payments are stuck, and whether any money has moved without a matching status.\n\nThird, contain the issue. Pause or throttle new submissions on the affected rail if continuing to accept payments would create more uncertain items, and stop bulk retries until the status of stuck payments is known. Fourth, assign a single incident owner and the needed roles: engineering, operations, treasury or clearing contacts, and communications. Preserve logs, message references, correlation IDs and database evidence before any restart or fix, so the root cause can be established afterwards.\n\nFifth, communicate on a fixed cadence, for example every thirty minutes, even when the update is that investigation continues. Say what is affected, what customers should do, and when the next update will arrive. Record every decision and its time, and only close the incident after reconciliation proves the affected payments are in a correct final state.", "flow_steps": [{"step": 1, "actor": "Monitoring", "action": "Detects a rise in failed instant payments and pages the on-call analyst", "system": "Monitoring and alerting"}, {"step": 2, "actor": "First responder", "action": "Confirms the incident, declares severity and opens the incident record", "system": "Incident management tool"}, {"step": 3, "actor": "First responder", "action": "Scopes impact by rail, channel, customer segment and time window", "system": "Dashboards and payment status store"}, {"step": 4, "actor": "Incident owner", "action": "Contains the issue by pausing affected submissions and stopping bulk retries", "system": "Payment engine controls"}, {"step": 5, "actor": "Engineering", "action": "Traces correlation IDs across gateway, service, event bus and ledger to find the failing transition", "system": "Logs and tracing"}, {"step": 6, "actor": "Operations", "action": "Verifies the true state of stuck payments against ledger and clearing evidence", "system": "Reconciliation"}, {"step": 7, "actor": "Communications", "action": "Issues customer and stakeholder updates on a fixed cadence", "system": "Status page and contact centre briefing"}, {"step": 8, "actor": "Incident owner", "action": "Applies the fix, verifies recovery, reconciles all affected payments and closes the incident with a review", "system": "Incident management tool"}], "happy_path": "The incident is declared within minutes, the affected rail is paused before more uncertain payments are created, and tracing shows a downstream consumer stopped processing events. The fix is applied, events are replayed idempotently, every stuck payment reaches a correct final state, reconciliation confirms no duplicate debits, and customers receive a clear closing update.", "negative_paths": [{"path": "API success but downstream incomplete", "trigger": "The API returns success but the downstream payment record is never created.", "handling": "Trace the correlation ID across gateway, service, event bus and database. Do not retry until the financial effect is known, and place the item in a controlled recovery state."}, {"path": "Restart destroys evidence", "trigger": "A service is restarted before logs and message references are preserved.", "handling": "Capture logs, correlation IDs and database snapshots first. Make evidence preservation a required step before any restart or fix."}, {"path": "Bulk retry duplicates payments", "trigger": "Stuck payments are retried in bulk while their original status is unknown.", "handling": "Block bulk retries during the incident. Resolve each payment from authoritative ledger and clearing evidence, and use idempotency keys so a genuine retry returns the original reference."}, {"path": "Silent incident", "trigger": "No updates are issued while diagnosis continues, so customers and stakeholders escalate.", "handling": "Publish updates on a fixed cadence even when there is no new cause, stating impact, what customers should do, and the next update time."}], "technical_data": "Trace one correlation ID across every boundary: API gateway, payment service, event bus, downstream consumer, database and ledger. Separate HTTP transport success from business completion, so a 200 or 202 response is never treated as proof that the payment completed. Use idempotency keys, durable outbox events and idempotent consumers so recovery replays do not duplicate financial effects. Check webhook delivery, dead-letter queues, payload mapping, database constraints and event ordering. Preserve logs and message IDs before any restart. Define rail-specific response service levels and escalation thresholds, and keep a runbook that names the owner, the containment actions and the evidence to capture for each failure type.", "messages_fields": [{"message": "Payment status event", "purpose": "Internal event recording each payment state transition, used for tracing and recovery.", "key_fields": ["Correlation ID, shared across all systems", "Payment ID and instruction ID", "Previous state and new state", "Event timestamp and version"]}, {"message": "pacs.002", "purpose": "Payment status report from the clearing system, used to confirm acceptance or rejection.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected", "Status timestamp"]}, {"message": "camt.053", "purpose": "Bank-to-customer statement used to verify whether a debit actually posted.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Balance after the entry"]}], "accounting_operational": "No payment may be retried or reversed until its ledger and clearing state are known. Stuck payments sit on an incident worklist with an owner, an age and a target resolution time, and aged items escalate. Reconciliation after recovery must prove that every affected payment has exactly one debit where due, no duplicate debits exist, and settlement accounts match clearing reports. Any manual correction needs a documented reason, a second check where policy requires it, and a full audit trail. Customer compensation, where policy provides for it, is handled as a separate controlled process, never as an unrecorded adjustment to a payment.", "gherkin": ["Given the API accepted a request but the downstream record is absent, When the first responder coordinates investigation, Then the team traces the same correlation ID across each integration boundary and identifies the failed transition.", "Given an incident is declared, When thirty minutes pass without a resolution, Then a status update is issued stating impact, customer guidance and the next update time.", "Given stuck payments have unknown status, When a bulk retry is requested, Then the retry is blocked until each payment is resolved from ledger and clearing evidence."], "assessment": [{"question": "What does an HTTP 200 or 202 response guarantee?", "options": ["That the request was received or accepted at the transport layer, not that the business transaction completed.", "That the beneficiary was credited.", "That the payment completed.", "That the ledger posted."], "answer": 0, "explanation": "HTTP success describes transport acceptance. Business completion must be confirmed from the payment state, ledger and clearing evidence."}, {"question": "What should happen before a service is restarted during an incident?", "options": ["Retry all stuck payments.", "Preserve logs, correlation IDs and database evidence so the cause can still be established.", "Close the incident record.", "Nothing, restart first."], "answer": 1, "explanation": "A restart can destroy the evidence needed for root cause analysis and for proving which payments were affected."}, {"question": "Why is a fixed update cadence important during an incident?", "options": ["It slows down the fix.", "It replaces the need for a fix.", "It keeps customers and stakeholders informed and reduces duplicate escalations while diagnosis continues.", "It only matters after resolution."], "answer": 2, "explanation": "Regular updates, even without a new cause, maintain trust and give customers clear guidance."}, {"question": "When is it safe to retry a stuck payment?", "options": ["As soon as the customer asks.", "Only after its ledger and clearing state are known and idempotency protects against a duplicate.", "After the incident is closed.", "Immediately, in bulk with the others."], "answer": 1, "explanation": "Retrying an uncertain payment risks a duplicate debit. Status must be resolved first, and the retry must return the original reference where the payment already exists."}]}}, {"id": "INS-012", "kind": "insight", "title": "Gateway versus bank responsibilities", "topic": "Gateway versus bank responsibilities", "theme": "API integration", "text": "Separate gateway orchestration, bank authorisation/processing and merchant notification responsibilities.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch47s4", "title": "Gateway, Aggregator and Third-Party Service Integration", "url": "lessons/ch47s4"}}, {"id": "INS-013", "kind": "insight", "title": "BA role in Agile Scrum", "topic": "BA role in Agile Scrum", "theme": "Requirements", "text": "Explain BA contribution across refinement, planning, delivery support, review and acceptance.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s4", "title": "Writing Jira User Stories for Payments", "url": "lessons/ch28s4"}}, {"id": "INS-014", "kind": "insight", "title": "BRD, FRD and use-case selection", "topic": "BRD, FRD and use-case selection", "theme": "Documentation", "text": "Choose artefacts based on audience, complexity, traceability and delivery context.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s2", "title": "Writing a BRD and a functional specification for a payment product", "url": "lessons/ch84s2"}}, {"id": "INS-015", "kind": "insight", "title": "Eliciting requirements from non-technical stakeholders", "topic": "Eliciting requirements from non-technical stakeholders", "theme": "Elicitation", "text": "Use interviews, workshops, observation, examples and structured playback.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-016", "kind": "insight", "title": "User story versus use case", "topic": "User story versus use case", "theme": "Requirements", "text": "Explain when outcome-oriented stories or interaction-oriented use cases are more useful.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-017", "kind": "insight", "title": "Resolving a late requirement gap", "topic": "Resolving a late requirement gap", "theme": "SDLC", "text": "Trace the gap to discovery, analysis, design, implementation or testing and agree corrective action.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-018", "kind": "insight", "title": "Creating process and data-flow diagrams", "topic": "Creating process and data-flow diagrams", "theme": "Process modelling", "text": "Select the right diagram and validate actors, triggers, decisions, hand-offs and data stores.", "domain": "Architecture & Process Design", "area": "Architecture & Process Design", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s2", "title": "Business Process Modelling: As-Is and To-Be Flows", "url": "lessons/ch28s2"}}, {"id": "INS-019", "kind": "insight", "title": "Validating requirements before development", "topic": "Validating requirements before development", "theme": "Requirements validation", "text": "Run walkthroughs, consistency checks, testability checks and stakeholder sign-off.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-020", "kind": "insight", "title": "Planning UAT and preparing test cases", "topic": "Planning UAT and preparing test cases", "theme": "UAT", "text": "Derive UAT coverage from business journeys, acceptance criteria, roles and exception paths.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s2", "title": "Test Levels: Unit, SIT, UAT and Regression", "url": "lessons/ch42s2"}}, {"id": "INS-021", "kind": "insight", "title": "KPI design for a digital banking application", "topic": "KPI design for a digital banking application", "theme": "Digital banking", "text": "Define adoption, task completion, failure, service, risk and customer outcome measures.", "domain": "Product Management", "area": "Product Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s4", "title": "Customer journeys in payments: the moments that decide trust", "url": "lessons/ch82s4"}}, {"id": "INS-022", "kind": "insight", "title": "Redesigning a KYC onboarding journey", "topic": "Redesigning a KYC onboarding journey", "theme": "KYC", "text": "Map friction, document collection, validation, screening, exception handling and conversion measures.", "domain": "Compliance & Digital Banking", "area": "Compliance & Digital Banking", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch24s2", "title": "KYC and Customer Due Diligence", "url": "lessons/ch24s2"}, "case": {"status": "authored", "business_problem": "Meridian Bank wants more new retail customers to complete digital onboarding, but only a small share of started applications reach an active account. Customers abandon the journey at document upload and at identity verification, and many who do finish are later held for manual review because documents are unclear or data does not match. The compliance team is worried that simplifying the journey will weaken controls, while the product team is worried that every extra step loses customers.\n\nThe redesign must map where customers drop out, which documents are genuinely needed for each customer type, how validation and screening work, and what happens when something fails. It must also measure conversion properly, so the bank can tell whether a change helped customers or only moved the failure to a later step.", "decision_exercise": {"scenario": "Meridian Bank is redesigning digital KYC onboarding. Dropout is highest at document upload and identity verification, and many completed applications stall in manual review. What is the best redesign approach?", "options": [{"id": "A", "text": "Add more document requirements so manual review has more evidence."}, {"id": "B", "text": "Map dropout and failure points, collect only the documents needed for each customer type, validate and screen in stages with clear guidance and exception handling, and measure conversion end to end."}, {"id": "C", "text": "Keep the journey unchanged and increase marketing spend to bring in more starters."}, {"id": "D", "text": "Remove document upload and identity checks to maximise completion."}], "correct_option": "B", "why": "Option B is correct because it reduces friction where it is caused by poor guidance or unnecessary requirements, while keeping validation and screening controls intact and measuring the real outcome. Option D removes controls and creates compliance risk. Option A increases friction and manual review load. Option C spends more to feed the same broken journey."}, "recommended_solution": "Start with evidence, not opinions. Measure the funnel stage by stage: started, identity details entered, document uploaded, identity verified, screening complete, account opened and first transaction. Break dropout down by device, document type, customer segment and failure reason, so the team fixes the actual causes instead of the loudest complaint.\n\nCollect documents by customer type and risk, not by a single long list for everyone. Ask for each document once, explain why it is needed and what a good capture looks like, and validate quality at capture so a blurred image is retaken immediately rather than failing hours later in manual review. Run identity verification, document validation and sanctions and adverse-media screening in a clear order, and show the customer a plain-language status at each stage.\n\nDesign exception handling as part of the journey, not as an afterthought. A failed check should tell the customer exactly what to do next, offer a supported alternative such as a different document or an assisted channel, and preserve the application so the customer does not start again. Route genuinely risky or unclear cases to trained reviewers with the full evidence pack, and set service levels for review so applications do not stall silently. Measure conversion, time to account opening, manual review rate and rework rate after every change, and only keep changes that improve completion without increasing bad outcomes.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Starts onboarding in the app and enters personal details", "system": "Mobile banking"}, {"step": 2, "actor": "Onboarding service", "action": "Determines the documents and checks required for this customer type and risk level", "system": "Onboarding service"}, {"step": 3, "actor": "Customer", "action": "Captures identity document with on-screen quality guidance", "system": "Document capture"}, {"step": 4, "actor": "Verification service", "action": "Validates the document and matches the customer identity", "system": "Identity verification service"}, {"step": 5, "actor": "Screening service", "action": "Runs sanctions, adverse-media and fraud screening", "system": "Screening service"}, {"step": 6, "actor": "Onboarding service", "action": "Decides the outcome: approve, request a correction, or route to manual review", "system": "Decision engine"}, {"step": 7, "actor": "Reviewer", "action": "Reviews referred applications with the full evidence pack", "system": "Case management"}, {"step": 8, "actor": "Bank", "action": "Opens the account, confirms the outcome to the customer and records the audit trail", "system": "Core banking and notification service"}], "happy_path": "The customer enters details once, captures a clear document with live guidance, passes identity verification and screening, and the account opens in the same session. The customer receives a clear confirmation and can transact immediately, and the full evidence pack is stored for audit.", "negative_paths": [{"path": "Poor document capture", "trigger": "The image is blurred or cropped, so validation fails.", "handling": "Detect quality at capture, explain the problem in plain language, and let the customer retake the image immediately without restarting the application."}, {"path": "Data mismatch", "trigger": "The name or date of birth on the document does not match the entered details.", "handling": "Show exactly which field differs, let the customer correct it or choose a matching document, and route unresolved mismatches to manual review with both values visible."}, {"path": "Screening hit", "trigger": "Screening returns a possible match that needs judgement.", "handling": "Hold the application in a defined review state, give the reviewer the screening evidence and the customer record, and do not auto-reject on a possible match alone."}, {"path": "Application abandoned", "trigger": "The customer leaves part-way through and returns later.", "handling": "Preserve the application and its documents securely, let the customer resume where they stopped, and send a single helpful reminder rather than repeated prompts."}], "technical_data": "Keep one onboarding case record with a stable application ID, the customer type, the required document set, each check result and its timestamp, and the final decision with its reason. Validate document quality, format and expiry at capture, and store documents securely with retention rules. Use structured customer data with clear field definitions, and record the source of every data value so a mismatch can be traced. Make screening calls idempotent and record the screening reference and result version. Separate the decision outcome from the channel display so a screen error cannot be mistaken for a rejection. Log every access to customer documents for audit, and mask sensitive data in logs and support screens.", "messages_fields": [{"message": "Onboarding application", "purpose": "Customer application submitted from the channel to the onboarding service.", "key_fields": ["Application ID", "Customer type and risk tier", "Full name and date of birth", "Address with town name and country code", "Nationality and identification type"]}, {"message": "Document verification result", "purpose": "Result returned by the identity verification service.", "key_fields": ["Application ID", "Document type and number", "Verification outcome", "Quality and authenticity checks passed or failed"]}, {"message": "Screening result", "purpose": "Result returned by the sanctions and adverse-media screening service.", "key_fields": ["Application ID", "Screening reference", "Match outcome, clear, possible or confirmed", "Lists checked and screening timestamp"]}], "accounting_operational": "Onboarding has no customer funds movement, so the operational impact is in worklists, service levels and audit. Referred applications sit on a reviewer worklist with an owner, an age and a target review time, and aged items escalate. No account may be opened until the required checks for that customer type are recorded as passed or formally overridden with approval. Rejected applications keep their evidence and reason for the required retention period. Report conversion, manual review rate, average time to open and rework rate weekly, and treat a rise in manual review as a signal to fix guidance or validation, not as a reason to loosen checks.", "gherkin": ["Given a destination requires a specific document, When the customer submits the application without it, Then the journey explains what is needed and does not create an incomplete account.", "Given a document image is blurred, When capture validation runs, Then the customer is asked to retake the image immediately and the application is preserved.", "Given screening returns a possible match, When the decision is made, Then the application is routed to manual review with the screening evidence attached and is not auto-rejected."], "assessment": [{"question": "What is the first step in redesigning a KYC journey?", "options": ["Measure the funnel stage by stage and find where and why customers drop out or fail.", "Add more documents.", "Change the branding.", "Remove the longest step."], "answer": 0, "explanation": "Evidence about dropout and failure reasons shows which steps actually cause the problem."}, {"question": "Why validate document quality at capture?", "options": ["So fewer documents are needed.", "So a poor image is retaken immediately instead of failing hours later in manual review.", "So screening can be skipped.", "It makes the app slower."], "answer": 1, "explanation": "Early quality checks prevent avoidable manual review and long waits for the customer."}, {"question": "How should a possible screening match be handled?", "options": ["Ignore it and open the account.", "Auto-reject the application.", "Ask the customer to decide.", "Route it to manual review with the full screening evidence for a judged decision."], "answer": 3, "explanation": "A possible match needs human judgement with the evidence visible. Auto-rejection on a possible match alone is wrong."}, {"question": "Which measure shows whether a redesign really worked?", "options": ["Number of applications started.", "Number of screens in the journey.", "End-to-end conversion to an active account, with manual review rate and time to open.", "Marketing spend."], "answer": 2, "explanation": "Starts alone can rise while completion falls. Conversion, review rate and time to open together show the real outcome."}]}}, {"id": "INS-023", "kind": "insight", "title": "Finding customers with repeated failed transactions", "topic": "Finding customers with repeated failed transactions", "theme": "SQL", "text": "Translate a business rule into a time-windowed SQL aggregation and validate data quality.", "domain": "Data & Reporting", "area": "Data & Reporting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch85s4", "title": "Analytics on payment data: liquidity, fraud and customer insight", "url": "lessons/ch85s4"}}, {"id": "INS-024", "kind": "insight", "title": "BA understanding of AML/CFT controls", "topic": "BA understanding of AML/CFT controls", "theme": "AML/CFT", "text": "Map customer and transaction risk controls, screening outcomes, case escalation and auditability.", "domain": "Compliance & Risk", "area": "Compliance & Risk", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch24s3", "title": "Transaction Monitoring", "url": "lessons/ch24s3"}}, {"id": "INS-025", "kind": "insight", "title": "Gathering requirements for a third-party payment gateway", "topic": "Gathering requirements for a third-party payment gateway", "theme": "API integration", "text": "Define API capabilities, request/response contracts, error handling, security, retries and reconciliation.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch47s7", "title": "Exercise: Design the Integration for a New Payment Rail (choose patterns, draw the integration map, define contracts and failure handling)", "url": "lessons/ch47s7"}, "case": {"status": "authored", "business_problem": "Northgate Retail sells online and in store, and wants to add a third-party payment gateway so customers can pay by card and by instant payment at checkout. The product team has a short list of gateway providers, but the requirements are still a set of general wishes: fast, secure, easy to integrate. Nobody has yet defined which payment methods are in scope, what the API must guarantee, how failures and refunds work, or how Northgate will reconcile gateway settlements against its own orders.\n\nWithout clear requirements, the team risks choosing a gateway that cannot support refunds, that reports success before the payment is complete, or that leaves finance unable to match settlements to orders. The business analyst must turn the general wishes into a testable set of requirements covering capabilities, contracts, error handling, security, retries and reconciliation before any provider is selected.", "decision_exercise": {"scenario": "Northgate Retail must define requirements for a third-party payment gateway before selecting a provider. Which approach gives the team a sound basis for selection?", "options": [{"id": "A", "text": "Choose the cheapest provider and define requirements during integration."}, {"id": "B", "text": "Require only that the gateway supports card payments, and add the rest later."}, {"id": "C", "text": "Define payment methods, API contracts, error handling, security, idempotency, retries, webhooks, refunds and reconciliation requirements up front, with acceptance criteria for each."}, {"id": "D", "text": "Ask the provider to define Northgate's requirements."}], "correct_option": "C", "why": "Option C is correct because selection and integration both depend on knowing what the gateway must do, what its responses guarantee, and how money and data are reconciled. Option A commits to a provider before knowing whether it fits. Option D hands Northgate's business needs to a seller. Option B leaves refunds, instant payments and reconciliation undefined until they become problems."}, "recommended_solution": "Start from the customer and finance outcomes, not from the provider brochure. List the payment methods, currencies, channels and customer journeys in scope, and for each one define the expected flow: authorisation, capture, refund, partial refund, void, chargeback handling and settlement timing. State what each API response guarantees, distinguishing receipt, validation, acceptance and completion, so a success response is never misread.\n\nDefine the contract in detail: request and response fields, mandatory and optional data, validation rules, error codes and their meaning, timeout values, retry rules with idempotency keys, webhook events and their delivery guarantees, and the status enquiry API for uncertain payments. Require that a retry with the same idempotency key returns the original payment reference and never creates a second charge. Require that the gateway supports duplicate detection and that Northgate can query the status of any payment by its own order reference and the gateway reference.\n\nCover security and operations as requirements, not as assumptions: authentication, key management, data protection, PCI scope, logging and monitoring, service levels, support hours, incident handling and exit terms. Define reconciliation from the start: settlement files, their format and timing, the identifiers that link a settlement line to an order, fee treatment, and the process for unmatched items. Write acceptance criteria for every requirement so each one can be tested before go-live, and score providers against the same criteria.", "flow_steps": [{"step": 1, "actor": "Business analyst", "action": "Documents payment methods, journeys, refunds and settlement needs with product and finance", "system": "Requirements workshop"}, {"step": 2, "actor": "Business analyst", "action": "Defines the API contract, error codes, timeouts, retries and webhook events", "system": "Requirements specification"}, {"step": 3, "actor": "Business analyst", "action": "Defines security, service levels, support and reconciliation requirements", "system": "Requirements specification"}, {"step": 4, "actor": "Northgate Retail", "action": "Scores gateway providers against the same acceptance criteria", "system": "Vendor evaluation"}, {"step": 5, "actor": "Gateway provider", "action": "Provides sandbox access, API documentation and settlement file samples", "system": "Provider sandbox"}, {"step": 6, "actor": "Engineering", "action": "Builds the integration and tests happy paths, failures, retries and refunds", "system": "Test environment"}, {"step": 7, "actor": "Finance", "action": "Reconciles test settlements against orders using the agreed identifiers", "system": "Reconciliation"}, {"step": 8, "actor": "Northgate Retail", "action": "Signs off against acceptance criteria and plans the production rollout", "system": "Go-live checklist"}], "happy_path": "The requirements are agreed before selection, the chosen gateway meets them, and integration tests pass for payment, refund, retry and reconciliation. In production, each order maps to one gateway payment, settlements reconcile to orders automatically, and a retried checkout returns the original payment reference instead of a duplicate charge.", "negative_paths": [{"path": "API success but order not created", "trigger": "The gateway returns success but Northgate's order record is not created.", "handling": "Trace the correlation ID across gateway, service and order system. Confirm the payment state through the status enquiry API before retrying, and reconcile financial effects first."}, {"path": "Duplicate charge on retry", "trigger": "A slow checkout response leads the customer to submit again and two charges are created.", "handling": "Require idempotency keys scoped to the order. A retry with the same key must return the original payment reference and never create a second charge."}, {"path": "Settlement cannot be matched", "trigger": "Settlement lines arrive without the order reference finance needs.", "handling": "Require the settlement file to carry the order reference, gateway reference, gross amount, fees and value date. Unmatched lines go to a finance worklist, never to an automatic write-off."}, {"path": "Cut-off missed", "trigger": "A payment is accepted too late for same-day settlement and the business expects the funds that day.", "handling": "Define cut-off times per rail and currency in the requirements, and show the expected settlement date to the business at the point of sale."}], "technical_data": "Define a canonical order-to-payment model with stable identifiers: order ID, idempotency key, gateway payment reference, end-to-end ID where applicable, and settlement line reference. Persist the idempotency key, payload hash, original payment reference and outcome, and define retention. Require webhook signatures and replay protection, and make webhook consumers idempotent so a duplicate delivery cannot create a duplicate order. Specify field validation, decimal precision, currency handling and timezone rules. Require structured error codes with a mapping to customer-facing messages, and require a status enquiry API so any uncertain payment can be resolved without guessing. Log every gateway request and response with correlation IDs, masked card data, and retention rules.", "messages_fields": [{"message": "pain.001", "purpose": "Payment initiation from Northgate to the gateway or bank, where applicable.", "key_fields": ["Instruction ID", "End-to-end ID", "Debtor and creditor details", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer payment message for the underlying transfer where the gateway routes through a bank rail.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected"]}, {"message": "Gateway webhook event", "purpose": "Asynchronous notification from the gateway about a payment state change.", "key_fields": ["Event ID and event type", "Gateway payment reference", "Order ID", "New payment status and timestamp", "Signature for verification"]}], "accounting_operational": "Each order must map to exactly one payment, and each settlement line must map to an order. Finance reconciles gateway settlements daily against orders, gross amounts, fees and value dates, and unmatched or short-settled items go to a worklist with an owner and an ageing rule. Refunds are posted as separate controlled transactions linked to the original payment, never as an edit to the original sale. Duplicate charges are refunded once with a clear reason and audit trail, and the incident is recorded so the retry control can be fixed. Settlement timing, fees and cut-off times are agreed in the contract so cash forecasting is based on written terms, not on assumptions.", "gherkin": ["Given an already accepted instruction, When the identical request is retried with the same idempotency key, Then the platform returns the original payment reference and does not create a second debit.", "Given the gateway accepted a request but the order record is absent, When the team traces the payment, Then the same correlation ID is followed across each integration boundary and the failed transition is identified.", "Given a settlement line arrives, When reconciliation runs, Then the line is matched to its order by reference and amount, or it is placed on the finance worklist for investigation."], "assessment": [{"question": "Why must requirements be defined before a gateway provider is selected?", "options": ["Because selection depends on knowing which payment methods, guarantees, refunds and reconciliation the gateway must support.", "So the cheapest provider can be chosen.", "Because integration is faster without requirements.", "Because providers will not talk to Northgate otherwise."], "answer": 0, "explanation": "Without requirements, the team cannot tell whether a provider fits, and gaps only appear during integration or in production."}, {"question": "What must a retry with the same idempotency key do?", "options": ["Delete the first payment.", "Create a second payment.", "Ignore the retry.", "Return the original payment reference without creating a second charge."], "answer": 3, "explanation": "Idempotency exists so a technical retry is safe. A second charge from the same key is a defect."}, {"question": "What does a gateway success response guarantee?", "options": ["That the order was created.", "That the beneficiary was credited.", "That settlement has happened.", "Only what the contract says it guarantees, which may be receipt or acceptance rather than completion."], "answer": 1, "explanation": "The contract must state whether success means receipt, validation, acceptance or completion. Each means something different."}, {"question": "Which identifiers must a settlement file carry?", "options": ["The order reference, gateway reference, gross amount, fees and value date.", "Only the gateway name.", "Only the date.", "Only the total amount."], "answer": 0, "explanation": "Finance can only reconcile settlements to orders when the file carries the linking references and the amounts that explain the net settlement."}]}}, {"id": "INS-026", "kind": "insight", "title": "Post-deployment stakeholder reporting", "topic": "Post-deployment stakeholder reporting", "theme": "Post-deployment", "text": "Report adoption, incidents, defects, service levels, benefits and open risks.", "domain": "Product Operations", "area": "Product Operations", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s8", "title": "Production support and root cause analysis: keeping payments running", "url": "lessons/ch84s8"}}, {"id": "INS-027", "kind": "insight", "title": "Loan lifecycle overview", "topic": "Loan lifecycle overview", "theme": "Banking lifecycle", "text": "Trace application, decision, agreement, disbursement, servicing, repayment and closure.", "domain": "Banking Products", "area": "Banking Products", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch49s1", "title": "What a Standby Letter of Credit Is", "url": "lessons/ch49s1"}}, {"id": "INS-028", "kind": "insight", "title": "NEFT, RTGS and IMPS comparison", "topic": "NEFT, RTGS and IMPS comparison", "theme": "Domestic rails", "text": "Compare operating model, speed, availability, settlement and customer use cases using current rules.", "domain": "Payment Rails", "area": "Payment Rails", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch9s5", "title": "RTGS: high value settlement with finality", "url": "lessons/ch9s5"}}, {"id": "INS-029", "kind": "insight", "title": "End-to-end payment transaction lifecycle", "topic": "End-to-end payment transaction lifecycle", "theme": "Payment lifecycle", "text": "Map initiation through validation, routing, clearing, settlement, posting and confirmation.", "domain": "Payment Foundations", "area": "Payment Foundations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch4s1", "title": "Initiation, where every payment begins", "url": "lessons/ch4s1"}, "case": {"status": "authored", "business_problem": "Northgate Retail pays a supplier in another country through Meridian Bank. The finance team at Northgate sees the payment leave its account, but the supplier says nothing has arrived, and nobody in either company can say where the payment is. The bank's channel shows the payment as sent, the payment engine shows it as processed, and the ledger shows the debit, yet the supplier's bank has no record of a credit.\n\nThe confusion comes from treating each screen as the whole truth. Initiation, validation, routing, clearing, settlement, posting and confirmation are separate stages, each with its own evidence and its own authoritative source. The learner must map the full lifecycle, know which system proves each stage, and explain to the customer what has happened and what happens next, without guessing.", "decision_exercise": {"scenario": "A cross-border supplier payment has left the debtor account but the supplier has not been credited, and the channel, engine and ledger disagree about the payment state. What should the analyst do?", "options": [{"id": "A", "text": "Wait for the supplier to confirm receipt before doing anything."}, {"id": "B", "text": "Tell the supplier the payment was sent, because the channel shows it as sent."}, {"id": "C", "text": "Trace the payment stage by stage from initiation to settlement using its stable identifiers, identify the last proven stage, and act only on that evidence."}, {"id": "D", "text": "Send the payment again so the supplier is paid."}], "correct_option": "C", "why": "Option C is correct because each lifecycle stage has its own evidence, and only the last proven stage tells the analyst where the payment really is. Option B treats a channel display as proof of settlement. Option D risks a duplicate payment. Option A leaves an unresolved payment with no owner."}, "recommended_solution": "Map the lifecycle as a chain of states with a named owner and a named piece of evidence for each one. Initiation creates the instruction with an instruction ID and end-to-end ID. Validation checks the account, the beneficiary, limits, fraud and sanctions, and either accepts or rejects with a reason. Routing selects the rail and the correspondent path. Clearing submits the payment message and awaits an acknowledgement that proves acceptance, not just delivery. Settlement moves funds between banks, and posting updates the ledger. Confirmation tells the channel and the customer the final outcome.\n\nAt each stage, keep the identifiers stable and separate: the instruction ID identifies the instruction, the end-to-end ID travels to the beneficiary bank, the transaction ID identifies the interbank transaction, and the UETR tracks the payment across the correspondent chain where applicable. Never reuse one internal ID to mean two different things, and never let a retry create a new instruction ID for the same business payment without linking it to the original.\n\nWhen a payment is delayed, find the last stage with evidence and work forward from there. If no clearing acknowledgement arrived within the expected window, hold the payment in an awaiting-response state, run a status enquiry, and do not resubmit blindly. If settlement reports show a different amount from the submitted payment, classify the difference as fees, foreign exchange, partial settlement or error before posting any adjustment. Confirm the outcome to the customer only when the evidence supports it.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits the payment instruction with beneficiary, amount and currency", "system": "Mobile banking or corporate channel"}, {"step": 2, "actor": "Payment engine", "action": "Validates the account, beneficiary, limits, fraud and sanctions checks", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Routes the payment to the chosen rail and correspondent path", "system": "Routing service"}, {"step": 4, "actor": "Payment engine", "action": "Sends the payment message to the clearing system", "system": "Clearing adapter"}, {"step": 5, "actor": "Clearing system", "action": "Returns an acknowledgement confirming acceptance or rejection", "system": "Clearing system"}, {"step": 6, "actor": "Settlement system", "action": "Settles funds between the banks and reports the settlement outcome", "system": "Settlement system"}, {"step": 7, "actor": "Core ledger", "action": "Posts the debit and any settlement entries with the original references", "system": "Core banking"}, {"step": 8, "actor": "Payment engine", "action": "Updates the payment to its final state and confirms the outcome to the customer", "system": "Notification service"}], "happy_path": "The instruction is validated, routed and accepted by clearing, settlement completes for the full amount, the ledger posts match the settlement report, and the beneficiary bank credits the supplier. The customer receives a confirmation with the payment reference, the amount, the value date and the tracking reference.", "negative_paths": [{"path": "Clearing acknowledgement delayed", "trigger": "No acknowledgement arrives within the expected window.", "handling": "Keep the payment in an awaiting-response state, correlate by message and transaction references, run a status enquiry, and do not resubmit blindly."}, {"path": "Settlement amount differs", "trigger": "The settlement report shows a different amount from the submitted payment.", "handling": "Classify the difference as fees, foreign exchange, partial settlement, netting or error. Reconcile at the correct level and post adjustments only under approved accounting rules."}, {"path": "Identifier reused with a different meaning", "trigger": "An internal transaction ID is mapped to the end-to-end reference, so tracking breaks.", "handling": "Maintain separate fields for internal ID, instruction ID, end-to-end ID, transaction ID and UETR, and map each only according to its defined meaning."}, {"path": "Late acknowledgement after timeout", "trigger": "An acknowledgement arrives after the payment was already placed in investigation.", "handling": "Process it idempotently against the current state. Do not regress the payment to an earlier state, and reconcile the outcome before notifying the customer."}], "technical_data": "Define a canonical payment state model with explicit transitions and the authoritative source for each transition. Keep instruction ID, end-to-end ID, transaction ID, UETR and clearing references in separate fields with a documented lifecycle and uniqueness scope. Correlate every acknowledgement, settlement report and ledger entry by those references, and make status handling idempotent so duplicate or late messages cannot create duplicate effects. Define rail-specific response service levels, timeout handling and status enquiry rules. Version state events so an older event cannot regress a newer state, log every transition, and retain the original instruction and all messages for audit. Reconcile submitted messages against acknowledgements and ledger entries on a scheduled cycle.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation.", "key_fields": ["Instruction ID", "End-to-end ID", "Debtor and creditor accounts", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer payment sent through clearing to the beneficiary bank.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency", "Remittance information"]}, {"message": "pacs.009", "purpose": "Financial institution to financial institution payment, used for the cover or settlement leg where applicable.", "key_fields": ["Instruction ID", "Debtor agent and creditor agent", "Settlement amount and currency", "Cover or settlement details"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected"]}, {"message": "camt.053", "purpose": "Bank-to-customer statement used to verify postings and settlement entries.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Balance after the entry"]}], "accounting_operational": "Debit the customer account once for the instructed amount and credit the settlement or clearing account. Settlement entries must match the clearing report for amount, currency and value date, and any difference must be classified before adjustment. Fees and foreign exchange differences are posted as separate lines with their own reason codes, never hidden inside the payment amount. Unmatched settlement items go to a reconciliation worklist with an owner and an ageing rule, and no variance is written off without policy approval. Operations owns the awaiting-response queue, with service levels per rail, and escalates aged items before they become customer complaints.", "gherkin": ["Given no clearing response is received within the expected window, When the timeout threshold is reached, Then the payment enters an investigation state without duplicate submission.", "Given a settlement amount differs from the expected amount, When reconciliation runs, Then the variance is classified and not auto-written off without policy approval.", "Given an instruction ID and end-to-end ID are both supplied, When the payment is mapped, Then each is placed in its correct semantic field."], "assessment": [{"question": "What is the difference between transport delivery and business acceptance?", "options": ["Delivery only applies to cards.", "Delivery means the message arrived; acceptance means the clearing system or beneficiary bank agreed to process it.", "Acceptance happens before delivery.", "They are the same thing."], "answer": 1, "explanation": "A message can be delivered and still be rejected. Only the business acknowledgement proves acceptance."}, {"question": "Which identifier travels to the beneficiary bank and stays stable across the payment?", "options": ["The internal database key.", "The channel session ID.", "The settlement batch number.", "The end-to-end ID."], "answer": 3, "explanation": "The end-to-end ID is carried through to the beneficiary bank and is used for tracking and investigation."}, {"question": "No clearing acknowledgement arrives in the expected window. What should happen?", "options": ["Hold the payment in an awaiting-response state and run a status enquiry without blind resubmission.", "Credit the beneficiary manually.", "Resubmit the payment immediately.", "Mark the payment as failed."], "answer": 0, "explanation": "Blind resubmission risks a duplicate payment. The payment must be held and its status enquired about first."}, {"question": "A settlement report shows less than the submitted amount. What is the correct first step?", "options": ["Repay the customer the difference.", "Write off the difference.", "Ignore it if it is small.", "Classify the difference as fees, foreign exchange, partial settlement, netting or error before any adjustment."], "answer": 3, "explanation": "The cause determines the correct accounting treatment. An unexplained difference must never be auto-written off."}]}}, {"id": "INS-030", "kind": "insight", "title": "Banking API integration walkthrough", "topic": "Banking API integration walkthrough", "theme": "API integration", "text": "Explain contract, authentication, payload, response, asynchronous status, monitoring and recovery.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch47s8", "title": "OpenAPI contracts: designing a payment API contract", "url": "lessons/ch47s8"}, "case": {"status": "authored", "business_problem": "Northgate Retail wants to connect its checkout directly to Meridian Bank's payment API so orders can be paid without leaving the Northgate site. The engineering team has the API documentation, but the business analyst must explain how the integration actually works end to end: how the client authenticates, what the request and response mean, how Northgate learns the final payment outcome, how failures are recovered, and how the integration is monitored.\n\nThe danger is a shallow walkthrough that only covers the happy path. In production, the API will return success while a downstream step fails, a field will differ between the screen, the payload and the database, and a future schema change will break a consumer that nobody knew existed. The walkthrough must cover the contract, authentication, payload, asynchronous status, monitoring and recovery, with evidence at each step.", "decision_exercise": {"scenario": "Northgate is integrating with Meridian Bank's payment API. The API returns a success response for a payment, but the order record is not created in Northgate's system. What should the team do first?", "options": [{"id": "A", "text": "Restart the Northgate order service."}, {"id": "B", "text": "Assume the payment failed and submit it again."}, {"id": "C", "text": "Tell the customer the payment failed."}, {"id": "D", "text": "Check what the response contract promises, then trace the correlation ID across the gateway, payment service, event bus and database to find the failed transition, and reconcile the financial effect before retrying."}], "correct_option": "D", "why": "Option D is correct because the response may only promise receipt or acceptance, and the failure may sit in a downstream consumer, a webhook or a database write. Tracing the same correlation ID finds the real break. Option B risks a duplicate payment. Option C states a conclusion the evidence does not support. Option A acts before the cause is known."}, "recommended_solution": "Walk through the integration in layers, and make each layer testable. Start with the contract: the OpenAPI definition, the endpoints, the request and response schemas, mandatory and optional fields, validation rules and error codes. State plainly what each response means, so a 202 means the request was accepted for processing, not that the payment completed, and a 200 on a status enquiry means the status was returned, not that the payment succeeded.\n\nNext, cover authentication and security: how the client proves its identity, how keys or tokens are issued and rotated, what scopes limit access, and how sensitive data is protected in transit and in logs. Then cover the payload: field definitions, decimal precision, currency and timezone rules, and the mapping from the Northgate order to the bank payment, with a named owner for each field.\n\nThen cover asynchronous status: webhooks or events that report the final outcome, their delivery guarantees, signature verification, retry policy and the status enquiry API that resolves any uncertain payment. Make webhook consumers idempotent so a duplicate delivery cannot create a duplicate order. Cover monitoring and recovery: dashboards, alerts, dead-letter queues, correlation ID tracing, and the runbook for each failure type. Finally, cover change: versioning, deprecation periods, consumer inventory and contract tests, so a breaking field rename is caught before it reaches production.", "flow_steps": [{"step": 1, "actor": "Northgate client", "action": "Authenticates to the bank API and receives a scoped token", "system": "API gateway"}, {"step": 2, "actor": "Northgate client", "action": "Submits a payment request with the order ID, idempotency key and payment details", "system": "API gateway"}, {"step": 3, "actor": "Payment service", "action": "Validates the request, persists the instruction and returns an acceptance response with a payment reference", "system": "Payment service"}, {"step": 4, "actor": "Payment service", "action": "Processes the payment and publishes a status event", "system": "Event bus"}, {"step": 5, "actor": "Bank", "action": "Sends a signed webhook or status event to Northgate when the outcome is known", "system": "Webhook service"}, {"step": 6, "actor": "Northgate", "action": "Verifies the webhook signature and updates the order idempotently", "system": "Order service"}, {"step": 7, "actor": "Northgate", "action": "Queries the status enquiry API for any payment whose outcome is still uncertain", "system": "Status enquiry API"}, {"step": 8, "actor": "Operations", "action": "Monitors dashboards, dead-letter queues and reconciliation, and acts on alerts", "system": "Monitoring and reconciliation"}], "happy_path": "Northgate authenticates, submits the payment with an idempotency key, and receives an acceptance response with a payment reference. The payment completes, the signed webhook arrives, the order is created exactly once, and the status enquiry API confirms the same outcome. Reconciliation matches the payment to the order and to settlement.", "negative_paths": [{"path": "API success but downstream incomplete", "trigger": "The API returns success but the order record is never created.", "handling": "Trace the correlation ID across gateway, service, event bus and database. Check webhook delivery, retries and dead-letter queues, and reconcile the financial effect before retrying."}, {"path": "Data differs across layers", "trigger": "The screen shows one value, the API payload carries another, and the database holds a third.", "handling": "Trace one record by its stable identifier through UI, payload, transformation, service logs and database write. Compare field by field to find the first point of divergence."}, {"path": "Breaking schema change", "trigger": "A new API version renames a field that an existing consumer still expects.", "handling": "Use explicit versioning and a compatibility policy. Keep the old field during an agreed deprecation period, run contract tests, and assess consumer impact before release."}, {"path": "Webhook lost or duplicated", "trigger": "A status webhook never arrives, or arrives twice.", "handling": "Never rely on webhooks alone. Use the status enquiry API to resolve uncertain payments, and make webhook consumers idempotent so a duplicate delivery has no second effect."}], "technical_data": "Keep a consumer inventory and a schema registry so every consumer of every field is known. Use explicit API versioning, prefer additive changes, and run contract tests on every release. Persist the idempotency key, payload hash, payment reference and outcome for every request, with a defined retention period. Sign webhooks, verify signatures, and make consumers idempotent by event ID. Log requests and responses with correlation IDs and masked sensitive data. Define field lineage from the user interface through the API payload, transformation, service and database, so a value difference can be traced to its first divergence. Use decimal precision rules that match the currency, and record timezones explicitly on every timestamp.", "messages_fields": [{"message": "Payment initiation request", "purpose": "Northgate request to the bank payment API.", "key_fields": ["Order ID", "Idempotency key", "Debtor and creditor details", "Amount, currency and value date", "End-to-end ID"]}, {"message": "Payment status webhook", "purpose": "Asynchronous notification of the payment outcome.", "key_fields": ["Event ID and event type", "Payment reference", "Order ID", "New status and timestamp", "Signature for verification"]}, {"message": "pacs.008", "purpose": "Customer payment message for the underlying transfer where the API routes through a bank rail.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected"]}], "accounting_operational": "Each order must map to exactly one payment, and each payment must map to exactly one order. Finance reconciles API payments against orders and settlements daily, and unmatched items go to a worklist with an owner. A duplicate webhook or a retried request must never create a second order or a second debit. Failed webhooks sit in a dead-letter queue with an age and an owner, and aged items escalate. API downtime or degraded service is handled under the agreed service level, with a customer message and a recovery plan that resolves uncertain payments through status enquiry rather than blind retry.", "gherkin": ["Given the API accepted a request but the downstream record is absent, When the team traces the payment, Then the same correlation ID is followed across each integration boundary and the failed transition is identified.", "Given a field differs across UI, API and database, When the team traces the same record ID layer by layer, Then the first point of divergence is evidenced and assigned for correction.", "Given a breaking schema change is proposed, When compatibility assessment identifies active consumers, Then migration and versioning are agreed before release."], "assessment": [{"question": "What does an HTTP 202 response from a payment API normally mean?", "options": ["The payment completed.", "The order was created.", "The request was accepted for processing, and the final outcome must be confirmed separately.", "The beneficiary was credited."], "answer": 2, "explanation": "202 means acceptance, not completion. The outcome arrives through a webhook, event or status enquiry."}, {"question": "A webhook arrives twice for the same payment. What should happen?", "options": ["Refund the payment.", "Process it idempotently so the second delivery has no additional effect.", "Ignore both deliveries.", "Create the order twice."], "answer": 1, "explanation": "Webhook consumers must be idempotent by event ID so duplicate delivery is harmless."}, {"question": "The screen, the API payload and the database show three different values for one field. How do you find the cause?", "options": ["Restart the API.", "Trace the same record ID layer by layer and compare values to find the first point of divergence.", "Change the database to match the screen.", "Guess which one is right."], "answer": 1, "explanation": "Field lineage tracing finds where the value first changed, whether in mapping, transformation, caching or a stale read."}, {"question": "How should a breaking API field rename be managed?", "options": ["Rename it and tell consumers afterwards.", "Rename it only in the documentation.", "Use versioning, keep the old field during an agreed deprecation period, assess consumer impact and run contract tests.", "Never rename a field."], "answer": 2, "explanation": "Versioning and a deprecation window protect existing consumers, and contract tests catch breaks before release."}]}}, {"id": "INS-031", "kind": "insight", "title": "End-to-end credit card transaction flow", "topic": "End-to-end credit card transaction flow", "theme": "Cards", "text": "Trace authorisation, clearing, billing/settlement and dispute touchpoints.", "domain": "Cards & Merchant Payments", "area": "Cards & Merchant Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch63s7", "title": "ATM Cash Withdrawals, the SEPA Cards Framework, Clearing and Settlement", "url": "lessons/ch63s7"}, "case": {"status": "authored", "business_problem": "A customer of Meridian Bank buys a laptop for EUR 1,200 at Northgate Retail using a Meridian credit card. The terminal shows the payment as approved, the customer leaves with the laptop, and Northgate expects the funds in its account. Two days later, Northgate's finance team cannot match the sale to a settlement, and the customer sees a pending authorisation on the card statement but no completed charge.\n\nThe confusion comes from treating authorisation, clearing, billing and settlement as one event. Authorisation only reserves funds and checks the card. Clearing moves the transaction record to the scheme and the issuer. Settlement moves the money. Billing shows the charge to the cardholder. The learner must trace the transaction through each touchpoint and explain where it can stall, what each party sees, and how a dispute would be handled.", "decision_exercise": {"scenario": "A EUR 1,200 card purchase shows as approved at the terminal, but two days later the merchant cannot match the sale to a settlement and the cardholder sees only a pending authorisation. What is the most likely situation and the right first step?", "options": [{"id": "A", "text": "The payment failed, so the merchant should ask the customer to pay again."}, {"id": "B", "text": "Authorisation succeeded but clearing or settlement has not yet completed or reconciled, so trace the transaction by its authorisation code and transaction reference through the acquirer, scheme and issuer records before acting."}, {"id": "C", "text": "The merchant should write off the sale."}, {"id": "D", "text": "The cardholder should be charged again by the issuer."}], "correct_option": "B", "why": "Option B is correct because an approved authorisation is only the first stage. Clearing and settlement follow, and a mismatch is usually a timing or reconciliation break, not proof of failure. Option A risks double charging the customer. Option D duplicates the charge. Option C gives up a valid sale without evidence."}, "recommended_solution": "Teach the card flow as four distinct stages with different owners and different evidence. Authorisation happens in seconds: the terminal sends the card and transaction details to the acquirer, the scheme routes them to the issuer, and the issuer checks the card status, the available credit and fraud rules, then approves or declines and places a hold on the funds. The authorisation code is the key reference for everything that follows.\n\nClearing happens later, usually in batches. The merchant submits the approved transaction, the acquirer sends a clearing record through the scheme, and the issuer receives it and matches it to the authorisation. Settlement then moves the money: the issuer pays the scheme, the scheme pays the acquirer, and the acquirer credits the merchant, each less any agreed fees. Billing shows the completed charge on the cardholder statement once clearing has matched.\n\nWhen a transaction is missing from settlement, trace it by authorisation code, transaction reference and batch ID across the merchant, acquirer, scheme and issuer records. A duplicate clearing record must be deduplicated by its message identity so it creates no second charge. A delayed clearing acknowledgement must be handled by holding the transaction in an awaiting-clearing state, never by resubmitting it blindly. Disputes follow a separate path: the cardholder raises the dispute, the issuer investigates with the merchant evidence, and the outcome is a chargeback or a rejection of the dispute, each with its own accounting treatment.", "flow_steps": [{"step": 1, "actor": "Cardholder", "action": "Presents the card at the Northgate terminal for EUR 1,200", "system": "Point of sale terminal"}, {"step": 2, "actor": "Acquirer", "action": "Sends the authorisation request through the card scheme to the issuer", "system": "Acquirer host"}, {"step": 3, "actor": "Issuer", "action": "Checks the card, available credit and fraud rules, approves the transaction and places a hold", "system": "Issuer authorisation system"}, {"step": 4, "actor": "Merchant", "action": "Completes the sale and submits the transaction in the daily clearing batch", "system": "Merchant acquiring system"}, {"step": 5, "actor": "Card scheme", "action": "Routes the clearing record to the issuer and calculates settlement", "system": "Card scheme"}, {"step": 6, "actor": "Issuer", "action": "Matches the clearing record to the authorisation and confirms the charge", "system": "Issuer clearing system"}, {"step": 7, "actor": "Settlement", "action": "Moves funds from issuer to scheme to acquirer, less agreed fees", "system": "Settlement accounts"}, {"step": 8, "actor": "Acquirer and issuer", "action": "Credit the merchant account and show the completed charge on the cardholder statement", "system": "Merchant account and card billing"}], "happy_path": "Authorisation is approved in seconds with an authorisation code. The transaction clears in the daily batch, settlement completes for the expected net amount, the merchant is credited, and the cardholder statement shows the completed EUR 1,200 charge with the merchant name. The authorisation hold is replaced by the completed charge.", "negative_paths": [{"path": "Clearing acknowledgement delayed", "trigger": "The clearing record is submitted but no acknowledgement arrives in the expected window.", "handling": "Hold the transaction in an awaiting-clearing state, correlate by transaction reference, and investigate without blind resubmission."}, {"path": "Settlement amount differs", "trigger": "The settlement report shows a different amount from the submitted sale.", "handling": "Classify the difference as fees, partial settlement or error, reconcile at the correct level, and post adjustments only under approved rules."}, {"path": "Duplicate clearing record", "trigger": "The same clearing record arrives twice.", "handling": "Deduplicate by message and transaction identity, make clearing handling idempotent, and ensure no second charge or second merchant credit is created."}, {"path": "Cardholder dispute", "trigger": "The cardholder disputes the charge after the statement arrives.", "handling": "Raise a dispute case with the authorisation code, clearing evidence and merchant records, follow the scheme dispute process, and post any chargeback as a separate controlled transaction."}], "technical_data": "Use the authorisation code, transaction reference, card reference and batch ID as the stable tracing keys across merchant, acquirer, scheme and issuer. Keep authorisation, clearing and settlement as separate states with explicit transitions, and never treat an authorisation as proof of settlement. Make clearing and status handling idempotent by message identity so duplicate records create no second effect. Record the authorisation hold, its expiry, the cleared amount, fees and the settlement amount as separate data items. Validate card data handling, tokenisation and masking rules, and keep the full transaction trail for dispute and audit purposes. Reconcile authorisations against clearing records and clearing records against settlement reports daily.", "messages_fields": [{"message": "ISO 8583 authorisation request (0100)", "purpose": "Authorisation request from the acquirer through the scheme to the issuer.", "key_fields": ["Primary account number or token", "Transaction amount and currency", "Merchant identification", "Terminal and cardholder verification data"]}, {"message": "ISO 8583 authorisation response (0110)", "purpose": "Issuer decision on the authorisation request.", "key_fields": ["Response code, approved or declined", "Authorisation code", "Available balance or credit information where provided"]}, {"message": "Clearing record", "purpose": "Batch clearing record sent from the acquirer through the scheme to the issuer.", "key_fields": ["Transaction reference and authorisation code", "Cleared amount and currency", "Merchant and acquirer identification", "Batch ID and value date"]}, {"message": "Settlement report", "purpose": "Scheme settlement report used for reconciliation.", "key_fields": ["Settlement amount, gross and net", "Fees applied", "Value date", "Participant account identification"]}], "accounting_operational": "Authorisation places a hold on the cardholder's available credit without posting a completed charge. Clearing converts the hold into a posted charge: debit the cardholder account and credit the scheme settlement account. Settlement credits the merchant account for the net amount after fees, and fees are recorded as separate income lines. A duplicate clearing record must not create a second charge. A chargeback debits the merchant and credits the cardholder as a separate controlled transaction with its own reference. Operations reconciles authorisations to clearing records and clearing records to settlement reports daily, and unmatched items sit on a worklist with an owner and a service level.", "gherkin": ["Given a clearing record is submitted, When no acknowledgement arrives within the expected window, Then the transaction enters an awaiting-clearing state without duplicate submission.", "Given an identical clearing record is received twice, When the second copy is processed, Then no duplicate charge or merchant credit occurs.", "Given a settlement amount differs from the submitted sale, When reconciliation runs, Then the variance is classified and not auto-written off without policy approval."], "assessment": [{"question": "What does a card authorisation do?", "options": ["It credits the merchant.", "It creates the cardholder statement.", "It settles the payment immediately.", "It checks the card and reserves funds, but it does not by itself settle the payment."], "answer": 3, "explanation": "Authorisation approves and holds funds. Clearing and settlement follow as separate stages."}, {"question": "Why might a merchant not see a settlement two days after an approved sale?", "options": ["The sale was never authorised.", "Clearing or settlement may still be in progress, or the settlement may not have reconciled to the sale.", "The terminal was switched off.", "The cardholder has no money."], "answer": 1, "explanation": "Authorisation, clearing and settlement run on different cycles, and a reconciliation break can also delay matching."}, {"question": "The same clearing record arrives twice. What must happen?", "options": ["Deduplicate by message identity so only one charge and one merchant credit occur.", "Credit the merchant twice.", "Ignore both copies.", "Charge the cardholder twice."], "answer": 0, "explanation": "Idempotent clearing handling ensures duplicate delivery has no second financial effect."}, {"question": "A cardholder disputes a completed charge. What is the correct handling?", "options": ["Raise a dispute case with authorisation, clearing and merchant evidence, follow the scheme process, and post any chargeback as a separate controlled transaction.", "Ask the merchant to pay the cardholder directly.", "Refund immediately without evidence.", "Delete the transaction."], "answer": 0, "explanation": "Disputes follow a defined scheme process with evidence, and a chargeback is a separate transaction with its own reference."}]}}, {"id": "INS-032", "kind": "insight", "title": "Gateway success but core banking posting fails", "topic": "Gateway success but core banking posting fails", "theme": "Core banking", "text": "Investigate the gap between payment acceptance and core ledger posting; protect against duplicate processing.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s5", "title": "Ledger Posting versus Settlement", "url": "lessons/ch68s5"}, "case": {"status": "authored", "business_problem": "Meridian Bank's payment gateway returns a success response for a corporate customer's EUR 40,000 supplier payment, and the channel shows the payment as accepted. Hours later, the supplier has not been paid, the finance team finds no debit in the core banking ledger, and the payment engine still shows the payment as in progress. The gateway said yes, the ledger says nothing happened, and the customer wants to know whether to send the payment again.\n\nThe gap sits between acceptance and posting. The gateway accepted the instruction, but the posting to the core ledger failed, so the payment never reached clearing. The learner must investigate the gap without creating a duplicate payment, decide which system is authoritative for each fact, and design the recovery so the payment posts exactly once.", "decision_exercise": {"scenario": "The payment gateway returns success, but the core ledger has no debit and the supplier has not been paid. What should the analyst do first?", "options": [{"id": "A", "text": "Reverse a debit that does not exist."}, {"id": "B", "text": "Resubmit the payment from the gateway so the supplier is paid."}, {"id": "C", "text": "Treat the gateway response as acceptance only, verify the payment engine state and the ledger posting using the original references, place the payment in a controlled exception state, and recover the posting exactly once."}, {"id": "D", "text": "Tell the customer the payment succeeded because the gateway said so."}], "correct_option": "C", "why": "Option C is correct because gateway success proves acceptance, not posting or settlement, and the ledger is authoritative for whether a debit exists. Recovery must post exactly once. Option B risks a duplicate payment if the original later posts. Option D states a conclusion the ledger contradicts. Option A is impossible and shows the state was never checked."}, "recommended_solution": "Separate the three facts and find the authoritative source for each. The gateway is authoritative for acceptance of the instruction. The payment engine is authoritative for the processing state. The core ledger is authoritative for whether a debit posted. When they disagree, the payment goes into a controlled exception state and no retry is allowed until the disagreement is resolved.\n\nTrace the payment by its instruction ID, end-to-end ID and ledger posting reference across the gateway, the payment engine, the ledger adapter and the core ledger. Check the ledger adapter logs, the outbox and the transaction boundary: did the posting commit, did the status event fail, or did the posting never reach the ledger? If the posting never happened, replay the posting once using the original posting reference and idempotency controls. If the posting happened but the status event was lost, replay the status event idempotently without reposting the debit. If the posting failed for a business reason such as insufficient funds or an account restriction, move the payment to a rejected state with the reason code and notify the customer.\n\nProtect against the duplicate that a retry would create. Persist the idempotency key and payload hash at intake, and make the ledger adapter reject a second posting for the same posting reference. Reconcile the payment engine against the ledger on a scheduled cycle, and alert on any payment that stays in an inconsistent state beyond its threshold. Keep the customer informed with the true state, not with the gateway message alone.", "flow_steps": [{"step": 1, "actor": "Corporate customer", "action": "Submits a EUR 40,000 supplier payment through the corporate channel", "system": "Corporate banking channel"}, {"step": 2, "actor": "Gateway", "action": "Validates the instruction and returns a success response", "system": "Payment gateway"}, {"step": 3, "actor": "Payment engine", "action": "Creates the payment and sends the debit instruction to the ledger adapter", "system": "Payment engine"}, {"step": 4, "actor": "Ledger adapter", "action": "Attempts to post the debit to the core ledger", "system": "Ledger adapter"}, {"step": 5, "actor": "Core ledger", "action": "Posts the debit or returns a failure, with a posting reference on success", "system": "Core banking"}, {"step": 6, "actor": "Payment engine", "action": "Updates the payment state from the ledger outcome", "system": "Payment engine and status store"}, {"step": 7, "actor": "Operations analyst", "action": "Investigates the gap using the original references and places the payment in an exception state", "system": "Operations workbench"}, {"step": 8, "actor": "Payment engine", "action": "Recovers the posting exactly once, or rejects the payment with a reason, and notifies the customer", "system": "Payment engine and notification service"}], "happy_path": "The gateway accepts the instruction, the ledger posts the debit once, the payment engine records the posting reference, the payment proceeds to clearing, the supplier is credited, and the customer receives a confirmation that matches the ledger entry. No duplicate posting and no manual correction are needed.", "negative_paths": [{"path": "Posting never reached the ledger", "trigger": "The ledger adapter fails before the debit is posted, so the ledger has no record.", "handling": "Detect the gap by reconciling engine states against ledger postings. Replay the posting once with the original posting reference and idempotency controls."}, {"path": "Posting succeeded but status event lost", "trigger": "The debit posts but the payment engine never learns about it.", "handling": "Replay the status event idempotently from the outbox using the original posting reference. Do not repost the debit."}, {"path": "Duplicate retry creates a second payment", "trigger": "The customer resubmits the instruction after a slow gateway response.", "handling": "Return the original payment reference for the same idempotency key. If two distinct instructions arrive, duplicate detection routes the uncertain match for review."}, {"path": "Out-of-order status events", "trigger": "An older status event arrives after a newer state has been recorded.", "handling": "Version events and ignore any event older than the current state, so the payment state never regresses."}], "technical_data": "Define the transaction boundary explicitly: the ledger posting and the status publication must be recoverable as a unit, using the outbox pattern so a failed event can be replayed. Give every posting a unique posting ID that the ledger enforces, so a replay cannot create a second debit. Keep instruction ID, end-to-end ID, posting reference and correlation ID in separate fields with a documented lifecycle. Make status consumers idempotent and version events so out-of-order delivery cannot regress state. Log the gateway response, the adapter request, the ledger outcome and every state transition with timestamps. Reconcile the payment engine against the ledger on a scheduled cycle, with ageing thresholds and alerts for unresolved gaps. Never equate a gateway success response with a ledger posting or with settlement.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation from the channel to the gateway.", "key_fields": ["Instruction ID", "End-to-end ID", "Debtor and creditor accounts", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer payment sent to clearing once the ledger posting succeeds.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report from clearing, confirming acceptance or rejection.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected"]}, {"message": "camt.053", "purpose": "Bank-to-customer statement used as evidence for whether the debit posted.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Balance after the entry"]}, {"message": "camt.054", "purpose": "Bank-to-customer debit or credit notification, used as evidence for an individual posting.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Related payment reference"]}], "accounting_operational": "Debit the customer account once for EUR 40,000 and credit the settlement account, using the original posting reference. If the posting never happened, post it once as the recovery action. If the posting happened but the status was lost, post nothing further. If the payment is rejected for a business reason, no debit is posted and the customer is told the reason. Unresolved gateway-to-ledger gaps sit on an operations worklist with an owner, an age and a service level, and aged items escalate. Reconciliation between the payment engine and the ledger must prove that every accepted payment has exactly one posting, and every posting has a matching payment, before the day is closed.", "gherkin": ["Given a ledger posting exists but the status event is missing, When recovery runs, Then the payment state is updated using the original posting reference without reposting the debit.", "Given out-of-order status events, When an older event arrives after a newer state, Then the payment state does not regress.", "Given an already accepted instruction, When the identical request is retried with the same idempotency key, Then the platform returns the original payment reference and does not create a second debit."], "assessment": [{"question": "The gateway returns success. What does that prove?", "options": ["That the instruction was accepted by the gateway, not that the ledger posted or the payment settled.", "That the payment completed.", "That the ledger posted the debit.", "That the supplier was paid."], "answer": 0, "explanation": "Gateway success is acceptance. Posting and settlement are separate stages with their own evidence."}, {"question": "Which system is authoritative for whether a debit exists?", "options": ["The customer statement screen.", "The gateway.", "The channel.", "The core ledger."], "answer": 3, "explanation": "Only the ledger can prove a posting. Other systems show their own view of the payment state."}, {"question": "The debit posted but the status event was lost. How is it recovered?", "options": ["By replaying the status event idempotently using the original posting reference.", "By asking the customer to pay again.", "By deleting the payment.", "By posting the debit again."], "answer": 0, "explanation": "The money already moved, so only the status needs to be corrected, without a second debit."}, {"question": "How is a duplicate ledger posting prevented during recovery?", "options": ["By posting faster.", "By turning off the ledger.", "By trusting the operator to be careful.", "By giving every posting a unique posting ID that the ledger enforces, and by persisting the idempotency key."], "answer": 3, "explanation": "A unique posting ID enforced by the ledger makes a replay safe, and the idempotency key stops duplicate instructions."}]}}, {"id": "INS-033", "kind": "insight", "title": "Quantifying a 20,000-transaction reconciliation gap", "topic": "Quantifying a 20,000-transaction reconciliation gap", "theme": "Data reconciliation", "text": "Use the stated 500 unmatched transactions \u00d7 \u20b98,000 average as an illustrative \u20b940 lakh exposure, then validate transaction-level facts.", "domain": "Reconciliation & Accounting", "area": "Reconciliation & Accounting", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch40s5", "title": "Breaks: Suspense Accounts, Unmatched Transactions, Duplicates and Date Mismatches", "url": "lessons/ch40s5"}, "case": {"status": "authored", "business_problem": "Meridian Bank processes 20,000 transactions in a day across its payment channels. The morning reconciliation shows 500 transactions unmatched between the ledger and the clearing reports. At an average of INR 8,000 per transaction, the unmatched population represents an illustrative exposure of INR 40 lakh, calculated as 500 multiplied by INR 8,000. The finance director wants to know whether the bank has lost INR 40 lakh, and the operations manager wants to know how many of the 500 are real breaks and how many are timing differences.\n\nThe headline number is a starting point, not a conclusion. An unmatched item may be a payment that cleared a day late, a fee that was never disclosed, a duplicate posting, or a genuine missing payment. The learner must quantify the gap honestly, separate timing differences from true breaks, validate the facts at transaction level, and explain the exposure without overstating it.", "decision_exercise": {"scenario": "Meridian Bank has 500 unmatched transactions out of 20,000, averaging INR 8,000 each, an illustrative exposure of INR 40 lakh. The finance director asks whether the bank has lost INR 40 lakh. What is the correct response?", "options": [{"id": "A", "text": "Write off the INR 40 lakh so reconciliation balances."}, {"id": "B", "text": "No. Report the illustrative exposure, then classify each unmatched item as a timing difference, a fee or foreign exchange difference, a duplicate or an error, and validate at transaction level before stating any loss."}, {"id": "C", "text": "Yes, report a INR 40 lakh loss immediately."}, {"id": "D", "text": "Ignore the 500 because they are only 2.5 percent of the total."}], "correct_option": "B", "why": "Option B is correct because the INR 40 lakh is the value of the unmatched population, not a proven loss. Only transaction-level classification can say how much is timing, how much is explained, and how much is a real break. Option C overstates an unproven loss. Option D dismisses a material control signal. Option A hides the break instead of investigating it."}, "recommended_solution": "Quantify in layers, and never present an illustrative figure as a confirmed loss. First, state the population clearly: 20,000 transactions processed, 500 unmatched, an unmatched rate of 2.5 percent, and an illustrative exposure of INR 40 lakh based on 500 multiplied by an average of INR 8,000. State that the average is an assumption and that the real exposure must be calculated from the actual amounts of the unmatched items.\n\nSecond, classify every unmatched item by cause. Timing differences are items that will match when a late statement or a next-day clearing report arrives. Fee and foreign exchange differences are items where the settled amount differs for an explained reason. Duplicates are items posted twice. True breaks are items with no matching record on the other side, an unexplained amount difference, or a missing reference. Each class needs a different action, a different owner and a different ageing rule.\n\nThird, validate at transaction level. Reconcile using stable identifiers, amount, currency, date and participant references, and trace a sample of items from the ledger to the clearing report and back. Check control totals at each stage: record counts, gross amounts and net amounts. Fourth, act on the results: clear timing differences when their counterpart arrives, post explained differences only under approved accounting rules, reverse duplicates once, and investigate true breaks with a named owner and a deadline. Report the residual unexplained exposure separately from the illustrative total, and track the unmatched rate daily so a rising trend is caught early.", "flow_steps": [{"step": 1, "actor": "Payment engine", "action": "Processes 20,000 transactions and records each with its references", "system": "Payment engine"}, {"step": 2, "actor": "Core ledger", "action": "Posts the ledger entries for the day", "system": "Core banking"}, {"step": 3, "actor": "Clearing system", "action": "Produces clearing and settlement reports", "system": "Clearing system"}, {"step": 4, "actor": "Reconciliation engine", "action": "Matches ledger entries to clearing records by reference, amount, currency and date", "system": "Reconciliation engine"}, {"step": 5, "actor": "Reconciliation engine", "action": "Reports 500 unmatched items and calculates the illustrative exposure", "system": "Reconciliation engine"}, {"step": 6, "actor": "Operations analyst", "action": "Classifies each unmatched item as timing, fee, duplicate or true break", "system": "Operations workbench"}, {"step": 7, "actor": "Operations analyst", "action": "Traces a sample at transaction level and validates the classification", "system": "Operations workbench"}, {"step": 8, "actor": "Finance", "action": "Posts approved corrections, reports the residual unexplained exposure, and tracks the unmatched rate daily", "system": "Finance and reporting"}], "happy_path": "Reconciliation matches 19,500 transactions automatically. Of the 500 unmatched, most prove to be timing differences that match when the next clearing report arrives, a small number are explained fee differences, and only a handful are true breaks. Each true break is investigated, corrected once, and the residual unexplained exposure is reported as a small, specific figure with named owners, not as the illustrative INR 40 lakh.", "negative_paths": [{"path": "Late statement", "trigger": "The clearing report arrives late, so items appear unmatched at the morning run.", "handling": "Classify them as timing differences, hold them for the next report, and confirm they match before closing them."}, {"path": "Unexplained short settlement", "trigger": "The settled amount is less than expected with no disclosed fee.", "handling": "Classify as a true break, investigate with the clearing participant, and do not write it off without policy approval."}, {"path": "Duplicate posting", "trigger": "A payment is posted twice in the ledger.", "handling": "Identify the duplicate by reference and amount, reverse one posting once, and fix the control that allowed the duplicate."}, {"path": "Report totals wrong, source correct", "trigger": "Operational screens show correct transactions but the management report totals are wrong.", "handling": "Trace lineage from source through extraction, transformation and aggregation, reconcile control totals at each stage, and fix the stage that caused the variance."}], "technical_data": "Define reconciliation keys explicitly: instruction ID, end-to-end ID, transaction reference, amount, currency, value date and participant reference, with tolerances for fees and foreign exchange. Reconcile at record count, gross amount and net amount, and keep control totals at each stage of any reporting pipeline so a variance can be located. Classify breaks with a controlled set of categories, ageing rules and owners, and never auto-write off an unexplained item. Keep the original ledger entry and clearing record for every break, and record the investigation, the decision and the correction against the same case. Handle partial batches by giving each transaction an independent outcome, so a valid item is not held back by a failed one. Track the unmatched rate, the aged break count and the residual exposure as daily control measures.", "messages_fields": [{"message": "camt.053", "purpose": "Bank-to-customer statement used as the ledger-side evidence for reconciliation.", "key_fields": ["Account identification", "Entry amount, currency and value date", "Posting reference", "Balance after the entry"]}, {"message": "camt.054", "purpose": "Bank-to-customer debit or credit notification for individual entries.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Related payment reference"]}, {"message": "pacs.008", "purpose": "Customer payment message, used to trace an individual payment behind an unmatched item.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency"]}, {"message": "pain.002", "purpose": "Payment status report for a file or batch, used to check item-level outcomes in a partial batch failure.", "key_fields": ["File or batch reference", "Transaction-level status", "Reason code per rejected item"]}], "accounting_operational": "Debit and credit entries must match clearing reports for amount, currency and value date. Timing differences need no accounting correction, only monitoring until their counterpart arrives. Explained fee and foreign exchange differences are posted as separate lines under approved rules. Duplicate postings are reversed once, with the original reference and a documented reason. True breaks sit on a reconciliation worklist with an owner, an age and a service level, and no break is written off without policy approval. The illustrative INR 40 lakh exposure is reported as illustrative, and the residual unexplained exposure is reported separately once classification is complete. Daily reporting covers the unmatched count, the unmatched rate, aged breaks and residual exposure.", "gherkin": ["Given a ledger debit without a matching clearing record, When reconciliation runs, Then the item is classified as an unmatched break and assigned for investigation.", "Given a settlement amount differs from the expected amount, When reconciliation runs, Then the variance is classified and not auto-written off without policy approval.", "Given a partially valid file and partial processing enabled, When the file is processed, Then each transaction receives an independent outcome and only accepted transactions proceed."], "assessment": [{"question": "500 unmatched transactions average INR 8,000 each. What is the illustrative exposure?", "options": ["INR 8,000.", "INR 40 lakh.", "INR 400 lakh.", "INR 4 lakh."], "answer": 1, "explanation": "500 multiplied by INR 8,000 equals INR 40,00,000, which is INR 40 lakh. It is illustrative until validated at transaction level."}, {"question": "What is the difference between a timing difference and a true break?", "options": ["A timing difference is always a loss.", "A true break always matches the next day.", "There is no difference.", "A timing difference will match when a late report arrives; a true break has no matching record or an unexplained difference."], "answer": 3, "explanation": "Timing differences resolve with time and the missing counterpart. True breaks need investigation and correction."}, {"question": "Why must the INR 40 lakh not be reported as a loss?", "options": ["Because the total is wrong.", "Because it is too small.", "Because it is the value of the unmatched population based on an average, not a proven loss, and most items may be timing or explained differences.", "Because finance has not approved it."], "answer": 2, "explanation": "Only transaction-level classification can establish how much, if anything, is actually lost."}, {"question": "A settlement is short with no disclosed fee. What should happen?", "options": ["Ignore it.", "Write it off.", "Charge the customer.", "Classify it as a true break, investigate, and do not write it off without policy approval."], "answer": 3, "explanation": "An unexplained short settlement is a break. It needs investigation and approved treatment, never an automatic write-off."}]}}, {"id": "INS-034", "kind": "insight", "title": "Approved loan but disbursement fails", "topic": "Approved loan but disbursement fails", "theme": "Loan operations", "text": "Trace approval, account validation, disbursement instruction, ledger posting and customer communication.", "domain": "Banking Products", "area": "Banking Products", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s7", "title": "Exercise: Trace One Payment Through Every Possible Failure Scenario (one USD cross-border payment traced through reject, return, recall, duplicate, timeout and outage, with what happens at each step)", "url": "lessons/ch41s7"}}, {"id": "INS-035", "kind": "insight", "title": "Two banking systems show different balances", "topic": "Two banking systems show different balances", "theme": "Customer data", "text": "Trace source-of-truth, posting sequence, pending entries, replication and reconciliation.", "domain": "Data & Reconciliation", "area": "Data & Reconciliation", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch40s5", "title": "Breaks: Suspense Accounts, Unmatched Transactions, Duplicates and Date Mismatches", "url": "lessons/ch40s5"}, "case": {"status": "authored", "business_problem": "A customer of Meridian Bank checks the mobile app and sees a balance of EUR 4,120, then calls the contact centre, where the agent's screen shows EUR 3,850. The difference is EUR 270, exactly the amount of a card payment the customer made that morning. The customer believes the bank has taken money twice, and the agent cannot say which balance is right.\n\nThe two systems are showing different views of the same account at different points in the posting sequence. The mobile app may show the available balance after a pending authorisation, while the agent screen may show the ledger balance before the clearing record arrived, or one system may be reading stale replicated data. The learner must trace the source of truth, the posting sequence, pending entries and replication, and explain the difference without guessing.", "decision_exercise": {"scenario": "The mobile app shows EUR 4,120 and the contact centre screen shows EUR 3,850 for the same account, a difference of EUR 270 matching a card payment made that morning. What should the analyst do first?", "options": [{"id": "A", "text": "Tell the customer to check again tomorrow."}, {"id": "B", "text": "Tell the customer the higher balance is correct."}, {"id": "C", "text": "Adjust one system to match the other."}, {"id": "D", "text": "Identify which system is authoritative for each balance type, trace the EUR 270 payment through authorisation, posting and replication, and compare the same account at the same point in time."}], "correct_option": "D", "why": "Option D is correct because the two screens may show different balance types or different points in time, and only tracing the payment and naming the authoritative source can say which value is right. Option B picks a value without evidence. Option C changes data to hide the difference. Option A leaves the customer without an answer."}, "recommended_solution": "Start by defining what each balance means. The ledger balance is the posted balance in the core banking system, and it is authoritative for posted funds. The available balance is the ledger balance less pending authorisations and holds, and it is authoritative for what the customer can spend. A channel balance may be either of these, or a cached copy of one of them, and the screen must say which one it shows.\n\nTrace the EUR 270 payment through its full sequence. The card authorisation places a hold and reduces the available balance immediately, but it does not change the ledger balance until clearing posts the charge. If the mobile app shows the available balance and the agent screen shows the ledger balance, a EUR 270 difference is expected and correct, and the explanation is the pending authorisation, not an error. If both screens claim to show the same balance type, check replication: when was each copy last updated, did the posting event reach both systems, and is one system reading a stale cache?\n\nCheck the identifiers as well. An internal transaction ID reused with a different meaning can map the EUR 270 to the wrong account or the wrong payment, so confirm that the instruction ID, end-to-end ID and posting reference all point to the same transaction. If the difference is a genuine data defect, correct it once through a controlled process with an audit trail, and fix the replication or caching cause. If the difference is a timing or definition difference, explain it plainly to the customer and record the explanation against the case.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Makes a EUR 270 card payment in the morning", "system": "Point of sale terminal"}, {"step": 2, "actor": "Issuer", "action": "Authorises the payment and places a hold on the available balance", "system": "Issuer authorisation system"}, {"step": 3, "actor": "Mobile app", "action": "Shows the available balance of EUR 4,120 after the hold", "system": "Mobile banking"}, {"step": 4, "actor": "Contact centre", "action": "Shows the ledger balance of EUR 3,850 on the agent screen", "system": "Contact centre system"}, {"step": 5, "actor": "Analyst", "action": "Identifies the balance type each screen shows and the authoritative source for each", "system": "Operations workbench"}, {"step": 6, "actor": "Analyst", "action": "Traces the EUR 270 payment by its references through authorisation, clearing and replication", "system": "Operations workbench"}, {"step": 7, "actor": "Analyst", "action": "Determines whether the difference is a pending hold, a replication lag or a genuine defect", "system": "Operations workbench"}, {"step": 8, "actor": "Bank", "action": "Explains the correct balance to the customer, or corrects the defect once with an audit trail", "system": "Notification service and core banking"}], "happy_path": "The analyst finds the mobile app shows the available balance after the EUR 270 authorisation hold, while the agent screen shows the ledger balance before clearing. Both values are correct for their own definition. The customer receives a clear explanation, the clearing record posts later that day, both balances converge, and no correction is needed.", "negative_paths": [{"path": "Stale replicated data", "trigger": "One system reads a cached balance that has not been updated since the payment posted.", "handling": "Check the replication timestamp and the last event applied. Refresh the cache from the authoritative source and fix the replication lag."}, {"path": "Missing ledger posting", "trigger": "The payment cleared but the ledger posting is missing, so the ledger balance is wrong.", "handling": "Reconcile the payment engine against the ledger, replay the posting once with the original reference, and alert on the gap."}, {"path": "Identifier mapped to the wrong meaning", "trigger": "An internal ID is reused as the end-to-end reference, so the payment is matched to the wrong record.", "handling": "Maintain separate fields for internal ID, instruction ID, end-to-end ID and posting reference, and re-map the affected records correctly."}, {"path": "Report totals wrong, source correct", "trigger": "A management report shows a different balance from the operational screens.", "handling": "Trace lineage from the source through extraction and aggregation, reconcile control totals at each stage, and fix the stage that caused the variance."}], "technical_data": "Name the authoritative source for each data item: the core ledger for posted balances, the authorisation system for holds, and the payment engine for payment state. Define the balance types explicitly and label every screen with the type it shows. Record the posting sequence with timestamps so any two views can be compared at the same point in time. Use versioned, idempotent events for replication, and record the last applied event and timestamp on each replica so staleness is visible. Keep instruction ID, end-to-end ID, transaction ID and posting reference in separate fields with a documented meaning. Mask sensitive data in logs and support screens, and log every correction with its reason, approver and original values.", "messages_fields": [{"message": "camt.053", "purpose": "Bank-to-customer statement showing the posted ledger balance and entries.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Closing balance"]}, {"message": "camt.054", "purpose": "Bank-to-customer debit or credit notification for an individual posting.", "key_fields": ["Account identification", "Entry amount and value date", "Posting reference", "Related payment reference"]}, {"message": "pacs.002", "purpose": "Payment status report used to confirm the payment state behind a balance difference.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected"]}, {"message": "ISO 8583 authorisation response (0110)", "purpose": "Issuer decision that places the hold behind an available-balance difference.", "key_fields": ["Response code", "Authorisation code", "Authorised amount"]}], "accounting_operational": "The ledger balance is the accounting truth for posted funds, and the available balance is the ledger balance less pending holds. No balance may be adjusted to match another screen; a genuine defect is corrected once through a controlled process with a reason, an approver and an audit trail. Pending authorisations sit as holds, not as postings, and they expire under the agreed rules if clearing never arrives. Reconciliation between the ledger, the authorisation system and the channel balances runs on a scheduled cycle, and differences beyond tolerance go to a worklist with an owner and an ageing rule. Customer complaints about balances are answered with the specific payment, its state and its timestamp, not with a general assurance.", "gherkin": ["Given out-of-order status events, When an older event arrives after a newer state, Then the payment state does not regress.", "Given an instruction ID and end-to-end ID are both supplied, When the payment is mapped, Then each is placed in its correct semantic field.", "Given source transactions reconcile but report totals do not, When lineage is traced across transformations, Then the stage causing the variance is identified with reproducible evidence."], "assessment": [{"question": "What is the difference between a ledger balance and an available balance?", "options": ["They are the same.", "The available balance is always higher.", "The ledger balance is the posted balance; the available balance is the ledger balance less pending authorisations and holds.", "The ledger balance includes future payments."], "answer": 2, "explanation": "A pending authorisation reduces what the customer can spend without yet changing the posted ledger balance."}, {"question": "Two systems show different balances for the same account. What is the first question to ask?", "options": ["Which system is newer?", "Which system does the customer prefer?", "Which balance is higher?", "Which balance type does each screen show, and which system is authoritative for it?"], "answer": 3, "explanation": "Different balance types and different update times explain most differences. The authoritative source must be named before any value is judged."}, {"question": "A replica shows a stale balance. How is staleness detected?", "options": ["By asking the customer.", "By checking the replication timestamp and the last event applied against the authoritative source.", "By comparing it to another replica.", "By restarting the replica."], "answer": 1, "explanation": "A replica should record when it was last updated and which event it last applied, so lag is visible and measurable."}, {"question": "A genuine balance defect is found. How should it be corrected?", "options": ["By asking the customer to ignore it.", "By editing the screen to show the right number.", "By posting an offsetting entry without a reason.", "Once, through a controlled correction process with a reason, an approver and an audit trail, and by fixing the underlying cause."], "answer": 3, "explanation": "Corrections need a recorded reason and approval, and the cause must be fixed so the defect does not return."}]}}, {"id": "INS-036", "kind": "insight", "title": "Legacy-to-new customer data mismatch", "topic": "Legacy-to-new customer data mismatch", "theme": "Migration", "text": "Define mapping, transformation, control totals, exception handling and migration sign-off.", "domain": "Data & Integration", "area": "Data & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch38s3", "title": "Source-to-Target Mapping and Field Transformation", "url": "lessons/ch38s3"}, "case": {"status": "authored", "business_problem": "Meridian Bank is migrating customer data from a legacy core system to a new platform. During the first rehearsal, the migration report shows thousands of mismatches: names that do not match, addresses that cannot be placed into the new structured format, dates in different formats, and payment records whose beneficiary details are incomplete. The programme manager must decide whether the migration is safe to proceed, and the business analyst must define the mapping, the transformation rules, the control totals and the exception handling before the next rehearsal.\n\nThe risk is that the new platform goes live with wrong customer data, so payments fail validation, statements go to the wrong address, and screening misses a match. The risk in the other direction is that the team invents data to fill the gaps, for example by guessing address components or payment values that the legacy record never held. The migration must be proven correct before sign-off, not fixed after go-live.", "decision_exercise": {"scenario": "During a migration rehearsal, thousands of customer records mismatch between the legacy system and the new platform, including addresses that cannot be placed into the new structured format. What should the team do?", "options": [{"id": "A", "text": "Proceed to go-live and fix mismatches afterwards."}, {"id": "B", "text": "Stop, define the field mapping and transformation rules, run control totals, classify exceptions, fix the source data or the mapping, and require sign-off only when the residuals are understood and owned."}, {"id": "C", "text": "Migrate only the records that match and leave the rest behind without a record."}, {"id": "D", "text": "Guess the missing address components so the records pass validation."}], "correct_option": "B", "why": "Option B is correct because migration quality must be proven before go-live, and every exception needs a known cause, an owner and a planned treatment. Option A puts wrong data into production. Option D invents data the source never held. Option C loses customer records silently."}, "recommended_solution": "Define the migration as a controlled data movement with proof at every stage. Start with a field-level mapping from the legacy system to the new platform: every source field, its target field, its transformation rule, its validation rule and its owner. Where the target needs a value the source does not hold, do not fabricate it. Identify whether the value can be derived from trusted contextual data, such as a settlement arrangement or a correspondent relationship, document the derivation rule and its confidence, and hold the record for repair where no valid derivation exists.\n\nHandle addresses with particular care. The requirement is a structured or hybrid address with at least a town name and country code, or a BIC only where that is permitted, and the timeline for structured addresses has been extended, so no fixed cut-off date should be taught or used as a project deadline. Legacy free-text addresses that cannot be safely decomposed must follow an approved remediation or exception process, with customer outreach where the address is needed for payments. Never split a free-text address into structured components by guessing.\n\nRun control totals at each stage: record counts, total balances, and counts by customer type, so a lost or duplicated record is visible immediately. Classify exceptions by cause, age them, and assign owners. Run the migration in rehearsal, compare the new platform against the legacy system record by record for a sample and in full for control totals, and only sign off when the residual exceptions are listed, understood and owned, with a plan and a date for each. Keep the original legacy record for audit, and make the migration reversible until the new platform is proven in production.", "flow_steps": [{"step": 1, "actor": "Migration team", "action": "Defines the field-level mapping, transformation rules and validation rules", "system": "Mapping specification"}, {"step": 2, "actor": "Migration team", "action": "Extracts customer data from the legacy system with control totals", "system": "Legacy core system"}, {"step": 3, "actor": "Migration engine", "action": "Transforms the data to the new platform format, applying documented derivation rules only", "system": "Migration engine"}, {"step": 4, "actor": "Migration engine", "action": "Validates each record against the new platform rules and routes failures to exceptions", "system": "Validation service"}, {"step": 5, "actor": "Operations", "action": "Reviews exceptions, fixes source data or the mapping, and requests missing data from customers where needed", "system": "Exception workbench"}, {"step": 6, "actor": "Migration team", "action": "Loads the validated records into the new platform", "system": "New platform"}, {"step": 7, "actor": "Migration team", "action": "Reconciles record counts, balances and control totals between legacy and new systems", "system": "Reconciliation"}, {"step": 8, "actor": "Programme manager", "action": "Signs off only when residuals are listed, understood and owned, with a plan for each", "system": "Sign-off record"}], "happy_path": "The mapping is agreed, transformation rules are documented, and the rehearsal loads cleanly. Control totals match between the legacy system and the new platform, exceptions are few and each has an owner and a plan, structured addresses validate correctly, and sign-off is given with a short, named residual list. Go-live proceeds with the legacy record retained for audit.", "negative_paths": [{"path": "Mandatory target value missing from source", "trigger": "A legacy MT message or customer record lacks a value the new ISO 20022 message requires.", "handling": "Do not fabricate the value. Derive it only from trusted contextual data under a documented rule, or hold the payment or record for repair."}, {"path": "Structured address cannot be derived", "trigger": "A legacy free-text address cannot be safely split into structured components.", "handling": "Follow the approved remediation or exception process, seek the correct address from the customer where needed, and do not guess components."}, {"path": "Incomplete beneficiary data", "trigger": "A migrated payment record omits a beneficiary address required for a destination.", "handling": "Validate requirements by rail and destination, use trusted beneficiary data only where policy permits, and request correction before submission."}, {"path": "Control totals do not match", "trigger": "Record counts or balances differ between the legacy system and the new platform.", "handling": "Stop the load, find the stage where the totals diverged, and fix the mapping or the extraction before proceeding."}], "technical_data": "Maintain a source-to-target mapping with derivation rules, confidence levels, data provenance and negative tests. Keep the original legacy message and record for audit, and record the transformation applied to every field. Use control totals at extraction, transformation, validation and load, and reconcile them at each stage. Validate addresses against the structured or hybrid requirement, with town name and country code as the minimum, and never invent components. Handle character sets explicitly: apply documented transliteration only where permitted, preserve the original customer-provided value, and record the transformed value. Version the mapping, test it with representative and edge-case records, and make the migration reversible until production is proven.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer payment message in the new ISO 20022 format, produced from the legacy record.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor and creditor agents", "Structured or hybrid postal address, town name and country code as minimum", "Settlement amount and currency"]}, {"message": "pacs.009", "purpose": "Financial institution to financial institution payment, used for the cover or settlement leg where applicable.", "key_fields": ["Instruction ID", "Debtor agent and creditor agent", "Settlement amount and currency"]}, {"message": "MT103 to pacs.008 mapping", "purpose": "Legacy MT103 customer payment mapped to the ISO 20022 customer payment.", "key_fields": ["Sender and receiver references", "Ordering customer and beneficiary customer", "Amount and currency", "Remittance information"]}, {"message": "MT202 COV to pacs.009 mapping", "purpose": "Legacy MT202 COV cover payment mapped to the ISO 20022 financial institution payment.", "key_fields": ["Sender and receiver references", "Cover payment details", "Amount and currency", "Related underlying payment reference"]}], "accounting_operational": "Customer balances and payment records must reconcile between the legacy system and the new platform to the cent, with control totals for record counts and total balances. No balance may be adjusted to make totals match; a difference is an exception to be investigated. Migrated payment records that cannot be validated must not be submitted to clearing. Exceptions sit on a worklist with an owner, an age and a service level, and aged items escalate before go-live. The migration sign-off records the residual exceptions, their owners and their planned resolution dates, and the legacy system is retained until the new platform is proven in production.", "gherkin": ["Given a mandatory target field cannot be reliably derived, When transformation runs, Then the payment is held for repair rather than populated with an invented value.", "Given a legacy unstructured address cannot be safely decomposed, When a structured-address requirement applies, Then the payment follows the approved remediation or exception process.", "Given a destination requires a beneficiary address, When the submitted instruction omits it, Then the API returns a specific validation error and does not create a payment."], "assessment": [{"question": "A target ISO 20022 field has no value in the legacy source. What should happen?", "options": ["Derive it only from trusted contextual data under a documented rule, or hold the record for repair.", "Leave the field blank and send the payment.", "Invent a plausible value.", "Copy a value from another record."], "answer": 0, "explanation": "A mandatory value must never be fabricated. It is derived only where a documented rule allows it, or the record is held."}, {"question": "What is the minimum for a structured or hybrid address?", "options": ["A full street address.", "Town name and country code, or a BIC only where permitted.", "A postcode only.", "A country name only."], "answer": 1, "explanation": "The requirement is a structured or hybrid address with at least town name and country code, or a BIC only where that is permitted."}, {"question": "How is migration quality proven before sign-off?", "options": ["By the number of records loaded.", "By testing one record.", "By control totals at each stage, record-by-record comparison, and a listed, owned residual exception list.", "By the project deadline."], "answer": 2, "explanation": "Control totals, comparison and a named residual list prove the migration. Volume alone proves nothing."}, {"question": "A legacy free-text address cannot be safely split into structured parts. What is correct?", "options": ["Split it by guessing the town and street.", "Use the head office address.", "Follow the approved remediation or exception process and seek the correct address where needed.", "Drop the address."], "answer": 2, "explanation": "Guessing address components invents data. The approved remediation process protects the customer and the payment."}]}}, {"id": "INS-037", "kind": "insight", "title": "Business process change just before UAT", "topic": "Business process change just before UAT", "theme": "Release management", "text": "Assess requirement impact, test scope, release risk and decision rights.", "domain": "Release Management", "area": "Release Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s6", "title": "Test strategy for payments: SIT, UAT, negative testing and the test pack", "url": "lessons/ch84s6"}}, {"id": "INS-038", "kind": "insight", "title": "Stakeholder changes requirements every week", "topic": "Stakeholder changes requirements every week", "theme": "Scope control", "text": "Set change intake, impact analysis, prioritisation and decision governance.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch45s6", "title": "Scheme Changes, Regulatory Change and Product Impact", "url": "lessons/ch45s6"}}, {"id": "INS-039", "kind": "insight", "title": "Business wants two weeks; development estimates six", "topic": "Business wants two weeks; development estimates six", "theme": "Feasibility", "text": "Clarify minimum outcome, options, scope slicing, dependencies and evidence-based trade-offs.", "domain": "Agile Delivery", "area": "Agile Delivery", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch83s5", "title": "Build versus buy: the decision framework for payment technology", "url": "lessons/ch83s5"}}, {"id": "INS-040", "kind": "insight", "title": "Change affects multiple applications and teams", "topic": "Change affects multiple applications and teams", "theme": "Impact analysis", "text": "Trace upstream/downstream systems, data, interfaces, controls, tests, operations and release dependencies.", "domain": "Architecture & Change", "area": "Architecture & Change", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch79s6", "title": "Microservices for payments: service boundaries and data ownership", "url": "lessons/ch79s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank must change its instant euro payments to match the current scheme rules: there is no longer a scheme-level maximum amount for SCT Inst, execution must complete within 10 seconds, and verification of payee is mandatory for instant euro payments. The change touches the mobile app, the payment engine, the sanctions and fraud services, the clearing adapter, the ledger, the customer notification service, the reconciliation process and the contact centre scripts. Each team sees only its own part, and nobody has yet mapped the full impact.\n\nWithout a proper impact analysis, the bank could release a change that lets a large payment through without a limit check, or that fails verification of payee for a valid beneficiary, or that breaks a downstream consumer that still expects the old maximum. The learner must trace the change upstream and downstream across systems, data, interfaces, controls, tests, operations and release dependencies, and produce a plan that every team can work from.", "decision_exercise": {"scenario": "Meridian Bank must remove the SCT Inst scheme maximum, meet the 10-second execution limit, and make verification of payee mandatory. The change touches many applications and teams. What is the best first step?", "options": [{"id": "A", "text": "Ask each team to make its own change and coordinate at go-live."}, {"id": "B", "text": "Release the change to one channel and see what breaks."}, {"id": "C", "text": "Trace the change upstream and downstream across systems, data, interfaces, controls, tests, operations and release dependencies, and agree the sequencing, the versioning and the rollback plan before any team builds."}, {"id": "D", "text": "Change the payment engine only, since that is where the limit lives."}], "correct_option": "C", "why": "Option C is correct because a change that crosses many systems can only be delivered safely when its full impact is mapped and its sequencing and rollback are agreed first. Option A leaves integration to chance. Option D ignores the channel, screening, ledger and reconciliation impacts. Option B uses production customers as the test."}, "recommended_solution": "Build the impact analysis as a map, not as a list of opinions. Start from the change and walk upstream: which channels, products and customer journeys can submit an instant euro payment, which limits and validations apply today, and which of those must change? Then walk downstream: the payment engine, fraud and sanctions checks, verification of payee, routing, the clearing adapter, the ledger, notifications, reconciliation and reporting. For each system, record what changes, what stays the same, and what breaks if the change is made without it.\n\nCover data and interfaces explicitly. The removal of the scheme maximum does not mean the bank has no limits: bank-level limits, customer limits and fraud thresholds still apply and must be reviewed. Verification of payee adds a new check with its own data, timing and failure handling, and its result must be recorded against the payment. Any interface that carried the old maximum, or that assumed a maximum existed, must be found through a consumer inventory, and breaking changes must be versioned with a deprecation period and contract tests.\n\nCover controls, tests, operations and release. Map the dependencies between checks: independent checks can run in parallel to protect the 10-second execution limit, while checks that depend on another result must stay sequential. Define the timeout budget for each check and the fail-open or fail-closed policy. Plan tests end to end, not per system, including a large-value payment, a verification of payee mismatch, a timeout in one check, and a downstream consumer still on the old version. Plan the release order, the rollback for each step, the operational staffing, the reconciliation checks after go-live, and the customer communication. No team builds until the map, the sequencing and the rollback are agreed.", "flow_steps": [{"step": 1, "actor": "Business analyst", "action": "Documents the scheme change and its business intent", "system": "Change request"}, {"step": 2, "actor": "Business analyst", "action": "Traces the change upstream to channels, products and customer journeys", "system": "Impact map"}, {"step": 3, "actor": "Business analyst", "action": "Traces the change downstream through engine, screening, verification of payee, clearing, ledger and reconciliation", "system": "Impact map"}, {"step": 4, "actor": "Architecture", "action": "Maps data and interface impacts, consumer inventory and versioning needs", "system": "Interface catalogue"}, {"step": 5, "actor": "Engineering", "action": "Agrees sequencing, timeout budgets, parallel and sequential controls, and the rollback plan", "system": "Design record"}, {"step": 6, "actor": "Testing", "action": "Runs end-to-end tests for large values, verification mismatches, timeouts and old-version consumers", "system": "Test environment"}, {"step": 7, "actor": "Operations", "action": "Prepares staffing, monitoring, reconciliation checks and customer communication", "system": "Release plan"}, {"step": 8, "actor": "Release manager", "action": "Releases in the agreed order, verifies each step, and rolls back if a check fails", "system": "Release management"}], "happy_path": "The impact map is agreed, every consumer of the old maximum is found and migrated, verification of payee is built with clear failure handling, and end-to-end tests pass for large values, mismatches and timeouts. The release runs in order, reconciliation confirms the first day of live payments, and customers experience faster, verified instant payments with no broken channel.", "negative_paths": [{"path": "Unknown downstream consumer", "trigger": "A consumer still expects the old maximum and rejects large payments.", "handling": "Maintain a consumer inventory and contract tests. Version the change, keep the old behaviour during an agreed deprecation period, and assess impact before release."}, {"path": "One control times out", "trigger": "A screening or verification check exceeds its budget and the 10-second execution limit is at risk.", "handling": "Define timeout budgets and a fail-open or fail-closed policy per check. Run independent checks in parallel and keep dependent checks sequential."}, {"path": "Late negative result after release", "trigger": "A check returns a negative result after the payment has already been released.", "handling": "Never release before all mandatory decisions are recorded. Define the aggregation rule and the handling for late results in the design."}, {"path": "Character encoding changes a name", "trigger": "A beneficiary name contains characters a downstream rail or legacy interface does not support.", "handling": "Apply documented character-set rules and transliteration only where permitted, preserve the original value, and record the transformation."}], "technical_data": "Keep a consumer inventory and a schema registry so every consumer of every changed field is known. Use explicit versioning, prefer additive evolution, and run contract tests on every release. Map the dependency graph between controls: independent checks run in parallel, dependent checks stay sequential, and the release waits for all mandatory decisions. Define timeout budgets that fit inside the 10-second execution limit, with a fail-open or fail-closed policy per check. Record the verification of payee result, the limit applied and the decision for every payment, with correlation IDs across all systems. Preserve the original beneficiary name alongside any transformed value, and apply documented character-set rules only. Log every decision with its timestamp for audit.", "messages_fields": [{"message": "pacs.008", "purpose": "Instant customer payment sent through clearing, now without a scheme-level maximum.", "key_fields": ["Instruction ID and end-to-end ID", "Debtor agent and creditor agent", "Settlement amount and currency, with no scheme cap applied", "Remittance information"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection within the execution window.", "key_fields": ["Original instruction ID", "Status code", "Reason code where rejected", "Status timestamp"]}, {"message": "Verification of payee request", "purpose": "Request to verify the beneficiary name against the account before release.", "key_fields": ["Creditor account identification", "Creditor name as supplied", "Match outcome, match, close match or no match", "Verification timestamp"]}, {"message": "Gateway webhook event", "purpose": "Asynchronous notification of the payment outcome to downstream consumers.", "key_fields": ["Event ID and event type", "Payment reference", "New payment status and timestamp", "Signature for verification"]}], "accounting_operational": "Removing the scheme maximum does not remove bank-level or customer-level limits, and those limits must be reviewed and recorded before go-live. Large-value instant payments need liquidity and settlement monitoring, and operations must be able to see them on a worklist with an owner. Verification of payee mismatches go to a controlled exception queue with a service level, never to an automatic release or an automatic rejection without a defined rule. Reconciliation after go-live must confirm that payments, ledger postings and clearing reports agree for the new flow, including large values. Any rollback must return each system to a consistent state, with no payment left half-released.", "gherkin": ["Given independent controls, When orchestration begins, Then they execute concurrently while release waits for all mandatory decisions.", "Given a breaking schema change is proposed, When compatibility assessment identifies active consumers, Then migration and versioning are agreed before release.", "Given a name contains unsupported characters, When mapping to a rail-specific format, Then the approved transformation or exception policy is applied and the original value is retained."], "assessment": [{"question": "What is the SCT Inst scheme maximum now?", "options": ["EUR 1 million.", "EUR 100,000.", "There is no scheme-level maximum now; the EUR 100,000 cap was removed.", "EUR 10,000."], "answer": 2, "explanation": "The EPC SCT Inst Rulebook 2025 removed the EUR 100,000 scheme maximum. Bank-level and customer-level limits still apply."}, {"question": "What is the maximum execution time for an instant euro payment?", "options": ["60 seconds.", "One business day.", "10 seconds.", "10 minutes."], "answer": 2, "explanation": "Regulation (EU) 2024/886 sets maximum execution at 10 seconds, with sub-timelines of 5, 7 and 9 seconds."}, {"question": "Which checks can safely run in parallel?", "options": ["All checks.", "Independent checks whose results do not depend on each other; dependent checks must stay sequential.", "Only fraud checks.", "None, all checks must be sequential."], "answer": 1, "explanation": "Parallel execution is safe only where no check needs another check result or enrichment first."}, {"question": "A downstream consumer still expects the old maximum. How is it handled?", "options": ["Find it through the consumer inventory, version the change, run contract tests, and agree migration before release.", "Ignore it.", "Remove the consumer.", "Change the consumer without telling it."], "answer": 0, "explanation": "A consumer inventory and versioning protect unknown or unready consumers from a breaking change."}]}}, {"id": "INS-041", "kind": "insight", "title": "User rejects feature built to signed-off requirements", "topic": "User rejects feature built to signed-off requirements", "theme": "UAT acceptance", "text": "Determine whether the issue is a defect, ambiguity, missed need or scope change.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s7", "title": "Exercise: Build a UAT Pack for a pacs.008 Change", "url": "lessons/ch42s7"}}, {"id": "INS-042", "kind": "insight", "title": "Designing discovery for a new product", "topic": "Designing discovery for a new product", "theme": "Product discovery", "text": "Define target users, problem statement, hypotheses, constraints, MVP and success metrics.", "domain": "Product Management", "area": "Product Management", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s7", "title": "Measuring product success: SLAs, KPIs and the numbers that matter", "url": "lessons/ch82s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank wants to launch an instant payment product for small business customers, and the product sponsor has asked the team to make payments faster. The request has no named user group, no baseline, no target speed and no statement of the problem customers actually face today. Small businesses currently pay suppliers through standard credit transfers that arrive later in the day, and some use card payments that carry higher fees, but nobody has measured how often a slow payment causes a real business cost such as a missed supplier discount or a delayed shipment. The bank already offers instant euro payments under the SCT Inst scheme, which has no scheme-level maximum amount since the 2025 rulebook change and must complete within 10 seconds, with Verification of Payee mandatory for instant euro payments from 9 October 2025. Those scheme facts shape what is technically possible, but they do not tell the team which customers need the product or what success looks like.\n\nThe discovery team has six weeks before the funding decision and must produce a recommendation the investment committee can trust. The team includes a business analyst, a product manager, a payments architect and an operations lead, and each of them holds a different view of what faster means. The architect wants to expose the existing instant rail through an API, the operations lead worries about fraud screening inside a 10-second window, and the sponsor wants a launch date. Without a disciplined discovery phase the bank risks building a technically correct product that solves nobody's urgent problem, or promising a speed the fraud and screening controls cannot support. The case asks the learner to run discovery properly: define target users, state the problem, form testable hypotheses, record constraints, define a minimum viable product and agree success metrics before any build commitment is made.", "decision_exercise": {"scenario": "Meridian Bank has six weeks of discovery time for a new instant payment product for small businesses. The sponsor wants faster payments but has not defined the user, the problem or the success measure. You are the business analyst and must recommend what discovery should deliver before the funding decision.", "options": [{"id": "A", "text": "Interview only the sponsor and the architect, then write requirements from their combined view of what faster means."}, {"id": "B", "text": "Skip discovery and start building an instant payment API, since the SCT Inst rail already exists and speed is the obvious requirement."}, {"id": "C", "text": "Promise a 10-second end-to-end payment for every customer and every amount, then design fraud controls afterwards."}, {"id": "D", "text": "Run structured discovery: define target users, state the problem, test hypotheses with evidence, record constraints, define the MVP and agree measurable success metrics."}], "correct_option": "D", "why": "Option D is correct because discovery exists to turn a vague goal into a testable, measurable product decision. Option B builds before knowing who benefits or what success means. Option A relies on two internal opinions and ignores customers, operations and risk. Option C commits to a speed target before checking whether screening, Verification of Payee and fraud controls can fit inside the 10-second execution window."}, "recommended_solution": "Start by naming the target users precisely, for example small businesses that pay domestic suppliers on fixed weekly cycles, and exclude segments the product will not serve in the first release. Write a problem statement in the form of who suffers, what it costs them, and how often, then gather evidence: payment volumes, current settlement times, supplier discount losses, and support contacts about late payments. Form hypotheses that can be tested, such as that suppliers offer early payment discounts that customers miss because standard transfers arrive too late, and test each one with data or customer interviews rather than opinion.\n\nMap the current journey from payment initiation to supplier receipt, mark every wait, manual step and failure point, and record the baseline: median and worst-case times, failure rates and costs. Then define the target state in measurable terms, for example 95 percent of eligible instant payments completed within 10 seconds with a defined fraud-screening pass rate, and state which rails, currencies, channels, amounts and customer segments are in scope. Record constraints explicitly: the 10-second SCT Inst execution limit, mandatory Verification of Payee, fraud and sanctions screening, cut-offs, and the fact that PSD2 remains the law in force while PSD3 is not law. Finally define the MVP as the smallest release that proves the value hypothesis, list what is deliberately excluded, and agree success metrics, owners and the evidence the investment committee will see at the funding gate.", "flow_steps": [{"step": 1, "actor": "Product Manager", "action": "Sponsor discovery kick-off and agree decision date and funding gate", "system": "Discovery workspace"}, {"step": 2, "actor": "Business Analyst", "action": "Define target user segments and draft problem statement with evidence sources", "system": "Discovery workspace"}, {"step": 3, "actor": "Business Analyst", "action": "Interview small business customers and map current payment journey", "system": "Journey mapping tool"}, {"step": 4, "actor": "Payments Architect", "action": "Document rail capabilities, SCT Inst 10-second limit and Verification of Payee requirement", "system": "Architecture repository"}, {"step": 5, "actor": "Operations Lead", "action": "Quantify current failure rates, manual work and support contacts", "system": "Operations reporting"}, {"step": 6, "actor": "Business Analyst", "action": "Draft testable hypotheses and agree success metrics with sponsor and risk", "system": "Discovery workspace"}, {"step": 7, "actor": "Product Manager", "action": "Define MVP scope and exclusions and present recommendation to investment committee", "system": "Investment committee pack"}], "happy_path": "Discovery ends with a signed-off problem statement, an evidence-backed hypothesis set, a measured baseline, a measurable target, an agreed MVP scope with exclusions, and success metrics with owners. The investment committee funds the MVP knowing which customers it serves, what it must achieve, and which constraints bound the design.", "negative_paths": [{"path": "Stakeholders disagree on what faster means", "trigger": "The sponsor, architect and operations lead each define speed differently.", "handling": "Facilitate a workshop that anchors faster to a measured customer outcome and a numeric target, and record dissent and the decision."}, {"path": "Speed conflicts with fraud controls", "trigger": "Screening and Verification of Payee cannot fit inside the 10-second window for some payments.", "handling": "Define which payments are eligible for instant execution, which route to a slower rail, and how the customer is told before submission."}, {"path": "No customer evidence supports the hypothesis", "trigger": "Interviews and data show late payments rarely cost customers money.", "handling": "Report the finding honestly, recommend stopping or pivoting the product, and do not manufacture a business case."}, {"path": "Scheme rule changes mid-discovery", "trigger": "A rulebook update changes a limit, deadline or mandatory field.", "handling": "Run rule impact analysis across channels, validation and operations, and re-baseline the target before the funding decision."}], "technical_data": "Keep a single discovery record with traceability from problem statement to hypothesis to evidence to requirement. Store baseline measurements with their source, date and query so they can be re-run. Version the scope and exclusions, and record every assumption with an owner and a validation date. Do not store customer interview notes with personal data beyond what is needed, and keep the decision log as the audit trail for the funding gate.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment initiation captured during journey mapping and MVP scoping", "key_fields": ["Instruction identification and end-to-end identification", "Debtor and creditor account and agent", "Amount and currency", "Remittance information for supplier reference"]}, {"message": "pacs.008", "purpose": "Instant credit transfer leg evaluated against SCT Inst rules during discovery", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Execution within the 10-second regulatory maximum", "Verification of Payee result"]}, {"message": "pacs.002", "purpose": "Payment status reporting used to measure success rates and failure causes", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "Discovery itself has no customer debit or credit, but the business case must quantify the financial effect of the target state: earlier supplier receipt, discount capture, reduced late-payment fees and lower manual handling. Operations must be staffed for the new failure modes, including payments rejected by Verification of Payee and payments that exceed the instant window and fall back to another rail. Define the worklists, service levels and reconciliation points for those exceptions before the build starts, so the MVP launch does not create an unstaffed queue.", "gherkin": ["Given a vague objective to make payments faster,", "When discovery is complete,", "Then an agreed measurable target and the in-scope payment journeys are documented.", "Given a hypothesis about missed supplier discounts,", "When customer evidence is gathered,", "Then the hypothesis is confirmed, refuted or revised with named evidence.", "Given the 10-second SCT Inst execution limit,", "When the target state is defined,", "Then fraud screening and Verification of Payee steps are shown to fit inside the limit or the payment is routed elsewhere."], "assessment": [{"question": "What is the first thing discovery must produce for a vague product request?", "options": ["A vendor shortlist", "A measurable problem statement with named target users", "A build plan", "A launch date"], "answer": 1, "explanation": "Discovery must first establish who suffers, what it costs and how often, otherwise every later decision rests on an untested assumption."}, {"question": "Under the current SCT Inst rules, which statement about the scheme maximum is correct?", "options": ["The scheme maximum is EUR 100,000", "There is no scheme-level maximum since the 2025 rulebook change", "The maximum depends on the customer segment", "The maximum is EUR 50,000"], "answer": 1, "explanation": "The EUR 100,000 scheme maximum was removed by the EPC SCT Inst Rulebook 2025, effective 5 October 2025, so no scheme-level maximum now applies."}, {"question": "Why must Verification of Payee be part of the discovery constraints?", "options": ["It only applies to direct debits", "It is optional for instant payments", "It replaces fraud screening", "It is mandatory for instant euro payments from 9 October 2025 and affects the 10-second journey"], "answer": 3, "explanation": "Verification of Payee is mandatory for instant euro payments from 9 October 2025, so the journey, timing and failure handling must include it."}, {"question": "What should the team do if customer evidence refutes the core hypothesis?", "options": ["Build the product anyway", "Hide the evidence from the investment committee", "Interview only supportive customers", "Report the finding honestly and recommend stopping or pivoting"], "answer": 3, "explanation": "Discovery exists to test hypotheses with evidence, and a refuted hypothesis is a valid outcome that prevents wasted build spend."}]}}, {"id": "INS-043", "kind": "insight", "title": "Optimising an inefficient legacy process", "topic": "Optimising an inefficient legacy process", "theme": "Process improvement", "text": "Map AS-IS, quantify pain points, design TO-BE and validate controls and operational impacts.", "domain": "Process Design", "area": "Process Design", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s2", "title": "Business Process Modelling: As-Is and To-Be Flows", "url": "lessons/ch28s2"}, "case": {"status": "authored", "business_problem": "Aldergate Bank runs a legacy supplier payment process that has grown by accretion over a decade. A corporate customer sends a payment file, operations staff print exception lists, re-key corrected details into three different screens, phone the customer for missing information, and then release the file late in the day. The process works, in the sense that most payments eventually leave, but it is slow, error-prone and expensive: re-keying introduces mistakes, nobody can say how long a file spends at each step, and the team cannot tell whether a delay comes from bad data, a system limit or a staffing gap. The head of operations has asked for the process to be optimised, but has not said which outcome matters most: faster release, fewer errors, lower cost, or better customer visibility.\n\nThe business analyst assigned to the work inherits a process nobody has mapped end to end. Each team describes only its own step, the documented procedure is three versions out of date, and two workarounds exist that nobody has written down. Meanwhile a recent client escalation complained that a changed process step disrupted the client's own operations, which shows that improvement work can make things worse if it is done without evidence. The learner must map the as-is process, quantify the pain with real measures, design a to-be process with controls that survive contact with real files, and validate the change with the people who run it and the customers who depend on it.", "decision_exercise": {"scenario": "Aldergate Bank's legacy supplier payment process is slow and error-prone, with re-keying across three screens and undocumented workarounds. The head of operations wants it optimised but has not prioritised speed, accuracy, cost or visibility. You are the business analyst asked to redesign it.", "options": [{"id": "A", "text": "Redesign the process from the documented procedure, since it is the official record of how the work should be done."}, {"id": "B", "text": "Remove the manual exception checks first to speed up release, and add controls later if errors rise."}, {"id": "C", "text": "Map the as-is process as actually performed, quantify pain at each step, design the to-be process with controls, and validate it with operators and customers."}, {"id": "D", "text": "Automate the current steps exactly as they are, because automation alone will remove the delays."}], "correct_option": "C", "why": "Option C is correct because improvement must start from the real process and measured pain, not from an outdated document. Option A designs around a procedure three versions out of date. Option D automates waste and undocumented workarounds. Option B removes controls before knowing which errors they catch, which trades speed for uncontrolled risk."}, "recommended_solution": "Begin by observing the work as performed, not as documented: follow real files from intake to release, time each step, and record every workaround, handoff and re-key. Quantify the pain with measures the business can compare: straight-through processing rate, repair rate by defect type, average and worst-case cycle time per step, rework hours, error rate after release, and customer contacts per file. Segment defects by root cause and source so the redesign fixes causes rather than symptoms, and identify which defects should be prevented at source through upstream validation instead of repaired downstream.\n\nDesign the to-be process around the measured bottlenecks: single capture with validation at source, no re-keying, itemised file outcomes, and a repair workbench with maker-checker control for sensitive changes. Keep the controls that the evidence shows actually catch errors, and remove only steps the data proves add no value. Validate the design with operators through a walkthrough of real files, and with customers through the changed touchpoints, including status visibility and repair requests. Pilot on a small volume, compare the same measures before and after, and only then roll out with training, updated procedures and a rollback plan.", "flow_steps": [{"step": 1, "actor": "Business Analyst", "action": "Observe live file processing and interview operators at each handoff", "system": "Process mapping tool"}, {"step": 2, "actor": "Operations Lead", "action": "Provide cycle time, repair and error measures for the last three months", "system": "Operations reporting"}, {"step": 3, "actor": "Business Analyst", "action": "Map as-is process with timings, workarounds and pain points", "system": "Process mapping tool"}, {"step": 4, "actor": "Business Analyst", "action": "Segment defects by root cause and prioritise fixes by impact", "system": "Defect analysis"}, {"step": 5, "actor": "Payments Architect", "action": "Design to-be process with single capture, validation and repair workbench", "system": "Architecture repository"}, {"step": 6, "actor": "Operations Lead", "action": "Walk through to-be design with operators using real files", "system": "Test environment"}, {"step": 7, "actor": "Business Analyst", "action": "Pilot to-be process, compare measures and report go or no-go", "system": "Pilot report"}], "happy_path": "The to-be process runs on a pilot volume with a higher straight-through processing rate, lower repair rate and shorter cycle time than the as-is baseline, measured on the same metrics. Operators confirm the new steps are workable, customers receive itemised outcomes and clear repair guidance, and the rollout proceeds with updated procedures and training.", "negative_paths": [{"path": "Client escalates that the change disrupted operations", "trigger": "A changed step makes a customer process harder or impossible.", "handling": "Acknowledge impact without defensiveness, establish facts and a workaround, name an owner and an update time, then investigate root cause separately from service recovery."}, {"path": "Automation reproduces the old errors faster", "trigger": "The to-be design automated a step that was itself the defect source.", "handling": "Stop the pilot, trace defects to the step that creates them, and fix the source before resuming."}, {"path": "Operators keep using the old workaround", "trigger": "The new step does not fit a real case the design missed.", "handling": "Observe the workaround, understand the case it serves, and change the design or the procedure rather than blaming operators."}, {"path": "Improvement in one metric harms another", "trigger": "Faster release raises the post-release error rate.", "handling": "Report both measures together, restore the control that caught the errors, and re-balance speed against accuracy with the process owner."}], "technical_data": "Record the as-is and to-be maps with version, date and owner, and keep the measurement definitions stable so before and after figures are comparable. Store defect segmentation with file ID, transaction ID, defect type, source and resolution so trends can be re-run. Log every repair with operator, field changed, old and new value, timestamp and checker, and keep the original file and the corrected file linked by the same file reference for audit.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment file instruction, validated at source in the to-be process", "key_fields": ["File identification and control sum", "Individual transaction identification", "Debtor and creditor account details", "Amount, currency and requested execution date"]}, {"message": "pain.002", "purpose": "Itemised file status report returned to the customer", "key_fields": ["File reference and acceptance status", "Per-transaction status and reason code", "Count of accepted and rejected items"]}, {"message": "pacs.008", "purpose": "Individual credit transfer created from each accepted file item", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Remittance information carried from the file item"]}], "accounting_operational": "Each accepted file item produces one debit to the customer account and one credit transfer; rejected items produce no financial movement. Repaired items must not lose their original traceability, and a repaired item that is resubmitted must not create a duplicate debit. Operations need a repair worklist with ageing and service levels, a control total that reconciles file value to debits posted, and a daily break report for items accepted but not settled. Staffing for the repair queue must be sized from the measured defect rate, not from optimism about the new validation.", "gherkin": ["Given a legacy process with undocumented workarounds,", "When the as-is map is produced,", "Then it reflects the process as actually performed with timings and handoffs.", "Given defect data segmented by root cause,", "When the to-be process is designed,", "Then fixes target the highest-impact causes and state which defects are prevented at source.", "Given a pilot of the to-be process,", "When the same measures are compared before and after,", "Then the improvement decision rests on measured evidence."], "assessment": [{"question": "Why must improvement start from the as-is process as actually performed?", "options": ["It is faster to document", "The documented procedure is out of date and workarounds are undocumented", "Operators prefer it", "The documented procedure is always accurate"], "answer": 1, "explanation": "The documented procedure is three versions out of date and two workarounds exist that nobody has written down, so only observation reveals the real process."}, {"question": "Which measure best shows whether repair work is falling?", "options": ["Straight-through processing rate and repair rate by defect type", "Number of staff on shift", "Customer satisfaction alone", "Number of files received"], "answer": 0, "explanation": "Straight-through processing rate and repair rate by defect type show directly how much work flows cleanly and where defects concentrate."}, {"question": "What should happen first when a client escalates that a change disrupted operations?", "options": ["Ask the client to wait for the next release", "Roll back immediately without evidence", "Confirm impact, containment, owner and next update time", "Debate who is at fault"], "answer": 2, "explanation": "Service recovery comes first: impact, a safe workaround, a named owner and an update time, with root cause and accountability handled afterwards."}, {"question": "Why is maker-checker control kept for sensitive repairs?", "options": ["It replaces validation", "It slows the process down", "It is required for all fields", "It prevents a single operator error from changing payment meaning"], "answer": 3, "explanation": "Maker-checker control on sensitive changes prevents one person's error or misuse from altering the amount, beneficiary or account of a payment."}]}}, {"id": "INS-044", "kind": "insight", "title": "Senior management asks for a solution without requirements", "topic": "Senior management asks for a solution without requirements", "theme": "Solution selection", "text": "Reframe the request around outcomes, constraints, options and decision criteria.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-045", "kind": "insight", "title": "Business says requirements complete; developers disagree", "topic": "Business says requirements complete; developers disagree", "theme": "Delivery communication", "text": "Use examples, walkthroughs, traceability and shared definitions to close interpretation gaps.", "domain": "Agile Delivery", "area": "Agile Delivery", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-046", "kind": "insight", "title": "Digital transformation faces user resistance", "topic": "Digital transformation faces user resistance", "theme": "Change adoption", "text": "Identify impacts, stakeholder groups, training needs, champions, feedback and adoption metrics.", "domain": "Change Management", "area": "Change Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s7", "title": "Workshop Facilitation: Running a Payments Discovery Workshop", "url": "lessons/ch28s7"}}, {"id": "INS-047", "kind": "insight", "title": "Demonstrating measurable BA contribution", "topic": "Demonstrating measurable BA contribution", "theme": "Business value", "text": "Connect process changes to cost, cycle time, error rates, customer experience and benefits realisation.", "domain": "Product Management", "area": "Product Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s7", "title": "Measuring product success: SLAs, KPIs and the numbers that matter", "url": "lessons/ch82s7"}}, {"id": "INS-048", "kind": "insight", "title": "SIT passes but production API fails", "topic": "SIT passes but production API fails", "theme": "API integration", "text": "Compare configuration, identity, network, certificates, payload, dependency versions and production data.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch80s3", "title": "Rate limiting and quotas: protecting the API and the client", "url": "lessons/ch80s3"}, "case": {"status": "authored", "business_problem": "Crestline Bank has integrated a merchant payment API that lets a retail partner submit payment instructions and receive status updates. The integration passed system integration testing cleanly: every test case returned the expected response, the test merchant onboarded without incident, and the release was approved. On the first morning in production, a third of live payment submissions fail. Some return authentication errors, some time out, and a few return a success response while the downstream order record is never created. The retail partner's customers are waiting at checkouts, the partner's support team is escalating, and the bank's first instinct is to blame the code that passed testing a week earlier.\n\nThe investigation must resist that instinct. SIT and production differ in ways that are invisible in a test report: different endpoints, certificates, credentials, network routes, firewall rules, feature flags, rate limits, downstream versions and, above all, real production data. A test payload is clean and predictable; a live payload carries the full variety of real customers, addresses, characters and amounts. The learner must compare the two environments systematically, use production-safe telemetry to isolate the failing boundary, and decide what can be fixed safely without making the live problem worse. The case also tests judgement about rollback: fixing forward is tempting, but only after containment is assessed.", "decision_exercise": {"scenario": "Crestline Bank's merchant payment API passed SIT but fails for a third of live submissions on the first production morning. Some fail with authentication errors, some time out, and some return success while no downstream order is created. You are the business analyst coordinating the investigation.", "options": [{"id": "A", "text": "Roll back production at once without investigation, since rollback always restores service."}, {"id": "B", "text": "Ask the retail partner to resubmit all failed payments, since a retry will probably succeed."}, {"id": "C", "text": "Conclude the code is faulty and start a code fix immediately, since SIT must have missed a defect."}, {"id": "D", "text": "Compare configuration, identity, network, certificates, payload, dependency versions and production data across environments, using telemetry to isolate the failing boundary before changing anything."}], "correct_option": "D", "why": "Option D is correct because a SIT pass with a production failure points first at environment differences, not at code. Option C assumes a defect without evidence. Option B risks duplicate payments, since some submissions already returned success while the downstream record is missing. Option A may be right eventually, but rollback without knowing the cause can restore the same failure or lose in-flight work."}, "recommended_solution": "Start by containing the impact: stop new submissions if the failure rate is rising, tell the partner what is known and what is not, and confirm which payments have a financial effect and which do not. Then compare the environments side by side in a fixed order: endpoint and configuration, credentials and scopes, certificates and expiry dates, network routes and firewall rules, feature flags, downstream service versions, rate limits, and payload versions. Pull production-safe telemetry for failing requests: the correlation ID, the request and response at each boundary, timings, and the downstream outcome. Reproduce the failure in a controlled way with a production-like payload, never by replaying live customer payments blindly.\n\nSeparate the failure modes, because each has a different fix: authentication errors point at credentials, certificates or scopes; timeouts point at network, downstream latency or rate limits; success-without-order points at the response contract and callback or event delivery. For each mode, confirm the root cause with evidence, assess the rollback and containment options, and only then change the environment or the code, with a retest that uses the failing production shape. Record the environment differences in a parity checklist so the next release checks them before deployment, and add certificate expiry alerts, contract tests and synthetic monitoring so the failure is caught before customers see it.", "flow_steps": [{"step": 1, "actor": "Support Lead", "action": "Contain impact, notify partner and confirm which payments have financial effect", "system": "Incident record"}, {"step": 2, "actor": "Business Analyst", "action": "Collect failing correlation IDs and map each failure mode", "system": "Incident record"}, {"step": 3, "actor": "Integration Engineer", "action": "Compare SIT and production configuration, endpoints and certificates", "system": "Configuration inventory"}, {"step": 4, "actor": "Integration Engineer", "action": "Check network routes, firewall rules, scopes and rate limits", "system": "Network and gateway logs"}, {"step": 5, "actor": "Business Analyst", "action": "Trace one success-without-order case across gateway, service, event bus and downstream", "system": "Distributed traces"}, {"step": 6, "actor": "Integration Engineer", "action": "Apply the evidenced fix and retest with production-shaped payloads", "system": "Test environment"}, {"step": 7, "actor": "Business Analyst", "action": "Record parity checklist and monitoring actions in the release record", "system": "Release record"}], "happy_path": "Each failure mode is traced to a specific environment difference with evidence, the fix is applied and retested with production-shaped payloads, and the integration runs cleanly in production. The parity checklist, certificate alerts and contract tests are in place so the same class of failure is caught before the next release.", "negative_paths": [{"path": "Expired production certificate", "trigger": "The production certificate expired while the SIT certificate is still valid.", "handling": "Renew through the controlled process, verify the chain and expiry date, and add an expiry alert with an owner."}, {"path": "Rate limit hit at live volume", "trigger": "Production traffic exceeds a downstream limit that SIT never approached.", "handling": "Confirm the limit with the provider, throttle or queue safely, and never silently drop payment submissions."}, {"path": "Production-only data shape", "trigger": "A live payload carries a character, address format or amount that SIT data never included.", "handling": "Fix validation and mapping for the real shape, add the shape to contract tests, and hold affected payments for review rather than guessing."}, {"path": "Success response but no downstream order", "trigger": "The API returns success on receipt while the event or callback that creates the order is lost.", "handling": "Treat HTTP success as receipt, not completion; trace the correlation ID, reconcile financial effects, and recover the order exactly once before any retry."}], "technical_data": "Persist the idempotency key, payload hash, original payment reference, correlation ID and outcome for every submission, and keep SIT and production configuration as versioned, comparable records. Log the request and response at each integration boundary with the same correlation ID so a single trace shows where a payment stopped. Never log full credentials or secrets. Keep contract tests in the schema registry with consumer inventory, so a breaking change is caught before release, and record certificate expiry dates with owners and alerts.", "messages_fields": [{"message": "pain.001", "purpose": "Merchant payment instruction submitted through the API", "key_fields": ["Instruction identification and end-to-end identification", "Debtor and creditor account details", "Amount and currency", "Idempotency key carried in the API request"]}, {"message": "pacs.008", "purpose": "Credit transfer created from an accepted instruction", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference for reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report used to confirm acceptance or rejection", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "A payment that returns success must be reconciled before any retry, because the debit may already exist even though the order record is missing. Hold ambiguous payments in a controlled recovery state and reconcile them against the ledger, the gateway log and the downstream order store using the correlation ID. Operations need a worklist of unreconciled submissions with ageing and service levels, and a rule that no operator replays a payment without checking its financial effect first. Certificate and secret expiry must be monitored as an operational control, not discovered by customers.", "gherkin": ["Given SIT passes but production fails,", "When evidence is compared across environments,", "Then the investigation tests configuration, identity, network, payload and dependency differences before code is blamed.", "Given an API returns success but the downstream record is absent,", "When the case is traced,", "Then the same correlation ID is followed across each integration boundary and the failed transition is identified.", "Given a production-only payload shape causes failures,", "When the fix is applied,", "Then the shape is added to contract tests and affected payments are recovered exactly once."], "assessment": [{"question": "What should be checked first when SIT passes but production fails?", "options": ["The release date", "The testers", "The code logic only", "Environment differences such as configuration, certificates, network, flags and data"], "answer": 3, "explanation": "SIT and production differ in configuration, identity, network, certificates, flags, limits and data, and those differences explain most SIT-pass and production-fail cases."}, {"question": "What does an HTTP 200 or 202 response guarantee?", "options": ["That the business transaction completed", "That the request was received or accepted at the transport level, not that downstream work completed", "That the order was created", "That the money moved"], "answer": 1, "explanation": "HTTP success describes transport receipt or acceptance; business completion must be confirmed by status enquiry, events and reconciliation."}, {"question": "Why is a blind retry dangerous after a success-without-order failure?", "options": ["It needs a new certificate", "It is slow", "It changes the amount", "The debit may already exist, so a retry can duplicate the payment"], "answer": 3, "explanation": "The payment may already have a financial effect even though the order record is missing, so reconciliation must come before any retry."}, {"question": "Which control prevents the next expired-certificate outage?", "options": ["Certificate expiry alerts with a named owner", "A larger rate limit", "A faster release cycle", "More testers"], "answer": 0, "explanation": "Expiry alerts with a named owner turn a silent calendar event into a managed operational control."}]}}, {"id": "INS-049", "kind": "insight", "title": "Critical requirement appears one day before deployment", "topic": "Critical requirement appears one day before deployment", "theme": "Release governance", "text": "Triage defect versus new scope, quantify risk and obtain formal go/no-go decision.", "domain": "Release Management", "area": "Release Management", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s6", "title": "Defect Management, Entry and Exit Criteria", "url": "lessons/ch42s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank is one day from deploying an upgrade to its instant euro payment service. UAT is signed off, regression evidence is filed, the deployment window is booked and the communications to customers are ready. Late in the afternoon, the compliance team raises a requirement nobody recorded: the new service must perform Verification of Payee on instant euro payments, which is mandatory from 9 October 2025, and the current build checks the payee name only for a subset of channels. The product owner argues the gap is a new requirement that should be deferred to the next release. Compliance argues it is a mandatory obligation that cannot wait. The release manager must decide by the morning, and the wrong call either ships a non-compliant service or delays a release the business has already announced.\n\nThe decision cannot be made on opinion or on who argues loudest. It needs triage, evidence and a formal decision by the release authority. The learner must separate a defect from new scope and from a safety or compliance obligation, quantify the risk of shipping and of delaying, check whether a safe interim control exists, and present options the release authority can actually decide between. The case also carries a trap: PSD3 is sometimes cited as the source of the obligation, but PSD3 is not law and PSD2 remains in force, so the obligation must be traced to its real source, which is Regulation (EU) 2024/886 and the scheme rules, not to a directive that has not been enacted.", "decision_exercise": {"scenario": "Meridian Bank deploys an instant euro payment upgrade tomorrow. UAT is signed off. Late today, compliance raises an unrecorded requirement: Verification of Payee must apply to instant euro payments. The product owner wants to defer it; compliance says it is mandatory. You are the business analyst asked to prepare the go or no-go evidence.", "options": [{"id": "A", "text": "Add the missing Verification of Payee check overnight without testing, since the requirement is mandatory."}, {"id": "B", "text": "Triage the requirement as defect, new scope or compliance obligation, quantify shipping and delaying risks, and present evidenced go or no-go options to the release authority."}, {"id": "C", "text": "Ship on schedule and defer the requirement, since UAT is signed off and the release is already announced."}, {"id": "D", "text": "Cancel the release permanently without a decision record, since any late requirement means the release is unsafe."}], "correct_option": "B", "why": "Option B is correct because a late requirement needs triage, evidence and a formal decision by the release authority, not a unilateral call. Option C ships a service that may breach a mandatory obligation. Option A adds an untested change to a signed-off build, which is how releases fail. Option D destroys a release that might be shippable with a safe interim control or a scoped deployment."}, "recommended_solution": "First classify the item precisely: is it a defect against an agreed requirement, a safety or compliance obligation, or genuinely new scope? Confirm the obligation at its source: Verification of Payee is mandatory for instant euro payments from 9 October 2025 under Regulation (EU) 2024/886, and SCT Inst execution has a 10-second maximum with no scheme-level maximum since the 2025 rulebook change. Do not cite PSD3 as the source, because PSD3 is not law and PSD2 remains in force; the provisional political agreement of 27 November 2025 does not make it applicable, with full application expected only around 2028. Then quantify the gap: which channels, payment types and volumes are affected, what happens to a payment when the check is missing, and what customer and regulatory harm follows.\n\nAssess the options with evidence: ship as planned, ship with a safe interim control such as restricting the affected channels, delay until the check is built and tested, or deploy a hotfix with a defined regression scope. For each option record the test evidence available, the rollback position, the data migration impact, the customer communication needed and the residual risk. Present the options to the release authority with a recommendation, and record the decision, the decision maker, the evidence relied on and the follow-up actions. If the release proceeds with a known gap, that must be a formal risk acceptance by the authorised person, never an informal agreement in a meeting.", "flow_steps": [{"step": 1, "actor": "Compliance Officer", "action": "Confirm the obligation, its source and its effective date", "system": "Obligation register"}, {"step": 2, "actor": "Business Analyst", "action": "Triage the item as defect, compliance obligation or new scope", "system": "Change request"}, {"step": 3, "actor": "Business Analyst", "action": "Quantify affected channels, volumes and customer harm", "system": "Impact assessment"}, {"step": 4, "actor": "Test Lead", "action": "State what can and cannot be tested before the deployment window", "system": "Test evidence"}, {"step": 5, "actor": "Release Manager", "action": "Assess rollback, interim controls and deployment risk per option", "system": "Release checklist"}, {"step": 6, "actor": "Release Authority", "action": "Decide go, no-go or conditional go and record the decision", "system": "Release decision record"}, {"step": 7, "actor": "Business Analyst", "action": "File decision, evidence and follow-up actions for audit", "system": "Release decision record"}], "happy_path": "The release authority makes a documented decision on evidence: either the release proceeds with a safe interim control and formal risk acceptance, or it is postponed until the check is built and tested. In both cases the decision, the decision maker, the evidence and the follow-up actions are recorded, and customers receive accurate communications about what is changing.", "negative_paths": [{"path": "Mandatory regulatory gap with no interim control", "trigger": "The missing check cannot be worked around and the obligation is already in force.", "handling": "Recommend postponement, record the regulatory basis and re-plan with a tested build."}, {"path": "Change cannot be tested in time", "trigger": "An overnight fix has no regression evidence.", "handling": "Do not ship untested change; choose between delay and a scoped deployment that excludes the affected channels."}, {"path": "Rollback cannot restore data", "trigger": "The deployment migrates data that cannot be reversed.", "handling": "Require a forward fix plan and a data backup before any go decision, and record the residual risk."}, {"path": "Workaround exists but creates manual risk", "trigger": "Staff could check payee names manually for a small volume.", "handling": "Quantify the manual volume, error rate and staffing, and accept it only as a time-bound interim control with an expiry date."}], "technical_data": "Keep the change request, the triage classification, the obligation source and effective date, the impact assessment and the release decision in one traceable record. Store test evidence with build version, environment and date so the authority can see exactly what was and was not tested. Record any risk acceptance with the name of the authorised person, the scope, the expiry and the follow-up action, and keep the customer communication version that matches the deployed scope.", "messages_fields": [{"message": "pacs.008", "purpose": "Instant credit transfer leg affected by the missing Verification of Payee check", "key_fields": ["Interbank settlement amount and currency", "Creditor name checked against the account", "Creditor agent and account", "Execution within the 10-second regulatory maximum"]}, {"message": "pacs.002", "purpose": "Payment status report showing acceptance or rejection after the check", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}, {"message": "pain.001", "purpose": "Customer payment initiation for the channels in scope of the check", "key_fields": ["Instruction identification", "Creditor name and account", "Amount and currency"]}], "accounting_operational": "If the release ships without the check, the bank faces payments sent to the wrong payee, customer loss, complaints and regulatory exposure, and operations would need a manual review queue with no defined capacity. If the release is delayed, the bank faces the cost of an unused deployment window, re-communication to customers and a revised launch date. Either way the accounting effect is the same discipline: no payment is released without a known status, rejected payments produce no debit, and any interim manual control must be staffed, measured and time-bound so it does not become a permanent unmonitored process.", "gherkin": ["Given a new request arrives after UAT sign-off,", "When severity and impact are assessed,", "Then the authorised release decision is recorded with test and rollback implications.", "Given a mandatory obligation is cited,", "When its source is checked,", "Then the obligation is traced to the law or rule in force and not to a directive that is not law.", "Given an interim control is proposed,", "When it is accepted,", "Then it is time-bound, staffed and recorded as formal risk acceptance by the authorised person."], "assessment": [{"question": "Who owns the go or no-go decision when a late requirement appears?", "options": ["The test lead", "The business analyst", "The product owner alone", "The release authority"], "answer": 3, "explanation": "The business analyst provides evidence and options; the release authority owns the go or no-go decision."}, {"question": "Which statement about PSD3 is correct for this decision?", "options": ["PSD3 only applies to direct debits", "PSD3 is law and replaces PSD2", "PSD3 is not law and PSD2 remains in force", "PSD3 applies from 9 October 2025"], "answer": 2, "explanation": "PSD3 and the Payment Services Regulation are not law; PSD2 remains in force, with full application of the new framework expected only around 2028."}, {"question": "From which date is Verification of Payee mandatory for instant euro payments?", "options": ["27 November 2025", "5 October 2025", "1 January 2026", "9 October 2025"], "answer": 3, "explanation": "Verification of Payee is mandatory for instant euro payments from 9 October 2025."}, {"question": "Why must an overnight untested fix be rejected?", "options": ["It adds change to a signed-off build without regression evidence", "It changes the launch date", "It needs a new vendor", "It is too expensive"], "answer": 0, "explanation": "An untested change to a signed-off build can introduce a worse failure, and no release authority can approve it without test evidence."}]}}, {"id": "INS-050", "kind": "insight", "title": "Duplicate transactions appear after release", "topic": "Duplicate transactions appear after release", "theme": "Duplicate processing", "text": "Investigate retries, idempotency, event redelivery, timeouts and weak deduplication controls.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s3", "title": "Retries, Dead Letter Queues, Timeouts and Unknown Outcomes", "url": "lessons/ch68s3"}, "case": {"status": "authored", "business_problem": "Solstice Bank released a new corporate payment channel that lets customers submit salary and supplier payments through an API. In the first week after release, the operations team notices duplicate debits: several corporate customers have been charged twice for the same instruction, and a few suppliers have been paid twice. The pattern is not random. Duplicates cluster around slow channel responses, where the customer system timed out, retried the submission, and both attempts were processed as separate payments. The release also changed the retry behaviour of an internal event consumer, so some events are now redelivered and processed a second time. Customers are asking for their money back, the finance team wants to know how many duplicates exist, and the release team wants to know whether to roll back.\n\nThe learner must investigate as an operations and controls problem, not only as a code defect. The core question is how the platform distinguishes a technical retry from a genuine second payment, and what happens when that distinction fails. The answer involves idempotency keys, payload hashes, duplicate detection rules, durable state and a recovery process that returns money exactly once. The case also tests the discipline of not silently discarding ambiguous payments: an uncertain match must go to review, never to an automatic delete or an automatic re-post.", "decision_exercise": {"scenario": "Solstice Bank released a new corporate payment API. In the first week, customers report duplicate debits: slow channel responses led to retries that were processed as separate payments, and an event consumer redelivers some events. You are the business analyst leading the investigation and the recovery.", "options": [{"id": "A", "text": "Block all retries in the channel, since retries are the cause of the problem."}, {"id": "B", "text": "Tell customers to submit a new payment to replace the duplicate, since the money will sort itself out in reconciliation."}, {"id": "C", "text": "Stop the duplicate path, identify every affected payment with idempotency and reference data, reverse duplicates exactly once through a controlled process, and fix idempotency, deduplication and redelivery handling."}, {"id": "D", "text": "Delete the second debit from the ledger directly, since it is obviously a duplicate."}], "correct_option": "C", "why": "Option C is correct because it contains the failure, identifies the full affected population, corrects each duplicate exactly once, and fixes the control that failed. Option B creates a third payment. Option D deletes a financial record without an audited reversal. Option A removes a legitimate recovery mechanism and leaves genuine timeouts with no safe path."}, "recommended_solution": "Start by containing the failure: confirm whether duplicates are still being created and, if so, stop the affected path or route it through a manual check. Then establish the affected population using stable identifiers rather than guesswork: match on idempotency key, instruction reference, end-to-end identification, debtor, creditor, amount, currency and value date, and separate confirmed duplicates from uncertain matches. For confirmed duplicates, reverse the second financial effect exactly once through the controlled reversal process, with a unique reversal reference linked to the original payment, and confirm the customer account and the supplier position. Uncertain matches go to a review worklist with maker-checker approval; they are never silently discarded or automatically re-posted.\n\nThen fix the cause at each layer. Persist the idempotency key with the payload hash, the original payment reference, timestamps and outcome, so a retry with the same key returns the original reference and creates no second debit. Apply duplicate detection using stable business identifiers, but do not rely on amount and beneficiary alone, because two genuine identical payments are possible. Make event redelivery idempotent so a redelivered event updates state once. Define the retention and replay policy for idempotency records, and add monitoring that alerts on duplicate detection events and on retries after timeouts. Finally, re-run the affected population check after the fix to prove no new duplicates are being created, and report the count, the value and the recovery status to finance and to affected customers.", "flow_steps": [{"step": 1, "actor": "Operations Lead", "action": "Contain the duplicate path and open the incident record", "system": "Incident record"}, {"step": 2, "actor": "Business Analyst", "action": "Define matching rules and identify confirmed duplicates and uncertain matches", "system": "Reconciliation report"}, {"step": 3, "actor": "Finance Operations", "action": "Reverse confirmed duplicates exactly once with linked reversal references", "system": "Core ledger"}, {"step": 4, "actor": "Integration Engineer", "action": "Persist idempotency keys with payload hash and original reference", "system": "Payment platform"}, {"step": 5, "actor": "Integration Engineer", "action": "Make event redelivery idempotent and add duplicate alerts", "system": "Payment platform"}, {"step": 6, "actor": "Business Analyst", "action": "Re-run the population check after the fix and report recovery status", "system": "Reconciliation report"}, {"step": 7, "actor": "Customer Support", "action": "Notify affected customers with the reversal reference and date", "system": "Customer communications"}], "happy_path": "Duplicates stop being created, every confirmed duplicate is reversed exactly once with a linked reference, uncertain matches are resolved through review, and the idempotency and redelivery controls are proven by a clean re-run of the population check. Customers receive a clear statement of what was reversed and when.", "negative_paths": [{"path": "Same key with altered payload", "trigger": "A retry arrives with the same idempotency key but different amount or beneficiary.", "handling": "Reject the request as a key conflict, return an error, and route it for review rather than creating a payment."}, {"path": "Retry after timeout", "trigger": "The channel times out, the customer retries, and the first attempt later completes.", "handling": "Return the original reference for the same key so the retry is recognised as the same instruction."}, {"path": "Duplicate detected after downstream submission", "trigger": "The duplicate is found only after the second payment has left the bank.", "handling": "Reverse through the controlled process with a linked reversal reference and reconcile the supplier position."}, {"path": "Concurrent requests", "trigger": "Two identical requests arrive at the same moment before either is persisted.", "handling": "Use a durable uniqueness constraint on the idempotency key so only one request creates the payment."}], "technical_data": "Persist the idempotency key scoped to the initiating party and instruction, the payload hash, the original payment ID, the timestamps and the outcome, and keep those records for the agreed retention period. Store the duplicate detection rules with their version and effective date, and log every duplicate detection event, reversal and review decision with operator, timestamp and reason. Keep the original and the reversal linked by reference so the audit trail shows exactly one financial effect per genuine instruction.", "messages_fields": [{"message": "pain.001", "purpose": "Corporate payment instruction submitted through the API", "key_fields": ["Instruction identification and end-to-end identification", "Idempotency key in the API request", "Debtor and creditor account details", "Amount and currency"]}, {"message": "pacs.008", "purpose": "Credit transfer created from each accepted instruction", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference used for duplicate matching"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection of each attempt", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "Each duplicate is a second debit to the customer account and a second credit to the supplier, so the reversal must credit the customer and, where the supplier was overpaid, recover or offset the second credit through the agreed process. Reversals go through suspense only where the standard process requires it, and each reversal is reconciled separately from the original payment so finance can prove the customer is whole. Operations need a duplicate worklist with ageing and service levels, a daily count and value of duplicates detected, and a rule that no operator reverses a payment without a linked original reference and a second approval for large values.", "gherkin": ["Given an already accepted instruction,", "When the identical request is retried with the same idempotency key,", "Then the platform returns the original payment reference and does not create a second debit.", "Given two payments share amount and beneficiary,", "When they carry different idempotency keys and references,", "Then they are treated as potentially genuine and routed for review rather than automatically discarded.", "Given a confirmed duplicate,", "When the reversal is processed,", "Then the customer account is credited exactly once with a reversal reference linked to the original payment."], "assessment": [{"question": "How do you distinguish a technical retry from a genuine second payment?", "options": ["By the time of day", "By the idempotency key and stable instruction identifiers", "By the channel used", "By amount and beneficiary alone"], "answer": 1, "explanation": "An idempotency key scoped to the initiating party and instruction, with the payload hash and original reference, identifies a retry; amount and beneficiary alone cannot, because two genuine identical payments are possible."}, {"question": "What should happen to an uncertain duplicate match?", "options": ["Ignore it", "Delete it silently", "Post it again", "Route it to a review worklist with maker-checker approval"], "answer": 3, "explanation": "An ambiguous payment must never be silently discarded or automatically re-posted; it goes to review with an audited decision."}, {"question": "Why is a direct ledger delete the wrong way to fix a duplicate debit?", "options": ["It changes the supplier balance only", "It is too slow", "It removes the financial record without an audited reversal linked to the original", "It needs a new system"], "answer": 2, "explanation": "A duplicate must be corrected through a controlled reversal with a linked reference, so the audit trail proves exactly one financial effect per genuine instruction."}, {"question": "What makes event redelivery safe?", "options": ["Faster consumers", "More retries", "Idempotent processing so a redelivered event updates state once", "Longer timeouts"], "answer": 2, "explanation": "Idempotent event handling ensures a redelivered event does not create a second payment or a second debit."}]}}, {"id": "INS-051", "kind": "insight", "title": "Requirement, development, testing or environment miss", "topic": "Requirement, development, testing or environment miss", "theme": "Delivery failure chain", "text": "Use a layered failure model to locate where intended behaviour diverged from production behaviour.", "domain": "SDLC & Quality", "area": "SDLC & Quality", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s1", "title": "Why Payment Testing Is Different", "url": "lessons/ch42s1"}}, {"id": "INS-052", "kind": "insight", "title": "Change requested after 70% of sprint is complete", "topic": "Change requested after 70% of sprint is complete", "theme": "Sprint scope", "text": "Assess reason, effort, dependencies and PO options without silently compromising sprint goal.", "domain": "Agile Delivery", "area": "Agile Delivery", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-053", "kind": "insight", "title": "Two senior stakeholders want opposite outcomes", "topic": "Two senior stakeholders want opposite outcomes", "theme": "Stakeholder conflict", "text": "Facilitate evidence-based prioritisation and document accountable decision.", "domain": "Stakeholder Management", "area": "Stakeholder Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-054", "kind": "insight", "title": "Critical UAT failure rate at test start", "topic": "Critical UAT failure rate at test start", "theme": "UAT readiness", "text": "Triage environment, test data, build, requirements and defect severity before deciding whether to continue.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s7", "title": "Exercise: Build a UAT Pack for a pacs.008 Change", "url": "lessons/ch42s7"}, "case": {"status": "authored", "business_problem": "Beacon Bank is starting user acceptance testing for a new SEPA direct debit collection service. On the first morning, the failure rate is critical: most test collections are rejected, mandate references cannot be found, and the test schedule shows collections submitted on the wrong day. The test manager wants to push on and log defects as they come. The business analyst suspects the problem is not the software but the readiness of the test itself: the environment, the test data, the build and the requirements may each be wrong in a different way, and continuing to test against a broken setup will produce defect noise that hides the real faults.\n\nThe learner must triage before deciding whether to continue, pause or stop. That means checking the environment configuration, the mandate test data, the build version, and whether the requirements the testers are using match the current scheme rules. The scheme facts matter here: an SDD Core collection must be submitted by D-1, one Inter-PSP Business Day before the Due Date, with pre-notification at the latest 14 Calendar Days before the Due Date, and an unused mandate must not be used after 36 months. A test that submits on the wrong day or uses a stale mandate will fail for the right reasons, and logging those as software defects wastes the whole test window. The case tests the discipline of an entry gate: UAT starts only when its entry criteria are met.", "decision_exercise": {"scenario": "Beacon Bank starts UAT for a new SEPA direct debit collection service. On the first morning most test collections fail: mandate references cannot be found and collections are submitted on the wrong day. The test manager wants to push on. You are the business analyst asked to triage before deciding whether to continue.", "options": [{"id": "A", "text": "Declare the build unfit and cancel UAT without checking the environment or the data."}, {"id": "B", "text": "Push on with testing and log every failure as a software defect, since UAT is about finding defects."}, {"id": "C", "text": "Change the test data to make the tests pass, since the schedule is tight."}, {"id": "D", "text": "Pause and triage environment, test data, build and requirements against entry criteria, then decide to continue, pause or stop with evidence."}], "correct_option": "D", "why": "Option D is correct because a critical failure rate at test start usually signals a readiness failure, and testing against a broken setup produces noise, not evidence. Option B logs environment and data failures as software defects. Option A blames the build without evidence. Option C falsifies the test and destroys its value."}, "recommended_solution": "Begin with a triage that separates the failure causes into four buckets: environment, test data, build and requirements. Check the environment first: is the UAT build the intended version, are the endpoints, credentials and scheme adapters pointed at the right test systems, and are the feature flags set as the release notes state? Then check the test data: do the mandate references exist in the test system, are the mandates within their validity, has any mandate been unused for 36 months, and are the collection dates consistent with the D-1 submission deadline and the 14-calendar-day pre-notification rule? Then check the requirements the testers are using against the current scheme rules, and confirm the test cases match them.\n\nSegment the failures by bucket and count them, so the decision rests on numbers rather than impressions. If the cause is environment or data, fix the readiness gap, re-run the entry criteria and restart the affected test cases with a clean record. If the cause is the build, raise defects with reproducible evidence and ask the test manager to decide whether the remaining test scope is still meaningful. If the requirements themselves are wrong, stop and correct them before any more testing. Record the triage, the entry criteria results and the continue, pause or stop decision, and re-plan the test window with the time the fix actually needs rather than the time the schedule wishes for.", "flow_steps": [{"step": 1, "actor": "Test Manager", "action": "Halt new test execution and open the triage record", "system": "Test management tool"}, {"step": 2, "actor": "Business Analyst", "action": "Segment failures by environment, data, build and requirements", "system": "Triage record"}, {"step": 3, "actor": "Test Environment Lead", "action": "Verify build version, endpoints, credentials and feature flags", "system": "Environment record"}, {"step": 4, "actor": "Test Data Lead", "action": "Verify mandate references, validity and collection dates against scheme rules", "system": "Test data inventory"}, {"step": 5, "actor": "Business Analyst", "action": "Check test cases against current SDD rules and requirements", "system": "Requirements traceability"}, {"step": 6, "actor": "Test Manager", "action": "Decide continue, pause or stop and re-plan the test window", "system": "Test plan"}, {"step": 7, "actor": "Business Analyst", "action": "Record the decision and the entry criteria evidence", "system": "Test management tool"}], "happy_path": "UAT restarts only after the entry criteria pass: the right build is deployed, the mandate data is valid and consistent with the D-1 and pre-notification rules, and the test cases match the current requirements. Failures found after restart are genuine defects with reproducible evidence, and the test plan reflects the time the fix actually needed.", "negative_paths": [{"path": "Mandate reference not found", "trigger": "Test data references mandates that were never loaded into the UAT environment.", "handling": "Reload the mandate data, verify each reference exists, and re-run the affected cases with a clean record."}, {"path": "Collection submitted on the wrong day", "trigger": "Test cases use a submission date that breaches the D-1 deadline.", "handling": "Correct the test schedule to the scheme rule and treat the earlier failures as data errors, not software defects."}, {"path": "Stale mandate used in testing", "trigger": "A mandate unused for 36 months is used in a test case.", "handling": "Remove the mandate from the test data, since an unused mandate must not be used after 36 months, and replace it with a valid one."}, {"path": "Environment points at the wrong downstream", "trigger": "UAT calls a test adapter that returns production-shaped errors.", "handling": "Correct the endpoint and configuration, verify the build version, and re-run the entry criteria before restarting."}], "technical_data": "Keep the entry criteria checklist with a pass or fail per item, the build version, the environment configuration and the test data inventory versioned together so a failure can be reproduced. Log every defect with the test case, the data used, the build version and the environment, so a defect can be separated from a readiness failure. Store the triage segmentation with counts per bucket, and keep the requirements traceability matrix current so a test case can be traced to the scheme rule it checks.", "messages_fields": [{"message": "pain.008", "purpose": "Direct debit instruction carrying mandate information for the collection", "key_fields": ["Mandate identification and date of signature", "Creditor and debtor identification", "Amount, currency and requested collection date", "Sequence type for first, recurrent or final collection"]}, {"message": "pacs.003", "purpose": "Direct debit collection message submitted to the debtor bank", "key_fields": ["Interbank settlement amount and currency", "Mandate related information", "Requested collection date consistent with the D-1 deadline", "Creditor agent and account"]}, {"message": "pacs.004", "purpose": "Return message used for SDD returns and refunds", "key_fields": ["Original collection reference", "Return reason code", "Amount returned", "Distinction between Core and B2B return windows"]}, {"message": "pacs.002", "purpose": "Payment status report for collection acceptance or rejection", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "A failed UAT collection in the test environment has no real financial effect, but the operational lesson is financial: if the same readiness failure reached production, collections would be rejected, creditors would miss expected funds, and returns and refunds would follow under scheme rules. Core returns run to D+5 Inter-PSP Business Days and B2B returns to D+3, authorised Core refunds run within 8 weeks of the debit date with no questions asked, and unauthorised claims run within 13 months. Operations must be able to explain to a creditor why a collection was rejected, which rule it breached, and what must change before resubmission, so the UAT defect record should capture the business meaning of each failure, not only its technical symptom.", "gherkin": ["Given a critical failure rate at the start of UAT,", "When triage is performed,", "Then failures are segmented by environment, data, build and requirements before any continue decision is made.", "Given a mandate has been unused for 36 months,", "When it is used in a test case,", "Then the test data is corrected because the mandate must not be used.", "Given the D-1 submission deadline,", "When a test collection is scheduled,", "Then the submission date is one Inter-PSP Business Day before the Due Date."], "assessment": [{"question": "What is the SDD Core collection submission deadline?", "options": ["D-3 before the Due Date", "D-1, one Inter-PSP Business Day before the Due Date", "D+5 after the Due Date", "On the Due Date"], "answer": 1, "explanation": "The SDD Core collection submission deadline is D-1, one Inter-PSP Business Day before the Due Date, not D-2."}, {"question": "How long before the Due Date must pre-notification be sent at the latest?", "options": ["7 Calendar Days", "30 Calendar Days", "14 Calendar Days", "1 Inter-PSP Business Day"], "answer": 2, "explanation": "Pre-notification must be sent at the latest 14 Calendar Days before the Due Date."}, {"question": "Why should testing pause when the failure rate is critical at the start of UAT?", "options": ["Because the build is always at fault", "Because the failures may come from environment or data readiness, and testing on will produce defect noise that hides real faults", "To save time", "Because testers are tired"], "answer": 1, "explanation": "A critical early failure rate usually signals a readiness failure, and continuing produces noise rather than evidence."}, {"question": "What happens to a mandate unused for 36 months?", "options": ["It needs a new creditor ID", "It must not be used", "It renews automatically", "It converts to B2B"], "answer": 1, "explanation": "A mandate unused for 36 months must not be used."}]}}, {"id": "INS-055", "kind": "insight", "title": "Incorrect EMI for a small customer subset", "topic": "Incorrect EMI for a small customer subset", "theme": "Financial calculation", "text": "Trace product terms, rate tables, rounding, dates, schedule generation and customer data.", "domain": "Lending & Data", "area": "Lending & Data", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s5", "title": "Test Data, Environments and Simulators", "url": "lessons/ch42s5"}, "case": {"status": "authored", "business_problem": "Aldergate Bank has received complaints from a small group of loan customers: their monthly EMI is wrong. Most customers are unaffected, which makes the problem harder, not easier. The complaints share a pattern that only emerges when the cases are compared: the affected loans were taken out on particular dates, some have a rate change in their history, and a few have a part-payment that the schedule did not handle. The lending team suspects a rounding error, the product team suspects the rate table, and the operations team suspects the customer data. Each theory explains some cases and none explains all of them.\n\nThe learner must trace the calculation from its inputs to its output instead of guessing. An EMI depends on the principal, the rate, the tenure, the schedule generation rules, the rounding policy, the treatment of rate changes and part-payments, and the dates on which each of those applies. A defect in any one of those, affecting only a narrow combination, produces exactly this symptom: a small subset wrong by a small amount, month after month. The case also tests the recovery discipline: correcting the schedule is not enough, because customers have already paid the wrong amount and the difference must be handled through a controlled adjustment, not a silent fix.", "decision_exercise": {"scenario": "Aldergate Bank receives complaints from a small group of loan customers whose monthly EMI is wrong. Most customers are unaffected. The affected loans share dates, rate changes or part-payments, and three teams hold three different theories. You are the business analyst asked to find the cause and define the correction.", "options": [{"id": "A", "text": "Tell affected customers the difference is immaterial and close the complaints."}, {"id": "B", "text": "Apply a rounding fix to all loans, since rounding is the most likely cause of a small EMI error."}, {"id": "C", "text": "Regenerate every schedule in the portfolio, since a full rebuild will fix the affected subset too."}, {"id": "D", "text": "Trace the calculation for affected and unaffected loans through product terms, rate tables, rounding, dates, schedule generation and customer data, then correct the cause and adjust affected accounts through a controlled process."}], "correct_option": "D", "why": "Option D is correct because a subset-only error needs a traced comparison between affected and unaffected cases, not a blanket fix. Option B assumes the cause without evidence and may change correct schedules. Option C rebuilds correct schedules and risks introducing new errors. Option A ignores a real financial error that compounds every month."}, "recommended_solution": "Start by defining the affected population precisely: list every complaining account and search for others with the same characteristics, so the fix covers silent cases as well as complaints. For each affected loan, capture the full calculation inputs: principal, sanctioned rate, rate change history with effective dates, tenure, schedule generation rules, rounding policy, part-payment history, and the dates each input applied. Then run the same inputs through an independent calculation and compare the result with the system schedule, line by line, so the first point of divergence is visible.\n\nSegment the divergences by cause: a rate change applied from the wrong date, a part-payment that did not re-amortise the schedule, a rounding rule applied at the wrong step, or a date rule that mishandles month ends and short months. Confirm each cause against the product terms and the rate table version in force on the relevant date, and check the unaffected population to confirm the cause explains why they are correct. Fix the cause, regenerate only the affected schedules, and validate the new schedules against the independent calculation before release. Then correct the customer impact through a controlled adjustment: compute the difference paid to date for each account, apply the adjustment with a linked reference and a clear customer statement, and confirm the new EMI and the remaining tenure in writing. Record the root cause, the population, the fix and the adjustment evidence for audit.", "flow_steps": [{"step": 1, "actor": "Customer Support", "action": "Log complaints and identify the full affected population", "system": "Complaint register"}, {"step": 2, "actor": "Business Analyst", "action": "Capture calculation inputs for affected and unaffected loans", "system": "Loan records"}, {"step": 3, "actor": "Lending Product", "action": "Confirm product terms and rate table versions with effective dates", "system": "Product terms"}, {"step": 4, "actor": "Business Analyst", "action": "Run an independent calculation and find the first point of divergence", "system": "Calculation workbook"}, {"step": 5, "actor": "Lending Systems", "action": "Fix the cause and regenerate only the affected schedules", "system": "Lending system"}, {"step": 6, "actor": "Finance Operations", "action": "Compute and apply controlled adjustments with linked references", "system": "Core ledger"}, {"step": 7, "actor": "Customer Support", "action": "Notify each affected customer with the corrected EMI and the adjustment", "system": "Customer communications"}], "happy_path": "Each affected loan has a corrected schedule that matches an independent calculation, the difference paid to date is adjusted through a controlled process with a linked reference, and every affected customer receives a clear statement of the corrected EMI and the adjustment. The root cause is fixed so no new loans take the wrong path, and the silent cases found by the population search are corrected too.", "negative_paths": [{"path": "Rate change applied from the wrong date", "trigger": "A rate change takes effect a month late, so the EMI uses the old rate for one instalment.", "handling": "Correct the effective date rule, regenerate the affected schedules, and adjust the difference."}, {"path": "Part-payment does not re-amortise", "trigger": "A part-payment reduces the balance but the schedule keeps the old EMI.", "handling": "Apply the product rule for part-payments, regenerate the schedule, and confirm the new EMI with the customer."}, {"path": "Rounding applied at the wrong step", "trigger": "Rounding the interest before the EMI is derived shifts the instalment by a small amount each month.", "handling": "Apply rounding at the step the product terms define, and validate against the independent calculation."}, {"path": "Month-end date rule mishandled", "trigger": "A loan starting on the 31st produces a wrong first instalment date.", "handling": "Correct the date rule for short months and validate the first instalment date for affected loans."}], "technical_data": "Store the calculation inputs with their source, version and effective date: product terms version, rate table version, schedule generation rules, rounding policy and the customer data snapshot used. Keep the independent calculation workbook with the comparison that shows the first point of divergence, and log every schedule regeneration and every adjustment with account, operator, timestamp, old and new values and checker. Preserve the original schedule alongside the corrected one so the change is auditable, and keep the adjustment reference linked to the loan account.", "messages_fields": [{"message": "pain.001", "purpose": "Customer instruction for a loan repayment or part-payment", "key_fields": ["Instruction identification", "Debtor account and amount", "Remittance information identifying the loan account", "Requested execution date"]}, {"message": "pacs.008", "purpose": "Credit transfer for a repayment that moves through the payment system", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference for reconciliation"]}, {"message": "camt.053", "purpose": "Account statement used to verify instalments received and adjustments posted", "key_fields": ["Account identification", "Entry amount, date and reference", "Balance after each entry"]}, {"message": "pacs.002", "purpose": "Payment status report for a repayment instruction", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "An incorrect EMI is a direct financial error: the customer pays too much or too little each month, and the difference accumulates in the loan balance and the interest charged. The correction must therefore be a controlled financial adjustment, not a silent schedule change: compute the difference to date, post the adjustment with a linked reference, and reconcile the adjusted balances to the corrected schedules. Operations need a worklist of affected accounts with the adjustment amount, the approval status and the customer notification status, and a service level for completing the corrections. The interest effect of the error must be included in the adjustment, and finance must confirm the total value corrected.", "gherkin": ["Given a small subset of loans has an incorrect EMI,", "When the calculation is traced,", "Then affected and unaffected loans are compared through product terms, rate tables, rounding, dates and schedule generation to find the first divergence.", "Given a rate change with an effective date,", "When the schedule is generated,", "Then the new rate applies from the correct date and the EMI is validated against an independent calculation.", "Given an affected customer has overpaid,", "When the schedule is corrected,", "Then the difference is adjusted through a controlled process with a linked reference and a clear customer statement."], "assessment": [{"question": "Why is a blanket rounding fix the wrong first step?", "options": ["Rounding is never the cause", "The cause is unproven and a blanket fix may change correct schedules", "Rounding cannot be fixed", "Customers dislike rounding"], "answer": 1, "explanation": "A subset-only error needs a traced comparison; an unproven blanket fix risks breaking the majority of correct schedules."}, {"question": "What does an independent calculation provide?", "options": ["A customer letter", "A faster schedule", "A comparison that shows the first point where the system calculation diverges", "A new product"], "answer": 2, "explanation": "Running the same inputs through an independent calculation exposes the first step where the system result differs."}, {"question": "Why must silent cases be found, not only complaints?", "options": ["Complaints are unreliable", "It is faster", "Regulators require it", "Loans with the same characteristics may be wrong without the customer noticing"], "answer": 3, "explanation": "Customers may not notice a small monthly error, so the population search must find every loan with the same cause."}, {"question": "How should the money already overpaid or underpaid be handled?", "options": ["By asking the customer to pay it back immediately", "Silently change the schedule", "Through a controlled adjustment with a linked reference and a clear customer statement", "By writing it off without a record"], "answer": 2, "explanation": "The difference is a real financial error and must be corrected through a controlled, audited adjustment that the customer can see."}]}}, {"id": "INS-056", "kind": "insight", "title": "Client says the new process has damaged operations", "topic": "Client says the new process has damaged operations", "theme": "Client escalation", "text": "Acknowledge impact, establish facts, provide safe workaround and agree recovery communications.", "domain": "Client Management", "area": "Client Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch44s6", "title": "Incident Management, Outages and Business Continuity", "url": "lessons/ch44s6"}}, {"id": "INS-057", "kind": "insight", "title": "UI, API and database values differ", "topic": "UI, API and database values differ", "theme": "Data lineage", "text": "Trace one record through presentation, request, transformation, persistence and read model.", "domain": "Data & Integration", "area": "Data & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch38s6", "title": "Data Lineage, Retention and Auditability", "url": "lessons/ch38s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank has a cross-border payment complaint that looks simple and turns out not to be: the customer sees one amount in the online banking screen, the API transmitted a different amount, and the persisted record in the database holds a third value. The payment also carries a beneficiary address that appears complete in the user interface but arrives truncated in the payment message. The customer wants to know which value is correct, and the bank cannot answer until it traces one record through every layer it passed through. Each team defends its own layer: the channel team says the screen shows what the customer entered, the API team says the payload was valid, and the database team says the record is what was stored.\n\nThe learner must trace the record layer by layer using a stable identifier, and find the first point where the value changes incorrectly. The causes to consider are concrete: a transformation that rounds or converts, a timezone shift on a date, a mapping that drops a field, a stale cache serving an old read model, an asynchronous update that has not yet landed, or a field truncation in the message mapping. The address issue adds a scheme rule: a structured or hybrid address is required, with a minimum of Town Name and Country Code, or BIC only, and the bank must not teach a fixed structured-address cut-off date, since the deadline was extended in July 2026 and a new timeline is expected by December 2026. The case also tests the MT to MX boundary: where a legacy message lacks a value the ISO 20022 message needs, the bank must never fabricate it.", "decision_exercise": {"scenario": "Meridian Bank receives a cross-border payment complaint: the customer sees one amount on screen, the API transmitted another, and the database holds a third. The beneficiary address also arrives truncated in the payment message. You are the business analyst asked to trace the record and find the first point of divergence.", "options": [{"id": "A", "text": "Trust the database value, since the database is the system of record and the other layers must be wrong."}, {"id": "B", "text": "Fix the screen to show the database value, since the customer only sees the screen."}, {"id": "C", "text": "Ask the customer to resubmit the payment with the correct amount, since the original is already confused."}, {"id": "D", "text": "Trace one affected record by its stable identifier through UI, API payload, transformation, persistence and read model, comparing values at each layer to find the first divergence."}], "correct_option": "D", "why": "Option D is correct because only a layer-by-layer trace with a stable identifier can show where a value first changes incorrectly. Option A assumes the answer without evidence. Option C creates a second payment on top of an unresolved one. Option B hides the divergence instead of fixing it."}, "recommended_solution": "Start by fixing the record: pick one affected payment and its stable identifier, such as the end-to-end identification, and use that single identifier at every layer so the comparison is about the same record. Capture the value at each point: what the customer entered and what the screen displayed, the API request payload as received, the transformed canonical model, the validation and defaulting applied, the database write, and the read model or cache that serves the screen. Compare the values in order and mark the first layer where the value changes without a documented rule. Check the usual suspects at that layer: decimal precision and rounding, currency conversion, timezone conversion on dates, character encoding, field truncation, a mapping that drops or merges fields, a stale cache, and an asynchronous update that has not yet been applied.\n\nFor the address, check the mapping from the channel fields to the message: whether the structured or hybrid address carries Town Name and Country Code as a minimum, whether any field is truncated by a length limit, and whether the mapping preserves the address the customer entered. Where a legacy MT message lacks a value the ISO 20022 message requires, do not fabricate it: check whether the value can be derived from trusted contextual data such as the settlement arrangement, document the derivation rule, and hold the payment for repair if no reliable derivation exists. Once the divergence is found, assign the fix to the owning layer, correct the affected record through a controlled process, and add a lineage check so the same field is compared across layers in regression testing.", "flow_steps": [{"step": 1, "actor": "Business Analyst", "action": "Select one affected record and its stable identifier for the trace", "system": "Investigation record"}, {"step": 2, "actor": "Channel Team", "action": "Provide the screen value and the customer input as captured", "system": "Channel logs"}, {"step": 3, "actor": "Integration Engineer", "action": "Provide the API request payload as received", "system": "API gateway logs"}, {"step": 4, "actor": "Integration Engineer", "action": "Show the canonical transformation, validation and defaulting applied", "system": "Service logs"}, {"step": 5, "actor": "Database Team", "action": "Provide the persisted record and the write timestamp", "system": "Database query"}, {"step": 6, "actor": "Business Analyst", "action": "Compare values layer by layer and mark the first divergence", "system": "Lineage record"}, {"step": 7, "actor": "Owning Team", "action": "Fix the layer, correct the record and add a lineage check", "system": "Defect record"}], "happy_path": "The first point of divergence is evidenced and assigned to the owning layer, the affected record is corrected through a controlled process, and the address mapping carries the required structured or hybrid address without truncation. The lineage check runs in regression testing so the same field is compared across layers before the next release.", "negative_paths": [{"path": "Rounding changes the amount", "trigger": "A transformation rounds the amount to two decimals at the wrong step.", "handling": "Correct the precision rule, document it in the field dictionary, and revalidate affected records."}, {"path": "Stale cache serves an old value", "trigger": "The screen reads a cached read model that has not yet received the latest update.", "handling": "Invalidate or refresh the cache on write, and show the authoritative value while the update is pending."}, {"path": "Address field truncated in mapping", "trigger": "The message mapping cuts the address to a length the scheme does not support.", "handling": "Fix the mapping to carry the full structured or hybrid address with Town Name and Country Code as a minimum."}, {"path": "Mandatory MX value absent in MT source", "trigger": "A legacy MT message lacks a value the ISO 20022 message requires.", "handling": "Do not fabricate the value; derive it only from trusted contextual data with a documented rule, or hold the payment for repair."}], "technical_data": "Create a field lineage record for the affected fields: source system, field name, transformation rule, owner, and the layer where each change happens. Store the captured values at each layer with the record identifier, timestamp and source log, using masked production evidence where customer data is involved. Keep the source-to-target mapping with its version, the derivation catalogue for any derived value, and the original source message for audit. Log every correction with operator, old and new value, timestamp and checker.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment initiation carrying the amount and beneficiary address", "key_fields": ["Instruction identification and end-to-end identification", "Amount and currency", "Creditor name and structured or hybrid address", "Debtor and creditor account details"]}, {"message": "pacs.008", "purpose": "Customer credit transfer leg, mapped from MT103 where applicable", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Structured or hybrid address with Town Name and Country Code as a minimum", "Remittance information"]}, {"message": "pacs.009", "purpose": "Financial institution transfer leg, mapped from MT202 COV where applicable", "key_fields": ["Interbank settlement amount and currency", "Cover payment details", "Settlement information"]}, {"message": "camt.053", "purpose": "Account statement used to confirm the persisted amount against the ledger", "key_fields": ["Account identification", "Entry amount, date and reference", "Balance after each entry"]}], "accounting_operational": "Until the divergence is resolved, the payment must not be released on an uncertain amount or address: hold it in a controlled state and reconcile the screen value, the API payload and the database record against the ledger entry before release. If the persisted amount differs from the amount the customer authorised, the customer must be told and must confirm the corrected instruction. Operations need a data-quality worklist for records whose layers disagree, with ageing and service levels, and a rule that no operator corrects a financial amount without a second approval and a full audit record.", "gherkin": ["Given a field differs across UI, API and DB,", "When the business analyst traces the same record ID layer by layer,", "Then the first point of divergence is evidenced and assigned for correction.", "Given a mandatory target field cannot be reliably derived,", "When transformation runs,", "Then the payment is held for repair rather than populated with an invented value.", "Given a structured address is required,", "When the payment message is built,", "Then the address carries Town Name and Country Code as a minimum, or BIC only, without truncation."], "assessment": [{"question": "What is the first step in tracing a value that differs across layers?", "options": ["Trust the database", "Restart the cache", "Pick one record and follow its stable identifier through every layer", "Ask the customer to resubmit"], "answer": 2, "explanation": "A single stable identifier, such as the end-to-end identification, keeps the comparison about the same record at every layer."}, {"question": "What must never be done when a legacy MT message lacks a value the ISO 20022 message needs?", "options": ["Fabricate a value to fill the field", "Ask the source system", "Hold the payment for repair", "Derive it from trusted data with a documented rule"], "answer": 0, "explanation": "A value must never be fabricated; it is derived only from trusted contextual data with a documented rule, or the payment is held for repair."}, {"question": "Which fields are the minimum for a structured or hybrid address?", "options": ["Town Name and Country Code, or BIC only", "Street name only", "Country name only", "Postcode only"], "answer": 0, "explanation": "The requirement stands at structured or hybrid address with a minimum of Town Name and Country Code, or BIC only."}, {"question": "Why is a fixed structured-address cut-off date not taught in this case?", "options": ["The deadline was extended in July 2026 and a new timeline is expected by December 2026", "It only applies to domestic payments", "It applies only to direct debits", "The requirement was removed"], "answer": 0, "explanation": "The SWIFT structured-address deadline was extended in July 2026, so no fixed cut-off date should be taught."}]}}, {"id": "INS-058", "kind": "insight", "title": "Two-week BA sprint for a Payment API integration", "topic": "Two-week BA sprint for a Payment API integration", "theme": "Sprint execution", "text": "Follow discovery, analysis, documentation, design, refinement, dev support, SIT, UAT and release readiness.", "domain": "APIs & Agile Delivery", "area": "APIs & Agile Delivery", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch26s8", "title": "System design deep dive: payment APIs at scale", "url": "lessons/ch26s8"}, "case": {"status": "authored", "business_problem": "Northgate Retail needs a Payment API integration delivered in a two-week sprint. The retailer's checkout must submit payment instructions to Crestline Bank, receive a clear acceptance or rejection, and create the order only when the payment outcome is known. The sprint has a fixed end date because the retailer has a trading peak approaching, and the team is small: one business analyst, two developers, one tester and a part-time architect. The product owner has a long list of wants, the bank's API documentation is mostly complete but silent on several edge cases, and nobody has yet agreed what the API response actually promises: receipt, validation, acceptance or completion.\n\nThe learner must run the sprint as a business analyst, not as a bystander. That means discovery and analysis in the first days, documentation that developers can build from, design and refinement with the bank's integration team, development support during the build, and SIT, UAT and release readiness before the sprint ends. The case tests prioritisation under a fixed deadline: the sprint cannot deliver everything, so the analyst must separate the minimum viable integration from the nice-to-have features, and must surface the risky unknowns early, such as what happens when the API returns success but the order is not created, and what happens when SIT passes but production behaves differently.", "decision_exercise": {"scenario": "Northgate Retail needs a Payment API integration with Crestline Bank delivered in a two-week sprint before a trading peak. The checkout must submit payments, receive a clear outcome, and create orders only when the payment outcome is known. You are the business analyst on a small team with a fixed end date.", "options": [{"id": "A", "text": "Accept the full product owner list into the sprint and work longer hours to deliver it all."}, {"id": "B", "text": "Build the happy path only and handle failures after go-live, since the peak is approaching."}, {"id": "C", "text": "Write the full specification first and start development only when it is complete, since accuracy matters more than the sprint date."}, {"id": "D", "text": "Prioritise the minimum viable integration, clarify the response contract and edge cases early, support development daily, and gate release on SIT, UAT and readiness evidence."}], "correct_option": "D", "why": "Option D is correct because a fixed-date sprint needs ruthless prioritisation, early clarification of the risky unknowns, and a release gate based on evidence. Option A overloads the sprint and guarantees a late or broken delivery. Option C spends the sprint writing and leaves no time to build or test. Option B ships a checkout that cannot handle the failures customers will actually meet."}, "recommended_solution": "Start the sprint with discovery compressed into the first two days: confirm the business outcome, the checkout journey, the payment types in scope, the expected volumes, and the response contract. The contract question matters most: agree in writing what each response means, so that an acceptance response is never mistaken for completion, and define the status enquiry path the retailer uses when a response is missing. Clarify the edge cases with the bank early: timeouts, duplicate submissions, callbacks that never arrive, and amounts near the product limits. Write the analysis as buildable documentation: field definitions, validation rules, error codes, idempotency, correlation IDs, and acceptance criteria in Given When Then form.\n\nDuring development, support the developers daily: answer questions the same day, refine stories as the bank's answers arrive, and keep the documentation current when a decision changes. Plan SIT around the integration boundaries, not only the happy path: test each failure mode, each error code and each retry. Run UAT with real checkout journeys and production-shaped data, and check release readiness before the sprint ends: environment parity, certificates, credentials, rate limits, monitoring, rollback and the support runbook. If scope must be cut, cut features, never the failure handling, the reconciliation or the release evidence, and record the cut with the product owner.", "flow_steps": [{"step": 1, "actor": "Business Analyst", "action": "Confirm business outcome, journey, scope and response contract in sprint days one and two", "system": "Sprint backlog"}, {"step": 2, "actor": "Business Analyst", "action": "Clarify edge cases with the bank integration team and document decisions", "system": "API contract record"}, {"step": 3, "actor": "Business Analyst", "action": "Write field definitions, validation, errors, idempotency and acceptance criteria", "system": "Requirements pack"}, {"step": 4, "actor": "Developers", "action": "Build the integration with daily analyst support and refinement", "system": "Sprint board"}, {"step": 5, "actor": "Tester", "action": "Run SIT across happy path, failure modes, retries and callbacks", "system": "Test evidence"}, {"step": 6, "actor": "Business Analyst", "action": "Run UAT with real checkout journeys and confirm release readiness", "system": "Release checklist"}, {"step": 7, "actor": "Product Owner", "action": "Accept or cut scope on evidence and approve the release decision", "system": "Sprint review record"}], "happy_path": "The sprint delivers a working integration that submits payments, interprets responses correctly, handles timeouts, duplicates and missing callbacks, and creates orders only when the payment outcome is known. SIT and UAT evidence is filed, the release checklist passes, and the deferred scope is recorded with the product owner rather than silently dropped.", "negative_paths": [{"path": "API returns success but no order is created", "trigger": "The response promises receipt, but the event or callback that creates the order is lost.", "handling": "Trace the correlation ID across gateway, service, event bus and order system, reconcile the financial effect, and recover the order exactly once."}, {"path": "SIT passes but production fails", "trigger": "Production differs in configuration, certificates, network or data.", "handling": "Compare environments before blaming code, and retest with production-shaped payloads."}, {"path": "Pre-production data mismatch near go-live", "trigger": "SIT and UAT passed but pre-production data does not match.", "handling": "Assess whether the mismatch is representative and release-critical, and delay or proceed only through formal risk acceptance."}, {"path": "Scope pressure threatens failure handling", "trigger": "The product owner asks to cut error handling to fit more features.", "handling": "Refuse the cut: failure handling, reconciliation and release evidence are part of the minimum viable integration."}], "technical_data": "Keep one contract record with the API version, the field definitions, the validation rules, the error catalogue, the idempotency rule, the correlation ID flow and the status enquiry path, all versioned together. Persist the idempotency key, payload hash, correlation ID, original payment reference and outcome for every submission, and log the request and response at each boundary. Store SIT and UAT evidence with build version, environment and date, and keep the release checklist with the parity, certificate, credential and monitoring checks signed off.", "messages_fields": [{"message": "pain.001", "purpose": "Checkout payment instruction submitted through the API", "key_fields": ["Instruction identification and end-to-end identification", "Debtor and creditor account details", "Amount and currency", "Idempotency key in the API request"]}, {"message": "pacs.008", "purpose": "Credit transfer created from an accepted instruction", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference for reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report used by the retailer to confirm the outcome", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "A payment accepted by the API but not yet confirmed must not create an order, and an order must not be created twice from a retried submission. The retailer and the bank reconcile on the correlation ID and the payment reference, and ambiguous payments sit in a controlled recovery state with a service level for resolution. Operations need a worklist of unreconciled submissions, monitoring on callback and event delivery, and a runbook that tells support exactly what to check before telling a customer the payment succeeded or failed. The sprint's success is measured by clean reconciliation after the peak, not only by a launch on the planned date.", "gherkin": ["Given the API accepts a request,", "When the retailer acts on the response,", "Then it treats the response as receipt or acceptance as the contract states, and confirms completion through status enquiry or events.", "Given a callback is missing,", "When the order system checks the payment,", "Then it uses the correlation ID and status enquiry to determine the outcome before creating or cancelling the order.", "Given a pre-production data mismatch is found,", "When release readiness is assessed,", "Then unexplained material differences block approval until resolved or formally risk-accepted."], "assessment": [{"question": "What must be agreed first about an API response?", "options": ["What the response promises: receipt, validation, acceptance or completion", "The retry count", "The response time only", "The colour of the checkout button"], "answer": 0, "explanation": "The response contract defines what success means, and mistaking receipt for completion is how orders are created for payments that never completed."}, {"question": "What should be cut first when a fixed-date sprint is overloaded?", "options": ["Release evidence", "Failure handling", "Features outside the minimum viable integration", "Reconciliation"], "answer": 2, "explanation": "Features can be deferred, but failure handling, reconciliation and release evidence are part of the minimum viable integration."}, {"question": "Why is SIT alone not enough evidence for go-live?", "options": ["SIT has no testers", "SIT is too slow", "Production can differ in configuration, certificates, network, limits and data", "SIT never tests the happy path"], "answer": 2, "explanation": "SIT passing does not prove production will behave the same way, because environments differ in ways that only parity checks and pre-production testing expose."}, {"question": "How should a missing callback be handled?", "options": ["Create the order anyway", "Resubmit immediately", "Trace the correlation ID and use status enquiry to determine the outcome", "Assume the payment failed"], "answer": 2, "explanation": "A missing callback leaves the outcome unknown, so the correlation ID and status enquiry must establish it before the order is created or the payment is retried."}]}}, {"id": "INS-059", "kind": "insight", "title": "Defining request and response expectations", "topic": "Defining request and response expectations", "theme": "API contract", "text": "Specify required/optional fields, validation, errors, status semantics, correlation and idempotency.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch47s8", "title": "OpenAPI contracts: designing a payment API contract", "url": "lessons/ch47s8"}, "case": {"status": "authored", "business_problem": "Crestline Bank is publishing a Payment API for corporate customers and retail partners, and the first draft of the contract is a list of fields with no rules. It does not say which fields are required and which are optional, what happens when a field is missing, which error code means what, whether a success response means the payment completed, or how a caller should safely retry. Two early consumers have already built against the draft and made opposite assumptions: one treats an acceptance response as proof the money moved, the other polls for a status that never arrives. The bank's reporting team has also asked for a field the API draft marks optional, and nobody has decided whether the bank will require it, derive it, or handle its absence.\n\nThe learner must write a contract that a consumer can build against without guessing. That means specifying required and optional fields, validation rules, error semantics, status semantics, correlation and idempotency, and the difference between scheme-level optionality and the bank's own product requirements. The scheme facts anchor the content: instant euro payments must complete within 10 seconds with no scheme-level maximum since the 2025 rulebook change, and Verification of Payee is mandatory for instant euro payments from 9 October 2025. The contract must also survive change: a future field rename or rulebook update must not silently break the consumers who built against version one.", "decision_exercise": {"scenario": "Crestline Bank is publishing a Payment API. The draft lists fields but no rules: nothing says which fields are required, what errors mean, whether success means completion, or how to retry safely. Two consumers have already built opposite assumptions. You are the business analyst asked to define the contract.", "options": [{"id": "A", "text": "Mark every field required, since that is the safest way to get complete data."}, {"id": "B", "text": "Rename fields freely in each release and promise that a success response means the money has moved, since consumers can adapt and want certainty."}, {"id": "C", "text": "Specify required and optional fields, validation, error semantics, status semantics, correlation and idempotency, and distinguish scheme optionality from the bank's own product requirements."}, {"id": "D", "text": "Publish the field list as the contract and let consumers ask questions when they get stuck."}], "correct_option": "C", "why": "Option C is correct because a usable contract must answer every question a consumer needs to build against it, and must separate what the scheme allows from what the bank requires. Option D leaves consumers guessing. Option A forces callers to supply data they may not have. Option B breaks existing consumers without warning and misstates what a success response guarantees."}, "recommended_solution": "Define every field with its name, type, cardinality, validation rule and error code, and state explicitly which fields are required, which are optional, and which are conditionally mandatory by rail, destination or product. Where a field is optional under the message schema but the bank's reporting or product needs it, say so in the contract: state the source the bank will use, the derivation rule if one exists, and the exception path when no trusted value is available, and never invent a value to satisfy reporting. Define the response contract in the same precision: which response means receipt, which means validation passed, which means acceptance, and which means completion, with the status enquiry path for every case where completion is not yet known. Specify idempotency: the key, its scope, its retention, and what the API returns for a retry with the same key and for a retry with the same key and a changed payload. Specify correlation: the ID the caller supplies, the ID the bank returns, and where each appears in logs, events and status reports.\n\nDefine the error catalogue with one meaning per code, the retry policy per error, and the rate limits with their headers and behaviour. Then govern change: version the contract explicitly, prefer additive evolution, give a deprecation period for any breaking change, assess consumer impact before release, and run contract tests against every known consumer. When a scheme rulebook update changes a mandatory field or a deadline, run the rule impact analysis across channels, the canonical model, validation, mapping and operations, and apply the new rule from its effective date with versioned configuration.", "flow_steps": [{"step": 1, "actor": "Business Analyst", "action": "Draft field definitions with cardinality, validation and error codes", "system": "API contract"}, {"step": 2, "actor": "Business Analyst", "action": "Define response and status semantics with the status enquiry path", "system": "API contract"}, {"step": 3, "actor": "Payments Architect", "action": "Define the canonical model so distinct source fields keep their meaning", "system": "Architecture repository"}, {"step": 4, "actor": "Reporting Lead", "action": "Confirm which optional fields reporting needs and the exception path", "system": "Data requirements"}, {"step": 5, "actor": "Integration Engineer", "action": "Define idempotency, correlation and retry behaviour", "system": "API contract"}, {"step": 6, "actor": "Business Analyst", "action": "Publish version one with the deprecation and change policy", "system": "API catalogue"}, {"step": 7, "actor": "Test Lead", "action": "Run contract tests against every known consumer", "system": "Test evidence"}], "happy_path": "Consumers build against a contract that answers every integration question without guessing: required, optional and conditionally mandatory fields are explicit, errors have one meaning each, success means what the contract says it means, retries are safe, and version one consumers keep working through the agreed migration window when the contract evolves.", "negative_paths": [{"path": "Optional field required by reporting", "trigger": "A field is optional in the message schema but a report needs it.", "handling": "State the trusted source or derivation, or follow the defined exception path; never invent a value."}, {"path": "Canonical model loses source semantics", "trigger": "Two channels send similar fields with different meanings and the model collapses them.", "handling": "Preserve the distinction in the canonical model with provenance and scheme-specific extensions."}, {"path": "Breaking field rename proposed", "trigger": "A new API version renames a field an active consumer uses.", "handling": "Run the consumer impact assessment, provide a deprecation period and migration plan, and keep version one working until the window ends."}, {"path": "Scheme rule changes mandatory data", "trigger": "A rulebook update changes a required field or deadline.", "handling": "Run rule impact analysis and apply the versioned rule from its effective date with parallel testing."}], "technical_data": "Version the contract, the field dictionary and the error catalogue together, and keep a consumer inventory so a breaking change can be assessed against every known caller. Store the canonical model with field ownership, cardinality, transformation rules and lineage, and keep the mapping from each source field to the canonical field with its provenance. Log requests and responses with the correlation ID and the idempotency key, and keep contract test results per consumer and per version as release evidence.", "messages_fields": [{"message": "pain.001", "purpose": "Payment instruction submitted through the API", "key_fields": ["Instruction identification and end-to-end identification", "Debtor and creditor account details", "Amount and currency", "Idempotency key and correlation ID"]}, {"message": "pacs.008", "purpose": "Credit transfer created from an accepted instruction, including instant payments within the 10-second limit", "key_fields": ["Interbank settlement amount and currency with no scheme-level maximum", "Creditor agent and account", "Verification of Payee result", "Instruction reference for reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report that gives the authoritative outcome", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}], "accounting_operational": "A contract that misstates what success means creates real financial harm: a consumer that treats acceptance as completion will fulfil orders for payments that later fail, and a consumer that retries blindly will duplicate debits. The contract must therefore make the financial states explicit, and operations must reconcile API submissions against the ledger on the correlation ID and the payment reference, with a worklist for submissions whose outcome is unknown. Rate limits and error handling must be monitored as operational controls, and any consumer that repeatedly breaches the contract must be contacted before it is throttled, so a business problem is not mistaken for a technical one.", "gherkin": ["Given a field is optional in the message schema but mandatory for the bank's product,", "When the contract is written,", "Then the bank's requirement, its source and its exception path are stated explicitly.", "Given two source fields with different business meaning,", "When mapped to the canonical model,", "Then their semantics remain distinguishable.", "Given a breaking schema change is proposed,", "When compatibility assessment identifies active consumers,", "Then migration and versioning are agreed before release."], "assessment": [{"question": "Can a field be optional in ISO 20022 but mandatory for the bank's product?", "options": ["Only if the customer agrees", "No, scheme optionality always wins", "Yes, the bank may require it for its product or reporting, with a stated source and exception path", "Only for direct debits"], "answer": 2, "explanation": "Scheme optionality and product requirements are different layers; the bank must state its own requirement, its source and what happens when no trusted value exists."}, {"question": "What must a contract state about a success response?", "options": ["Nothing, success is obvious", "That the order should be created", "That the money has moved", "Exactly what it promises: receipt, validation, acceptance or completion, and how to confirm completion"], "answer": 3, "explanation": "Success at the transport level is not completion, so the contract must say what each response means and how completion is confirmed."}, {"question": "How should a breaking field rename be handled?", "options": ["Never rename anything", "Assess consumer impact, provide a deprecation period and a migration plan", "Rename it silently", "Rename it and tell consumers afterwards"], "answer": 1, "explanation": "Breaking changes need a consumer impact assessment, a deprecation period and a migration plan, with the old version working until the window ends."}, {"question": "What is the maximum execution time for an instant euro payment under the current rules?", "options": ["10 seconds", "60 seconds", "5 minutes", "One business day"], "answer": 0, "explanation": "The maximum execution time for an instant euro payment is 10 seconds under Regulation (EU) 2024/886."}]}}, {"id": "INS-060", "kind": "insight", "title": "BA role in SIT defect discussions", "topic": "BA role in SIT defect discussions", "theme": "SIT defects", "text": "Assess reproducibility, requirement traceability, business impact, fix validation and regression.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s2", "title": "Test Levels: Unit, SIT, UAT and Regression", "url": "lessons/ch42s2"}}, {"id": "INS-061", "kind": "insight", "title": "BA support during deployment and hypercare", "topic": "BA support during deployment and hypercare", "theme": "Production monitoring", "text": "Monitor critical journeys, exception rates, unresolved transactions and stakeholder updates.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch44s5", "title": "Operational Controls, Queues and Exception Handling", "url": "lessons/ch44s5"}}, {"id": "INS-062", "kind": "insight", "title": "Gateway response succeeds but order system receives no callback", "topic": "Gateway response succeeds but order system receives no callback", "theme": "API failure", "text": "Trace event/callback delivery, correlation ID, retries, persistence and customer impact.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch80s7", "title": "Webhooks and event delivery: signatures, retries, ordering and replay", "url": "lessons/ch80s7"}, "case": {"status": "authored", "business_problem": "Northgate Retail runs a checkout where the payment gateway returns a success response, the customer sees a confirmation screen, and then nothing happens: the order system never receives the callback, so no order is created, no goods are picked, and the customer is charged for a purchase the retailer cannot see. The failure is intermittent, which makes it worse: most checkouts work, so the team assumes the occasional failure is a customer problem, until the finance team finds a growing list of payments with no matching order. The retailer and the bank each insist their side worked, because each side can show a successful record: the gateway shows a successful payment, and the order system shows no order was ever requested.\n\nThe learner must trace the event and callback delivery across the whole chain and establish what the gateway response actually promised. A success response at the gateway may mean only that the payment was accepted, not that the downstream order was created, and the callback that bridges the two can be lost, delayed, duplicated or delivered to the wrong endpoint. The case also carries a cross-border instant payment dimension: where the sender is debited and the receiving system reports a technical failure or no final response, the bank must determine whether the debit is provisional, final or held, and resolve it without both crediting the beneficiary and refunding the sender. The discipline throughout is exactly-once financial effect with a recoverable state for everything uncertain.", "decision_exercise": {"scenario": "Northgate Retail's checkout shows customers a payment success, but the order system receives no callback and creates no order, while the customer has been charged. The failure is intermittent and both the gateway and the order system claim their side worked. You are the business analyst asked to trace the failure and define the recovery.", "options": [{"id": "A", "text": "Trace the correlation ID across gateway, payment service, event bus and order system, determine what the gateway response promised, reconcile the financial effect, and recover each payment exactly once."}, {"id": "B", "text": "Tell affected customers to place the order again, since the first payment will be refunded automatically."}, {"id": "C", "text": "Assume the callback was lost and replay all callbacks from the last 24 hours."}, {"id": "D", "text": "Change the checkout to create the order before the payment, so a missing callback cannot block fulfilment."}], "correct_option": "A", "why": "Option A is correct because only a traced, reconciled recovery can establish the true state of each payment and correct it exactly once. Option B creates a second charge before the first is resolved. Option C replays callbacks blindly, which can duplicate orders for payments that already succeeded late. Option D creates orders for payments that may never complete."}, "recommended_solution": "Start by containing the impact: identify every payment with no matching order, stop telling customers a payment succeeded until its outcome is known, and give support a holding message that is honest about the uncertainty. Then trace one affected payment end to end using its correlation ID: the gateway request and response, the payment service state, the event published to the bus, the callback delivery attempts and their responses, and the order system intake. Determine what the gateway response actually promised: receipt, validation, acceptance or completion, and check whether the contract allows the retailer to treat it as completion. Inspect the callback configuration, the endpoint, the retry policy, the dead-letter queue and the persistence of the event, because a callback lost in any of those places leaves the same symptom.\n\nFor each affected payment, establish the financial state before acting: was the sender debited, is the debit provisional, final or held, and has the beneficiary been credited? Where a cross-border instant leg is involved and the receiving system reported a technical failure or no final response, use the scheme rules and the leg status to decide whether to await confirmation, return funds or open a controlled investigation, and never allow both a beneficiary credit and a sender refund for the same payment. Recover each case exactly once: create the missing order where the payment completed, or refund where it did not, with a unique recovery reference linked to the original payment. Then fix the delivery: durable events with an outbox, idempotent consumers, a status enquiry path the order system can use when a callback is missing, alerting on callback failures and dead-letter depth, and a reconciliation that matches payments to orders every day.", "flow_steps": [{"step": 1, "actor": "Support Lead", "action": "Identify payments with no matching order and give support a holding message", "system": "Incident record"}, {"step": 2, "actor": "Business Analyst", "action": "Trace one payment by correlation ID across gateway, service, event bus and order system", "system": "Distributed traces"}, {"step": 3, "actor": "Integration Engineer", "action": "Inspect callback configuration, retries, dead-letter queue and event persistence", "system": "Gateway and event logs"}, {"step": 4, "actor": "Business Analyst", "action": "Determine what the gateway response promised under the contract", "system": "API contract"}, {"step": 5, "actor": "Finance Operations", "action": "Establish the financial state of each affected payment before recovery", "system": "Core ledger"}, {"step": 6, "actor": "Integration Engineer", "action": "Fix delivery with durable events, idempotent consumers and status enquiry", "system": "Payment platform"}, {"step": 7, "actor": "Business Analyst", "action": "Reconcile payments to orders daily and report recovery status", "system": "Reconciliation report"}], "happy_path": "Every affected payment is resolved exactly once: orders are created where payment completed, refunds are issued where it did not, and no payment is both credited to a beneficiary and refunded to the sender. Callback delivery is durable and observable, the order system can enquire on status when a callback is missing, and daily reconciliation matches payments to orders so the next failure is found by the bank, not by the customer.", "negative_paths": [{"path": "Callback lost in transit", "trigger": "The gateway sends the callback but the network or the endpoint drops it.", "handling": "Retry with backoff, record delivery attempts, and let the order system enquire on status when no callback arrives within the agreed window."}, {"path": "Event consumer failed", "trigger": "The event is published but the order consumer crashes before creating the order.", "handling": "Use durable events and idempotent consumers so a redelivered event creates the order once."}, {"path": "Late success after timeout", "trigger": "The payment succeeds after the retailer has already treated it as failed.", "handling": "Resolve by the payment reference and correlation ID: one outcome wins, and a refund and a credit must never both happen."}, {"path": "Ledger posting succeeds but status update fails", "trigger": "The core ledger records the debit but the payment platform stays in an earlier state.", "handling": "Replay the missing event idempotently using the original posting reference, without reposting the debit."}], "technical_data": "Persist the correlation ID, the idempotency key, the payment reference, the gateway response, the callback delivery attempts with their responses, and the event publication record, all linked so one trace shows the whole chain. Use durable event publication, such as the outbox pattern, so a ledger posting and its status event cannot diverge silently. Store the contract definition of each response, the callback endpoint and retry policy with their versions, and log every recovery action with operator, timestamp, original reference and recovery reference.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment instruction submitted at checkout", "key_fields": ["Instruction identification and end-to-end identification", "Debtor and creditor account details", "Amount and currency", "Correlation ID carried through the chain"]}, {"message": "pacs.008", "purpose": "Credit transfer leg for the payment, including the cross-border instant leg where applicable", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference for reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report giving the authoritative outcome when a callback is missing", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}, {"message": "camt.053", "purpose": "Account statement confirming whether the sender debit exists", "key_fields": ["Account identification", "Entry amount, date and reference", "Balance after each entry"]}], "accounting_operational": "Until the outcome is known, an affected payment sits in a controlled recovery state: the debit is either provisional, final or held, and no operator creates an order or issues a refund until the state is established. Reconciliation matches every gateway payment to an order or a refund each day, and unmatched items age into a worklist with service levels and an owner. The financial rule is absolute: exactly one financial effect per genuine payment, so a late success must cancel a planned refund, and a refund must cancel a planned fulfilment, with both decisions recorded against the same payment reference.", "gherkin": ["Given a timeout followed by a late success,", "When the late event is received,", "Then the system resolves the transaction without both crediting the beneficiary and refunding the sender.", "Given the API accepted a request but the downstream record is absent,", "When the case is traced,", "Then the same correlation ID is followed across each integration boundary and the failed transition is identified.", "Given a ledger posting exists but the status event is missing,", "When recovery runs,", "Then the payment state is updated using the original posting reference without reposting the debit."], "assessment": [{"question": "What does a gateway success response guarantee?", "options": ["Only what the contract says it promises, which may be receipt or acceptance rather than completion", "That the money arrived", "That the callback was delivered", "That the order was created"], "answer": 0, "explanation": "A gateway response promises only what the contract defines; completion must be confirmed by status enquiry, events and reconciliation."}, {"question": "What is the first safe step for a payment with no matching order?", "options": ["Replay all callbacks", "Tell the customer to pay again", "Create the order immediately", "Establish the financial state before creating an order or issuing a refund"], "answer": 3, "explanation": "Acting before the financial state is known risks a duplicate order, a duplicate charge, or both a credit and a refund."}, {"question": "Why must event consumers be idempotent?", "options": ["It removes the need for callbacks", "So a redelivered event creates the order once instead of twice", "It speeds up the gateway", "It makes them faster"], "answer": 1, "explanation": "Idempotent consumers ensure a redelivered event updates state once, which is what makes recovery by replay safe."}, {"question": "What prevents a payment being both credited and refunded after a late success?", "options": ["Resolving by payment reference and correlation ID so one outcome wins", "A faster callback", "A new gateway", "A larger rate limit"], "answer": 0, "explanation": "A single resolution keyed on the payment reference and correlation ID ensures one outcome wins and the other is cancelled."}]}}, {"id": "INS-063", "kind": "insight", "title": "Coordinating business, dev, QA, gateway and support", "topic": "Coordinating business, dev, QA, gateway and support", "theme": "Cross-team coordination", "text": "Establish one incident view, clear owners, evidence requests and update cadence.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s8", "title": "Production support and root cause analysis: keeping payments running", "url": "lessons/ch84s8"}}, {"id": "INS-064", "kind": "insight", "title": "\u20b918,500 debit but e-commerce order remains pending", "topic": "\u20b918,500 debit but e-commerce order remains pending", "theme": "Production incident", "text": "Trace gateway, bank, merchant callback and order creation; determine fulfilment versus refund path.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s5", "title": "Ledger Posting versus Settlement", "url": "lessons/ch68s5"}, "case": {"status": "authored", "business_problem": "A customer of Northgate Retail pays Rs 18,500 for an order through the retailer's checkout. The bank account is debited, the payment gateway reports success, and the order remains pending: no confirmation, no dispatch, no delivery date. The customer contacts support, who can see the debit in the bank statement but cannot see the order, and the retailer cannot tell the customer whether the goods will arrive or the money will come back. The amount matters for the investigation: Rs 18,500 is well within the usual bank cap of around Rs 5 lakh for IMPS, and within the UPI limit of INR 5 lakh for specified categories, so the failure is not a limit breach. It is a state failure: the money moved, or appears to have moved, while the order state did not.\n\nThe learner must trace the payment through the gateway, the bank, the merchant callback and the order creation, and then decide between the two possible endings: fulfilment or refund. That decision cannot be made from the customer's statement alone, nor from the gateway's success alone. It needs the ledger entry, the gateway record, the callback delivery record and the order system state, all matched on the same reference. The case also tests the recovery discipline for the amount in question: a Rs 18,500 debit that is not matched to an order must be resolved through a controlled process with a reference the customer can quote, not through an informal promise that the money will come back.", "decision_exercise": {"scenario": "A customer pays Rs 18,500 at Northgate Retail. The bank account is debited and the gateway reports success, but the order remains pending with no confirmation or dispatch. Support can see the debit but cannot see the order. You are the business analyst asked to trace the payment and decide whether the customer gets fulfilment or a refund.", "options": [{"id": "A", "text": "Treat the gateway success as proof the order will be fulfilled and tell the customer to wait."}, {"id": "B", "text": "Tell the customer the money will be refunded automatically and close the case."}, {"id": "C", "text": "Trace the gateway, bank, merchant callback and order creation on the same reference, establish whether the payment completed, and then fulfil the order or refund through a controlled process with a reference."}, {"id": "D", "text": "Ask the customer to pay again so the order can be created, and sort out the first debit later."}], "correct_option": "C", "why": "Option C is correct because only a traced, evidenced decision can choose between fulfilment and refund, and either ending needs a controlled process with a reference. Option B promises a refund before knowing whether the payment completed. Option D takes a second Rs 18,500 before the first is resolved. Option A treats a gateway success as proof of an order that the order system never created."}, "recommended_solution": "Start by fixing the reference: take the payment reference from the customer's bank statement and the gateway transaction ID, and confirm they belong to the same payment. Then trace the four boundaries in order. First, the gateway: did it authorise and capture the payment, what response did it return, and what callback did it send? Second, the bank: does the ledger show a debit of Rs 18,500, on which rail, and with what status? The rail matters for the timeline: IMPS is instant and typically bank-capped around Rs 5 lakh, NEFT settles in half-hourly batches, RTGS settles individually in real time with a minimum of Rs 2 lakh, and UPI allows INR 5 lakh for specified categories, so a Rs 18,500 payment could have travelled on IMPS or UPI without breaching a limit, and the rail record shows whether settlement completed. Third, the merchant callback: was it delivered, did the endpoint acknowledge it, and does the dead-letter queue hold it? Fourth, the order system: was an order created, in what state, and is it linked to the payment reference?\n\nOnce the four boundaries are known, the decision follows the evidence. If the payment completed and the callback was lost, create the order from the payment record exactly once and confirm fulfilment to the customer with the order reference. If the payment did not complete, or the debit is provisional and will not settle, refund the Rs 18,500 through the controlled process with a refund reference, a date and a written confirmation. If the state is still uncertain after the trace, hold the payment in a controlled recovery state, tell the customer what is known, what is being checked and when the next update will come, and do not promise a date the bank cannot guarantee. Record every step against the same reference so the customer, support and finance all see one story.", "flow_steps": [{"step": 1, "actor": "Support Lead", "action": "Capture the payment reference and gateway transaction ID and open the case", "system": "Case record"}, {"step": 2, "actor": "Business Analyst", "action": "Trace the gateway record, response and callback delivery", "system": "Gateway logs"}, {"step": 3, "actor": "Finance Operations", "action": "Confirm the ledger debit of Rs 18,500, the rail and the settlement status", "system": "Core ledger"}, {"step": 4, "actor": "Integration Engineer", "action": "Check callback delivery, endpoint acknowledgement and dead-letter queue", "system": "Merchant callback logs"}, {"step": 5, "actor": "Business Analyst", "action": "Check the order system for an order linked to the payment reference", "system": "Order system"}, {"step": 6, "actor": "Business Analyst", "action": "Decide fulfilment or refund on the evidence and record the decision", "system": "Case record"}, {"step": 7, "actor": "Customer Support", "action": "Confirm the outcome to the customer with the order or refund reference", "system": "Customer communications"}], "happy_path": "The customer receives one clear outcome: either the order is created and confirmed with an order reference and a delivery expectation, or the Rs 18,500 is refunded with a refund reference and a date. The payment, the callback, the ledger entry and the order are all linked on the same reference, and the case record shows the evidence the decision rested on.", "negative_paths": [{"path": "Gateway success but callback lost", "trigger": "The payment completed but the callback that creates the order never arrived.", "handling": "Create the order from the payment record exactly once and confirm fulfilment with the order reference."}, {"path": "Debit provisional and payment not settled", "trigger": "The bank shows a debit but the rail record shows the payment did not complete.", "handling": "Refund through the controlled process with a refund reference and a written confirmation."}, {"path": "Late success after a refund was promised", "trigger": "The payment completes after support has already told the customer a refund is coming.", "handling": "Cancel the refund, create the order, and tell the customer what changed and why, with the new reference."}, {"path": "Duplicate charge on retry", "trigger": "The customer paid again while the first payment was unresolved.", "handling": "Reverse the duplicate exactly once through the controlled process and link both payments to the same case."}], "technical_data": "Persist the payment reference, the gateway transaction ID, the correlation ID, the ledger entry reference, the callback delivery attempts and the order reference in one case record, so any team can follow the same payment. Log the rail and settlement status with the amount, currency and timestamp, and keep the customer's statement reference alongside the bank's records. Store the decision, the decision maker and the evidence relied on, and log the fulfilment or refund with its reference, date and operator. Never store full card or account credentials in the case record.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment instruction submitted at checkout", "key_fields": ["Instruction identification and end-to-end identification", "Debtor account and amount of Rs 18,500", "Creditor account of the merchant", "Remittance information identifying the order"]}, {"message": "pacs.008", "purpose": "Credit transfer leg where the payment moves through the payment system", "key_fields": ["Interbank settlement amount and currency", "Creditor agent and account", "Instruction reference for reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report giving the authoritative outcome", "key_fields": ["Original instruction reference", "Status code and reason code", "Timestamp of each status transition"]}, {"message": "camt.053", "purpose": "Account statement confirming the Rs 18,500 debit", "key_fields": ["Account identification", "Entry amount, date and reference", "Balance after the entry"]}, {"message": "camt.054", "purpose": "Debit notification confirming the debit to the account", "key_fields": ["Account identification", "Entry amount, date and reference", "Related payment reference"]}], "accounting_operational": "A Rs 18,500 debit with no order is a real financial break, not a display problem, so reconciliation must treat it as one: match every gateway payment to an order or a refund each day, and age unmatched items into a worklist with service levels and an owner. If the order is fulfilled, the merchant's revenue and the customer's payment reconcile on the same reference. If the money is refunded, the refund is a separate credit to the customer account with its own reference, reconciled separately from the original debit so finance can prove the customer is whole. Operations must be able to answer, for any unmatched debit, how old it is, who owns it, and what the next step is.", "gherkin": ["Given a ledger debit without a matching order,", "When reconciliation runs,", "Then the item is classified as an unmatched break and assigned for investigation.", "Given a payment completed but the callback was lost,", "When the order system recovers,", "Then the order is created exactly once from the payment record.", "Given a payment did not complete,", "When the case is resolved,", "Then the customer is refunded through a controlled process with a refund reference and a written confirmation."], "assessment": [{"question": "Why is the gateway success alone not enough to promise fulfilment?", "options": ["The customer paid by card", "Gateway success may mean acceptance, while the order depends on callback delivery and order creation", "The gateway is slow", "The amount is too small"], "answer": 1, "explanation": "The gateway, the bank, the callback and the order system are separate boundaries, and success at one does not prove the others completed."}, {"question": "Which rail facts are relevant to a Rs 18,500 payment in India?", "options": ["Only RTGS can carry it", "Only NEFT can carry it", "No rail can carry it", "RTGS minimum Rs 2 lakh means it could not have used RTGS; IMPS and UPI can carry it within their limits"], "answer": 1, "explanation": "RTGS has a minimum of Rs 2 lakh, so a Rs 18,500 payment could not have used RTGS, while IMPS and UPI can carry it within their limits."}, {"question": "What should support tell the customer while the outcome is still uncertain?", "options": ["That the order is on its way", "What is known, what is being checked and when the next update will come", "That the money will be back tomorrow", "Nothing until the case closes"], "answer": 1, "explanation": "An honest holding message states what is known, what is being checked and when the next update will come, without promising a date the bank cannot guarantee."}, {"question": "How should a refund be recorded?", "options": ["As a separate credit with its own reference, reconciled separately from the original debit", "By deleting the debit", "As a verbal promise", "By editing the statement"], "answer": 0, "explanation": "A refund is a separate credit with its own reference, reconciled separately from the original debit, so finance can prove the customer is whole."}]}}, {"id": "INS-065", "kind": "insight", "title": "Hundreds of similar complaints within 20 minutes", "topic": "Hundreds of similar complaints within 20 minutes", "theme": "Incident scale", "text": "Quantify affected population, identify common failure window and stop further customer harm.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s8", "title": "Incident communication: who is told, what they are told, and when", "url": "lessons/ch68s8"}, "case": {"status": "authored", "business_problem": "Meridian Bank runs a retail mobile banking service used by several hundred thousand customers. On a weekday morning, between 09:12 and 09:32, the contact centre receives more than 300 complaints with the same shape: customers report a debit that does not match the payment status shown in the app, or a credit they expected that has not appeared. Social media posts repeat the same wording, and branch staff report customers arriving in person with the same concern. The technical cause is not yet known, and the incident bridge has only just been opened.\n\nThe operations team does not yet know how many customers are affected, how much money is involved, or whether the problem is still happening. Some complaints may describe the same underlying payment twice, once from the payer and once from the payee, so a raw complaint count is not an affected population. A second batch file is due to be processed within the hour, and nobody can yet say whether it is safe to release it. Every minute of delay increases customer harm and the risk that a well meant fix, such as a bulk re-credit, creates duplicate compensation.\n\nThe bank must bound the financial exposure, identify the common failure window, stop further harm, and preserve evidence, all before the root cause is known. The case is about sequencing: containment and quantification first, root cause analysis in parallel, and remediation only under maker-checker control once the affected set is proven.", "decision_exercise": {"scenario": "It is 09:35. More than 300 similar complaints have arrived in 20 minutes, the cause is unknown, and a second payment batch is due within the hour. As the duty payments manager, what do you do first?", "options": [{"id": "A", "text": "Open a deep technical investigation into the payment engine logs and wait for the root cause before taking any customer or processing action."}, {"id": "B", "text": "Freeze the next batch, quantify the affected population and value for the 09:12 to 09:32 window, preserve transaction evidence, and open an affected-transaction register before any remediation."}, {"id": "C", "text": "Immediately re-credit every complaining customer in full so complaints stop, then reconcile afterwards."}, {"id": "D", "text": "Tell the contact centre the issue is a display error and ask customers to wait 24 hours while engineering investigates."}], "correct_option": "B", "why": "B is correct because containment and quantification bound the harm: freezing the next batch stops new exposure, the windowed population count separates real impact from duplicate complaints, and the register makes any later remediation auditable. A is wrong because root cause work can run in parallel but must not delay containment. C is wrong because re-crediting on complaint alone risks duplicate compensation where the original payment later settles. D is wrong because the bank does not yet know it is only a display error, and telling customers that without evidence misleads them."}, "recommended_solution": "Start with an incident bridge that separates three workstreams: customer and financial containment, technical root cause analysis, and communications. Containment owns the affected-transaction register, the decision on the next batch, and any remediation. Root cause owns logs, queue state and downstream confirmations. Communications owns one consistent customer message, updated as facts are confirmed, and never states a cause that is not yet proven.\n\nQuantify the population from systems, not from complaint counts. Pull all transactions in the failure window, join them by payment reference and correlation ID across the channel, payment engine, ledger and clearing records, and classify each item as confirmed affected, possibly affected, or unaffected. Value the exposure as the sum of confirmed debits without a matching credit or settlement confirmation, and track it as a single controlled figure that only moves when evidence changes. Hold the next batch until the window is understood, or release only items proven to be outside the affected population.\n\nPreserve evidence before any fix is applied: freeze log rotation for the window, snapshot queue depths and retry state, and record every status change with timestamps. Reconcile the ledger against external payment records item by item. Remediate only from the register, with maker-checker approval, one adjustment per affected payment, and a duplicate check against any later settlement. Close the incident only when the register is empty or fully explained, reconciliation balances, and the root cause has a preventive fix with a named owner.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Reports a debit that does not match the app status, or a missing expected credit", "system": "Mobile banking and contact centre"}, {"step": 2, "actor": "Incident manager", "action": "Opens the incident bridge and separates containment, root cause and communications workstreams", "system": "Incident management tool"}, {"step": 3, "actor": "Payments operations", "action": "Extracts all transactions in the 09:12 to 09:32 window and joins them by payment reference and correlation ID", "system": "Payment engine and reconciliation service"}, {"step": 4, "actor": "Payments operations", "action": "Classifies each item as confirmed affected, possibly affected or unaffected and values the exposure", "system": "Affected-transaction register"}, {"step": 5, "actor": "Incident manager", "action": "Freezes the next batch release until the affected population is proven", "system": "Batch scheduler"}, {"step": 6, "actor": "Engineering", "action": "Preserves logs, queue state and retry state for the window and runs root cause analysis in parallel", "system": "Logging and monitoring platform"}, {"step": 7, "actor": "Payments operations", "action": "Reconciles ledger postings against clearing and scheme status records item by item", "system": "Core ledger and reconciliation service"}, {"step": 8, "actor": "Payments operations", "action": "Applies approved remediation from the register with maker-checker control and duplicate checks", "system": "Ledger and case management"}, {"step": 9, "actor": "Communications", "action": "Issues a consistent customer update based only on confirmed facts and the remediation plan", "system": "Contact centre scripts and app messaging"}, {"step": 10, "actor": "Incident manager", "action": "Closes the incident only when the register is fully explained, reconciliation balances and a preventive fix is owned", "system": "Incident management tool"}], "happy_path": "The bridge opens within minutes. The windowed extract identifies 412 affected payments worth a single controlled exposure figure, with duplicate complaints de-duplicated by reference. The next batch is held, then released for items proven outside the window. Ledger and clearing records reconcile, remediation is applied once per affected payment under maker-checker control, customers receive one accurate update, and the root cause fix is tracked to closure.", "negative_paths": [{"path": "Unknown in-flight state", "trigger": "Some payments were accepted by the engine but no downstream confirmation arrived, so their settlement state is unknown.", "handling": "Hold each item in a pending or unknown state, query by correlation ID, and do not retry or reverse it until the downstream status is confirmed."}, {"path": "Delayed external confirmation", "trigger": "Clearing or scheme confirmations arrive late, so early reconciliation shows false mismatches.", "handling": "Age the items in the register, re-run reconciliation on a defined cadence, and do not treat a missing confirmation as a failure until the agreed timeout passes."}, {"path": "Multiple rails affected", "trigger": "The same window touches more than one rail, each with its own status model and cut-off.", "handling": "Segment the register by rail, apply each rail's status and cut-off rules separately, and never merge rail outcomes into one assumed state."}, {"path": "Partial batch impact", "trigger": "Only some items in a batch are affected, and the rest are healthy.", "handling": "Apply item-level outcomes, release healthy items only after proof, and keep accepted items out of any resubmission when rejected items are repaired."}, {"path": "Duplicate compensation risk", "trigger": "A customer is re-credited and the original payment then settles, paying them twice.", "handling": "Check every remediation against later settlement and ledger postings, use the register as the single source of remediation, and reverse duplicate credits under the same maker-checker control."}], "technical_data": "Use the payment reference and correlation ID as the join keys across channel, engine, ledger and clearing records, with event versioning so an older status event cannot regress a newer state. Persist an incident snapshot of queue depth, retry counts and in-flight items at bridge opening. Keep the affected-transaction register as a durable store with state transitions, timestamps, evidence links and maker-checker records, and never edit history in place. Apply idempotency keys to every remediation adjustment so a retry cannot double-post. Retain logs for the window under a hold, and record every status change in an audit trail that shows who decided, on what evidence, and when.", "messages_fields": [{"message": "pacs.002", "purpose": "Payment status report used to confirm acceptance or rejection of an instruction by the next agent in the chain.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code and additional information"]}, {"message": "camt.053", "purpose": "Bank to customer statement used as external evidence of ledger postings for the window.", "key_fields": ["Statement period", "Entry reference", "Amount, currency and value date", "Booking date"]}, {"message": "camt.054", "purpose": "Bank to customer debit credit notification used to evidence individual credits and debits.", "key_fields": ["Notification reference", "Related payment reference", "Amount and currency", "Credit or debit indicator"]}], "accounting_operational": "Debits without a matching credit or settlement confirmation sit as an exposure that must be quantified, not assumed. The ledger is reconciled item by item against clearing records; unmatched items go to a controlled suspense or exception worklist with an owner and an ageing SLA, and are never written off from the register without approval. Remediation postings are separate linked entries that reference the original payment, so the original record stays immutable and the adjustment is traceable. Duplicate compensation is prevented by checking each remediation against later settlement before and after posting. The incident is closed only when the register balances to zero unexplained items and the suspense balance is fully explained.", "gherkin": ["Given customer funds may be impacted and the root cause is unknown", "When incident response starts", "Then the team first establishes exposure and prevents further harm", "And root cause investigation runs in parallel without blocking containment", "Given a partially valid batch and partial processing enabled", "When the batch is processed", "Then each transaction receives an independent outcome", "And only accepted transactions proceed to settlement"], "assessment": [{"question": "What should the incident team establish first when customer funds may be affected and the cause is unknown?", "options": ["A press statement blaming a supplier", "The full technical root cause", "The next marketing campaign date", "The affected population, the value exposed, and how to stop further harm"], "answer": 3, "explanation": "Containment and quantification bound the harm. Root cause work runs in parallel but must not delay stopping further exposure."}, {"question": "Why is a raw complaint count not the affected population?", "options": ["Complaints are always exaggerated", "The same payment can be reported twice, by payer and payee, and some complaints may be unrelated", "The contact centre cannot count", "Complaints only arrive by phone"], "answer": 1, "explanation": "Complaints must be de-duplicated by payment reference and correlation ID and joined to system records before the affected set is known."}, {"question": "What control prevents duplicate compensation during remediation?", "options": ["Re-crediting quickly before anyone notices", "A single affected-transaction register with maker-checker approval and a duplicate check against later settlement", "Asking the customer to promise not to spend the money", "Deleting the original payment record"], "answer": 1, "explanation": "One register, one adjustment per affected payment, and a check against later settlement stops a re-credit plus a late settlement paying twice."}, {"question": "When a batch is only partly affected, what is the correct handling?", "options": ["Reject the whole batch automatically", "Ignore the healthy items", "Resubmit the entire batch including accepted items", "Apply item-level outcomes, release only items proven healthy, and never resubmit accepted items with repaired ones"], "answer": 3, "explanation": "File-level and transaction-level acceptance are separate. Accepted items must not be resubmitted when rejected items are repaired."}]}}, {"id": "INS-066", "kind": "insight", "title": "Payment volume rises 300% during zero-fee campaign", "topic": "Payment volume rises 300% during zero-fee campaign", "theme": "Capacity and resilience", "text": "Correlate traffic, latency, timeout, failure rates and downstream capacity; consider campaign throttling.", "domain": "Architecture & Resilience", "area": "Architecture & Resilience", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch79s7", "title": "Engine performance and capacity: throughput, latency budgets and load testing", "url": "lessons/ch79s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank launches a zero-fee weekend campaign for retail payments. Within the first hour, payment volume rises to 300 percent of a normal peak, roughly four times the usual load. Latency climbs, channel sessions start timing out, and the clearing connector queue grows faster than it drains. Customers retry the same payment from the app, which adds duplicate submissions to an already loaded platform. The campaign team wants the promotion to continue; operations wants to protect cut-off deadlines and avoid a backlog that cannot be cleared the same day.\n\nThe problem is not only raw volume. Timeouts create unknown outcomes, so a retry may duplicate a payment that was already accepted. The queue holds payments with different cut-offs and different customer impact, and a simple first-in first-out drain may let high value or time critical payments miss their deadlines while low value items consume capacity. Downstream capacity is finite: the clearing connector, the ledger and the fraud service each have their own limits, and pushing harder at the front door only moves the failure downstream.\n\nThe bank needs a controlled response that keeps the platform stable, protects the payments most at risk, prevents retry storms, and gives the campaign a throttle it can actually operate, rather than a choice between letting everything through and switching the campaign off.", "decision_exercise": {"scenario": "Volume is four times normal peak, latency is climbing, the clearing queue is growing, and customers are retrying timed-out payments. What is the first controlled response?", "options": [{"id": "A", "text": "Apply back-pressure at the channel, prioritise the queue by cut-off and customer impact, throttle new campaign intake, and block duplicate retries with idempotency checks."}, {"id": "B", "text": "Raise every timeout and let all traffic through, trusting the platform to catch up overnight."}, {"id": "C", "text": "Restart the payment engine to clear the queue and reprocess everything from the start."}, {"id": "D", "text": "Switch the campaign off without telling customers and reject all new payments."}], "correct_option": "A", "why": "A is correct because back-pressure protects the platform, prioritisation protects cut-off critical payments, throttling controls new load, and idempotency stops retries becoming duplicates. B is wrong because longer timeouts and unlimited intake overload downstream systems. D is wrong because an unexplained shutdown harms customers and does not clear the backlog safely. C is wrong because a restart loses in-flight state and risks duplicate or lost payments."}, "recommended_solution": "Treat the surge as a capacity problem with three controls: intake, queue and recovery. At intake, apply back-pressure through the API gateway and channel: queue or gracefully defer non critical traffic, show a clear pending state instead of a silent timeout, and throttle campaign traffic to a rate the downstream chain can sustain. Communicate the throttle honestly so customers stop retrying blindly. At the queue, prioritise by cut-off risk and customer impact, not by arrival order alone, and age items so nothing sits silently past its deadline.\n\nPrevent retry storms with idempotency. Every submission carries an idempotency key scoped to the initiating party and instruction; a retry with the same key returns the original reference instead of creating a second payment. Where the outcome is unknown after a timeout, the channel must query by correlation ID and show a pending or unknown state until the engine confirms the outcome. Never retry automatically with a new key.\n\nPlan recovery before the surge ends. Define a circuit breaker for the clearing connector with a bounded retry schedule, a dead-letter path for items that cannot be processed, and a controlled replay that reconciles every queued item against the ledger and clearing acknowledgements before release. After the event, size capacity from measured traffic, latency, timeout and failure rates per component, and make campaign throttling a pre-agreed product control with named thresholds, not an improvisation during the next campaign.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits a payment during the zero-fee campaign", "system": "Mobile banking and web channel"}, {"step": 2, "actor": "API gateway", "action": "Applies back-pressure and throttling when intake exceeds the sustainable rate", "system": "API gateway"}, {"step": 3, "actor": "Payment engine", "action": "Accepts the instruction, checks idempotency, and places it in a durable prioritised queue", "system": "Payment engine"}, {"step": 4, "actor": "Payment engine", "action": "Prioritises queued items by cut-off risk and customer impact", "system": "Queue manager"}, {"step": 5, "actor": "Clearing connector", "action": "Sends items to clearing within connector capacity, with a circuit breaker on failure", "system": "Clearing connector"}, {"step": 6, "actor": "Channel", "action": "Shows a pending or unknown state after a timeout and queries by correlation ID instead of resubmitting", "system": "Channel status service"}, {"step": 7, "actor": "Payment engine", "action": "Reconciles queued and sent items against ledger postings and clearing acknowledgements", "system": "Reconciliation service"}, {"step": 8, "actor": "Operations", "action": "Replays the backlog in a controlled order after the connector recovers, with duplicate checks", "system": "Operations console"}, {"step": 9, "actor": "Communications", "action": "Updates customers on delayed payments and the campaign throttle", "system": "App messaging and contact centre"}, {"step": 10, "actor": "Product and engineering", "action": "Reviews traffic, latency, timeout and failure rates and resets capacity and throttle thresholds", "system": "Capacity review"}], "happy_path": "Back-pressure holds intake at a sustainable rate, the queue drains in priority order, no payment misses its cut-off, timed-out submissions resolve to a single payment through idempotency, and the backlog replays cleanly after the connector recovers with every item reconciled to the ledger.", "negative_paths": [{"path": "Retry storm", "trigger": "Customers retry timed-out payments and each retry creates a new submission.", "handling": "Return the original reference for the same idempotency key, show a pending state, and rate limit retries from the channel."}, {"path": "Queue storage pressure", "trigger": "The backlog grows until queue storage or memory is at risk.", "handling": "Shed or defer non critical intake early, alert on queue depth thresholds, and spill to durable storage with an ageing policy."}, {"path": "Expired payments", "trigger": "Queued items pass their cut-off or validity window while waiting.", "handling": "Expire them under a defined policy, reverse or release any reservation once, notify the customer, and never release an expired payment silently."}, {"path": "Partial replay", "trigger": "Only some queued items replay after recovery and the rest are unaccounted for.", "handling": "Reconcile the full queue against sent messages, acknowledgements and ledger entries before declaring recovery complete."}, {"path": "Downstream overload", "trigger": "The ledger or fraud service becomes the bottleneck once the connector recovers.", "handling": "Apply back-pressure per component, drain at the slowest downstream rate, and monitor latency and failure rates at each hop, not only at the front door."}], "technical_data": "Make the queue durable with a persisted item state, priority, cut-off timestamp, correlation ID and idempotency key, so a restart does not lose or duplicate work. Use a circuit breaker with a bounded retry schedule and exponential back-off for the clearing connector, and a dead-letter queue for items that exhaust retries. Emit latency, timeout rate, failure rate and queue depth per component so the bottleneck is visible, and alert on thresholds rather than on total volume alone. Keep status as a durable state machine with an authoritative source per transition, and use outbox or inbox patterns so a status update cannot be lost between the engine and the ledger. Every retry must carry the original idempotency key and payload hash.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation carrying the original instruction and idempotency reference from the channel.", "key_fields": ["Instruction identification", "End to end identification", "Debtor and creditor account", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer credit transfer sent to clearing for each accepted payment.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection at each hop.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "camt.054", "purpose": "Debit credit notification evidencing the ledger posting for a completed payment.", "key_fields": ["Notification reference", "Related payment reference", "Amount and currency"]}], "accounting_operational": "Queued payments are not settled payments, so no settlement posting is made until clearing acceptance is confirmed. Any reservation or hold taken at acceptance must be released or reversed exactly once if the payment expires or is rejected, and the reversal must reference the original instruction. The backlog becomes an operational worklist ordered by cut-off risk, with ageing alerts and a named owner, and recovery is measured by reconciled items, not by queue depth alone. Fees waived under the campaign are recorded as waived, not as missing, so revenue reporting stays accurate. If a duplicate does slip through, it is handled as a linked exception with a single reversal, never by deleting the original posting.", "gherkin": ["Given the clearing connector is unavailable", "When queue depth crosses the defined threshold", "Then alerts and controlled back-pressure are activated", "And new intake is throttled to the sustainable rate", "Given a submission timeout", "When the client enquires using the original reference", "Then the platform returns the current known state", "And does not create a new transaction"], "assessment": [{"question": "Why is back-pressure better than simply raising timeouts during a volume surge?", "options": ["It increases revenue", "It protects downstream systems from overload and keeps the platform stable while intake is controlled", "It removes the need for a queue", "It makes the app look faster"], "answer": 1, "explanation": "Longer timeouts and unlimited intake push the failure downstream to the connector, ledger or fraud service. Back-pressure controls load at the sustainable rate."}, {"question": "A customer retries after a timeout. What prevents a duplicate payment?", "options": ["Asking the customer to wait a day", "Charging a retry fee", "Deleting the first payment", "Returning the original reference for the same idempotency key and showing a pending state until the outcome is confirmed"], "answer": 3, "explanation": "The same idempotency key must return the original payment reference. A retry with a new key is a new payment."}, {"question": "How should a recovery queue be drained after an outage?", "options": ["In a controlled priority order by cut-off risk and customer impact, reconciling every item before declaring recovery complete", "By reprocessing everything twice", "First in, first out, as fast as possible", "By deleting the oldest items"], "answer": 0, "explanation": "Priority order protects cut-off critical payments, and reconciliation proves no item was lost or duplicated during replay."}, {"question": "What does a circuit breaker do for a failing clearing connector?", "options": ["It stops repeated retries hammering the connector, applies a bounded retry schedule, and routes exhausted items to a dead-letter path", "It increases the retry rate", "It deletes queued payments", "It bypasses clearing entirely"], "answer": 0, "explanation": "Repeated retries during an outage create a retry storm. A circuit breaker pauses calls, retries on a schedule, and isolates items that cannot be processed."}]}}, {"id": "INS-067", "kind": "insight", "title": "Failures across UPI, cards, net banking and wallets", "topic": "Failures across UPI, cards, net banking and wallets", "theme": "Channel comparison", "text": "Segment incidents by rail/channel, gateway, bank, response code, time and transaction state.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch9s7", "title": "How the rails differ: limits, timing and cost", "url": "lessons/ch9s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank and its retail partner Northgate Retail both see payment failures on the same day, but the failures do not look the same everywhere. UPI payments fail with timeouts, card payments fail at the gateway, net banking sessions drop before confirmation, and wallet payments fail after the wallet is debited. Customers report the same complaint, that the payment failed, but the underlying state is different on each rail: some payments never left the bank, some were debited but not settled, and some settled while the channel still showed failure.\n\nTreating all failures as one incident hides the real pattern. A single failure rate for the whole day says nothing about which rail, gateway, bank, response code or time window is actually broken. Without segmentation, the team cannot tell whether the cause is a UPI switch problem, a card gateway limit, a net banking session fault, or a wallet reconciliation lag, and any fix aimed at the wrong rail wastes the incident window.\n\nThe work is to segment the incident by rail and channel, gateway, bank, response code, time and transaction state, then resolve each segment on its own evidence. The case also tests limit discipline: each rail has its own limits, and a payment that is valid on one rail may be above the limit on another, so a blanket retry across rails can create new failures.", "decision_exercise": {"scenario": "Failures are reported across UPI, cards, net banking and wallets on the same day, with different symptoms on each rail. What is the right first analytical step?", "options": [{"id": "A", "text": "Announce a single platform outage and stop all payment traffic until engineering finds one root cause."}, {"id": "B", "text": "Retry every failed payment on a different rail automatically."}, {"id": "C", "text": "Tell customers to try again later and close the incident when complaint volume falls."}, {"id": "D", "text": "Segment every failure by rail, channel, gateway, bank, response code, time window and transaction state, then work each segment on its own evidence."}], "correct_option": "D", "why": "D is correct because the symptoms differ by rail, so only segmentation shows which rail, gateway or time window is actually broken and what state each payment is in. A is wrong because there is no evidence of a single platform cause. B is wrong because an automatic cross-rail retry can duplicate a payment that was already debited and can breach the other rail's limits. C is wrong because falling complaint volume does not prove the payments were resolved."}, "recommended_solution": "Build one incident table segmented by rail and channel, gateway, bank, response code, time window and transaction state, and join each row to its ledger and clearing evidence by correlation ID. For each segment, answer three questions: did the payment leave the customer account, did it reach clearing or the scheme, and what is its authoritative state now. UPI, card, net banking and wallet segments are worked separately because their settlement models, status sources and reversal paths differ, even when the customer symptom looks identical.\n\nApply the limit hierarchy inside each segment. A scheme maximum, a regulatory obligation, a bank product limit and a customer level risk limit are separate rules with a defined precedence, and the strictest applicable limit governs. In India, that means respecting the rail facts: UPI has a limit of INR 5 lakh for specified categories, RTGS has a minimum of Rs 2 lakh with no RBI maximum, IMPS is typically bank capped around Rs 5 lakh, and NEFT settles in half-hourly batches. A payment above a customer limit but below a scheme maximum is still correctly rejected, and the customer message must say so in plain terms.\n\nResolve each segment on its own evidence. A payment debited but not settled goes to reconciliation and, where the rail allows, a reversal or return; a payment that never left the account needs no financial remediation, only a corrected status; a payment that settled while the channel showed failure needs a status correction and a customer confirmation, not a second payment. Close a segment only when its items reconcile and its failure rate returns to normal for that rail, not when the overall daily rate looks acceptable.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Attempts a payment through UPI, card, net banking or wallet and sees a failure", "system": "Channel or merchant checkout"}, {"step": 2, "actor": "Payments operations", "action": "Collects failures into one table segmented by rail, channel, gateway, bank, response code, time and state", "system": "Incident and reporting service"}, {"step": 3, "actor": "Payments operations", "action": "Joins each failure to ledger and clearing evidence by correlation ID", "system": "Reconciliation service"}, {"step": 4, "actor": "Payments operations", "action": "Classifies each item as never debited, debited but not settled, or settled with a wrong channel status", "system": "Exception workbench"}, {"step": 5, "actor": "Rail specialists", "action": "Investigate each rail segment on its own evidence and status source", "system": "Rail monitoring tools"}, {"step": 6, "actor": "Payments operations", "action": "Applies the correct remedy per segment: status correction, reversal, return or no financial action", "system": "Ledger and case management"}, {"step": 7, "actor": "Product", "action": "Checks the failed amounts against scheme, regulatory, bank and customer limits for that rail", "system": "Limits service"}, {"step": 8, "actor": "Communications", "action": "Sends rail specific customer updates that state what actually happened to their money", "system": "App messaging and contact centre"}, {"step": 9, "actor": "Operations", "action": "Re-runs reconciliation per segment until every item is explained", "system": "Reconciliation service"}, {"step": 10, "actor": "Incident manager", "action": "Closes each segment only when its failure rate and reconciliation are normal for that rail", "system": "Incident management tool"}], "happy_path": "Segmentation shows the UPI failures are timeouts in one time window, the card failures are a single gateway response code, and the wallet failures are a reconciliation lag. Each segment is resolved on its own evidence, debited but unsettled items are reversed once, settled items get a corrected status, and every segment reconciles before closure.", "negative_paths": [{"path": "Ambiguous status across systems", "trigger": "The channel shows pending, the engine shows processed, and the ledger has no posting.", "handling": "Define the authoritative source for each state, correlate by ID, and hold the item in an exception queue rather than inferring a state."}, {"path": "Duplicate across rails", "trigger": "A customer retries a failed UPI payment by card and both eventually settle.", "handling": "Detect the duplicate by customer, amount and time window, route it for review, and reverse one leg under maker-checker control instead of silently discarding it."}, {"path": "Limit breach on retry", "trigger": "A retry on another rail exceeds that rail's limit and fails again.", "handling": "Validate amount against the target rail's scheme, bank and customer limits before routing, and explain the limit in the customer message."}, {"path": "Stale status cache", "trigger": "The channel keeps showing failure after the payment has settled.", "handling": "Invalidate the cached status from the authoritative status store and confirm the corrected state to the customer."}, {"path": "Out-of-order events", "trigger": "An older status event arrives after a newer one and regresses the payment state.", "handling": "Apply event versioning so an older event cannot overwrite a newer state."}], "technical_data": "Store a canonical payment state model with one authoritative source per transition, and join channel, engine, ledger and clearing records by correlation ID and payment reference. Keep rail specific reason code mappings, so the same internal reason can produce the correct external code and customer text per rail and jurisdiction. Version status events and make consumers idempotent so out-of-order or duplicate events cannot regress state. Record limit evaluations with the rule hierarchy applied, the effective date, and the limit that actually governed, so a rejection can be explained later. Retain the segmented incident table as audit evidence, including gateway, bank, response code and time window for every item.", "messages_fields": [{"message": "pacs.002", "purpose": "Payment status report used to confirm the authoritative status of an instruction at each hop.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code and additional information"]}, {"message": "pacs.008", "purpose": "Customer credit transfer for account based rails where the bank sends the interbank leg.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "camt.053", "purpose": "Bank to customer statement evidencing whether a debit or credit was actually posted.", "key_fields": ["Statement period", "Entry reference", "Amount, currency and value date"]}, {"message": "camt.054", "purpose": "Debit credit notification evidencing an individual posting where a statement alone is not enough.", "key_fields": ["Notification reference", "Related payment reference", "Amount and currency", "Credit or debit indicator"]}], "accounting_operational": "Each rail segment has its own accounting treatment, so a single incident cannot be cleared with one journal. Debited but unsettled items sit in a reconciliation exception worklist until the rail confirms settlement or a reversal is posted as a separate linked entry. Items that never left the account need no financial posting, only a status correction. Items that settled while the channel showed failure need a customer confirmation and no second payment. Suspense balances are aged per rail with an SLA, and the incident closes per segment when that segment's ledger, clearing and channel records all agree.", "gherkin": ["Given out-of-order status events", "When an older event arrives after a newer state", "Then the payment state does not regress", "And the authoritative state is preserved", "Given a payment amount above a customer limit but below the scheme maximum", "When limits are evaluated", "Then the bank's stricter applicable limit is enforced", "And the customer receives the correct rejection reason"], "assessment": [{"question": "Why must failures be segmented by rail instead of treated as one incident?", "options": ["Because regulators require four incidents", "Because settlement models, status sources, limits and reversal paths differ by rail, so one fix cannot fit all segments", "Because each rail has a different logo", "Because customers prefer it"], "answer": 1, "explanation": "The same customer symptom can mean never debited, debited but unsettled, or settled with a wrong status, and the correct remedy depends on the rail."}, {"question": "A payment is above the customer limit but below the scheme maximum. What happens?", "options": ["It is split across rails", "It is accepted because the scheme allows it", "It is queued until the limit changes", "It is rejected because the stricter applicable bank or customer limit governs"], "answer": 3, "explanation": "Scheme maximum, regulatory obligation, bank product limit and customer limit are separate rules with a precedence order, and the strictest applicable limit is enforced."}, {"question": "UPI, RTGS and NEFT differ in which of these ways?", "options": ["They all settle in half-hourly batches", "NEFT is instant and RTGS is batched", "UPI limit is INR 5 lakh for specified categories, RTGS minimum is Rs 2 lakh with no RBI maximum, and NEFT settles in half-hourly batches", "RTGS has a maximum of Rs 2 lakh"], "answer": 2, "explanation": "UPI has a 5 lakh limit for specified categories, RTGS settles individually in real time with a Rs 2 lakh minimum and no RBI maximum, and NEFT settles in half-hourly batches."}, {"question": "A wallet payment was debited but the merchant shows failure. What is the first check?", "options": ["Refund the customer immediately without checking", "Join the wallet debit to the ledger and clearing evidence by correlation ID to establish whether it settled", "Close the merchant account", "Re-debit the wallet"], "answer": 1, "explanation": "The authoritative state comes from joined system evidence, not from the channel display alone. Only then can the team choose reversal, return or status correction."}]}}, {"id": "INS-068", "kind": "insight", "title": "Evidence required during payment surge", "topic": "Evidence required during payment surge", "theme": "Incident data", "text": "Collect transaction IDs, gateway responses, API logs, timeout rates, timestamps and reconciliation status.", "domain": "Data & Operations", "area": "Data & Operations", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch40s4", "title": "Transaction-Level Matching: References, Amounts, Currencies and Value Dates", "url": "lessons/ch40s4"}}, {"id": "INS-069", "kind": "insight", "title": "Checkout, authentication, status, refund and reversal APIs", "topic": "Checkout, authentication, status, refund and reversal APIs", "theme": "Payment API use cases", "text": "Map API touchpoints across payment initiation and lifecycle operations.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch80s4", "title": "Error taxonomy: HTTP status is not the payment status", "url": "lessons/ch80s4"}}, {"id": "INS-070", "kind": "insight", "title": "Difference between payment gateway and processor", "topic": "Difference between payment gateway and processor", "theme": "Gateway vs processor", "text": "Explain orchestration/connectivity versus transaction processing roles, noting provider models vary.", "domain": "Payment Architecture", "area": "Payment Architecture", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch30s1", "title": "What a Payment Gateway Does", "url": "lessons/ch30s1"}}, {"id": "INS-071", "kind": "insight", "title": "Payment timeout and uncertain final status", "topic": "Payment timeout and uncertain final status", "theme": "Timeout handling", "text": "Use status enquiry and reconciliation before retrying; apply idempotency and duplicate controls.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s7", "title": "Exercise: Trace One Payment Through Every Possible Failure Scenario (one USD cross-border payment traced through reject, return, recall, duplicate, timeout and outage, with what happens at each step)", "url": "lessons/ch41s7"}, "case": {"status": "authored", "business_problem": "Northgate Retail, a corporate customer of Meridian Bank, submits a supplier payment through the bank's online channel. The screen spins, then times out. No confirmation appears, no reference is shown, and the accounts team does not know whether the payment was accepted, executed, or never received. The supplier is waiting, the payment is time critical, and the accounts team is tempted to submit it again immediately so the supplier is paid on time.\n\nA blind resubmission is the dangerous option. If the first instruction was accepted by the payment engine and the response was simply lost, a second submission creates a duplicate debit and pays the supplier twice. If the first instruction never reached the engine, waiting without action misses the supplier deadline. The channel, the payment engine, the ledger and the clearing system can each hold a different view of the same payment, and none of them alone proves whether funds moved.\n\nThe case is about treating a timeout as an unknown outcome, not as a failure, and proving the outcome from authoritative evidence before any retry, cancellation or reversal is attempted.", "decision_exercise": {"scenario": "A corporate payment times out with no confirmation and no reference shown. The supplier deadline is near. What do you do?", "options": [{"id": "A", "text": "Assume the payment failed and reverse the supplier invoice in the accounts system."}, {"id": "B", "text": "Treat the outcome as unknown, query the payment engine and ledger by the original correlation ID, show a pending state, and retry only with the same idempotency key if the original is proven not accepted."}, {"id": "C", "text": "Cancel the payment by sending a cancellation request straight away."}, {"id": "D", "text": "Submit the payment again immediately with a new reference so the supplier is paid on time."}], "correct_option": "B", "why": "B is correct because a timeout proves nothing about the outcome. Status enquiry by the original correlation ID establishes whether the engine accepted it, and a retry with the same idempotency key cannot duplicate an accepted payment. D is wrong because a new reference creates a second payment if the first was accepted. A is wrong because no evidence yet shows a failure. C is wrong because cancellation is only valid for a payment in an eligible state, and a cancellation request does not prove the original outcome."}, "recommended_solution": "Make the timeout path explicit in the product: the channel shows a pending or unknown state, never a success and never a failure, until the outcome is confirmed. The status enquiry uses the original correlation ID and payment reference to ask the payment engine, then the ledger, then the downstream clearing status, in that order. Each source answers a different question: the engine says whether the instruction was accepted, the ledger says whether a debit was posted, and the clearing status says whether the interbank leg was accepted or settled. Only the combination proves whether funds moved.\n\nRetry only with the same idempotency key and the same payload hash. If the engine returns the original reference, the retry is answered from the stored outcome and no second payment is created. If the engine proves the instruction was never accepted, a new submission may proceed, and that decision is recorded with its evidence. If the engine accepted the payment but the downstream outcome is still unknown, the payment stays pending with an ageing alert until clearing confirms or rejects it.\n\nHandle the ledger gap as a recoverable event problem, not as a data edit. If the ledger posted a debit but the status event failed, replay the missing event idempotently from the original posting reference without reposting the debit. If the ledger has no posting and the engine has no acceptance, the payment was never created. Every step is logged with the correlation ID so the supplier, the customer and operations all see the same evidence trail.", "flow_steps": [{"step": 1, "actor": "Corporate user", "action": "Submits a supplier payment through the online channel", "system": "Corporate online banking"}, {"step": 2, "actor": "Channel", "action": "Times out without a response and shows a pending or unknown state, not a failure", "system": "Channel status service"}, {"step": 3, "actor": "Channel", "action": "Queries the payment engine using the original correlation ID and payment reference", "system": "API gateway"}, {"step": 4, "actor": "Payment engine", "action": "Returns the stored outcome if the instruction was accepted, or confirms it was never accepted", "system": "Payment engine"}, {"step": 5, "actor": "Payments operations", "action": "Checks the ledger for a debit posted under the original posting reference", "system": "Core ledger"}, {"step": 6, "actor": "Payments operations", "action": "Checks the downstream clearing status for acceptance or settlement", "system": "Clearing connector"}, {"step": 7, "actor": "Payment engine", "action": "Replays a missing status event idempotently if the ledger posted but the status update failed", "system": "Event outbox"}, {"step": 8, "actor": "Channel", "action": "Shows the confirmed state to the customer and, only if proven not accepted, allows a retry with the same idempotency key", "system": "Channel status service"}, {"step": 9, "actor": "Payments operations", "action": "Raises an ageing alert if the downstream outcome stays unknown past the agreed timeout", "system": "Operations console"}, {"step": 10, "actor": "Payments operations", "action": "Records the enquiry, the evidence and the final decision against the correlation ID", "system": "Audit trail"}], "happy_path": "The status enquiry finds the original instruction was accepted and the ledger debit matches the clearing acceptance. The channel shows the confirmed reference, the supplier is paid once, and no retry is needed. If instead the enquiry proves the instruction was never accepted, a single retry with the same idempotency key creates one payment and the supplier deadline is met.", "negative_paths": [{"path": "Engine accepted but response lost", "trigger": "The payment was accepted, the channel timed out, and the customer retries.", "handling": "Return the original reference for the same idempotency key and never create a second debit."}, {"path": "Connector timed out", "trigger": "The clearing connector accepted the message but its response was lost.", "handling": "Query the clearing status by reference, hold the payment pending, and do not resend the interbank message."}, {"path": "Ledger posted but status update failed", "trigger": "The core ledger has the debit, but the payment platform still shows an earlier state.", "handling": "Replay the missing event idempotently from the original posting reference without reposting the debit."}, {"path": "Status store lag", "trigger": "The status service shows stale data while the engine has already moved the payment on.", "handling": "Read the authoritative engine state for the enquiry and refresh the status store from it, rather than trusting the cached view."}, {"path": "Duplicate retry with a new key", "trigger": "A retry is submitted with a new idempotency key and creates a second payment.", "handling": "Detect the duplicate by business identifiers, hold the second payment for review, and reverse one leg under maker-checker control."}], "technical_data": "Persist the idempotency key, payload hash, original payment ID, correlation ID and timestamps at intake, before any downstream call, so a retry can always be answered from stored state. Keep a durable payment state machine with an authoritative source for each transition, and use event versioning so an older event cannot regress a newer state. Use an outbox pattern for ledger and status events so a posting and its notification either both become recoverable or neither is lost silently. Make every status consumer idempotent, and record ageing alerts when a payment stays in an unknown state past its timeout. A cancellation request is a separate process with its own eligibility check, never a substitute for a status enquiry.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation carrying the instruction and the idempotency reference.", "key_fields": ["Instruction identification", "End to end identification", "Debtor and creditor account", "Instructed amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report used to confirm acceptance, rejection or pending status at each hop.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code and additional information"]}, {"message": "camt.053", "purpose": "Bank to customer statement evidencing whether the ledger debit was actually posted.", "key_fields": ["Statement period", "Entry reference", "Amount, currency and value date"]}, {"message": "camt.056", "purpose": "Payment cancellation request, used only if a valid cancellation process is initiated after the state is known.", "key_fields": ["Original instruction reference", "Cancellation reason", "Requester identification"]}, {"message": "camt.029", "purpose": "Resolution of investigation, the response to a cancellation request.", "key_fields": ["Original instruction reference", "Investigation status", "Cancellation status"]}], "accounting_operational": "No accounting entry is made on a timeout alone, because no outcome is proven. If the ledger shows a debit, that posting stands and is reconciled to the clearing status; if the ledger shows no debit and the engine shows no acceptance, no entry exists and no reversal is needed. A duplicate created by a blind retry is handled as a linked exception: one leg is reversed as a separate entry referencing the original, under maker-checker control, and the original posting is never deleted. Unknown outcome items sit in an ageing worklist with an SLA, and the worklist is cleared only by a confirmed clearing or ledger event, not by the passage of time.", "gherkin": ["Given a submission timeout", "When the client enquires using the original reference", "Then the platform returns the current known state", "And does not create a new transaction", "Given a ledger posting exists but the status event is missing", "When recovery runs", "Then the payment state is updated using the original posting reference", "And the debit is not reposted"], "assessment": [{"question": "A payment submission times out. What does the timeout prove?", "options": ["The payment succeeded", "The payment was rejected by clearing", "Nothing about the outcome. It is unknown until a status enquiry proves it", "The payment failed"], "answer": 2, "explanation": "A timeout means the response was lost. The engine may have accepted the payment, or it may never have received it. Only enquiry by correlation ID proves the outcome."}, {"question": "What is the safe way to retry after a timeout?", "options": ["Retry with the same idempotency key and the same payload, so an accepted payment returns its original reference", "Wait a day and submit a larger amount", "Retry by phone instead", "Submit again with a new reference"], "answer": 0, "explanation": "The same idempotency key returns the stored outcome for an accepted instruction. A new key creates a second payment."}, {"question": "Which system proves whether a debit was actually posted?", "options": ["The channel screen", "The customer's memory", "The core ledger, joined by the original posting reference", "The marketing page"], "answer": 2, "explanation": "The channel shows a view that may be stale. The ledger is the authoritative record of the debit, and clearing status proves the interbank outcome."}, {"question": "The ledger posted a debit but the payment status never updated. What fixes it?", "options": ["Tell the customer the payment failed", "Delete the ledger entry", "Replay the missing status event idempotently from the original posting reference without reposting the debit", "Post the debit again"], "answer": 2, "explanation": "The posting is correct and must not be duplicated. The missing event is recovered from the outbox using the original reference."}]}}, {"id": "INS-072", "kind": "insight", "title": "Why customers abandon payment page", "topic": "Why customers abandon payment page", "theme": "Problem solving", "text": "Analyse funnel, validation errors, latency, payment options and user experience evidence.", "domain": "Product Analytics", "area": "Product Analytics", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s4", "title": "Customer journeys in payments: the moments that decide trust", "url": "lessons/ch82s4"}}, {"id": "INS-073", "kind": "insight", "title": "Why loan approval time rises from hours to days", "topic": "Why loan approval time rises from hours to days", "theme": "Operational efficiency", "text": "Map process bottlenecks, queues, manual checks, dependencies and rework.", "domain": "Process Improvement", "area": "Process Improvement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s2", "title": "Business Process Modelling: As-Is and To-Be Flows", "url": "lessons/ch28s2"}}, {"id": "INS-074", "kind": "insight", "title": "Why UAT fails despite all test cases passing", "topic": "Why UAT fails despite all test cases passing", "theme": "UAT analysis", "text": "Check test design, representativeness, data, expected outcomes and unmet business needs.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s5", "title": "Test Data, Environments and Simulators", "url": "lessons/ch42s5"}}, {"id": "INS-075", "kind": "insight", "title": "Why the same change is requested every sprint", "topic": "Why the same change is requested every sprint", "theme": "Stakeholder management", "text": "Identify unresolved root need, weak discovery, policy uncertainty or lack of decision ownership.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch45s5", "title": "Roadmaps, Prioritisation and Stakeholder Management", "url": "lessons/ch45s5"}}, {"id": "INS-076", "kind": "insight", "title": "Translate business value for stakeholders", "topic": "Translate business value for stakeholders", "theme": "Communication", "text": "Communicate outcome, customer impact, revenue, compliance, timing and decisions.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s2", "title": "Business models in payments: where the money comes from", "url": "lessons/ch82s2"}}, {"id": "INS-077", "kind": "insight", "title": "Translate rules and edge cases for developers", "topic": "Translate rules and edge cases for developers", "theme": "Communication", "text": "Explain triggers, conditions, data, expected behaviour and failure outcomes.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch29s3", "title": "API Business Data, Rules and Validations", "url": "lessons/ch29s3"}}, {"id": "INS-078", "kind": "insight", "title": "Translate scenarios into testable QA coverage", "topic": "Translate scenarios into testable QA coverage", "theme": "Communication", "text": "Define positive, negative, boundary and regression scenarios with expected results.", "domain": "Testing & UAT", "area": "Testing & UAT", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch42s3", "title": "Writing Test Scenarios for Happy Path and Negative Path", "url": "lessons/ch42s3"}}, {"id": "INS-079", "kind": "insight", "title": "Translate incident and recovery status for support", "topic": "Translate incident and recovery status for support", "theme": "Communication", "text": "Provide symptom, affected users, workaround, ownership, severity and next update.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch68s8", "title": "Incident communication: who is told, what they are told, and when", "url": "lessons/ch68s8"}}, {"id": "INS-080", "kind": "insight", "title": "Functional versus non-functional requirements", "topic": "Functional versus non-functional requirements", "theme": "BA fundamentals", "text": "Differentiate behaviour from performance, security, availability, usability and supportability needs.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s2", "title": "Writing a BRD and a functional specification for a payment product", "url": "lessons/ch84s2"}}, {"id": "INS-081", "kind": "insight", "title": "Requirements Traceability Matrix", "topic": "Requirements Traceability Matrix", "theme": "Traceability", "text": "Connect business objectives, requirements, stories, design, tests, defects and release evidence.", "domain": "Requirements Engineering", "area": "Requirements Engineering", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s3", "title": "User stories and acceptance criteria for payments: Gherkin in practice", "url": "lessons/ch84s3"}}, {"id": "INS-082", "kind": "insight", "title": "BA responsibilities across SDLC", "topic": "BA responsibilities across SDLC", "theme": "SDLC", "text": "Explain discovery through deployment and post-release validation.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s1", "title": "Requirements Gathering for Payments Projects", "url": "lessons/ch28s1"}}, {"id": "INS-083", "kind": "insight", "title": "Translate prior domain experience into BA value", "topic": "Translate prior domain experience into BA value", "theme": "Career transition", "text": "Map transferable skills to domain knowledge, elicitation, documentation, delivery and outcomes.", "domain": "Career & Professional Skills", "area": "Career & Professional Skills", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s7", "title": "Your Learning Path Forward", "url": "lessons/ch35s7"}}, {"id": "INS-084", "kind": "insight", "title": "Present project experience with evidence", "topic": "Present project experience with evidence", "theme": "Interview positioning", "text": "Structure project walkthrough around problem, role, decisions, systems, risks and measurable result.", "domain": "Interview Masterclass", "area": "Interview Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s6", "title": "Interview Q and A for Payments Roles", "url": "lessons/ch35s6"}}, {"id": "INS-085", "kind": "insight", "title": "Respond when you do not know a technical answer", "topic": "Respond when you do not know a technical answer", "theme": "Interview positioning", "text": "State assumptions, explain reasoning, identify what you would validate and avoid bluffing.", "domain": "Interview Masterclass", "area": "Interview Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s6", "title": "Interview Q and A for Payments Roles", "url": "lessons/ch35s6"}}, {"id": "INS-086", "kind": "insight", "title": "Common payment failure reasons", "topic": "Common payment failure reasons", "theme": "Payment exceptions", "text": "Classify issuer decline, validation, limit, timeout, connectivity, risk and downstream processing failures.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s1", "title": "The Exception Landscape: What Can Go Wrong", "url": "lessons/ch41s1"}}, {"id": "INS-087", "kind": "insight", "title": "Duplicate transaction investigation", "topic": "Duplicate transaction investigation", "theme": "Payment exceptions", "text": "Trace repeated requests, client retries, gateway references, idempotency keys and ledger postings.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s7", "title": "Exercise: Trace One Payment Through Every Possible Failure Scenario (one USD cross-border payment traced through reject, return, recall, duplicate, timeout and outage, with what happens at each step)", "url": "lessons/ch41s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank receives a complaint from Northgate Retail: a supplier payment appears twice on the account statement, for the same amount, to the same supplier, on the same day. The supplier confirms receiving two credits. The accounts team insists they only intended one payment, but the channel log shows two submissions seconds apart, after a slow response on the first attempt. Finance wants one payment reversed immediately; operations is not yet sure which of the two postings is the original and which is the duplicate, or whether both reached clearing.\n\nThe investigation must trace the full chain before any money moves. The two submissions may share an idempotency key, in which case the platform should have returned the original reference and no second payment should exist, which would point to a platform defect. They may carry different keys, in which case both are technically distinct instructions and the duplicate came from the retry behaviour, not from the platform. They may also differ in a field, such as the end to end reference, which would explain why duplicate detection missed them. A gateway reference, a ledger posting and a clearing acknowledgement must all be joined before the team can say which payment to reverse.\n\nReversing the wrong leg, or reversing before clearing confirms the state of each leg, can leave the supplier unpaid or create a second error on top of the first. The case is about evidence led investigation: trace, prove, then reverse once under control.", "decision_exercise": {"scenario": "A supplier was paid twice for the same amount on the same day after a slow channel response and a retry. What is the first step before any reversal?", "options": [{"id": "A", "text": "Trace both submissions through channel, gateway, idempotency store, ledger and clearing by reference and key, prove which leg is the duplicate, then reverse that leg once under maker-checker control."}, {"id": "B", "text": "Ask the supplier to send the money back by a new payment and close the case."}, {"id": "C", "text": "Reverse the second statement line immediately so the supplier is not overpaid for long."}, {"id": "D", "text": "Delete the duplicate instruction from the payment engine so it disappears from reporting."}], "correct_option": "A", "why": "A is correct because the reversal target can only be chosen from joined evidence: idempotency keys, gateway references, ledger postings and clearing acknowledgements. C is wrong because the second statement line may be the original and the first may be the duplicate, and clearing state is still unknown. D is wrong because deleting a record destroys the audit trail. B is wrong because it moves the bank's error onto the customer and leaves the bank's own records unresolved."}, "recommended_solution": "Reconstruct both payments end to end from the same evidence set. For each submission, collect the channel timestamp, the idempotency key and payload hash, the gateway reference, the payment engine reference, the ledger posting reference, and the clearing acknowledgement or pacs.002 status. Join them by correlation ID and compare the two chains field by field. If the keys match and the payloads match, the platform should have returned the original reference, so a second payment indicates a defect in the idempotency check, a race between concurrent requests, or a key that was not persisted before the downstream call.\n\nIf the keys differ, the duplicate is a business retry, not a platform duplicate, and the fix is in channel behaviour and customer guidance, not in the engine. Check whether duplicate detection rules using stable business identifiers, such as debtor, creditor, amount, value date and remittance reference, should have flagged the second instruction for review, while remembering that amount and beneficiary alone are never enough to block a payment, because two legitimate identical payments are possible.\n\nReverse only the proven duplicate leg, as a separate linked entry that references the original payment, under maker-checker approval. Confirm with clearing whether that leg settled before choosing between a cancellation request, a return, or a separate refund, because the correct mechanism depends on the leg's state. If the duplicate is detected after downstream submission, do not silently discard it; hold it, investigate, and record the outcome. After the case, fix the root cause: persist the idempotency key before the downstream call, lock concurrent retries on the same key, and make the channel show a pending state after a slow response instead of inviting an immediate resubmission.", "flow_steps": [{"step": 1, "actor": "Corporate user", "action": "Submits a supplier payment, sees a slow response, and submits again seconds later", "system": "Corporate online banking"}, {"step": 2, "actor": "Channel", "action": "Sends both submissions to the payment platform, each with its own request details", "system": "API gateway"}, {"step": 3, "actor": "Payment engine", "action": "Checks the idempotency store for each submission and creates a payment record for each accepted instruction", "system": "Payment engine"}, {"step": 4, "actor": "Investigator", "action": "Collects channel, gateway, idempotency, ledger and clearing records for both submissions", "system": "Exception workbench"}, {"step": 5, "actor": "Investigator", "action": "Joins the two chains by correlation ID and compares keys, payload hashes, references and timestamps", "system": "Exception workbench"}, {"step": 6, "actor": "Investigator", "action": "Proves which leg is the original and which is the duplicate, and confirms each leg's clearing state", "system": "Clearing connector and reconciliation service"}, {"step": 7, "actor": "Payments operations", "action": "Reverses the proven duplicate leg once, as a linked entry under maker-checker control", "system": "Core ledger"}, {"step": 8, "actor": "Payments operations", "action": "Confirms the reversal with the supplier and updates the customer status for both legs", "system": "Case management"}, {"step": 9, "actor": "Engineering", "action": "Fixes the idempotency or channel defect that allowed the duplicate", "system": "Payment engine"}, {"step": 10, "actor": "Payments operations", "action": "Closes the case only when both legs reconcile and the duplicate control is proven", "system": "Reconciliation service"}], "happy_path": "The investigation shows the two submissions carried different idempotency keys but identical business identifiers, and only one leg had settled. The duplicate leg is reversed once as a linked entry, the supplier confirms a single credit, the channel is changed to show a pending state after a slow response, and no further duplicates occur from the same cause.", "negative_paths": [{"path": "Same key with altered payload", "trigger": "The retry carries the same idempotency key but a changed amount or beneficiary.", "handling": "Reject the retry as a key conflict, hold it for review, and never apply the altered payload to the original payment."}, {"path": "Duplicate detected after downstream submission", "trigger": "The second payment has already been sent to clearing before detection.", "handling": "Do not silently discard it. Use the cancellation or return path valid for its state, and reconcile the outcome."}, {"path": "Concurrent requests", "trigger": "Two identical requests arrive at the same moment and both pass the idempotency check.", "handling": "Serialise intake on the idempotency key, persist the key before the downstream call, and let the second request return the first reference."}, {"path": "Ambiguous status across systems", "trigger": "The channel shows one payment, the engine shows two, and the ledger shows one posting.", "handling": "Define the authoritative source per state, join by correlation ID, and hold both legs in an exception queue until the states converge."}, {"path": "Cancellation requested after processing started", "trigger": "The customer asks to cancel the duplicate after it has left the engine.", "handling": "Check the durable state and scheme rules first, initiate camt.056 only if eligible, and never promise cancellation before the counterparty responds."}], "technical_data": "Persist the idempotency key, payload hash, original payment ID, gateway reference, ledger posting reference and timestamps at intake, atomically with the first accepted record, so a concurrent retry cannot slip through. Apply duplicate detection on stable business identifiers in addition to the key, and route uncertain matches to review instead of silently discarding them. Keep the original payment record immutable and link the reversal to it by reference, with maker-checker records. Use event versioning and idempotent consumers so a status replay cannot change the duplicate finding. Retain the full investigation evidence, including both request payloads, so the root cause can be proven later.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation for each submission, carrying its idempotency and end to end references.", "key_fields": ["Instruction identification", "End to end identification", "Debtor and creditor account", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer credit transfer sent to clearing for each accepted leg.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "pacs.002", "purpose": "Payment status report confirming the status of each leg at clearing.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "camt.056", "purpose": "Payment cancellation request, used only if the duplicate leg is in an eligible state for cancellation.", "key_fields": ["Original instruction reference", "Cancellation reason", "Requester identification"]}, {"message": "camt.029", "purpose": "Resolution of investigation, the response to a cancellation request.", "key_fields": ["Original instruction reference", "Investigation status", "Cancellation status"]}, {"message": "pacs.004", "purpose": "Payment return, used if the duplicate leg is returned after settlement rather than cancelled.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and currency"]}], "accounting_operational": "Both legs are posted as separate ledger entries, and the original entries are never deleted or edited. The duplicate is reversed by a separate linked entry that references the original payment, under maker-checker control, so the statement shows the debit, the duplicate debit and the reversal as distinct events. If the duplicate leg settled, the reversal follows the rail's return or refund path and is reconciled against the clearing record; if it had not settled, the reservation is released once. The case sits in an exception worklist with an owner and an ageing SLA until both legs reconcile, and the supplier confirmation is filed as evidence.", "gherkin": ["Given an already accepted instruction", "When the identical request is retried with the same idempotency key", "Then the platform returns the original payment reference", "And does not create a second debit", "Given a cancellation request", "When the payment is already settled and cannot be cancelled under scheme rules", "Then the system records the request outcome", "And does not falsely mark the original payment cancelled"], "assessment": [{"question": "Two submissions share the same idempotency key and the same payload. What should happen?", "options": ["Both are deleted", "The second returns the original payment reference and no second debit is created", "Two payments are created", "The second is charged a fee"], "answer": 1, "explanation": "An idempotency key scoped to the initiating party and instruction must return the stored outcome for a retry, not create a new payment."}, {"question": "Why are amount and beneficiary alone not enough to block a duplicate?", "options": ["Because the beneficiary is always wrong", "Because the system cannot read amounts", "Because duplicates never share an amount", "Because two legitimate identical payments to the same beneficiary are possible, so uncertain matches need review, not silent blocking"], "answer": 3, "explanation": "Amount and beneficiary alone cannot distinguish a technical retry from a genuine second payment. Stable business identifiers plus review are needed."}, {"question": "A duplicate is found after it has already been sent to clearing. What is correct?", "options": ["Hold it, use the cancellation or return path valid for its state, and reconcile the outcome", "Delete the original payment", "Ignore it because clearing will fix it", "Silently discard it"], "answer": 0, "explanation": "Once submitted downstream, a duplicate needs a controlled cancellation or return under scheme rules, with reconciliation, not silent deletion."}, {"question": "How is a duplicate reversal recorded?", "options": ["As a separate linked entry referencing the original payment, under maker-checker control", "By deleting the original posting", "By editing the amount on the original entry", "By posting it to a different customer"], "answer": 0, "explanation": "Original records stay immutable. The reversal is a new linked entry so the full history remains auditable."}]}}, {"id": "INS-088", "kind": "insight", "title": "Refund API versus reversal API", "topic": "Refund API versus reversal API", "theme": "Payment APIs", "text": "Compare business trigger, timing, original transaction linkage and ledger effects; validate rail/provider semantics.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch26s8", "title": "System design deep dive: payment APIs at scale", "url": "lessons/ch26s8"}}, {"id": "INS-089", "kind": "insight", "title": "Validating a payment API", "topic": "Validating a payment API", "theme": "Payment APIs", "text": "Review authentication, schema, mandatory fields, business validation, response codes, idempotency and observability.", "domain": "APIs & Integration", "area": "APIs & Integration", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch26s8", "title": "System design deep dive: payment APIs at scale", "url": "lessons/ch26s8"}, "case": {"status": "authored", "business_problem": "BrightPay Solutions, a fintech partner, is integrating with Meridian Bank's payment API to submit customer credit transfers on behalf of its merchants. In testing, the API returns a successful HTTP response, but the merchant's downstream order record is not created, and in one case the payment is debited while the merchant dashboard still shows the order as unpaid. BrightPay's developers argue the API is broken; Meridian's team argues the API accepted the request correctly and the failure is downstream. Neither side can prove where the payment stopped, because the request crossed an API gateway, a payment service, an event bus, a downstream consumer and a database, and each hop logged a different identifier.\n\nThe integration also has gaps that testing has not yet covered. Mandatory fields are not consistently validated, error responses use different codes for the same business failure, idempotency behaviour is undocumented, and nobody has agreed what a successful response actually promises: receipt, validation, acceptance, or completion. A scheme rule change during the integration, such as a new mandatory data field, would break the contract silently if versioning and effective dates are not handled.\n\nThe case is about validating the API as a contract: authentication, schema, mandatory fields, business validation, response codes, idempotency and observability, so that a success response means something provable and a failure can be traced to one hop.", "decision_exercise": {"scenario": "The payment API returns HTTP 200, but the merchant order is not created and the payment may have been debited. What is the first validation step?", "options": [{"id": "A", "text": "Assume the API is broken and rebuild the payment service."}, {"id": "B", "text": "Tell the merchant to retry the payment with a new reference."}, {"id": "C", "text": "Check what the response contract promises, then trace the same correlation ID across gateway, service, event bus, downstream consumer and database to find the failed transition."}, {"id": "D", "text": "Increase the HTTP timeout and retest once."}], "correct_option": "C", "why": "C is correct because HTTP success is a transport outcome, not proof of business completion. Only tracing one correlation ID across every hop shows whether the failure is in the callback, the event consumer, the payload mapping or the database. A is wrong because no evidence yet points at the payment service. B is wrong because a blind retry can duplicate a payment that was already debited. D is wrong because a longer timeout does not fix a lost callback or a failed consumer."}, "recommended_solution": "Start from the contract, not from the code. The OpenAPI definition must state, for each endpoint, what a success response promises: receipt, validation, acceptance, or completion, and what the caller must do next in each case. HTTP 200 or 202 is a transport acknowledgement, never proof that a downstream order, account or ledger record was created. Authentication, authorisation and rate limits are tested first, because an unauthenticated success in testing hides a production failure.\n\nValidate the payload in layers. Schema validation checks structure and types; mandatory field validation checks the business required fields for the rail and scheme version; business validation checks limits, account state, currency and beneficiary data against reference data. Each failure returns a stable, documented error code with a reason that maps to one business cause, so the partner can act on it without guessing. Idempotency is part of the contract: the same key returns the original reference, a key with an altered payload is rejected as a conflict, and retention and replay policy are written down.\n\nMake the integration observable by correlation ID. Every hop, gateway, service, event, webhook, consumer and database write, carries the same correlation ID, and status enquiry by that ID returns the current known state. Webhook delivery is retried on a schedule with a dead-letter path, and financial effects are reconciled before any retry. Scheme rule changes are handled as versioned rules with effective dates, so a payment processed before and after the effective date uses the correct rule set, and mixed version traffic is tested explicitly.", "flow_steps": [{"step": 1, "actor": "Partner developer", "action": "Authenticates and submits a payment request with an idempotency key to the API", "system": "Partner client and API gateway"}, {"step": 2, "actor": "API gateway", "action": "Validates authentication, rate limits and schema, and assigns a correlation ID", "system": "API gateway"}, {"step": 3, "actor": "Payment service", "action": "Validates mandatory fields and business rules against limits and reference data", "system": "Payment service"}, {"step": 4, "actor": "Payment service", "action": "Checks the idempotency store and returns the original reference for a retry", "system": "Idempotency store"}, {"step": 5, "actor": "Payment service", "action": "Accepts the instruction, persists it durably, and publishes an event to the event bus", "system": "Payment service and event bus"}, {"step": 6, "actor": "Downstream consumer", "action": "Consumes the event and creates the order, account or ledger record", "system": "Downstream system"}, {"step": 7, "actor": "Payment service", "action": "Sends a webhook or callback with the payment status to the partner", "system": "Webhook service"}, {"step": 8, "actor": "Partner", "action": "Confirms the outcome by status enquiry using the correlation ID if the webhook is missing", "system": "Partner client"}, {"step": 9, "actor": "Operations", "action": "Reconciles financial effects before any retry and investigates dead-letter items", "system": "Reconciliation service"}, {"step": 10, "actor": "Product", "action": "Applies a scheme rule change as a versioned rule from its effective date and retests the contract", "system": "Rule engine"}], "happy_path": "The contract states that acceptance means the instruction passed validation and was persisted, not that settlement is complete. A retry returns the original reference, the downstream order is created exactly once, the webhook arrives, and a missing webhook is resolved by a status enquiry on the same correlation ID with no duplicate payment.", "negative_paths": [{"path": "Callback lost", "trigger": "The webhook never reaches the partner, so the partner does not know the outcome.", "handling": "Retry webhook delivery on a schedule, keep a dead-letter path, and let the partner resolve the outcome by status enquiry."}, {"path": "Event consumer failed", "trigger": "The payment is accepted but the downstream consumer fails and no order is created.", "handling": "Trace the correlation ID to the failed consumer, fix the cause, replay the event idempotently, and reconcile before retrying."}, {"path": "Payload mapping error", "trigger": "A field is mapped incorrectly between the API payload and the downstream record.", "handling": "Fail the mapping visibly with a documented error, hold the item for repair, and never silently drop a field."}, {"path": "Duplicate retry", "trigger": "The partner retries after a timeout with a new key and creates a second payment.", "handling": "Detect the duplicate by business identifiers, hold the second payment for review, and reverse one leg under control."}, {"path": "Scheme rule change mid-integration", "trigger": "A new mandatory field takes effect and old payloads start failing.", "handling": "Apply versioned rules by effective date, publish the change with a migration window, and test mixed version traffic."}], "technical_data": "Separate HTTP transport success from business completion in the contract and in every status response. Persist the idempotency key, payload hash, correlation ID, request and response bodies, and the outcome before any downstream call. Use durable events with an outbox pattern so an accepted payment cannot lose its downstream notification, and make every consumer idempotent with event versioning. Log the correlation ID at every hop, including gateway, service, event bus, consumer and database, so one query reconstructs the whole journey. Version the API and the scheme rules independently, with effective dates, and keep a regression suite that covers authentication failure, schema failure, business validation failure, duplicate key, altered payload, lost callback and dead-letter recovery.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation submitted through the API, carrying the partner's instruction and idempotency reference.", "key_fields": ["Instruction identification", "End to end identification", "Debtor and creditor account", "Instructed amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection of the instruction.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code and additional information"]}, {"message": "pacs.008", "purpose": "Customer credit transfer sent to clearing for an accepted payment.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}], "accounting_operational": "An API acceptance does not create a settlement posting until the payment is processed and clearing confirms it, so the ledger and the partner's order record must be reconciled before any retry is allowed. A duplicate created by a blind retry is a linked exception with a single reversal, never a deleted record. Failed webhook deliveries and dead-letter events go to an operational worklist with an owner and an ageing SLA, because an unprocessed event can hide a financial effect. Scheme rule changes are costed and scheduled as product changes with customer communication, not absorbed silently by operations.", "gherkin": ["Given the API accepted a request but the downstream record is absent", "When the BA coordinates investigation", "Then the team traces the same correlation ID across each integration boundary", "And identifies the failed transition", "Given a scheme rule becomes effective on a defined date", "When a payment is processed before and after that date", "Then the correct versioned rule set is applied"], "assessment": [{"question": "A payment API returns HTTP 200 but no downstream order is created. What does the 200 prove?", "options": ["The money moved", "Only that the HTTP request was received and processed at the transport layer. It does not prove business completion", "The payment settled", "The order was created"], "answer": 1, "explanation": "HTTP success is a transport outcome. The contract must state whether acceptance means receipt, validation, acceptance or completion, and the downstream record must be traced by correlation ID."}, {"question": "A retry uses the same idempotency key but a changed amount. What should the API do?", "options": ["Ignore the change silently", "Create a second payment", "Accept the new amount", "Reject it as a key conflict and hold it for review"], "answer": 3, "explanation": "The same key with an altered payload is a conflict. Applying the new payload to the original payment would corrupt the instruction."}, {"question": "A webhook is lost. How does the partner learn the payment outcome?", "options": ["By submitting the payment again", "By a status enquiry using the original correlation ID, with webhook retry and a dead-letter path behind it", "By waiting for the scheme to call", "By guessing from the dashboard"], "answer": 1, "explanation": "Status enquiry on the correlation ID is the recovery path. A blind resubmission risks a duplicate."}, {"question": "A scheme rule changes a mandatory field. How is it implemented safely?", "options": ["Apply it to all payments immediately, including ones already in flight", "As a versioned rule with an effective date, so payments before and after the date use the correct rule set", "Ignore it until a customer complains", "Change the API without telling partners"], "answer": 1, "explanation": "Effective dated, versioned rules protect in-flight payments and give partners a migration window with regression testing."}]}}, {"id": "INS-090", "kind": "insight", "title": "Settlement cycle and customer communication", "topic": "Settlement cycle and customer communication", "theme": "Payment settlement", "text": "Explain the meaning and limitations of T+1/T+2 examples; use scheme- and product-specific rules.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch77s1", "title": "Settlement cycle design: choosing when and how often to settle", "url": "lessons/ch77s1"}}, {"id": "INS-091", "kind": "insight", "title": "Feature technically complete but business problem remains", "topic": "Feature technically complete but business problem remains", "theme": "Problem solving", "text": "Revisit hypothesis, user behaviour, process adoption, operational constraints and outcome measures.", "domain": "Product Management", "area": "Product Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch82s5", "title": "From strategy to backlog: product requirements and the roadmap", "url": "lessons/ch82s5"}}, {"id": "INS-092", "kind": "insight", "title": "Loan approval time increases from two hours to two days", "topic": "Loan approval time increases from two hours to two days", "theme": "Problem solving", "text": "Analyse queue time, manual reviews, document quality, decision rules and hand-offs.", "domain": "Banking Products", "area": "Banking Products", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s2", "title": "Business Process Modelling: As-Is and To-Be Flows", "url": "lessons/ch28s2"}}, {"id": "INS-093", "kind": "insight", "title": "Why stakeholders repeat the same change request", "topic": "Why stakeholders repeat the same change request", "theme": "Problem solving", "text": "Investigate root need, decision latency, incomplete discovery and feedback loops.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s1", "title": "Requirements Gathering for Payments Projects", "url": "lessons/ch28s1"}}, {"id": "INS-094", "kind": "insight", "title": "BA ownership without direct authority", "topic": "BA ownership without direct authority", "theme": "Delivery ownership", "text": "Drive clarity, decision records, follow-ups and transparent escalation across teams.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch28s7", "title": "Workshop Facilitation: Running a Payments Discovery Workshop", "url": "lessons/ch28s7"}}, {"id": "INS-095", "kind": "insight", "title": "Managing written communication and sign-offs", "topic": "Managing written communication and sign-offs", "theme": "Delivery ownership", "text": "Use meeting notes, action owners, decisions, assumptions and explicit approval records.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s2", "title": "Writing a BRD and a functional specification for a payment product", "url": "lessons/ch84s2"}}, {"id": "INS-096", "kind": "insight", "title": "Choose a target BA domain before learning tools", "topic": "Choose a target BA domain before learning tools", "theme": "Career transition", "text": "Evaluate transferable experience, domain demand, interest and realistic entry path.", "domain": "Career & Professional Skills", "area": "Career & Professional Skills", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s7", "title": "Your Learning Path Forward", "url": "lessons/ch35s7"}}, {"id": "INS-097", "kind": "insight", "title": "Build practical BA projects rather than only theory", "topic": "Build practical BA projects rather than only theory", "theme": "Career transition", "text": "Create a portfolio with problem statement, process maps, stories, API contract and UAT evidence.", "domain": "Career & Professional Skills", "area": "Career & Professional Skills", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch29s6", "title": "Hands-on BA Deliverables Checklist", "url": "lessons/ch29s6"}}, {"id": "INS-098", "kind": "insight", "title": "Optimise recruiter search visibility", "topic": "Optimise recruiter search visibility", "theme": "Career transition", "text": "Align profile keywords with target role, domain, skills and verifiable experience.", "domain": "Career & Professional Skills", "area": "Career & Professional Skills", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s7", "title": "Your Learning Path Forward", "url": "lessons/ch35s7"}}, {"id": "INS-099", "kind": "insight", "title": "Explain an unfamiliar scenario logically", "topic": "Explain an unfamiliar scenario logically", "theme": "Interview technique", "text": "Clarify assumptions, break down flow, identify risks and state what evidence you would obtain.", "domain": "Interview Masterclass", "area": "Interview Masterclass", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch35s6", "title": "Interview Q and A for Payments Roles", "url": "lessons/ch35s6"}}, {"id": "INS-100", "kind": "insight", "title": "Walk through current project and exact BA responsibilities", "topic": "Walk through current project and exact BA responsibilities", "theme": "Interview technique", "text": "Structure answer around context, scope, stakeholders, systems, deliverables, decisions and outcomes.", "domain": "Interview Masterclass", "area": "Interview Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch29s6", "title": "Hands-on BA Deliverables Checklist", "url": "lessons/ch29s6"}}, {"id": "INS-101", "kind": "insight", "title": "INDA versus INGA settlement method", "topic": "INDA versus INGA settlement method", "theme": "Payment BA Awareness", "text": "Distinguish settlement method choices and their impact on payment processing and liquidity.", "domain": "Payment Architecture", "area": "Payment Architecture", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch14s6", "title": "INDA, INGA, COVE and CLRG codes", "url": "lessons/ch14s6"}}, {"id": "INS-102", "kind": "insight", "title": "End-to-end payment workflow", "topic": "End-to-end payment workflow", "theme": "Payment BA Awareness", "text": "Map initiation, validation, processing, routing, clearing, settlement and confirmation.", "domain": "Payment Foundations", "area": "Payment Foundations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch4s1", "title": "Initiation, where every payment begins", "url": "lessons/ch4s1"}, "case": {"status": "authored", "business_problem": "Northgate Retail pays more than 200 suppliers each week through Meridian Bank, using a single bulk file. The finance team thinks of a payment as one action: upload the file, and the suppliers get paid. In practice, a payment passes through initiation, validation, processing, routing, clearing, settlement and confirmation, and each stage has its own owner, its own status, and its own failure mode. When a supplier calls to say they were not paid, the finance team cannot say which stage failed, because they only ever saw the file acknowledgement.\n\nThe confusion has real consequences. A file acknowledgement is treated as proof that every supplier was paid, so a rejected item is not chased until the supplier complains. A payment accepted by the bank is treated as settled, so a later clearing rejection catches the team by surprise. A returned payment is treated as a cancellation, so the original payment record is questioned instead of the return being handled as a new linked event. The team needs a workflow map that separates each stage and names the evidence that proves it.\n\nThe case follows one bulk file from initiation to confirmation, showing where each stage can fail, what status it produces, and how the team proves the outcome without guessing.", "decision_exercise": {"scenario": "Northgate Retail uploads a bulk supplier file and receives a file acknowledgement. A supplier later says they were not paid. What does the acknowledgement actually prove?", "options": [{"id": "A", "text": "That no further checking is needed."}, {"id": "B", "text": "That every supplier in the file was paid."}, {"id": "C", "text": "That the file was received and passed file-level checks. Each transaction still needs its own validation, processing, clearing and settlement outcome."}, {"id": "D", "text": "That the money has settled in every supplier account."}], "correct_option": "C", "why": "C is correct because file-level acceptance and transaction-level acceptance are separate. The acknowledgement proves receipt and file-level checks only. B and A are wrong because acceptance is not settlement, and a clearing rejection or a return can still follow. A is wrong because each transaction needs its own outcome and reconciliation."}, "recommended_solution": "Map the workflow as seven stages with a defined status and a defined evidence artefact at each stage. Initiation captures the instruction with a unique reference, idempotency key and remittance data. Validation checks schema, mandatory fields, limits, account state and sanctions screening, and produces an item level outcome for every transaction. Processing enriches the instruction, reserves funds where the product requires it, and routes it by rail, currency, value and cut-off. Routing selects the clearing path and the intermediary chain from effective dated reference data. Clearing sends the interbank message and waits for acceptance or rejection. Settlement moves funds between accounts at the central bank or through correspondent accounts. Confirmation updates the customer status and the statement only when the authoritative settlement or clearing evidence arrives.\n\nKeep the statuses distinct at every stage. Channel acceptance means the bank received a valid instruction. Payment engine acceptance means it passed validation. Clearing acceptance means the next agent accepted the interbank message. Settlement finality means the funds moved irrevocably. A return after settlement is a new linked event, recorded with the original references, not an erasure of the original payment. A partial batch failure is handled item by item: valid items proceed where partial processing is permitted, rejected items receive an item level reason, and accepted items are never resubmitted when rejected items are repaired.\n\nReconcile at the end of the workflow, not in the middle of it. The ledger, the clearing acknowledgements and the customer statements are joined by payment reference and correlation ID, and any item without a matching outcome in all three sits in an exception worklist. The workflow is complete only when every transaction has a final status that is proven by evidence, not when the file was uploaded.", "flow_steps": [{"step": 1, "actor": "Corporate user", "action": "Creates a bulk supplier file with one instruction per supplier and uploads it", "system": "Corporate online banking"}, {"step": 2, "actor": "Payment platform", "action": "Acknowledges receipt of the file and validates the file structure and control totals", "system": "File intake service"}, {"step": 3, "actor": "Payment engine", "action": "Validates each transaction for schema, mandatory fields, limits, account state and screening", "system": "Payment engine"}, {"step": 4, "actor": "Payment engine", "action": "Enriches accepted instructions, reserves funds where required, and selects the rail and route", "system": "Routing engine"}, {"step": 5, "actor": "Clearing adapter", "action": "Sends each accepted payment as an interbank message to clearing", "system": "Clearing connector"}, {"step": 6, "actor": "Clearing system", "action": "Accepts or rejects each message and returns a status for each item", "system": "Clearing system"}, {"step": 7, "actor": "Settlement system", "action": "Settles accepted payments by moving funds between settlement accounts", "system": "Settlement system"}, {"step": 8, "actor": "Ledger", "action": "Posts the debit and credit entries once settlement or clearing evidence is confirmed", "system": "Core ledger"}, {"step": 9, "actor": "Channel", "action": "Updates the customer status and statement for each transaction from the authoritative outcome", "system": "Channel status service"}, {"step": 10, "actor": "Payments operations", "action": "Reconciles ledger, clearing and statement records for every item and clears exceptions", "system": "Reconciliation service"}], "happy_path": "The file is acknowledged, every transaction passes validation, each accepted payment clears and settles, the ledger posts match the clearing acknowledgements, and the customer sees a final confirmed status per supplier with a statement entry to match. Rejected items, if any, carry an item level reason and are repaired without resubmitting accepted items.", "negative_paths": [{"path": "Partial batch failure", "trigger": "Some transactions fail validation while others pass.", "handling": "Apply item level outcomes under the agreed partial processing rule, return reasons per item, and never resubmit accepted items."}, {"path": "Clearing rejection after acceptance", "trigger": "The bank accepted the instruction but clearing rejects the interbank message.", "handling": "Move the payment to a defined rejected state, reverse or release any reservation once, and notify the channel with the mapped reason."}, {"path": "Return after settlement", "trigger": "The beneficiary bank returns a payment after it settled.", "handling": "Treat the return as a new linked event with the original references, post it separately, and update the customer status."}, {"path": "File control sum mismatch", "trigger": "The file total does not match the sum of its transactions.", "handling": "Reject the file at intake, tell the customer the exact mismatch, and do not process any item from it."}, {"path": "Duplicate file", "trigger": "The same file is uploaded twice.", "handling": "Detect the duplicate by file ID and control totals, return the original outcomes, and do not reprocess the items."}], "technical_data": "Give every file a file ID and every transaction a transaction ID, instruction ID, end to end ID and correlation ID, and carry those identifiers through every stage so any item can be traced from upload to settlement. Keep file-level and transaction-level acceptance as separate states with separate evidence. Validate against effective dated reference data for routing, limits and screening, and record which version governed each decision. Use idempotency keys at intake so a duplicate file or a retried instruction returns the original outcome. Store status transitions with timestamps and the authoritative source for each transition, and make status consumers idempotent so an out-of-order event cannot regress a payment.", "messages_fields": [{"message": "pain.001", "purpose": "Customer credit transfer initiation, one per supplier, carrying the bulk file and item references.", "key_fields": ["Instruction identification", "End to end identification", "Debtor and creditor account", "Instructed amount and currency", "Remittance information"]}, {"message": "pain.002", "purpose": "Customer payment status report giving item level outcomes for the file.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "pacs.008", "purpose": "Customer credit transfer sent to clearing for each accepted payment.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "pacs.002", "purpose": "Payment status report confirming clearing acceptance or rejection per item.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "pacs.004", "purpose": "Payment return, used when a settled payment is returned by the beneficiary side.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and currency"]}, {"message": "camt.053", "purpose": "Bank to customer statement evidencing the final ledger postings.", "key_fields": ["Statement period", "Entry reference", "Amount, currency and value date"]}], "accounting_operational": "The ledger posts one entry per settled payment, or one aggregate entry plus item level detail where batch booking is the agreed product, and in either case the aggregate and the item totals must reconcile. A clearing rejection releases or reverses any reservation exactly once. A return after settlement is a separate linked entry, so the original debit and the return credit both remain visible. Fees are posted as separate entries with their own references. The daily reconciliation joins the file, the clearing acknowledgements and the ledger, and any item without a matching outcome in all three sits in an exception worklist with an owner and an ageing SLA.", "gherkin": ["Given a partially valid file and partial processing enabled", "When the file is processed", "Then each transaction receives an independent outcome", "And only accepted transactions proceed", "Given a clearing rejection correlated to a payment", "When the response is received", "Then the payment is moved to the appropriate rejected state", "And any related accounting reservation is handled once", "Given a valid return message", "When the original transaction is identified", "Then the return is recorded as a linked transaction", "And the original record remains immutable"], "assessment": [{"question": "What does a file acknowledgement prove?", "options": ["Settlement is complete", "Every transaction was paid", "The suppliers have been credited", "The file was received and passed file-level checks. Transaction outcomes are still to come"], "answer": 3, "explanation": "File-level and transaction-level acceptance are separate. The acknowledgement proves receipt, not payment."}, {"question": "A payment is accepted by the bank but rejected by clearing. What is its state?", "options": ["Settled", "Cancelled by the customer", "Paid", "Rejected at clearing, with any reservation reversed or released once and the channel notified"], "answer": 3, "explanation": "Channel acceptance, engine acceptance, clearing acceptance and settlement are distinct states. A clearing rejection moves the payment to a defined rejected state."}, {"question": "A settled payment is returned by the beneficiary bank. How is it recorded?", "options": ["By deleting the original payment", "By editing the original amount to zero", "By ignoring it", "As a new linked event with the original references, keeping the original record immutable"], "answer": 3, "explanation": "A return is a separate financial event linked to the original. The original record must remain immutable for audit and reconciliation."}, {"question": "In a partial batch failure, what happens to accepted items when rejected items are repaired?", "options": ["They are paid twice", "They are not resubmitted. Only rejected items are repaired and reprocessed", "They are resubmitted with the repairs", "They are deleted"], "answer": 1, "explanation": "Accepted items already have an outcome. Resubmitting them would duplicate payments. Only rejected items go through repair."}]}}, {"id": "INS-103", "kind": "insight", "title": "MT-to-MX mapping when MX requires data absent in MT", "topic": "MT-to-MX mapping when MX requires data absent in MT", "theme": "Payment BA Awareness", "text": "Identify data loss, enrichment, translation rules and exception governance during coexistence.", "domain": "ISO 20022", "area": "ISO 20022", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch6s9", "title": "MT versus MX worked comparison: the same payment as MT103 and as pacs.008, field by field", "url": "lessons/ch6s9"}, "case": {"status": "authored", "business_problem": "Meridian Bank is migrating cross-border payments from MT to ISO 20022 MX messages during the coexistence period. A corporate customer sends an MT103 that carries the beneficiary name and an unstructured address, but the MX pacs.008 that must be produced requires structured or hybrid address data, with a minimum of Town Name and Country Code, or a BIC only where that is permitted. The MT message simply does not contain the town, and nobody at the bank can invent it. If the mapping fills a guessed value, the payment carries false data. If it leaves the field blank, the MX message fails validation at the next agent. If it holds every such payment for repair, the straight through processing rate collapses.\n\nThe same gap appears in other fields. An MT202 COV cover payment maps to a pacs.009, but the underlying customer information that the cover must carry may be incomplete in the MT. Remittance information that fitted in an MT free text field may not map cleanly to the structured MX elements. Each gap needs a rule: enrich from a trusted source, derive from reference data, hold for repair, or reject with a clear reason. The rule must be governed, because an enrichment that changes the meaning of a payment is a different risk from an enrichment that only reformats it.\n\nThe case is about governing data loss during coexistence: identifying what is missing, where it can be safely enriched, and what must go to an exception queue rather than being guessed.", "decision_exercise": {"scenario": "An MT103 must become a pacs.008, but the MX message requires a Town Name that the MT does not contain. What is the correct handling?", "options": [{"id": "A", "text": "Drop the address entirely and send the payment with only the beneficiary name."}, {"id": "B", "text": "Invent a likely town name so the message validates and the payment is not delayed."}, {"id": "C", "text": "Leave the address blank and send the message anyway."}, {"id": "D", "text": "Apply the governed translation rule: enrich only from a trusted source such as the customer master or reference data, and if no trusted source holds the town, hold the payment for repair or reject it with a clear reason. Never fabricate the value."}], "correct_option": "D", "why": "D is correct because a mandatory target value missing from the source message must never be fabricated. Enrichment is only valid from a trusted, governed source, and an unresolvable gap goes to repair or rejection with an audit trail. B is wrong because a guessed town is false data. C and B are wrong because the message would fail validation or breach the structured address requirement."}, "recommended_solution": "Start with a field level mapping inventory that lists, for each MT to MX pair, the source field, the target field, whether the target is mandatory, and what happens when the source is absent. MT103 maps to pacs.008 for the customer leg, and MT202 COV maps to pacs.009 for the cover leg, and each mapping is versioned against the message version in force. For every mandatory MX field with no MT equivalent, define one of four governed outcomes: enrich from a trusted source, derive deterministically from reference data, hold for repair, or reject. The choice is recorded per field, per corridor, with an owner and an effective date.\n\nEnrichment is only permitted from a trusted source. The customer master, the beneficiary master, or a governed reference data set can supply a Town Name that the customer has already provided; a mapping table cannot invent one. Enriched values are tagged with their source so a downstream investigation can tell what came from the customer and what came from enrichment. A repair is a controlled change: an operator corrects a permitted field under maker-checker control, the change is audited, and the transaction is revalidated before release. A repair that changes the payment meaning, such as changing the beneficiary or the amount, is not a repair and must be rejected back to the customer.\n\nHandle the structured address requirement explicitly. The requirement stands: structured or hybrid address, with a minimum of Town Name and Country Code, or BIC only where permitted. Do not teach a fixed cut-off date for this change, because the timeline was extended and a new timeline was expected; teach the requirement and the need to check the current SWIFT timeline before configuring a date. Measure the impact as a defect Pareto: which fields, which corridors and which customers generate the most repairs, so the bank fixes the gap at source, by improving upstream capture, rather than repairing the same defect payment after payment.", "flow_steps": [{"step": 1, "actor": "Corporate user", "action": "Submits a cross-border payment in MT format through the channel", "system": "Corporate online banking"}, {"step": 2, "actor": "Payment engine", "action": "Receives the MT103 and identifies the target MX message as pacs.008", "system": "Payment engine"}, {"step": 3, "actor": "Translation service", "action": "Maps each MT field to its MX equivalent using the versioned mapping inventory", "system": "Translation service"}, {"step": 4, "actor": "Translation service", "action": "Flags mandatory MX fields that have no MT source, including the missing Town Name", "system": "Translation service"}, {"step": 5, "actor": "Enrichment service", "action": "Looks up the missing value in the trusted customer or beneficiary master", "system": "Reference data service"}, {"step": 6, "actor": "Repair workbench", "action": "Holds the payment for repair if no trusted source holds the value, with the gap shown to the operator", "system": "Repair workbench"}, {"step": 7, "actor": "Operator", "action": "Corrects a permitted field under maker-checker control, or rejects the payment with a clear reason", "system": "Repair workbench"}, {"step": 8, "actor": "Payment engine", "action": "Revalidates the completed MX message against the scheme rules before release", "system": "Payment engine"}, {"step": 9, "actor": "Clearing adapter", "action": "Sends the pacs.008 to the next agent", "system": "SWIFT connector"}, {"step": 10, "actor": "Payments operations", "action": "Reports the repair rate by field, corridor and customer to drive upstream fixes", "system": "Operations reporting"}], "happy_path": "The MT103 maps cleanly to pacs.008, the Town Name is enriched from the beneficiary master where the customer already provided it, the message validates, and the payment proceeds without manual touch. Where enrichment is not possible, the item goes to repair once, is corrected under maker-checker control, revalidates, and settles.", "negative_paths": [{"path": "Mandatory value absent and no trusted source", "trigger": "The Town Name is missing from the MT and from every trusted source.", "handling": "Hold the payment for repair or reject it with a clear reason. Never fabricate the value."}, {"path": "Enrichment changes payment meaning", "trigger": "A repair corrects the beneficiary name or the amount, not just the address format.", "handling": "Treat it as a new instruction, not a repair. Reject it back to the customer for confirmation."}, {"path": "High repair rate in a remittance file", "trigger": "Most transactions in a file need manual repair for missing or inconsistent data.", "handling": "Segment defects by root cause and source, improve upstream validation, and prioritise repairs by SLA."}, {"path": "Cover leg loses customer data", "trigger": "The MT202 COV maps to pacs.009 but the underlying customer information is incomplete.", "handling": "Hold the cover leg, enrich from the original customer leg where it exists, and never send a cover without its required underlying data."}, {"path": "Mixed version traffic", "trigger": "Some counterparties still send MT while others send MX, and the mapping versions differ.", "handling": "Apply the mapping version that matches the message version in force for that corridor, and test mixed version traffic explicitly."}], "technical_data": "Keep the mapping inventory as versioned configuration, with the MT version, the MX version, the field mapping, the mandatory flag and the gap rule for each field. Tag every enriched value with its source system and timestamp so the audit trail distinguishes customer supplied data from enriched data. Persist the original MT message unchanged alongside the generated MX message, with a shared correlation ID, so any downstream query can compare the two. Apply maker-checker control to repairs, audit every change, and revalidate the full message after repair, not only the changed field. Record straight through processing rate, repair ageing and defect Pareto by field, corridor and customer, and use them to drive upstream capture fixes.", "messages_fields": [{"message": "MT103", "purpose": "Single customer credit transfer in MT format, the source message for the customer leg.", "key_fields": ["Field 50 ordering customer", "Field 59 beneficiary customer", "Field 70 remittance information", "Field 32A value date, currency and amount"]}, {"message": "pacs.008", "purpose": "Customer credit transfer in MX format, the target message for the customer leg.", "key_fields": ["Debtor and creditor identification", "Structured or hybrid postal address with Town Name and Country Code", "Instructed amount and currency", "Remittance information"]}, {"message": "MT202 COV", "purpose": "General financial institution transfer with cover information, the source message for the cover leg.", "key_fields": ["Field 50 ordering institution", "Field 56 intermediary", "Field 57 account with institution", "Field 58 beneficiary institution"]}, {"message": "pacs.009", "purpose": "Financial institution credit transfer in MX format, the target message for the cover leg.", "key_fields": ["Debtor and creditor agent", "Cover and underlying customer information", "Interbank settlement amount"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection of the generated MX message.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}], "accounting_operational": "A held payment creates no settlement posting until it is released, so the ledger is unaffected by the repair queue itself; the operational cost is time, repair capacity and SLA risk. A rejected payment releases any reservation once and notifies the customer with the exact missing field, so the customer can correct it at source. A repaired payment is revalidated before release, and the repair is audited as a separate event linked to the original instruction. The repair worklist is prioritised by value date and cut-off, with ageing alerts, and its size is reported as a straight through processing metric, not hidden inside a general backlog.", "gherkin": ["Given a repairable transaction", "When an authorised operator corrects a permitted field", "Then the change is audited", "And the transaction is revalidated before release", "Given a mandatory MX field with no MT source and no trusted enrichment source", "When translation completes", "Then the payment is held for repair or rejected with a clear reason", "And no value is fabricated"], "assessment": [{"question": "MT103 maps to which MX message?", "options": ["camt.053", "pacs.008", "pain.001", "pacs.009"], "answer": 1, "explanation": "MT103, the single customer credit transfer, maps to pacs.008. MT202 COV maps to pacs.009."}, {"question": "A mandatory MX field is missing from the MT and no trusted source holds it. What is correct?", "options": ["Hold the payment for repair or reject it with a clear reason, and never fabricate the value", "Delete the payment", "Invent a plausible value", "Leave the field blank and send it"], "answer": 0, "explanation": "A mandatory target value missing from the source must never be fabricated. Enrichment only comes from a trusted source, or the item goes to repair or rejection."}, {"question": "What is the minimum structured address requirement taught here?", "options": ["Structured or hybrid address with a minimum of Town Name and Country Code, or BIC only where permitted", "Full street address only", "Country only", "No address is needed"], "answer": 0, "explanation": "The requirement is structured or hybrid address, minimum Town Name and Country Code, or BIC only. No fixed cut-off date is taught, because the timeline was extended."}, {"question": "A repair changes the beneficiary name. How is it handled?", "options": ["By the operator alone without audit", "By editing the original MT", "As a new instruction. It is rejected back to the customer for confirmation, not repaired silently", "As a normal repair"], "answer": 2, "explanation": "A change to the beneficiary or amount changes the payment meaning. That is not a repair; it needs fresh customer confirmation."}]}}, {"id": "INS-104", "kind": "insight", "title": "SWIFT messaging versus ISO 20022", "topic": "SWIFT messaging versus ISO 20022", "theme": "Payment BA Awareness", "text": "Explain network/service versus message standard and their relationship in payment flows.", "domain": "ISO 20022", "area": "ISO 20022", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch6s1", "title": "What ISO 20022 is", "url": "lessons/ch6s1"}}, {"id": "INS-105", "kind": "insight", "title": "UPI customer instant credit versus interbank settlement", "topic": "UPI customer instant credit versus interbank settlement", "theme": "Payment BA Awareness", "text": "Separate customer experience timing from settlement model and liquidity exposure.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch18s6", "title": "Choosing a Model for a Payment System", "url": "lessons/ch18s6"}, "case": {"status": "authored", "business_problem": "A customer of Meridian Bank in India pays a merchant by UPI and sees the money leave the account instantly, with the merchant confirming receipt within seconds. The customer assumes the banks have already settled with each other. In fact, the customer experience and the interbank settlement are two different events: the customer debit and the merchant credit happen in near real time, while the interbank settlement between the banks follows the scheme's settlement cycle, and the bank carries a liquidity and reconciliation exposure in between.\n\nThe distinction matters when something goes wrong. If the merchant's bank has credited the merchant but the interbank leg is delayed, the customer cannot be debited twice to fix it. If the customer's bank debited the customer but the merchant never received the credit, the customer needs a reversal, not a second payment. If a payment is above the UPI limit for its category, it must be routed elsewhere, and the customer needs to know why UPI was not available rather than being told the payment simply failed.\n\nThe case separates the three clocks in every UPI payment: the customer clock, which is instant; the clearing clock, which confirms the instruction; and the settlement clock, which moves funds between banks. It also places UPI alongside the other Indian rails so the learner can choose the right rail for the amount and the need, instead of treating all instant looking payments as the same.", "decision_exercise": {"scenario": "A UPI payment shows as successful to the customer within seconds, but the interbank settlement between the two banks has not yet happened. Has the payment settled?", "options": [{"id": "A", "text": "No. The customer leg is complete, but interbank settlement follows the scheme settlement cycle, and the bank carries the exposure until it completes."}, {"id": "B", "text": "Yes, customer confirmation is settlement."}, {"id": "C", "text": "No, the customer payment should be reversed until settlement happens."}, {"id": "D", "text": "Yes, because UPI is real time in every sense."}], "correct_option": "A", "why": "A is correct because customer experience timing and settlement are separate. The debit and credit are instant for the customer, while interbank settlement follows the scheme cycle. B is wrong because confirmation is not settlement finality. D is wrong for the same reason. C is wrong because reversing a completed customer leg would create a second error."}, "recommended_solution": "Teach the payment as three linked but separate events, each with its own authoritative source. The customer event is the debit to the payer and the credit to the payee, confirmed in seconds through the UPI switch. The clearing event is the confirmation that the instruction was accepted and routed correctly. The settlement event is the movement of funds between the banks through the scheme settlement cycle. Operations must be able to show, for any payment, which of the three events has happened and which has not, by joining the customer record, the switch confirmation and the settlement record by transaction reference.\n\nChoose the rail by amount, urgency and settlement need, not by habit. UPI is instant for the customer with a limit of INR 5 lakh for specified categories. IMPS is instant and typically bank capped around Rs 5 lakh. NEFT settles in half-hourly batches and suits non urgent transfers. RTGS settles individually in real time, has a minimum of Rs 2 lakh and no RBI maximum, and suits high value time critical transfers. All four operate 24x7x365, so availability does not distinguish them; amount, urgency and settlement model do. The UPI-PayNow linkage, live since 21 February 2023, lets a customer pay a Singapore payee by UPI ID, mobile number or VPA, with an initial Indian daily limit of Rs 60,000, and the same three clock separation applies across the border.\n\nHandle failures by the event that failed. A customer debit without a merchant credit is a reversal case, not a retry case. A merchant credit without a completed interbank leg is a settlement and reconciliation case, not a customer case. A payment above the UPI limit is a routing case: explain the limit, offer the correct rail, and never silently split the payment to fit under the limit.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Initiates a UPI payment to a merchant by UPI ID, mobile number or VPA", "system": "UPI app"}, {"step": 2, "actor": "Payer bank", "action": "Validates the instruction, checks the UPI limit for the category, and debits the customer", "system": "Core banking and UPI switch"}, {"step": 3, "actor": "UPI switch", "action": "Routes the instruction to the payee bank and confirms acceptance", "system": "UPI switch"}, {"step": 4, "actor": "Payee bank", "action": "Credits the merchant account and confirms the credit to the switch", "system": "Core banking"}, {"step": 5, "actor": "Customer", "action": "Sees instant confirmation that the merchant has been paid", "system": "UPI app"}, {"step": 6, "actor": "Scheme", "action": "Nets and settles the interbank positions between the banks in the settlement cycle", "system": "Settlement system"}, {"step": 7, "actor": "Payer bank", "action": "Reconciles the customer debit, the switch confirmation and the settlement record", "system": "Reconciliation service"}, {"step": 8, "actor": "Merchant", "action": "Sees the credit in the merchant account and statement", "system": "Merchant banking"}, {"step": 9, "actor": "Payments operations", "action": "Investigates any item where the customer leg and the settlement leg disagree", "system": "Exception workbench"}, {"step": 10, "actor": "Payments operations", "action": "Closes the payment only when customer, clearing and settlement records all agree", "system": "Reconciliation service"}], "happy_path": "The customer pays, the merchant is credited within seconds, the switch confirms acceptance, and the interbank settlement completes in the scheme cycle. The reconciliation joins the customer debit, the switch confirmation and the settlement record, all three agree, and the payment closes with no exception.", "negative_paths": [{"path": "Debited but not credited", "trigger": "The payer bank debited the customer but the payee bank never credited the merchant.", "handling": "Hold the payment as a reversal case, return the funds to the customer as a separate linked entry, and never ask the customer to pay again."}, {"path": "Credited but settlement delayed", "trigger": "The merchant is credited but the interbank settlement leg is delayed.", "handling": "Treat it as a settlement and liquidity case for the bank, not a customer case, and do not debit the customer a second time."}, {"path": "Above the UPI limit", "trigger": "The amount exceeds the UPI limit of INR 5 lakh for its category.", "handling": "Explain the limit, route the payment by IMPS, NEFT or RTGS as the amount and urgency require, and never split it silently to fit."}, {"path": "Clearing rejection after acceptance", "trigger": "The bank accepted the instruction but the clearing participant rejects the resulting message.", "handling": "Move the payment to a defined rejected state, reverse or release any reservation once, and notify the customer with the mapped reason."}, {"path": "Cross-border proxy failure", "trigger": "A UPI-PayNow payment fails because the proxy identifier does not resolve to the intended payee.", "handling": "Do not debit the customer, show the exact proxy failure, and let the customer correct the identifier before retrying."}], "technical_data": "Store the customer leg, the switch confirmation and the settlement record as separate events linked by the transaction reference and UPI transaction ID, each with its own timestamp and authoritative source. Never derive the settlement state from the customer confirmation screen. Record the limit evaluation, including the category, the amount, and the limit that governed, so a rejection can be explained. Use idempotency on the UPI instruction so a retry after a timeout returns the original outcome. Reconcile the three events on a defined cadence, age unmatched items in an exception worklist, and alert when a customer leg and a settlement leg disagree past the agreed window.", "messages_fields": [{"message": "UPI transaction message", "purpose": "Switch message carrying the UPI instruction between payer and payee banks.", "key_fields": ["Transaction ID", "Payer and payee VPA or UPI ID", "Amount and currency", "Transaction status"]}, {"message": "pacs.008", "purpose": "Customer credit transfer used where an account based interbank leg is sent for the underlying payment.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection of an instruction.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "camt.053", "purpose": "Bank to customer statement evidencing the customer debit and credit.", "key_fields": ["Statement period", "Entry reference", "Amount, currency and value date"]}], "accounting_operational": "The customer debit and the merchant credit are posted at the customer leg, while the interbank settlement is a separate bank to bank movement that follows the scheme cycle. Until settlement completes, the bank carries a settlement exposure that is monitored by treasury and reconciled by operations. A debit without a credit is reversed as a separate linked entry to the customer, under maker-checker control, and is never netted silently against another payment. A credit without a completed settlement leg stays visible in the nostro or settlement reconciliation worklist until the cycle completes. Batch booking questions do not arise for a single UPI payment, but where a merchant receives many UPI credits, the statement must still allow each credit to be traced to its transaction reference.", "gherkin": ["Given a clearing rejection correlated to a payment", "When the response is received", "Then the payment is moved to the appropriate rejected state", "And any related accounting reservation is handled once", "Given a batch with one returned transaction", "When accounting is generated", "Then aggregate and item-level records reconcile", "And successful items are not reversed"], "assessment": [{"question": "A UPI payment is confirmed to the customer in seconds. Has interbank settlement happened?", "options": ["No. Customer timing and interbank settlement are separate, and settlement follows the scheme cycle", "No, the payment is not real", "Yes, confirmation is settlement", "Yes, UPI settles instantly between banks"], "answer": 0, "explanation": "The customer debit and credit are instant, but the banks settle through the scheme settlement cycle. The two events must be tracked separately."}, {"question": "Which rail suits a high value time critical transfer of Rs 50 lakh?", "options": ["NEFT, because it is batched", "RTGS, which settles individually in real time, has a minimum of Rs 2 lakh and no RBI maximum", "Cash", "UPI, because it is instant"], "answer": 1, "explanation": "RTGS is the high value real time rail. UPI is limited to INR 5 lakh for specified categories and IMPS is typically bank capped around Rs 5 lakh."}, {"question": "NEFT, RTGS, IMPS and UPI differ in settlement in which way?", "options": ["They all settle in half-hourly batches", "NEFT settles in half-hourly batches, RTGS settles individually in real time, IMPS and UPI are instant for the customer", "RTGS is batched and NEFT is real time", "IMPS settles weekly"], "answer": 1, "explanation": "NEFT is half-hourly batches, RTGS is individual real time settlement, and IMPS and UPI give instant customer confirmation. All four operate 24x7x365."}, {"question": "A customer was debited by UPI but the merchant was never credited. What is correct?", "options": ["Debit the customer again to try to push it through", "Treat it as a reversal case and return the funds as a separate linked entry", "Ask the customer to pay again", "Do nothing and wait a month"], "answer": 1, "explanation": "A debit without a credit is reversed once as a linked entry. A second payment would risk paying twice if the first credit later arrives."}]}}, {"id": "INS-106", "kind": "insight", "title": "SDD file submission D-1 versus infrastructure readiness", "topic": "SDD file submission D-1 versus infrastructure readiness", "theme": "Payment BA Awareness", "text": "Assess scheme calendar, file cut-off, bank processing and operational capacity before changing dates.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}}, {"id": "INS-107", "kind": "insight", "title": "Payment routing under uncertainty", "topic": "Payment routing under uncertainty", "theme": "Payment BA Awareness", "text": "Define routing rules, eligibility, fallback, decision precedence and auditability.", "domain": "Payment Routing", "area": "Payment Routing", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch25s5", "title": "Routing, Clearing and Settlement", "url": "lessons/ch25s5"}, "case": {"status": "authored", "business_problem": "Meridian Bank routes cross-border payments through correspondent banks. On a Tuesday morning, a correspondent reduces Meridian's intraday credit limit without warning, cutting the capacity available on a busy euro corridor by half. The routing engine, which was configured the previous day, keeps sending payments down the same corridor until treasury notices the limit change. Some payments queue, some are rejected by the correspondent, and the operations team cannot say which payments are affected, which alternative route is available, or which payments must be prioritised.\n\nRouting under uncertainty is not a single decision. It is a set of rules that must answer, for each payment, whether the preferred route is still eligible, whether an alternative route is available and at what cost, whether the payment should wait for capacity or be rerouted, and who decides when the rules conflict. If the rules are not written down, each operator improvises, and the same payment can be routed differently by two people on the same day. If the decision is not recorded, nobody can explain later why a payment took the expensive route or missed its cut-off.\n\nThe case is about making routing explainable: eligibility, fallback, decision precedence and auditability, so that a limit change produces a controlled rerouting, not a queue of unexplained failures.", "decision_exercise": {"scenario": "A correspondent halves Meridian's intraday credit limit on a busy corridor mid-morning. Payments are queuing and some are being rejected. What should the routing response be?", "options": [{"id": "A", "text": "Reject all payments on the corridor immediately without checking alternatives."}, {"id": "B", "text": "Send every payment by the most expensive alternative route without prioritisation."}, {"id": "C", "text": "Update the route eligibility controls with the revised limit, quantify the affected corridor and currency, prioritise critical payments, assess alternative correspondents, and record every routing decision."}, {"id": "D", "text": "Keep sending payments down the same corridor and hope the limit is restored."}], "correct_option": "C", "why": "C is correct because routing must follow the revised capacity, not the stale configuration. Quantifying the impact, prioritising critical payments and assessing alternatives keeps the corridor controlled, and recording decisions makes them auditable. D is wrong because it keeps breaching a limit that no longer exists. A is wrong because some payments may fit within the reduced limit or a valid alternative. B is wrong because unprioritised use of the expensive route wastes capacity and money."}, "recommended_solution": "Govern routing as a rule set with four layers: eligibility, fallback, precedence and audit. Eligibility says which routes a payment may use, based on currency, corridor, amount, value date, cut-off, correspondent capability and available intraday credit. A route that fails any eligibility test is excluded before any cost comparison happens. Fallback says what happens when the preferred route is unavailable: wait for capacity, use the next eligible route, hold for treasury decision, or reject with a reason, and the choice depends on the payment's urgency and the customer's terms.\n\nPrecedence resolves conflicts. When two rules disagree, the written order decides: scheme and regulatory rules first, then liquidity and credit limits, then customer and product rules, then cost. No operator overrides precedence silently; an override needs a named approver, a reason and an expiry. Auditability means every routing decision records the payment reference, the candidate routes, the limit and capacity applied, the rule version, the decision and the decision maker. A payment that missed its cut-off can then be explained from its own record, not reconstructed from memory.\n\nOperate the limit change as a controlled event. Treasury owns the limit, its effective time and its communication to the routing engine. Operations quantifies the affected corridor and currency, identifies the payments at risk of missing cut-off, and prioritises them under policy. The routing engine enforces the revised capacity before release, so no payment is sent down a route it cannot fund. After the event, the team reviews whether the fallback worked, whether the alternative capacity was enough, and whether the limit change process needs a faster notification path.", "flow_steps": [{"step": 1, "actor": "Treasury", "action": "Receives the correspondent intraday credit limit reduction and records its effective time", "system": "Treasury and limits service"}, {"step": 2, "actor": "Treasury", "action": "Updates the routing eligibility controls with the revised capacity", "system": "Reference data service"}, {"step": 3, "actor": "Routing engine", "action": "Re-evaluates queued and new payments against the revised limit before release", "system": "Routing engine"}, {"step": 4, "actor": "Payments operations", "action": "Quantifies the affected corridor, currency and payment count, and identifies cut-off risk", "system": "Operations console"}, {"step": 5, "actor": "Payments operations", "action": "Prioritises critical payments under policy and holds the rest for capacity or an alternative route", "system": "Queue manager"}, {"step": 6, "actor": "Routing engine", "action": "Selects the next eligible alternative correspondent where one exists and the cost is approved", "system": "Routing engine"}, {"step": 7, "actor": "Clearing adapter", "action": "Sends prioritised payments by the selected route", "system": "SWIFT connector"}, {"step": 8, "actor": "Payments operations", "action": "Records every routing decision with candidate routes, limits applied and decision maker", "system": "Audit trail"}, {"step": 9, "actor": "Communications", "action": "Updates affected customers where a payment will be delayed or rerouted", "system": "Contact centre and channel messaging"}, {"step": 10, "actor": "Treasury", "action": "Reviews the fallback after the event and agrees a faster limit notification path", "system": "Capacity review"}], "happy_path": "The limit change is applied to the routing controls within minutes, queued payments are re-evaluated, critical payments use the remaining capacity or a valid alternative, no payment is sent down a route it cannot fund, every decision is recorded, and customers whose payments are delayed receive an accurate update.", "negative_paths": [{"path": "Limit update arrives late", "trigger": "Payments were already sent down the corridor before the limit change reached the routing engine.", "handling": "Recall or hold the affected items where the rail allows, reconcile them against the correspondent statement, and fix the notification path."}, {"path": "Alternative route costs more", "trigger": "The only eligible alternative charges more or settles later.", "handling": "Apply the cost and value date rules under precedence, get approval where the policy requires it, and tell the customer before rerouting."}, {"path": "No substitute correspondent", "trigger": "No alternative route exists for the corridor and currency.", "handling": "Hold the payments under a defined policy, prioritise by cut-off, escalate to treasury for contingency funding, and communicate the delay."}, {"path": "Stale reference data", "trigger": "The routing engine uses yesterday's correspondent capability and selects a route that cannot serve the currency.", "handling": "Exclude the route on re-evaluation, hold the payment for repair, and require controlled approval for reference data changes."}, {"path": "Invalid agent sequence", "trigger": "The selected intermediary chain cannot serve the destination.", "handling": "Reject the route in the eligibility check, select the next valid chain, or hold the payment for repair."}], "technical_data": "Store routing rules as effective dated configuration with a version, an owner and a precedence order, so any payment can be re-evaluated against the rules that governed it at the time. Keep correspondent limits, capability, currency support and cut-off as reference data with controlled change approval and an effective timestamp. Record every routing decision as an immutable event with the payment reference, candidate routes, limits applied, rule version, decision and decision maker, and make the decision explainable from that record alone. Use a durable queue with priority, cut-off and ageing, and enforce capacity before release rather than detecting a breach after sending. Alert treasury and operations when utilisation crosses a threshold, not only when the limit is already breached.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer carrying the customer leg through the selected route.", "key_fields": ["Instruction identification", "End to end identification", "Interbank settlement amount", "Debtor and creditor agent"]}, {"message": "pacs.009", "purpose": "Financial institution credit transfer carrying the interbank or cover leg through the correspondent chain.", "key_fields": ["Instruction identification", "Debtor and creditor agent", "Interbank settlement amount"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection by each agent in the chain.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}], "accounting_operational": "Payments held for capacity create no settlement posting, and any reservation is held or released under the routing decision, exactly once. A rerouted payment keeps its original instruction reference, with the new route recorded as a separate event, so the ledger and the nostro reconciliation can follow the payment across correspondents. Nostro balances at each correspondent are monitored against the revised intraday limit, and a payment that would breach the limit is not released. The rerouting worklist is ordered by cut-off risk with an ageing SLA, and the cost difference of an alternative route is recorded for treasury reporting rather than absorbed silently.", "gherkin": ["Given a correspondent limit is reduced", "When a payment route is evaluated", "Then the revised capacity is enforced before release", "And the decision is recorded with the limits applied", "Given a candidate intermediary that does not support the payment currency", "When routing rules execute", "Then that intermediary is excluded", "And the next eligible route is considered"], "assessment": [{"question": "A correspondent halves the intraday credit limit mid-morning. What must happen first in routing?", "options": ["Keep using the old limit", "Reject every payment", "Ignore the limit until tomorrow", "Enforce the revised capacity in the route eligibility controls before any further release"], "answer": 3, "explanation": "Routing must follow the limit in force. Enforcing the revised capacity before release prevents payments being sent down a route they cannot fund."}, {"question": "What resolves a conflict between two routing rules?", "options": ["The cheapest route always wins", "The first rule in the file", "A written precedence order, with scheme and regulatory rules first, then liquidity limits, then product rules, then cost", "The operator's preference that day"], "answer": 2, "explanation": "Precedence must be written down and applied consistently, with any override needing a named approver, a reason and an expiry."}, {"question": "Why must every routing decision be recorded?", "options": ["To slow the process down", "Because the system requires it for no reason", "So a payment that took an expensive route or missed a cut-off can be explained from its own record", "For marketing"], "answer": 2, "explanation": "Auditability means the decision, the candidate routes, the limits applied and the decision maker are all recorded, so the outcome is explainable later."}, {"question": "No alternative correspondent exists for a corridor. What is correct?", "options": ["Delete the payments", "Route through a correspondent that does not support the currency", "Send the payment anyway", "Hold the payments under policy, prioritise by cut-off, escalate to treasury, and communicate the delay"], "answer": 3, "explanation": "Without an eligible route the payment must wait under a defined policy with treasury escalation and customer communication, not be forced down an invalid route."}]}}, {"id": "INS-108", "kind": "insight", "title": "Wrong intermediary bank information", "topic": "Wrong intermediary bank information", "theme": "Payment BA Awareness", "text": "Investigate agent-chain data, routing reference data, repair and rejection/return handling.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch75s3", "title": "Investigation: the wrong intermediary", "url": "lessons/ch75s3"}, "case": {"status": "authored", "business_problem": "Northgate Retail pays a supplier in a new market through Meridian Bank. The payment instruction names an intermediary bank that, on investigation, cannot serve the destination currency and has no settlement relationship for that corridor. The payment is rejected downstream, the supplier is not paid, and the accounts team cannot tell whether the fault is in the message mapping, the routing reference data, or the routing logic itself. The same intermediary appears in a remittance file with a high repair rate, because key agent chain data is missing or inconsistent across many items.\n\nThe agent chain is the heart of a cross-border payment. The debtor agent, the intermediary agents and the creditor agent must form a valid sequence, each able to serve the currency and the corridor, each with a settlement relationship where one is needed. A single wrong intermediary breaks the chain, and the failure can surface far downstream as a rejection, a return, or a payment that sits unprocessed. A repair that changes the intermediary without checking the chain can create a second error.\n\nThe case traces the route decision, compares the selected intermediary with the bank's routing policy, currency capability, country restrictions and reference data, and shows how to repair the chain under control without changing the meaning of the payment.", "decision_exercise": {"scenario": "A cross-border payment is rejected because the named intermediary cannot serve the destination currency. Where do you investigate first?", "options": [{"id": "A", "text": "Ask the supplier to choose a different bank."}, {"id": "B", "text": "Assume the message mapping is wrong and rewrite the mapping."}, {"id": "C", "text": "Trace the route decision and compare the selected intermediary with routing policy, currency capability, country restrictions, settlement relationship and effective dated reference data."}, {"id": "D", "text": "Resend the same payment immediately and hope it clears."}], "correct_option": "C", "why": "C is correct because the fault could be in the mapping, the reference data or the routing logic, and only comparing the selected intermediary against policy, capability and reference data shows which one it is. B is wrong because it assumes the cause without evidence. A is wrong because the fault is in the bank's routing, not the supplier's choice. D is wrong because resending the same invalid chain repeats the rejection."}, "recommended_solution": "Investigate in order: route decision, reference data, then mapping. First, reconstruct the route decision from its audit record: which candidate intermediaries were considered, which were excluded, which rule selected the one that was used, and which version of the rules governed. Then compare the selected intermediary with the routing policy, its currency capability, country restrictions, settlement relationship and the effective dated reference data in force at the time. If the reference data was stale or wrong, the fix is in reference data governance, not in the payment. If the data was correct but the logic selected the wrong intermediary, the fix is in the routing rules. If both were correct but the message carried a different intermediary, the fix is in the mapping or in the upstream capture.\n\nRepair the agent chain under maker-checker control. The operator may correct the intermediary to a valid one that serves the currency and corridor, but may not change the beneficiary, the amount or the value date as part of the repair. The change is audited, the payment is revalidated against the full chain, and the corrected payment is released as the same instruction with a repair event, not as a new payment. Where the chain cannot be repaired, the payment is rejected with a reason that explains the fault in plain terms, and the customer is asked to provide corrected agent details.\n\nPrevent recurrence by measuring the defect Pareto: which intermediaries, corridors and customers generate the most repairs, and whether the cause is upstream capture, reference data or routing logic. Keep internal diagnostic detail separate from the customer visible reason, so the customer receives an accurate permitted explanation while operations retains the full diagnostic record. Apply country specific disclosure rules where a reject reason must not expose sensitive account information.", "flow_steps": [{"step": 1, "actor": "Corporate user", "action": "Submits a cross-border supplier payment with intermediary details", "system": "Corporate online banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction and selects an intermediary chain from routing rules and reference data", "system": "Routing engine"}, {"step": 3, "actor": "Payment engine", "action": "Checks each intermediary for currency capability, country restrictions and settlement relationship", "system": "Reference data service"}, {"step": 4, "actor": "Clearing adapter", "action": "Sends the pacs.008 and, where needed, the pacs.009 cover leg to the chain", "system": "SWIFT connector"}, {"step": 5, "actor": "Intermediary", "action": "Rejects the payment because it cannot serve the destination currency", "system": "Correspondent bank"}, {"step": 6, "actor": "Investigator", "action": "Traces the route decision and compares the selected intermediary with policy, capability and reference data", "system": "Exception workbench"}, {"step": 7, "actor": "Operator", "action": "Repairs the intermediary under maker-checker control or rejects the payment with a clear reason", "system": "Repair workbench"}, {"step": 8, "actor": "Payment engine", "action": "Revalidates the corrected agent chain before release", "system": "Payment engine"}, {"step": 9, "actor": "Clearing adapter", "action": "Resends the payment through the valid chain", "system": "SWIFT connector"}, {"step": 10, "actor": "Payments operations", "action": "Reports the repair rate by intermediary, corridor and customer to drive upstream fixes", "system": "Operations reporting"}], "happy_path": "The routing engine selects a valid intermediary that serves the currency and corridor, the agent chain validates, the payment clears through the chain, the beneficiary is credited, and the routing decision is recorded with the rule version and reference data that governed it.", "negative_paths": [{"path": "Incorrect priority rule", "trigger": "The routing logic ranks an ineligible intermediary above an eligible one.", "handling": "Fix the rule precedence, re-evaluate the affected payments, and regression test the corridor."}, {"path": "Stale reference data", "trigger": "The intermediary's capability changed but the reference data was not updated.", "handling": "Hold the payment, update the reference data under controlled approval, and revalidate before release."}, {"path": "Unsupported service", "trigger": "The intermediary does not offer the service the payment needs.", "handling": "Exclude it in the eligibility check and select the next valid intermediary or hold for repair."}, {"path": "Invalid agent sequence", "trigger": "The agents do not form a valid chain to the destination.", "handling": "Reject the route, rebuild the chain from the debtor agent to the creditor agent, and revalidate the full sequence."}, {"path": "Repair changes payment meaning", "trigger": "A repair alters the beneficiary or amount as well as the intermediary.", "handling": "Treat it as a new instruction, reject it back to the customer, and never repair it silently."}], "technical_data": "Keep the correspondent master as effective dated reference data with currency capability, country restrictions, service support and settlement relationships, changed only under controlled approval with an owner and an effective timestamp. Record every routing decision with the candidate intermediaries, the rule version, the reference data version and the decision maker, so the decision is explainable. Validate the full agent sequence before release, not each agent in isolation. Apply maker-checker control to repairs, audit every change, and revalidate the whole message after repair. Keep a governed reason code catalogue with internal diagnostic detail separate from the customer visible text, so a reject reason never exposes sensitive account information.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer carrying the customer leg and the agent chain.", "key_fields": ["Instruction identification", "End to end identification", "Debtor agent, intermediary agents and creditor agent", "Interbank settlement amount"]}, {"message": "pacs.009", "purpose": "Financial institution credit transfer carrying the interbank or cover leg through the correspondent chain.", "key_fields": ["Instruction identification", "Debtor and creditor agent", "Interbank settlement amount", "Cover information where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection by each agent.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}, {"message": "pain.002", "purpose": "Customer payment status report giving the item level outcome to the customer.", "key_fields": ["Original instruction reference", "Transaction status code", "Status reason code"]}], "accounting_operational": "A payment held for intermediary repair creates no settlement posting, and any reservation is held until the corrected chain is released or the payment is rejected, when it is released once. A payment rejected downstream is moved to a defined rejected state and the customer is notified with the mapped reason. If the payment had already settled before the error was found, the recovery follows the return path as a separate linked event, never by editing the original posting. Nostro reconciliation must show the payment against the correct correspondent once the chain is corrected, and the repair worklist is aged by value date and cut-off with an SLA.", "gherkin": ["Given a candidate intermediary that does not support the payment currency", "When routing rules execute", "Then that intermediary is excluded", "Given a repairable transaction", "When an authorised operator corrects a permitted field", "Then the change is audited", "And the transaction is revalidated before release", "Given an internal reject reason containing sensitive data", "When a customer status is generated for a restricted jurisdiction", "Then only the approved external description is disclosed"], "assessment": [{"question": "An intermediary cannot serve the destination currency. What should routing do?", "options": ["Ask the beneficiary to change currency", "Exclude it in the eligibility check and select the next valid intermediary or hold the payment for repair", "Remove the currency from the payment", "Use it anyway"], "answer": 1, "explanation": "Eligibility is checked before cost or preference. An intermediary that cannot serve the currency is excluded, and the payment is rerouted or held."}, {"question": "Is the fault in mapping, reference data or routing logic? How do you tell?", "options": ["Ask the supplier", "Rewrite all three", "Guess", "Reconstruct the route decision and compare the selected intermediary with policy, capability and the reference data in force at the time"], "answer": 3, "explanation": "The audit record shows which candidates were considered and which rule selected the intermediary. Comparing it with the reference data in force isolates the fault."}, {"question": "A repair needs to change the intermediary. What else may the operator change in the same repair?", "options": ["The value date to any date", "The beneficiary and amount as well", "The currency", "Only a permitted field such as the intermediary. Changing the beneficiary or amount is a new instruction, not a repair"], "answer": 3, "explanation": "A repair corrects a permitted field under maker-checker control. Changing the payment meaning needs fresh customer confirmation."}, {"question": "A reject reason contains sensitive account information. What does the customer see?", "options": ["The full internal reason", "Nothing at all", "Another customer's reason", "Only the approved external description for that jurisdiction, while operations keeps the diagnostic detail internally"], "answer": 3, "explanation": "Internal diagnostic detail stays internal. The customer receives an accurate, permitted explanation under the jurisdiction's disclosure rules."}]}}, {"id": "INS-109", "kind": "insight", "title": "SDD pacs.004 return versus refund", "topic": "SDD pacs.004 return versus refund", "theme": "Payment BA Awareness", "text": "Distinguish scheme return and refund business events, triggers, timelines and accounting treatment.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}, "case": {"status": "authored", "business_problem": "Northgate Retail Europe collects monthly subscriptions by SEPA Direct Debit from customers of Meridian Bank. Two events arrive on the same day and look similar, but they are not the same. First, a debtor bank returns a collection because the debtor account has insufficient funds. Second, a debtor asks for a refund of an authorised collection, saying the amount was higher than agreed. The collections team wants to treat both as a failed collection and retry them. The operations team knows that a return and a refund are different business events with different triggers, different timelines, different messages and different accounting, and that treating a refund as a return, or the other way round, breaches scheme rules.\n\nThe distinction turns on who initiates the event and why. A return is initiated by the debtor bank, usually because the collection cannot be executed, and it unwinds the collection. A refund is initiated by the debtor, as a claim on an authorised collection, and it is governed by the debtor's refund rights, which differ between SDD Core and SDD B2B. The timelines are strict, the message is pacs.004 in both cases but the business meaning differs, and the accounting must keep the original collection and the later event as separate linked entries.\n\nThe case follows both events from trigger to accounting, so the learner can classify each one correctly, apply the right timeline, and post the right entries without confusing the two.", "decision_exercise": {"scenario": "A debtor bank returns a collection for insufficient funds, and on the same day a different debtor claims a refund of an authorised collection. How should the team classify them?", "options": [{"id": "A", "text": "Both are failed collections. Retry both."}, {"id": "B", "text": "The first is a return initiated by the debtor bank. The second is a refund claim initiated by the debtor, governed by Core or B2B refund rights and timelines. Handle each under its own scheme rules."}, {"id": "C", "text": "Both are refunds. Pay both immediately."}, {"id": "D", "text": "Both are returns. Reject both claims."}], "correct_option": "B", "why": "B is correct because a return and a refund differ in initiator, trigger and scheme rights. A return unwinds a collection that cannot be executed; a refund is a debtor claim on an authorised collection. A, C and D are wrong because they apply one treatment to two different business events."}, "recommended_solution": "Classify first, then act. A return is initiated by the debtor bank when the collection cannot be executed, for reasons such as insufficient funds, an invalid account or a closed account. A refund is initiated by the debtor as a claim on a collection that was executed, and the claim is tested against the debtor's scheme rights. For SDD Core, an authorised collection can be refunded within 8 weeks of the debit date, no questions asked, and an unauthorised collection can be claimed within 13 months. For SDD B2B, there is no authorised refund right at all, so a debtor who agreed the collection cannot claim a refund on that ground; only an unauthorised B2B claim follows the unauthorised route. Keeping Core and B2B rights distinct is the single most important control in this case.\n\nApply the scheme timelines exactly. An SDD Core collection is submitted by D-1, one Inter-PSP Business Day before the Due Date, with pre-notification at the latest 14 Calendar Days before the Due Date. A Core return must be made within D+5 Inter-PSP Business Days, and a B2B return within D+3. A reversal is only possible from the settlement date and within 5 Inter-PSP Business Days following the Due Date. A mandate that has been unused for 36 months must not be used. A cancellation after submission goes by camt.056 with a camt.029 response, and acceptance is not guaranteed.\n\nRecord both events in pacs.004, but keep their business meaning separate in the case record and in the ledger. The return and the refund are each a new linked event referencing the original collection, never an edit or deletion of the original. Validate the return reason, amount, currency and original references before posting, and reconcile both legs. If a return arrives after the debtor account has closed, apply the bank's closed account policy, route the funds to an approved suspense or unclaimed funds process, and preserve traceability. If a refund claim arrives outside its timeframe, reject it with the scheme reason and a clear explanation, and do not pay it as a goodwill gesture dressed up as a scheme refund.", "flow_steps": [{"step": 1, "actor": "Creditor", "action": "Submits an SDD collection by D-1, after pre-notification at the latest 14 Calendar Days before the Due Date", "system": "Creditor payment system"}, {"step": 2, "actor": "Creditor bank", "action": "Sends the collection to the debtor bank for the Due Date", "system": "Clearing system"}, {"step": 3, "actor": "Debtor bank", "action": "Debits the debtor account on the Due Date for an authorised collection", "system": "Core banking"}, {"step": 4, "actor": "Debtor bank", "action": "Returns a collection that cannot be executed, for example for insufficient funds, within the return window", "system": "Debtor bank operations"}, {"step": 5, "actor": "Debtor", "action": "Claims a refund of an authorised Core collection within 8 weeks of the debit date", "system": "Debtor bank channel"}, {"step": 6, "actor": "Debtor bank", "action": "Validates the scheme, the collection date, the authorisation status and the claim timeframe", "system": "Claims service"}, {"step": 7, "actor": "Debtor bank", "action": "Sends a pacs.004 return or refund for the validated event, linked to the original collection", "system": "Clearing system"}, {"step": 8, "actor": "Creditor bank", "action": "Receives the pacs.004, validates the reason, amount, currency and original references, and posts it as a linked entry", "system": "Payment engine and ledger"}, {"step": 9, "actor": "Creditor", "action": "Sees the return or refund against the original collection and updates the customer account", "system": "Creditor reporting"}, {"step": 10, "actor": "Payments operations", "action": "Reconciles the original collection and the pacs.004 event, and ages any unmatched item", "system": "Reconciliation service"}], "happy_path": "The collection is submitted by D-1 with timely pre-notification, the debtor account is debited on the Due Date, an insufficient funds collection is returned within D+5 for Core, and an authorised Core refund claimed within 8 weeks is paid as a separate linked pacs.004 event. The original collection stays immutable, both legs reconcile, and the creditor updates the customer account from the linked records.", "negative_paths": [{"path": "Refund claim outside the timeframe", "trigger": "An authorised Core refund is claimed after 8 weeks from the debit date.", "handling": "Reject the claim with the scheme reason and a clear explanation. Do not pay it as a scheme refund."}, {"path": "Unauthorised collection claim", "trigger": "The debtor says the collection was never authorised.", "handling": "Test the claim under the unauthorised route, within 13 months, and investigate the mandate before paying."}, {"path": "B2B authorised refund claimed", "trigger": "A B2B debtor claims a refund of an authorised collection.", "handling": "Refuse under scheme rules, because B2B has no authorised refund right, and explain the correct route for an unauthorised claim."}, {"path": "Return after the account has closed", "trigger": "A valid return arrives after the original debtor account has been closed.", "handling": "Apply the closed account policy, route the funds to approved suspense or unclaimed funds, and preserve traceability."}, {"path": "Return amount mismatch", "trigger": "The pacs.004 amount or currency does not match the original collection.", "handling": "Hold the return for investigation, do not post it, and resolve the mismatch with the debtor bank before acting."}], "technical_data": "Store the mandate, the collection, the return and the refund as separate records linked by the original collection reference and the mandate reference, with the scheme, Core or B2B, recorded on each. Validate every pacs.004 against the original collection for reason, amount, currency and references before posting, and reject or hold mismatches. Enforce the timelines as effective dated rules: D-1 submission, D+5 Core and D+3 B2B return windows, 8 week authorised Core refund, 13 month unauthorised claim, 5 day reversal window from settlement, and the 36 month mandate non-use rule. Keep the original collection immutable, record each event with its initiator, trigger and timeframe check, and make the claims service the authoritative source for refund eligibility. A cancellation after submission is a separate camt.056 and camt.029 exchange, tracked independently from the return.", "messages_fields": [{"message": "pacs.004", "purpose": "Payment return, used for both SDD returns and refunds, linked to the original collection.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and currency", "Original mandate reference"]}, {"message": "pain.008", "purpose": "Customer direct debit initiation carrying the SDD collection instruction.", "key_fields": ["Mandate identification", "Creditor identification", "Debtor account", "Instructed amount and Due Date"]}, {"message": "camt.056", "purpose": "Payment cancellation request, used to cancel a collection after submission.", "key_fields": ["Original instruction reference", "Cancellation reason", "Requester identification"]}, {"message": "camt.029", "purpose": "Resolution of investigation, the response to a cancellation request. Acceptance is not guaranteed.", "key_fields": ["Original instruction reference", "Investigation status", "Cancellation status"]}], "accounting_operational": "The original collection is posted as a debit to the debtor and a credit to the creditor on the Due Date, and it stays immutable. A return is posted as a separate linked entry that reverses the collection, debiting the creditor and crediting the debtor, with the return reason recorded. A refund is posted the same way as a linked entry, but its case record shows it as a debtor claim under the scheme refund right, not as a bank initiated return. If the debtor account has closed, the funds go to an approved suspense or unclaimed funds account with an owner and an ageing SLA, never to an invalid account. The collections worklist is ordered by return and refund deadlines, D+5 for Core returns, D+3 for B2B returns, and 8 weeks for authorised Core refunds, and each item is reconciled to both the original collection and the pacs.004 event.", "gherkin": ["Given an eligible authorised Core collection refund request within the applicable period", "When the claim is validated", "Then the bank applies the scheme-defined refund process", "Given a return is received for a closed account", "When posting is attempted", "Then the closed-account policy is applied", "And funds remain traceable", "Given a valid return message", "When the original transaction is identified", "Then the return is recorded as a linked transaction", "And the original record remains immutable"], "assessment": [{"question": "Who initiates an SDD return, and who initiates an SDD refund?", "options": ["The creditor initiates both", "The scheme initiates both", "The debtor bank initiates a return. The debtor initiates a refund claim on an authorised collection", "The creditor bank initiates both"], "answer": 2, "explanation": "A return is a debtor bank event when a collection cannot be executed. A refund is a debtor claim on a collection that was executed."}, {"question": "An authorised SDD Core collection is debited. How long does the debtor have to claim a refund, no questions asked?", "options": ["13 months", "8 weeks from the debit date", "5 days", "36 months"], "answer": 1, "explanation": "SDD Core gives an authorised refund right within 8 weeks of the debit date, no questions asked. Unauthorised claims run to 13 months."}, {"question": "A B2B debtor claims a refund of an authorised collection. What is correct?", "options": ["Pay it after 8 weeks", "Treat it as a return", "Refuse under scheme rules, because B2B has no authorised refund right", "Pay it, as for Core"], "answer": 2, "explanation": "B2B has no authorised refund right. Only an unauthorised B2B claim follows the unauthorised route."}, {"question": "What are the SDD return windows for Core and B2B?", "options": ["Both D+1", "Both 8 weeks", "Core D+5 and B2B D+3 Inter-PSP Business Days", "Core D+3 and B2B D+5"], "answer": 2, "explanation": "Core returns run to D+5 Inter-PSP Business Days and B2B returns to D+3. Submission is D-1 and pre-notification is at the latest 14 Calendar Days before the Due Date."}, {"question": "How is an SDD return or refund recorded?", "options": ["By deleting the original collection", "By cancelling the mandate", "By editing the original amount", "As a new linked pacs.004 event referencing the original collection, keeping the original immutable"], "answer": 3, "explanation": "Both events use pacs.004 as a new linked entry. The original collection stays immutable for audit and reconciliation."}]}}, {"id": "INS-110", "kind": "insight", "title": "Missing requested execution date in SEPA Request to Pay", "topic": "Missing requested execution date in SEPA Request to Pay", "theme": "Payment BA Awareness", "text": "Define date derivation, customer choice, validation and downstream execution rules.", "domain": "SEPA & Request to Pay", "area": "SEPA & Request to Pay", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch74s8", "title": "SEPA Request to Pay: asking for a payment instead of pulling it", "url": "lessons/ch74s8"}}, {"id": "INS-111", "kind": "insight", "title": "Sequential versus parallel payment controls", "topic": "Sequential versus parallel payment controls", "theme": "Payment BA Awareness", "text": "Assess control dependencies, latency, risk coverage and orchestration behaviour.", "domain": "Payment Architecture", "area": "Payment Architecture", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch79s4", "title": "Orchestration failure handling: timeouts, retries, compensation and sagas", "url": "lessons/ch79s4"}}, {"id": "INS-112", "kind": "insight", "title": "90% of remittance file enters repair", "topic": "90% of remittance file enters repair", "theme": "Payment BA Awareness", "text": "Balance transaction-level repair flexibility against operational capacity, customer experience and reconciliation.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch40s4", "title": "Transaction-Level Matching: References, Amounts, Currencies and Value Dates", "url": "lessons/ch40s4"}, "case": {"status": "authored", "business_problem": "Meridian Bank receives a daily remittance file from Northgate Retail, a large corporate customer that pays several thousand suppliers in one batch. On a typical morning, around 90 percent of the transactions in the file enter the manual repair queue because key data is missing or inconsistent: beneficiary account numbers that fail the modulus check, remittance information that exceeds the permitted length, missing beneficiary names, and currency codes that do not match the beneficiary account currency. The repair team of six operators can clear roughly 400 items a day, while the file routinely contains more than 3,000 defective items, so the queue grows every day and the oldest items age past the customer's value-date promise.\n\nThe business impact is visible on three fronts at once. Suppliers complain to Northgate Retail about late payment, and Northgate Retail escalates to its relationship manager at Meridian Bank, threatening to move the business to a competitor. Operations management sees overtime rising and error rates climbing as operators rush, and two recent rushed repairs changed a beneficiary account number and sent funds to the wrong supplier, which then had to be recovered through a return process. Finance cannot close the daily reconciliation cleanly because repaired items lose their original references, so the same payment appears under two different identifiers in different reports.\n\nThe root tension is that the repair workbench is flexible enough to fix almost anything, which hides the real problem. Every defect that an operator can repair is a defect that the sending customer and the bank's own intake validation allowed through. The bank must decide how much repair flexibility to keep, which defects to prevent at source, and how to protect straight-through processing, customer experience and reconciliation while the file quality improves.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Reject the entire file every day until Northgate Retail sends a perfect file, and hold all supplier payments until then."}, {"id": "B", "text": "Segment defects by root cause and source, block the preventable defect classes at intake with actionable guidance to the customer, and prioritise the remaining repair queue by SLA and value date."}, {"id": "C", "text": "Double the repair team and extend overtime so the queue clears each day, keeping the current repair workbench unchanged."}, {"id": "D", "text": "Allow operators to repair any field without approval so items move faster, and reconcile the file only at month end."}], "scenario": "You are the business analyst for Meridian Bank's payment operations team. The Northgate Retail remittance file has a 90 percent repair rate, the repair queue is growing daily, and two recent repairs sent funds to the wrong beneficiary. Senior management asks you to recommend the first intervention.", "why": "Option B is correct because it attacks the root causes, stops preventable defects at source, and protects the queue that remains with SLA-based prioritisation. Option C only adds capacity to a broken process and leaves the error rate and wrong-beneficiary risk untouched. Option D removes controls and increases the risk of misdirected payments and lost traceability. Option A punishes the customer and all suppliers for defects that are partly the bank's own validation gap, and it breaks the value-date promise for every payment including the clean ones."}, "recommended_solution": "Start by measuring the problem properly. Classify every repair in the last four weeks by defect type, by source system and by field, and build a Pareto view so the team can see which five or six defect classes drive most of the 90 percent. For each class, decide whether it is preventable at intake, enrichable from reference data, or genuinely repairable only by a human. Typical preventable classes are account-number format failures, missing beneficiary names and remittance text over the permitted length, all of which can be validated in the customer upload portal with a clear, field-level error message that tells Northgate Retail exactly what to fix.\n\nSecond, redesign the repair workbench around control, not just speed. Repaired items must keep their original instruction reference and a full before-and-after audit record, so reconciliation can always trace a payment back to the file line it came from. Sensitive changes, above all beneficiary account numbers, require maker-checker approval and trigger re-validation and re-screening before release. The workbench should show the operator the permitted repair for each defect class, not a free-text edit of any field, and it should prioritise by value date and SLA so the items closest to breaching their promise are worked first.\n\nThird, agree a staged improvement plan with the customer and with Operations. Publish a weekly defect report to Northgate Retail showing defect counts by class and the exact upload changes needed, and agree a target straight-through-processing rate with milestones rather than demanding perfection in one step. Internally, track straight-through-processing rate, repair ageing, rework rate and operator productivity daily, and review them in a short weekly forum with Operations, Product and the relationship manager. The goal is a file that mostly flows straight through, a small repair queue that is worked within SLA, and a full audit trail on every item that is touched.", "flow_steps": [{"action": "Uploads the daily remittance file through the corporate upload portal", "actor": "Northgate Retail", "step": 1, "system": "Corporate banking portal"}, {"action": "Validates file structure, account formats, currency and remittance length, and returns field-level errors for preventable defects", "actor": "Payment platform", "step": 2, "system": "File intake and validation service"}, {"action": "Enriches valid items from reference data, for example beneficiary name from the account directory where permitted", "actor": "Payment platform", "step": 3, "system": "Enrichment service"}, {"action": "Routes clean items straight through and repairable items to the controlled repair workbench", "actor": "Payment platform", "step": 4, "system": "Payment engine and repair workbench"}, {"action": "Corrects only permitted fields, with maker-checker approval for beneficiary account changes", "actor": "Repair operator", "step": 5, "system": "Repair workbench"}, {"action": "Re-validates and re-screens every repaired item before release", "actor": "Payment platform", "step": 6, "system": "Validation and screening services"}, {"action": "Executes the payment and generates the interbank message", "actor": "Payment engine", "step": 7, "system": "Payment engine"}, {"action": "Reconciles executed items against the original file lines using the preserved instruction reference", "actor": "Operations", "step": 8, "system": "Reconciliation service"}], "happy_path": "Northgate Retail uploads a file that passes intake validation, with only a small number of genuinely repairable items. Clean items flow straight through to the payment engine and execute on the promised value date. Repairable items enter the workbench, are corrected within SLA with maker-checker approval where required, are re-validated and re-screened, and then execute. Every item reconciles to its original file line, the straight-through-processing rate is reported daily, and suppliers are paid on time.", "negative_paths": [{"handling": "Flag the defect class in the Pareto report, raise it with the customer as a source-system fix, and add a targeted intake rule so the file is rejected with a precise message instead of entering repair each day.", "path": "Repeated defect from the same source", "trigger": "The same account-format defect appears in every daily file because the customer's source system generates it"}, {"handling": "Require maker-checker approval for sensitive fields, re-run validation and screening, and keep a before-and-after audit record; if the change is material and cannot be confirmed, return the item to the customer instead of releasing it.", "path": "Repair changes the payment meaning", "trigger": "An operator corrects a beneficiary account number or amount and the payment no longer matches the customer's intent"}, {"handling": "Prioritise by value date and SLA, escalate to Operations management, notify the customer of the affected items and revised timing, and do not release items by skipping validation to catch up.", "path": "Repair queue exceeds SLA", "trigger": "Defect volume spikes and items age past their value date"}, {"handling": "Detect duplicates by instruction reference and idempotency key at intake, reject the duplicate lines with a clear reason, and reconcile the file against already-executed items before any new execution.", "path": "Duplicate after resubmission", "trigger": "The customer resubmits a corrected file containing items that were already repaired and executed"}], "technical_data": "Keep the original instruction reference immutable from intake to ledger so a repaired item never loses traceability. Use an idempotency key per file line so a resubmitted file cannot execute the same payment twice. Store every repair as a before-and-after event with operator, checker, timestamp, reason code and field-level change, retained for audit. Define editable fields by payment state, so a field that is editable in repair is locked once the item is released to the engine. Re-run sanctions and fraud screening after any material change to beneficiary, amount or currency. Capture defect codes in a governed catalogue with effective dates, and measure straight-through-processing rate, repair ageing, rework and operator productivity from the same event store so the metrics cannot drift from the underlying data.", "messages_fields": [{"key_fields": ["Instruction identification, the unique reference per transaction that must survive repair", "Creditor account and name, validated against the account format rules", "Instructed amount and currency, checked for consistency with the creditor account", "Remittance information, kept within the permitted length and character set"], "message": "pain.001", "purpose": "Customer to bank payment initiation file carrying the batch of supplier payments"}, {"key_fields": ["Original instruction identification, so the customer can match the status to its file line", "Transaction status, for example accepted, pending repair, rejected or executed", "Status reason code and additional information, giving an actionable explanation for each rejected or repaired item"], "message": "pain.002", "purpose": "Payment status report back to the customer for accepted, repaired, rejected and executed items"}, {"key_fields": ["End-to-end identification, carried from the original instruction", "Creditor account and agent, the validated beneficiary details", "Remittance information, the supplier reference the beneficiary sees"], "message": "pacs.008", "purpose": "Interbank customer credit transfer for each executed supplier payment"}], "accounting_operational": "Each executed item produces a debit to the Northgate Retail account and a corresponding interbank settlement entry, with the batch control total reconciled against the sum of executed items plus rejected and repaired items still in the queue. Repaired items must not create a second accounting event for the same instruction, so the ledger posts once per executed item, keyed to the original instruction reference. Items that cannot be repaired are rejected without a ledger posting, and the customer statement shows only executed payments. Operations works from a repair ageing worklist with SLA targets per value date, and any item that ages past its value date is escalated to the relationship manager and reported to the customer with a revised timing. Wrong-beneficiary repairs are treated as operational incidents with a recovery workflow and a root-cause review.", "gherkin": ["Given a repairable transaction in the repair queue", "When an authorised operator corrects a permitted field", "Then the change is recorded with before-and-after values and the transaction is revalidated before release", "Given a file line that was already repaired and executed", "When the customer resubmits the same file line", "Then the duplicate is rejected at intake and no second payment is created", "Given a repair that changes a beneficiary account number", "When the operator submits the change", "Then maker-checker approval and re-screening are required before the item can be released", "Given a repair queue that has items older than the value-date SLA", "When the daily ageing check runs", "Then the aged items are escalated to Operations management and reported to the customer"], "assessment": [{"answer": 0, "explanation": "The original reference is the link between the file line, the repair, the executed payment and the ledger. Without it, reconciliation cannot prove which file line produced which payment.", "options": ["So reconciliation can trace the executed payment back to the original file line", "So the repair operator can find it faster", "So the payment engine can skip screening", "So the customer can change the amount later"], "question": "Why should a repaired payment keep its original instruction reference?"}, {"answer": 1, "explanation": "Changing the beneficiary account redirects funds to a different account, so it carries the highest misdirection risk and needs a second person to check it.", "options": ["Adding an internal note", "Changing the beneficiary account number", "Correcting a spelling error in remittance text", "Reassigning the item to another operator"], "question": "Which repair change most needs maker-checker approval?"}, {"answer": 2, "explanation": "Segmenting defects shows which classes are preventable at source. Fixing those at intake reduces the queue permanently, while more operators only add capacity to a broken process.", "options": ["Hire more repair operators", "Let operators edit any field without approval", "Segment defects by root cause and prevent the preventable classes at intake", "Reject the whole file every day"], "question": "What is the best first intervention when 90 percent of a file enters repair?"}, {"answer": 3, "explanation": "The instruction reference and idempotency key identify the line as already executed, so intake must reject it and prevent a second payment.", "options": ["Hold it until month end", "Execute it again to be safe", "Send it to repair", "Reject it at intake using the instruction reference and idempotency key"], "question": "How should a duplicate file line be handled on resubmission?"}, {"answer": 2, "explanation": "Straight-through processing is the proportion of items that complete automatically. A low rate, such as 10 percent here, signals an intake or data quality problem, not just a staffing problem.", "options": ["The number of files received per day", "The size of the repair team", "The share of items that flow from intake to execution without manual repair", "How fast operators type"], "question": "What does the straight-through-processing rate measure?"}]}}, {"id": "INS-113", "kind": "insight", "title": "Country-specific MS03 reject/return reason privacy", "topic": "Country-specific MS03 reject/return reason privacy", "theme": "Payment BA Awareness", "text": "Determine configuration scope (engine, country, entity), legal privacy constraints and implementation fit.", "domain": "Compliance & Payment Processing", "area": "Compliance & Payment Processing", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s6", "title": "ISO 20022 Messages and Reason Codes for Exceptions (pacs.002, pacs.004, camt.056, camt.029, pain.002 with real reason codes)", "url": "lessons/ch41s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank operates in several countries from a single payment engine, and a rejected payment must be explained to the customer. The internal diagnostic reason for a rejection is often precise and sensitive: it may state that the beneficiary account is closed, that the account holder name does not match, or that the account is subject to a restriction. In some jurisdictions, disclosing that detail to the payer would reveal private information about the beneficiary, which local privacy rules forbid. In others, the customer is entitled to a fuller explanation. The bank's current configuration applies one reason text everywhere, so it either discloses too much in a restricted jurisdiction or gives a vague, unhelpful message where a fuller explanation is permitted.\n\nThe problem surfaced when a corporate customer in a restricted jurisdiction received a rejection notice that stated the beneficiary account was closed, and the beneficiary complained that their account status had been disclosed to a third party. Compliance opened a review, and the product team discovered that the reason-code mapping had no country dimension at all: one internal code mapped to one external text for every entity and every country. Operations also reported the opposite failure, where customers in other jurisdictions received only a generic code and opened support cases because they could not tell whether to correct the account number, contact the beneficiary, or simply retry.\n\nThe bank needs a design that keeps full diagnostic detail for Operations and audit, while disclosing only what each jurisdiction permits to each audience. The configuration must be explicit about its scope, engine, country or entity, so a change for one country cannot silently change the message a customer sees in another.", "decision_exercise": {"correct_option": "D", "options": [{"id": "A", "text": "Remove reason codes entirely and tell customers only that the payment failed."}, {"id": "B", "text": "Use one generic reason text for every country so nothing sensitive is ever disclosed anywhere."}, {"id": "C", "text": "Disclose the full internal reason to every customer so Operations receives fewer support calls."}, {"id": "D", "text": "Keep internal diagnostic detail separate from customer-visible text, and apply jurisdiction-specific disclosure rules with a governed reason-code catalogue mapped to scheme codes."}], "scenario": "You are the business analyst for Meridian Bank's payment engine. A rejection reason contains sensitive beneficiary account information. In one operating country, local privacy rules forbid disclosing it to the payer; in another, a fuller explanation is permitted. Compliance asks you to recommend the design.", "why": "Option D is correct because it preserves operational transparency internally while disclosing only what each jurisdiction permits externally, with a governed catalogue so the mapping is controlled and testable. Option B is safe but unhelpful, and it drives support calls where a fuller explanation is allowed. Option C breaches privacy rules in restricted jurisdictions. Option A leaves customers unable to correct the problem and leaves Operations without a usable reason."}, "recommended_solution": "Separate the reason into three layers and never let them collapse into one field. The internal diagnostic reason stays in the payment record and the Operations view, with the full detail needed to investigate. The customer-visible reason is derived from it through a governed mapping table that is keyed by internal code, country, entity and channel, and that produces only the approved external text for that jurisdiction. The scheme reason code sent to the counterparty follows the scheme's own code list, so the external message the counterparty sees is a scheme code, not the bank's internal wording.\n\nGovern the mapping as configuration, not as code buried in the engine. Each mapping row needs an owner, an effective date, a privacy review sign-off and a language version, because the same code may need different wording in different languages and the permitted wording can change when local rules change. Changes go through a controlled release with regression tests that run the same rejection through every country and entity configuration and assert the exact customer-visible text for each, so a change for one country cannot silently alter another.\n\nFinally, make the audit trail prove what was disclosed and to whom. Log the internal code, the mapped external text, the jurisdiction applied and the channel for every rejection notice, so Compliance can evidence that a restricted disclosure never happened. Provide Operations with a separate diagnostic view that shows the internal reason without exposing it to the customer, and give the support team a scripted explanation for each external code so customers get consistent, permitted help when they call.", "flow_steps": [{"action": "Rejects the payment and records the internal diagnostic reason code", "actor": "Payment engine", "step": 1, "system": "Payment engine"}, {"action": "Looks up the internal code against country, entity and channel to find the approved external text", "actor": "Reason mapping service", "step": 2, "system": "Reason-code catalogue"}, {"action": "Maps the internal reason to the applicable scheme reason code for the counterparty", "actor": "Reason mapping service", "step": 3, "system": "Reason-code catalogue"}, {"action": "Sends the scheme-coded rejection to the counterparty without internal wording", "actor": "Payment platform", "step": 4, "system": "Scheme adapter"}, {"action": "Sends the customer the approved external description for their jurisdiction and language", "actor": "Notification service", "step": 5, "system": "Notification service"}, {"action": "Views the full internal diagnostic detail in the Operations workbench", "actor": "Operations", "step": 6, "system": "Operations workbench"}, {"action": "Records the internal code, the external text disclosed, the jurisdiction and the channel", "actor": "Audit service", "step": 7, "system": "Audit store"}], "happy_path": "A payment is rejected for a sensitive reason. Operations sees the full diagnostic detail and can act on it. The counterparty receives the correct scheme code. The customer receives an accurate explanation that is permitted in their jurisdiction, in their language, with enough guidance to correct the problem or contact the beneficiary. The audit record proves exactly what was disclosed.", "negative_paths": [{"handling": "Default to the most restrictive approved text when no mapping exists, alert Compliance and Operations, and block the notification until a governed mapping is added.", "path": "Internal reason accidentally exposed", "trigger": "A mapping row is missing for a country, and the system falls back to the internal text"}, {"handling": "Route the payment to an Operations queue with the raw code, apply the generic permitted text to the customer, and add the code to the catalogue through the governed change process.", "path": "Unknown reason code", "trigger": "A new scheme or engine code has no entry in the catalogue"}, {"handling": "Fall back to the approved text in the default language for that jurisdiction, log the gap, and commission the translation through the governed process rather than machine-translating a sensitive message on the fly.", "path": "Language mismatch", "trigger": "The customer language has no approved translation for the external text"}, {"handling": "Run the full country and entity regression suite before release, assert the exact text per jurisdiction, and roll back the mapping change if any assertion fails.", "path": "Mapping change affects another country", "trigger": "A change intended for one jurisdiction alters the text shown in another"}], "technical_data": "Model the reason as three separate attributes: internal diagnostic code, scheme code, and customer-visible text key. Never store the internal wording in the same field as the customer text, and never let a channel read the internal field directly. Key the mapping by internal code, country, entity, channel and language, with effective-from and effective-to dates so a rule change can be staged and audited. Version the catalogue and keep prior versions for historical reconstruction of what a customer was told. Use correlation IDs to link the rejection, the mapping applied, the notification sent and the audit record. Test the mapping matrix exhaustively across country and entity combinations in the regression suite, including the missing-mapping fallback.", "messages_fields": [{"key_fields": ["Original instruction identification, linking the rejection to the payment", "Transaction status, rejected", "Status reason code, the scheme code only, never internal diagnostic wording", "Additional information, only where the scheme permits and privacy rules allow"], "message": "pacs.002", "purpose": "Payment status report carrying the rejection to the counterparty using the scheme reason code"}, {"key_fields": ["Original instruction identification", "Transaction status and the customer-visible reason text for the customer's jurisdiction", "Status reason information, limited to the approved wording for that country and language"], "message": "pain.002", "purpose": "Payment status report to the originating customer with the approved external explanation"}], "accounting_operational": "A rejected payment must not leave a dangling accounting entry, so any reservation or debit raised when the payment was accepted is reversed once, and the reversal is linked to the original instruction reference. Operations works from a rejection worklist that shows the internal diagnostic reason, the external text sent, the jurisdiction applied and the age of the item, with SLA targets for customer follow-up where the customer must correct and resubmit. Support teams use the governed explanation script for each external code, and Compliance reviews a sample of disclosures each month against the jurisdiction rules. A privacy breach caused by an incorrect disclosure is treated as an incident with notification to Compliance and a mapping fix through the governed change process.", "gherkin": ["Given an internal reject reason containing sensitive beneficiary information", "When a customer status is generated for a restricted jurisdiction", "Then only the approved external description for that jurisdiction is disclosed", "Given a rejection with no mapping for the customer's country", "When the notification is prepared", "Then the most restrictive approved text is used and Compliance is alerted", "Given a mapping change for one country", "When the regression suite runs", "Then the customer-visible text for every other country and entity remains unchanged", "Given a rejected payment that had raised an accounting reservation", "When the rejection is processed", "Then the reservation is reversed exactly once and linked to the original instruction"], "assessment": [{"answer": 3, "explanation": "The internal reason can reveal sensitive facts about the beneficiary, such as an account closure. Privacy rules in some jurisdictions forbid sharing that with the payer, so the two layers must stay separate.", "options": ["To save storage space", "Because customers prefer short messages", "Because scheme codes change often", "Because the internal detail may contain private information about another party that the customer's jurisdiction forbids disclosing"], "question": "Why must internal diagnostic detail be kept separate from customer-visible reason text?"}, {"answer": 0, "explanation": "Failing safe means disclosing the least, not the most. The restrictive fallback protects privacy while Compliance adds a governed mapping.", "options": ["Use the most restrictive approved text and alert Compliance", "Show the internal reason so the customer understands", "Send no notification at all", "Copy the mapping from a neighbouring country"], "question": "What should happen when no mapping exists for a customer's country?"}, {"answer": 2, "explanation": "Disclosure rules, wording and language all vary by jurisdiction and audience, so the mapping must be keyed by all of those dimensions to be correct.", "options": ["Scheme code only", "Language only", "Internal code, country, entity, channel and language", "Internal code only"], "question": "What is the scope that a reason-code mapping must be keyed by?"}, {"answer": 0, "explanation": "pacs.002 is the payment status report, and it carries the scheme reason code to the counterparty, not the bank's internal diagnostic wording.", "options": ["pacs.002 with the scheme reason code", "camt.053", "pain.001", "pacs.008"], "question": "Which message carries the rejection to the counterparty?"}, {"answer": 0, "explanation": "A change for one jurisdiction can silently affect another, so the regression suite must assert the exact text for every country and entity combination before release.", "options": ["Run a regression suite asserting the exact customer text for every country and entity", "Test it in one country only", "Ask one customer to check it", "Deploy it and wait for complaints"], "question": "How should a mapping change be validated before release?"}]}}, {"id": "INS-114", "kind": "insight", "title": "Throughput increase: five clients add ten million transactions monthly", "topic": "Throughput increase: five clients add ten million transactions monthly", "theme": "Payment BA Awareness", "text": "Translate volume growth into throughput, concurrency, queue, storage, monitoring and resilience requirements.", "domain": "Architecture & Non-functional Requirements", "area": "Architecture & Non-functional Requirements", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch48s6", "title": "Resilience at Scale: Transactions, Breakers and Recovery", "url": "lessons/ch48s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank has signed five new corporate clients, and together they are forecast to add ten million transactions a month to the payment platform. That is roughly 330,000 extra transactions a day on average, but the new clients are payroll and supplier-payment businesses whose files land in concentrated morning windows, so the peak load is far higher than the average suggests. The current platform was sized for the existing book, and its busiest hour already runs at about 70 percent of measured capacity. The chief operating officer wants a straight answer: can the platform absorb the growth, what breaks first, and what must change before the first new client goes live.\n\nThe risk is not only slow processing. If the payment engine saturates, files queue, value-date promises slip, and the repair and reconciliation teams face a backlog they cannot clear the same day. If a downstream dependency such as sanctions screening or the ledger slows under load, latency grows across every payment, including those of existing clients. A retry storm makes it worse: channels that time out resubmit, and each resubmission adds load to a system that is already saturated, turning a capacity problem into an outage.\n\nThe business analyst must translate a commercial forecast, ten million transactions a month from five clients, into engineering requirements that can be tested: transactions per second at average, peak and burst, end-to-end latency, queue depth, storage growth, and the recovery objectives if a component fails under load. The answer has to be evidence from load testing, not an assertion that the platform should cope.", "decision_exercise": {"correct_option": "A", "options": [{"id": "A", "text": "Build a capacity model from average, peak and burst volumes, load-test the complete chain, and onboard in stages against agreed throughput and latency thresholds with defined degradation behaviour."}, {"id": "B", "text": "Ask the new clients to spread their files evenly across 24 hours and change nothing on the platform."}, {"id": "C", "text": "Onboard all five clients at once and monitor the platform in production, scaling reactively if it slows."}, {"id": "D", "text": "Increase the timeout on every channel so slow payments are not noticed by customers."}], "scenario": "You are the business analyst for Meridian Bank. Five new clients will add ten million transactions a month, concentrated in morning peaks. The platform already runs at 70 percent of measured capacity in its busiest hour. The chief operating officer asks for your recommendation before the first client goes live.", "why": "Option A is correct because it converts the forecast into testable non-functional requirements, proves the platform against them with load testing, and de-risks go-live with staged onboarding and agreed degradation behaviour. Option C risks an outage for existing clients as well as new ones. Option B is not in the bank's control, since client file timing follows their business cycles. Option D hides latency instead of fixing capacity and increases the risk of duplicate submissions."}, "recommended_solution": "Start with a capacity model, not a guess. Take the ten million monthly transactions and derive the average daily volume, then model the peak hour and the burst minute from the new clients' file patterns, because payroll and supplier files arrive in concentrated windows. Add the amplification factors that load tests often miss: retry traffic when channels time out, duplicate submissions, screening re-runs after repair, and reconciliation reads. For each component in the chain, channel, gateway, orchestration, screening, engine, connectors and ledger, record the measured throughput, the latency at that throughput, and the point at which latency degrades, so the model identifies the first bottleneck rather than assuming the engine is the constraint.\n\nSecond, load-test the complete chain, not individual services in isolation. Run the agreed average, peak and stress profiles end to end with realistic payload sizes and realistic dependency latency, and measure throughput, latency percentiles, queue depth, error rate and resource use. Define the scaling thresholds and the headroom policy in advance, for example that the platform must sustain peak load at no more than 60 percent of measured capacity, and define graceful degradation: which traffic is shed first, how back-pressure is applied to channels, and what customers are told when degradation starts.\n\nThird, onboard in stages and make go-live conditional on evidence. Bring the first client live, measure actual peak behaviour against the model, and only then onboard the next. Put queue-depth and latency alerts, circuit breakers and dead-letter handling in place before the first go-live, and agree recovery objectives for each component so a failure under load has a rehearsed recovery path. Report the capacity position weekly to the chief operating officer in the same numbers every time, so growth is tracked against the model rather than discovered in an incident.", "flow_steps": [{"action": "Submits a payment file in the morning peak window", "actor": "Corporate client", "step": 1, "system": "Corporate banking channel"}, {"action": "Authenticates, rate-limits and applies back-pressure when the platform is saturated", "actor": "API gateway", "step": 2, "system": "API gateway"}, {"action": "Splits the file into individual payment instructions with correlation IDs", "actor": "Orchestration service", "step": 3, "system": "Orchestration service"}, {"action": "Runs sanctions and fraud screening within its latency budget", "actor": "Screening service", "step": 4, "system": "Screening service"}, {"action": "Validates, routes and executes payments in priority order", "actor": "Payment engine", "step": 5, "system": "Payment engine"}, {"action": "Delivers messages to the clearing system and handles acknowledgements", "actor": "Clearing connector", "step": 6, "system": "Clearing connector"}, {"action": "Posts accounting entries and updates balances", "actor": "Ledger service", "step": 7, "system": "Core ledger"}, {"action": "Tracks throughput, latency, queue depth and error rate against thresholds and alerts Operations", "actor": "Monitoring service", "step": 8, "system": "Monitoring and alerting"}], "happy_path": "The capacity model predicts the peak load from the five new clients, load testing proves the complete chain sustains it within latency targets, and staged onboarding confirms the model in production. Morning files process within their value-date windows, queue depth stays within limits, latency stays within target percentiles, and existing clients see no degradation.", "negative_paths": [{"handling": "Apply back-pressure at the gateway, shed lower-priority traffic first under the agreed degradation policy, alert Operations, and scale or fail over the screening service.", "path": "Dependency saturation", "trigger": "The screening service slows under peak load and latency grows across every payment"}, {"handling": "Enforce idempotency keys so retries do not create duplicate work, return a pending state instead of timing out silently, and apply circuit breakers to the retrying channel.", "path": "Retry storm", "trigger": "Channels time out and resubmit the same payments, multiplying the load on a saturated platform"}, {"handling": "Prioritise by value date and SLA, notify affected customers early, pause lower-priority intake, and reconcile every queued item after recovery.", "path": "Queue growth beyond recovery", "trigger": "The durable queue grows faster than the engine can drain it and value dates are at risk"}, {"handling": "Identify the contention in load-test evidence, apply the agreed scaling or partitioning change, and do not onboard the next client until the bottleneck is proven resolved.", "path": "Database contention", "trigger": "Concurrent writes to the ledger and status store contend and throughput collapses"}, {"handling": "Test failover under peak load, not only at idle, and keep the recovery objective and the degraded-service communication plan rehearsed.", "path": "Failover capacity insufficient", "trigger": "A component fails at peak and the standby cannot carry the load"}], "technical_data": "Define non-functional requirements as numbers: average, peak and burst transactions per second, end-to-end latency percentiles, maximum queue depth, maximum queue age, storage growth per million transactions, and recovery time and recovery point objectives. Use durable queues with a defined retention and dead-letter policy, and correlation IDs that survive every hop so a single payment can be traced under load. Make every submission idempotent so retries and replays cannot create duplicate payments. Instrument each component with throughput, latency, queue depth, error rate and resource metrics on a common dashboard, and set alerts on thresholds that are agreed in advance, not discovered during an incident. Keep load-test evidence versioned with the configuration it was run against, so a later change can be compared with the baseline.", "messages_fields": [{"key_fields": ["Batch control total and item count, used to verify the file was received complete", "Instruction identification per item, used for idempotency and tracing", "Instructed amount and currency per item"], "message": "pain.001", "purpose": "Customer file carrying the batch of payment instructions that drives the volume"}, {"key_fields": ["End-to-end identification carried from the original instruction", "Interbank settlement amount and date", "Creditor account and agent"], "message": "pacs.008", "purpose": "Interbank customer credit transfer generated per executed payment"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code where applicable"], "message": "pacs.002", "purpose": "Payment status report confirming acceptance, execution or rejection per item"}], "accounting_operational": "Ten million extra transactions a month increases ledger posting volume, statement generation, reconciliation matching and storage proportionally, so Finance and Operations must size those processes for the same peak, not just the average. The batch control total for each file must reconcile to executed, rejected and queued items every day, and any item that is queued past its value date must be reported to the customer with a revised timing. Operations works from queue-depth and ageing dashboards with agreed escalation thresholds, and Treasury must confirm that settlement liquidity covers the higher peak-day outflows. If degradation is triggered, the agreed order of shedding and the customer communication must be followed, and every shed or delayed item must be reconciled after recovery.", "gherkin": ["Given forecast peak load from the five new clients", "When the system is tested at the agreed stress level", "Then throughput and latency remain within the approved thresholds", "Given the clearing connector is unavailable at peak", "When queue depth crosses the agreed threshold", "Then alerts and controlled back-pressure are activated", "Given a channel submission that times out under load", "When the client retries with the same idempotency key", "Then no duplicate payment is created", "Given a component failure during peak load", "When failover is triggered", "Then the standby sustains the agreed degraded throughput within the recovery objective"], "assessment": [{"answer": 0, "explanation": "Payroll and supplier files land in concentrated windows, so the platform must be sized for the peak hour and burst minute, not the monthly average divided by thirty days.", "options": ["Because files arrive in concentrated peaks and bursts, so peak and burst load are far higher than the average", "Because the average ignores the number of clients", "Because averages do not include weekends", "Because averages are hard to calculate"], "question": "Why is the average daily volume not enough to size a payment platform?"}, {"answer": 0, "explanation": "When channels time out and resubmit, the same work arrives twice or more, which deepens the saturation and can turn a slowdown into an outage. Idempotency and pending states prevent this.", "options": ["Each timed-out submission is sent again, multiplying load on a system that is already saturated", "Retries bypass screening", "Retries use a different message format", "Retries are slower than new payments"], "question": "What makes a retry storm dangerous during saturation?"}, {"answer": 3, "explanation": "Bottlenecks hide in dependencies, so the whole chain must be tested together at realistic peak and stress levels with realistic payload sizes and dependency latency.", "options": ["Only the database", "One service in isolation at low volume", "Only the user interface", "The complete chain end to end at average, peak and stress profiles with realistic payloads"], "question": "What should load testing cover to be meaningful for this growth?"}, {"answer": 1, "explanation": "Graceful degradation is a pre-agreed policy for what is shed first, how back-pressure is applied and what customers are told, so a capacity breach is controlled rather than chaotic.", "options": ["Turning off monitoring during peaks", "A defined order for shedding lower-priority traffic and applying back-pressure when capacity is exceeded", "Letting the platform fail silently", "Asking customers to wait without telling them"], "question": "What is graceful degradation in this context?"}, {"answer": 0, "explanation": "Staged onboarding turns the capacity model into measured evidence. If the first client behaves differently from the forecast, the plan can be corrected before the remaining load arrives.", "options": ["So actual peak behaviour can be measured against the model after each client before adding the next", "Because the clients prefer it", "To delay revenue", "To avoid load testing"], "question": "Why onboard the five clients in stages rather than all at once?"}]}}, {"id": "INS-115", "kind": "insight", "title": "One-hour cut-off extension", "topic": "One-hour cut-off extension", "theme": "Payment BA Awareness", "text": "Assess downstream scheme windows, liquidity, operational staffing, customer promise and exception handling.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch44s2", "title": "Cut-Off Management and Processing Calendars", "url": "lessons/ch44s2"}, "case": {"status": "authored", "business_problem": "Northgate Retail, a large corporate customer of Meridian Bank, asks for its same-day payment cut-off to be extended by one hour, from 15:00 to 16:00. Its suppliers have moved their own ordering deadlines later, and a payment that misses the 15:00 cut-off now settles a day later, which costs Northgate Retail early-payment discounts and strains supplier relationships. The relationship manager supports the request and argues that it is only one hour, but the operations team is cautious: a cut-off is not a single clock on a single screen, it is the end of a chain of deadlines that includes channel availability, validation, fraud and sanctions screening, engine processing, the scheme or clearing deadline, correspondent cut-offs, liquidity availability, settlement, ledger posting and reconciliation.\n\nThe real question is which downstream deadline is the true constraint. If the clearing system closes at 15:30, extending the customer cut-off to 16:00 is meaningless, because payments accepted after 15:30 cannot reach clearing the same day. If the sanctions team finishes at 15:00, late payments would sit unscreened. If Treasury has already allocated the day's liquidity, late payments could fail for insufficient funds even though the customer account holds the money. And if the reconciliation batch starts at 16:00, late payments could collide with it and corrupt the daily close.\n\nThe bank must assess the extension end to end and approve it only for the routes, currencies, customers and dates where every downstream control can still be met. A partial approval, for example for one rail only, is a legitimate outcome, and a refusal with a clear explanation is better than an approval that silently breaks the same-day promise.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Extend the channel cut-off only, and let late payments queue for the next day without telling the customer."}, {"id": "B", "text": "Run an end-to-end impact assessment across channel, screening, engine, scheme and correspondent deadlines, liquidity, staffing, settlement and reconciliation, and approve only the routes where every downstream control can still be met."}, {"id": "C", "text": "Extend the cut-off by one hour for all rails, currencies and customers immediately, since it is only one hour."}, {"id": "D", "text": "Refuse the request without assessment because cut-offs should never change."}], "scenario": "You are the business analyst for Meridian Bank. Northgate Retail asks for a one-hour extension to its same-day payment cut-off. The relationship manager supports it. You must recommend whether and how to approve it.", "why": "Option B is correct because a cut-off is the end of a chain of deadlines, and the extension is only valid where every downstream participant, control and process can still meet the revised window. Option C ignores the true constraint, which may be a clearing or correspondent deadline earlier than the new cut-off. Option A breaks the same-day promise silently. Option D refuses without evidence and may reject an extension that is achievable for some routes."}, "recommended_solution": "Map the full chain before deciding anything. For each rail and currency the customer uses, list every deadline in order: channel close, validation and screening completion, engine processing, scheme or clearing submission, correspondent cut-off, settlement, ledger posting and reconciliation start. Identify the earliest binding constraint for each route, because that is the real cut-off, and record the staffing that each step needs, including sanctions and fraud coverage, Treasury liquidity cover and Operations support for exceptions.\n\nThen model the extension against normal and peak volumes. An extra hour of intake is not free: it adds payments to the busiest part of the day, it extends the screening and Operations shifts, and it shortens the window between the last payment and the reconciliation batch. Test the revised window end to end, including a peak-volume day, a late clearing rejection, and a liquidity shortfall, and define the fallback and rollback: what happens to payments that are accepted in the extended hour but then rejected by clearing, and how the extension is switched off if a downstream participant cannot meet it on a given day.\n\nApprove narrowly and communicate precisely. Enable the extension only for the eligible rails, currencies, customers and operating dates, configure it as effective-dated rules rather than a manual override, and tell the customer exactly which payment types are covered and what happens to payments that arrive in the extended hour but cannot complete the same day. Monitor the first weeks against the modelled volumes and service levels, and review whether the extension should continue, be widened or be withdrawn.", "flow_steps": [{"action": "Submits a payment in the extended hour between 15:00 and 16:00", "actor": "Northgate Retail", "step": 1, "system": "Corporate banking channel"}, {"action": "Checks the payment is eligible for the extended window by rail, currency and customer", "actor": "Payment platform", "step": 2, "system": "Cut-off and eligibility service"}, {"action": "Completes fraud and sanctions screening within the extended staffing window", "actor": "Screening team and service", "step": 3, "system": "Screening service"}, {"action": "Validates, routes and releases the payment", "actor": "Payment engine", "step": 4, "system": "Payment engine"}, {"action": "Submits the payment to the scheme or clearing system before its deadline", "actor": "Clearing connector", "step": 5, "system": "Clearing connector"}, {"action": "Confirms settlement liquidity covers the extended-hour outflows", "actor": "Treasury", "step": 6, "system": "Treasury and liquidity service"}, {"action": "Posts the accounting entries and updates the customer balance", "actor": "Ledger service", "step": 7, "system": "Core ledger"}, {"action": "Reconciles the extended-hour payments in the daily close without colliding with the reconciliation batch", "actor": "Operations", "step": 8, "system": "Reconciliation service"}], "happy_path": "The impact assessment shows that the scheme and correspondent deadlines allow the extra hour for the customer's main rail, staffing and liquidity are extended to match, and the extension is enabled only for that rail and currency. Payments submitted between 15:00 and 16:00 are screened, cleared, settled and reconciled the same day, and the customer receives same-day confirmation.", "negative_paths": [{"handling": "Do not enable the extension for that route, tell the customer the true constraint, and offer the next-day value date or an alternative rail whose deadline allows the extra hour.", "path": "Clearing closes earlier than the new cut-off", "trigger": "The scheme deadline is 15:30, so payments accepted at 15:45 cannot reach clearing the same day"}, {"handling": "Hold the affected payments, notify the customer and Treasury, and release them only when cover is confirmed or value-date them for the next business day with the customer's agreement.", "path": "Liquidity unavailable in the extended hour", "trigger": "Treasury has allocated the day's settlement funds and the late payments exceed the remaining cover"}, {"handling": "Do not release unscreened payments. Extend the screening shift as part of the approval, or restrict the extension to low-risk payment types that can be screened automatically.", "path": "Screening cover ends at the old cut-off", "trigger": "The sanctions team finishes at 15:00 and late payments sit unscreened"}, {"handling": "Reschedule the batch or ring-fence the extended-hour items for a supplementary reconciliation, and do not let the batch post an incomplete daily position.", "path": "Reconciliation batch collision", "trigger": "The daily reconciliation batch starts at 16:00 and late payments arrive while it is running"}], "technical_data": "Model cut-offs as effective-dated configuration keyed by rail, currency, customer segment and operating date, never as a single global clock. Each payment must carry its value date, its cut-off eligibility result and the downstream deadline it was assessed against, so an exception can be traced to the constraint that caused it. Keep the customer instruction status distinct from the clearing status, so a payment accepted in the extended hour that is then rejected by clearing is shown as clearing-rejected, not as a customer error. Use correlation IDs across channel, engine, clearing and ledger so the extended-hour population can be reported and reconciled separately. Log the staffing, liquidity and deadline assumptions behind each approval so the extension can be re-assessed when any of them changes.", "messages_fields": [{"key_fields": ["Interbank settlement date, the value date the extension promises", "End-to-end identification carried from the customer instruction", "Creditor account and agent"], "message": "pacs.008", "purpose": "Interbank customer credit transfer for payments released in the extended hour"}, {"key_fields": ["Original instruction identification", "Transaction status, distinguishing channel acceptance from clearing acceptance", "Status reason code where clearing rejects a late payment"], "message": "pacs.002", "purpose": "Payment status report confirming acceptance, clearing outcome or rejection"}, {"key_fields": ["Account identification", "Entry amount, currency and value date", "Related instruction reference"], "message": "camt.054", "purpose": "Debit or credit notification confirming the ledger posting for the customer"}], "accounting_operational": "Payments in the extended hour must settle and post the same day for the extension to mean anything, so Treasury must confirm liquidity cover for the extended window and Finance must confirm that the ledger and reconciliation batches can absorb the later postings. If a payment accepted in the extended hour is rejected by clearing, any reservation is reversed once and the customer is told the revised value date. Operations needs extended staffing for screening, exception handling and customer support, and the daily reconciliation must include the extended-hour population as a separately reported segment so a late item cannot be lost between the old close and the new one. Service levels for the extended hour are monitored separately from the normal window.", "gherkin": ["Given an extension request for a one-hour later cut-off", "When any critical downstream participant cannot meet the revised window", "Then the extension is not enabled for that route", "Given a payment submitted in the extended hour for an eligible rail", "When screening, clearing and liquidity all complete within their deadlines", "Then the payment settles the same day and the customer receives same-day confirmation", "Given a payment submitted in the extended hour for a route whose clearing deadline has passed", "When the payment is processed", "Then it is value-dated for the next business day and the customer is told the revised date", "Given a payment accepted in the extended hour that clearing then rejects", "When the rejection is received", "Then the payment moves to a clearing-rejected state and any reservation is reversed once"], "assessment": [{"answer": 2, "explanation": "A cut-off is the end of a chain. The extension is only real if every downstream deadline, including clearing and correspondent cut-offs, can still be met.", "options": ["The reconciliation batch start time alone", "The channel closing time", "The earliest binding downstream deadline in the whole chain, such as the clearing or correspondent deadline", "The customer's preference"], "question": "What is the true constraint on a cut-off extension?"}, {"answer": 2, "explanation": "Acceptance by the bank's channel does not guarantee clearing acceptance. Keeping the states distinct prevents the bank from promising same-day settlement for a payment clearing has rejected.", "options": ["Because clearing never rejects payments", "To make reports longer", "Because a payment accepted by the channel can still be rejected by clearing, and the customer must be told the true outcome", "Because channels are slower"], "question": "Why must channel acceptance be kept distinct from clearing acceptance?"}, {"answer": 0, "explanation": "Unscreened payments must never be released. Either the staffing is extended to match the new window, or the extension is limited to what can be screened within the available cover.", "options": ["Extend screening cover, or restrict the extension to payment types that can be screened automatically", "Ignore the gap", "Release payments without screening", "Ask the customer to screen their own payments"], "question": "What should happen if the sanctions team finishes before the extended cut-off?"}, {"answer": 2, "explanation": "Effective-dated, keyed configuration makes the extension precise, testable and reversible, and prevents it from applying to routes where it was never approved.", "options": ["By asking operators to remember it", "As a single global clock change", "As effective-dated rules keyed by rail, currency, customer and operating date", "As a manual override each day"], "question": "How should the extension be configured?"}, {"answer": 1, "explanation": "The bank cannot move the clearing deadline. The honest outcome is to decline that route, explain why, and offer what is actually achievable.", "options": ["Accept the payments and value-date them silently for the next day", "Do not enable the extension for that route and explain the constraint, offering an alternative rail or next-day value dating", "Accept the payments and hope clearing takes them", "Extend the clearing deadline unilaterally"], "question": "What is the right outcome if clearing closes at 15:30 and the customer wants a 16:00 cut-off?"}]}}, {"id": "INS-116", "kind": "insight", "title": "Optional purpose code required by downstream system", "topic": "Optional purpose code required by downstream system", "theme": "Payment BA Awareness", "text": "Identify mandatory downstream enrichment, source ownership, validation and repair behaviour.", "domain": "Data & ISO 20022", "area": "Data & ISO 20022", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch39s6", "title": "Mandatory, Optional and Conditional Fields, Schema Validation, External Code Sets, Version Management and Market Practice Rules", "url": "lessons/ch39s6"}}, {"id": "INS-117", "kind": "insight", "title": "EU instant payments maximum amount regulatory change", "topic": "EU instant payments maximum amount regulatory change", "theme": "Payment BA Awareness", "text": "Separate scheme-level maximum from bank/customer limits and evaluate routing rule impact.", "domain": "SEPA Instant & Regulation", "area": "SEPA Instant & Regulation", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch11s10", "title": "SEPA Instant Payments Regulation: phased obligations from 2025", "url": "lessons/ch11s10"}, "case": {"status": "authored", "business_problem": "Aldergrove Manufacturing, a corporate customer of Meridian Bank, wants to pay a supplier 250,000 euro instantly on a Friday afternoon. The payments team at the bank is unsure whether the payment can go as an instant payment at all. An older internal guide still says the scheme maximum for instant euro payments is 100,000 euro, and the product configuration enforces that cap. A newer colleague says the cap has been removed, and the customer is pressing for an answer before the supplier's deadline. Meanwhile the bank's own product limit for instant payments is 50,000 euro for this customer segment, and the fraud team has a separate velocity limit on large instant payments. Three different numbers are in play, and nobody in the room can say with confidence which one governs.\n\nThe facts that settle the question come from the current scheme and regulatory position. The EPC SCT Inst Rulebook 2025 removed the 100,000 euro scheme maximum, effective 5 October 2025, so there is now no scheme-level maximum for instant euro payments. Regulation (EU) 2024/886 requires a maximum execution time of 10 seconds, with sub-timelines of 5, 7 and 9 seconds for the stages within that window. Verification of Payee is mandatory for instant euro payments from 9 October 2025. None of that removes the bank's own right to set a lower product limit or a customer-level risk limit, but those limits must be presented as the bank's own, not as a scheme cap.\n\nThe bank must separate the four layers, scheme maximum, regulatory obligation, bank product limit and customer-level risk limit, decide their precedence, set an effective date for the change, and update routing, channels, customer terms and communications consistently. A payment above the bank's product limit but below any scheme maximum must be handled by the bank's own rule, for example by routing it to a non-instant rail or by seeking an approved exception, and the customer must be told which limit applied and why.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Reject the payment, citing the old 100,000 euro scheme maximum."}, {"id": "B", "text": "Apply the limit hierarchy: no scheme maximum now applies, but the bank's stricter product and customer risk limits govern, so route the payment to the appropriate non-instant rail or an approved exception process and explain which limit applied."}, {"id": "C", "text": "Send it instantly, ignoring the bank's product limit because the scheme cap is gone."}, {"id": "D", "text": "Split the payment into five instant payments of 50,000 euro to work around the product limit."}], "scenario": "You are the business analyst for Meridian Bank. A corporate customer wants to send 250,000 euro instantly. The old internal guide says the scheme maximum is 100,000 euro. The current rulebook has removed that scheme maximum, but the bank's own product limit for this customer is 50,000 euro. The customer asks which limit applies.", "why": "Option B is correct because it separates the layers: the scheme maximum no longer exists, but the bank's own product and risk limits still govern and must be enforced transparently. Option A teaches an outdated rule, since the 100,000 euro scheme maximum was removed effective 5 October 2025. Option C ignores the bank's legitimate risk controls. Option D is structuring to evade a limit and creates reconciliation and fraud risks."}, "recommended_solution": "First, establish the authoritative facts and record them with their sources and effective dates. The scheme maximum of 100,000 euro was removed by the EPC SCT Inst Rulebook 2025, effective 5 October 2025, and there is now no scheme-level maximum. The regulatory execution obligation is a maximum of 10 seconds under Regulation (EU) 2024/886, and Verification of Payee is mandatory for instant euro payments from 9 October 2025. The old 100,000 euro figure must be removed from every guide, configuration comment and training slide, because a stale number in one place will be quoted as the rule.\n\nSecond, define the limit hierarchy explicitly and implement it as effective-dated configuration. The order is: regulatory obligations first, then the scheme rules, then the bank's product limit, then the customer-level risk limit, with the strictest applicable limit winning for any given payment. For Aldergrove Manufacturing, that means the 50,000 euro product limit governs the 250,000 euro request, and the correct handling is to route it to the appropriate non-instant rail or to an approved exception process, with the customer told plainly that the bank's product limit applied, not a scheme cap.\n\nThird, manage the transition. Apply the new scheme position from its effective date, decide how in-flight and standing instructions are treated, update every channel consistently so the mobile app, the corporate portal and the API give the same answer, and update customer terms and communications. Regression-test the hierarchy with cases above and below each limit, including a payment above the customer limit but below the old scheme maximum, and keep a rule inventory that records which rulebook version and regulation applies to each payment date.", "flow_steps": [{"action": "Submits a 250,000 euro instant payment instruction through the corporate portal", "actor": "Aldergrove Manufacturing", "step": 1, "system": "Corporate banking portal"}, {"action": "Evaluates the payment against the scheme rules, the bank product limit and the customer risk limit in precedence order", "actor": "Limits service", "step": 2, "system": "Limits and rules service"}, {"action": "Checks the beneficiary name against the account before the payment proceeds", "actor": "Verification of Payee service", "step": 3, "system": "Verification of Payee service"}, {"action": "Routes the payment: instant if within all limits, otherwise to the non-instant rail or the exception process", "actor": "Payment engine", "step": 4, "system": "Payment engine"}, {"action": "Executes the instant payment within the 10-second maximum where the instant route applies", "actor": "Payment engine", "step": 5, "system": "Payment engine"}, {"action": "Settles the instant payment and returns confirmation", "actor": "Clearing system", "step": 6, "system": "Instant clearing system"}, {"action": "Tells the customer the outcome and, where a limit applied, which limit and why", "actor": "Notification service", "step": 7, "system": "Notification service"}, {"action": "Posts the debit and credit and updates the customer balance", "actor": "Ledger service", "step": 8, "system": "Core ledger"}], "happy_path": "A payment within the scheme rules and within the bank's product and customer limits is verified, executed within 10 seconds, confirmed to the customer, and settled. A payment above the bank's product limit is routed to the appropriate non-instant rail or exception process, and the customer is told clearly that the bank's product limit applied, not a scheme cap.", "negative_paths": [{"handling": "Apply the single governed hierarchy in the limits service for every channel, so all channels enforce the same strictest applicable limit and give the same explanation.", "path": "Conflicting limits", "trigger": "A payment is above the customer limit but below the old scheme maximum, and different channels give different answers"}, {"handling": "Use effective-dated rules keyed to the payment date, remove the stale 100,000 euro figure from all configuration, and regression-test payments dated before and after the change.", "path": "Effective-date transition", "trigger": "A payment is processed around the date the scheme maximum was removed and the old rule is still in configuration"}, {"handling": "Warn the customer with the Verification of Payee result, do not proceed without the customer's informed decision, and record the outcome and the customer's choice.", "path": "Verification of Payee mismatch", "trigger": "The beneficiary name does not match the account for a large instant payment"}, {"handling": "Apply the timeout and confirmation rules, do not leave the payment in an unknown state, and report the outcome to the customer with the defined next steps.", "path": "Instant execution exceeds 10 seconds", "trigger": "A dependency is slow and the payment cannot complete within the regulatory maximum"}], "technical_data": "Implement limits as effective-dated configuration in a single limits service, with separate fields for scheme maximum, regulatory obligation, bank product limit and customer risk limit, each with its owner, source and effective dates. Never hard-code the old 100,000 euro figure anywhere. Record the rule version applied to each payment, including the rulebook version and the regulation, so a payment can be reconstructed later. Use correlation IDs across the limits check, Verification of Payee, execution and confirmation. Apply the 10-second execution budget as a measured service level with sub-timeline monitoring at 5, 7 and 9 seconds, and alert when the budget is at risk. Keep the routing decision, the limit that governed it and the customer explanation in the audit record.", "messages_fields": [{"key_fields": ["Interbank settlement amount and date", "End-to-end identification", "Creditor account and agent, verified through Verification of Payee"], "message": "pacs.008", "purpose": "Interbank customer credit transfer for the instant euro payment where the instant route applies"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code and information explaining which limit governed"], "message": "pacs.002", "purpose": "Payment status report confirming execution or rejection, including the reason where a limit applied"}], "accounting_operational": "An instant payment that executes creates an immediate debit and settlement entry, so Treasury must hold liquidity for large instant outflows even though there is no longer a scheme maximum to cap them. Payments routed to a non-instant rail instead follow that rail's value date and settlement timing, and the customer statement must show the rail actually used. Operations monitors instant execution times against the 10-second maximum and investigates breaches, and the limits service changes are subject to a governed release with customer communications for any product-limit change. A payment that exceeds the execution window must be reconciled as an exception, never left in an unknown state.", "gherkin": ["Given a payment amount above a customer limit but below any scheme maximum", "When limits are evaluated", "Then the bank's stricter applicable limit is enforced and the customer is told which limit applied", "Given the SCT Inst Rulebook 2025 effective date of 5 October 2025", "When a payment is processed after that date", "Then no 100,000 euro scheme maximum is applied", "Given an instant euro payment", "When it is executed", "Then it completes within the 10-second regulatory maximum", "Given an instant euro payment from 9 October 2025", "When the beneficiary is checked", "Then Verification of Payee is performed before execution"], "assessment": [{"answer": 1, "explanation": "The EPC SCT Inst Rulebook 2025 removed the 100,000 euro scheme maximum, effective 5 October 2025. There is now no scheme-level maximum.", "options": ["100,000 euro", "There is no scheme-level maximum now", "1,000,000 euro", "50,000 euro"], "question": "What is the scheme-level maximum for SCT Inst payments under the Rulebook 2025?"}, {"answer": 2, "explanation": "The regulation requires a maximum execution of 10 seconds, with sub-timelines of 5, 7 and 9 seconds for the stages within that window.", "options": ["60 seconds", "5 seconds for the whole payment", "10 seconds", "1 business day"], "question": "What is the maximum execution time for an instant euro payment under Regulation (EU) 2024/886?"}, {"answer": 2, "explanation": "The scheme no longer caps the amount, but the bank's own product and customer risk limits still apply, and the strictest applicable limit wins.", "options": ["No limit applies", "The customer's preference", "The bank's stricter applicable limit", "The scheme maximum"], "question": "A payment is above the bank's product limit but below any scheme maximum. Which limit governs?"}, {"answer": 1, "explanation": "Verification of Payee became mandatory for instant euro payments from 9 October 2025.", "options": ["5 October 2025", "9 October 2025", "1 January 2026", "It is still optional"], "question": "When did Verification of Payee become mandatory for instant euro payments?"}, {"answer": 0, "explanation": "A stale limit in one place is enough for staff or systems to enforce it. Removing it everywhere is part of implementing the rule change correctly.", "options": ["Because a stale figure in any guide or comment will be quoted as the current rule and cause wrong rejections", "Because the figure was never real", "To save space", "Because customers dislike round numbers"], "question": "Why must the old 100,000 euro figure be removed from guides and configuration?"}]}}, {"id": "INS-118", "kind": "insight", "title": "Stale Intermediary Agent 2 data", "topic": "Stale Intermediary Agent 2 data", "theme": "Payment BA Awareness", "text": "Define reference data ownership, validation, update process and routing failure controls.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch75s3", "title": "Investigation: the wrong intermediary", "url": "lessons/ch75s3"}}, {"id": "INS-119", "kind": "insight", "title": "Vendor says capability exists: verify configuration granularity", "topic": "Vendor says capability exists: verify configuration granularity", "theme": "Payment BA Awareness", "text": "Validate whether a capability is configurable by country, entity, product or payment type.", "domain": "Vendor & Solution Assessment", "area": "Vendor & Solution Assessment", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch83s6", "title": "Vendor selection and management: choosing and controlling a payment supplier", "url": "lessons/ch83s6"}}, {"id": "INS-120", "kind": "insight", "title": "Explain payment rules without jargon", "topic": "Explain payment rules without jargon", "theme": "Payment BA Awareness", "text": "Translate scheme concepts into trigger, decision, rule, timeline and system behaviour for developers.", "domain": "Professional Masterclass", "area": "Professional Masterclass", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch84s1", "title": "Requirements gathering for payments: workshops, elicitation and the domain language", "url": "lessons/ch84s1"}}, {"id": "INS-121", "kind": "insight", "title": "Why direct debit matters for European recurring payments", "topic": "Why direct debit matters for European recurring payments", "theme": "SEPA Direct Debit", "text": "Compare recurring payment use cases and market context; validate market statistics before publication.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 1, "depth_name": "Quick insight", "difficulty": "Foundation", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s1", "title": "SDD Core and B2B: Two Schemes, Two Risk Profiles", "url": "lessons/ch62s1"}}, {"id": "INS-122", "kind": "insight", "title": "Creditor role and Creditor Identifier", "topic": "Creditor role and Creditor Identifier", "theme": "SEPA Direct Debit", "text": "Explain creditor identification and its role in SDD collection initiation.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s2", "title": "The Four-Corner SDD Model and Mandate Flows", "url": "lessons/ch62s2"}}, {"id": "INS-123", "kind": "insight", "title": "Mandate lifecycle and mandate data", "topic": "Mandate lifecycle and mandate data", "theme": "SEPA Direct Debit", "text": "Capture mandate creation, amendment, cancellation, reference and evidence requirements.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s3", "title": "e-Mandate Service and Its ISO 20022 Messages", "url": "lessons/ch62s3"}, "case": {"status": "authored", "business_problem": "Harbour Energy, a utility creditor, collects monthly bills from 40,000 household customers by SEPA Direct Debit. Its billing system generates a collection file each month, but the mandate data behind the file is uneven: some mandates were signed on paper years ago and their scanned images are stored in a shared drive, some were created online and their consent evidence is in a different system, and some mandates were amended when customers changed bank accounts, with the amendment recorded only as a free-text note. When a collection is rejected for a missing or invalid mandate, the billing team cannot prove quickly whether a valid mandate existed, and the customer disputes the collection.\n\nThe lifecycle problem is wider than storage. A mandate that has not been used for 36 months must not be used, yet Harbour Energy has no systematic check for dormant mandates, so a customer who left three years ago could still be collected from if their account were still open. Amendments are not versioned, so when a customer changes account, the old account details and the new ones sit side by side with no clear current version. Cancellations arrive by phone, email and letter, and not all of them reach the mandate register, so a cancelled mandate can still generate a collection.\n\nHarbour Energy needs a mandate lifecycle that covers creation, amendment, cancellation, reference and evidence, with each mandate carrying a unique reference, a status, a version history and retrievable consent evidence, and with collection validation that checks the mandate before any file is submitted. The creditor, not the debtor's bank, owns the mandate evidence, and the bank must be able to rely on the creditor's validation.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Collect from every customer and refund anyone who complains."}, {"id": "B", "text": "Build a governed mandate lifecycle with a unique reference, status, versioned amendments, retrievable consent evidence and a 36-month dormancy rule, and validate every collection against the mandate before submission."}, {"id": "C", "text": "Resubmit the collection and ask the debtor's bank to check the mandate."}, {"id": "D", "text": "Delete all mandates older than a year to remove the stale data."}], "scenario": "You are the business analyst for Harbour Energy. A collection is rejected for a missing mandate, but the billing team believes a mandate was signed. Dormant mandates are not checked, amendments are unversioned, and cancellations sometimes never reach the mandate register. The operations director asks for your recommendation.", "why": "Option B is correct because it fixes the lifecycle itself: unique references, versioned amendments, evidence retention and dormancy control, with validation before submission so invalid collections never leave the creditor. Option C shifts the creditor's responsibility to the debtor's bank. Option A collects without authority and creates refund and complaint volumes. Option D destroys valid mandates and their evidence."}, "recommended_solution": "Create a single mandate register as the system of record. Every mandate gets a unique mandate reference, the creditor identifier, the debtor name and IBAN, the scheme, the date of signature, the signature or consent evidence, the status, and a version number. Amendments create a new version rather than overwriting the old one, so the history shows what changed, when, and under whose authority. Cancellations change the status to cancelled with a date, reason and channel, and a cancelled mandate can never generate a collection again. Evidence must be retrievable by reference within the agreed service level, whether the original was paper or electronic.\n\nBuild collection validation against the register, not against the billing file alone. Before a collection is included in the submission file, the platform checks that an active mandate exists for the debtor, that the creditor identifier and debtor account match the current mandate version, that the mandate has been used within the last 36 months, and that the pre-notification requirement has been met. Any collection that fails is routed to repair or rejection with a clear reason, and never submitted in the hope that the debtor's bank will accept it.\n\nFinally, govern the lifecycle with controls and reporting. Report monthly on dormant mandates approaching 36 months, on mandates whose evidence cannot be retrieved, on amendments and cancellations by channel, and on collections rejected for mandate reasons. Make the mandate owner accountable for evidence completeness, and test the register with a simulated dispute: can the team produce the mandate, its version history and its evidence for any given collection within the agreed time?", "flow_steps": [{"action": "Signs the mandate, on paper or electronically, authorising Harbour Energy to collect by direct debit", "actor": "Customer", "step": 1, "system": "Mandate capture service"}, {"action": "Registers the mandate with a unique reference, creditor identifier, debtor IBAN and retrievable consent evidence", "actor": "Harbour Energy", "step": 2, "system": "Mandate register"}, {"action": "Amends the mandate, for example by changing bank account, creating a new versioned record", "actor": "Customer", "step": 3, "system": "Mandate register"}, {"action": "Generates the monthly collection and checks each item against the current mandate version", "actor": "Harbour Energy billing", "step": 4, "system": "Billing system"}, {"action": "Validates the mandate and submits the collection file", "actor": "Creditor PSP", "step": 5, "system": "Creditor PSP platform"}, {"action": "Routes the collection to the debtor PSP", "actor": "Clearing system", "step": 6, "system": "Clearing system"}, {"action": "Debits the debtor account on the due date", "actor": "Debtor PSP", "step": 7, "system": "Debtor PSP platform"}, {"action": "Reconciles the collection against the mandate register and the billing record", "actor": "Harbour Energy", "step": 8, "system": "Reconciliation service"}], "happy_path": "A customer signs a mandate that is registered with a unique reference and retrievable evidence. Monthly collections are validated against the current mandate version, pass, and are submitted and debited on the due date. An amendment creates a new version and later collections use the new account. A cancellation stops future collections immediately. Every collection can be traced to its mandate and evidence.", "negative_paths": [{"handling": "Block the collection before submission, route it to repair with a clear reason, and do not submit it in the hope the debtor PSP will accept it.", "path": "Mandate missing or invalid", "trigger": "A collection is generated for a debtor with no active mandate, or with mandate details that do not match the collection"}, {"handling": "Re-check mandate status at submission time, exclude the revoked item from the file, and record the exclusion with its reason.", "path": "Mandate revoked after file creation", "trigger": "The customer cancels the mandate after the collection file has been generated but before submission"}, {"handling": "Block the collection, mark the mandate dormant, and require a new mandate from the customer before any further collection.", "path": "Dormant mandate over 36 months", "trigger": "A mandate has not been used for 36 months and a collection is attempted"}, {"handling": "Treat the mandate as unproven, refund or reverse under the applicable process, escalate the evidence gap to the mandate owner, and fix the storage failure.", "path": "Evidence unavailable in a dispute", "trigger": "A customer disputes a collection and the signed mandate cannot be retrieved"}, {"handling": "Reject the duplicate at registration, enforce uniqueness in the register, and investigate the source system that generated it.", "path": "Duplicate mandate reference", "trigger": "Two mandates carry the same reference for different debtors"}], "technical_data": "Model the mandate as a versioned entity with a unique reference, creditor identifier, debtor IBAN, scheme, signature date, evidence pointer, status and version number, and never overwrite a prior version. Enforce referential integrity so a collection must reference an existing active mandate version. Apply the 36-month dormancy rule as a scheduled check that flags and then blocks dormant mandates. Store consent evidence with a durable pointer and a retrieval service level, and retain it for the period the scheme and local rules require. Use correlation IDs to link the mandate, the collection instruction, the interbank message and the ledger entry. Log every lifecycle event, creation, amendment, cancellation and use, with actor, timestamp and reason.", "messages_fields": [{"key_fields": ["Mandate identification, the unique reference for the mandate relied upon", "Creditor scheme identification, the creditor identifier", "Debtor account IBAN and name, matching the current mandate version", "Instructed amount, due date and sequence type"], "message": "pain.008", "purpose": "Customer direct debit initiation file from the creditor to its PSP carrying the collections"}, {"key_fields": ["Mandate identification and related mandate data", "Creditor scheme identification", "Debtor account and instructed amount", "Due date and sequence type"], "message": "pacs.003", "purpose": "Interbank direct debit collection from the creditor PSP to the debtor PSP"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code where the collection is rejected"], "message": "pacs.002", "purpose": "Payment status report for acceptance or rejection of the collection"}, {"key_fields": ["Original instruction identification and return reason code", "Returned amount", "Reference to the original collection"], "message": "pacs.004", "purpose": "Payment return for a collection returned by the debtor PSP, including refund cases"}], "accounting_operational": "Each collected item produces a credit to Harbour Energy and a debit to the debtor, with the batch control total reconciled against executed, rejected and returned items. A collection that is blocked for a mandate reason never posts, so it appears in the exception report rather than in the ledger. Returns and refunds are posted as separate linked events against the original collection, never by deleting it. Operations works from a mandate exception worklist with SLA targets for evidence retrieval and repair, and Finance monitors the value of collections blocked for mandate reasons as a measure of billing quality. Dormant mandates are reported monthly so the business can see how much of its mandate base is no longer usable.", "gherkin": ["Given a collection with no active mandate", "When validation runs", "Then the collection is not submitted and a clear reason is recorded", "Given a mandate that has not been used for 36 months", "When a collection is attempted against it", "Then the collection is blocked and the mandate is marked dormant", "Given a customer amends their bank account", "When the amendment is recorded", "Then a new mandate version is created and later collections use the new account", "Given a customer cancels a mandate", "When the cancellation is recorded", "Then no further collection is generated for that mandate"], "assessment": [{"answer": 3, "explanation": "The creditor obtains and holds the mandate. The creditor must validate collections against it and be able to produce the evidence when a collection is disputed.", "options": ["The clearing system", "The debtor", "The debtor's bank", "The creditor, who must hold the mandate and its evidence"], "question": "Who owns mandate validation and evidence?"}, {"answer": 0, "explanation": "A mandate unused for 36 months must not be used. The creditor must obtain a new mandate before collecting again.", "options": ["It must not be used, and a new mandate is needed before further collection", "It can be used once more as a test", "It can still be used indefinitely", "It is automatically renewed"], "question": "What happens to a mandate that has not been used for 36 months?"}, {"answer": 2, "explanation": "Versioning preserves the history, so any collection can be traced to the mandate version that was current when it was made, and disputes can be resolved from the record.", "options": ["As a free-text note", "By overwriting the old details", "As a new version, keeping the full history of what changed and when", "By deleting the old mandate"], "question": "How should a mandate amendment be recorded?"}, {"answer": 3, "explanation": "pacs.003 is the interbank direct debit collection message, carrying the mandate identification and the collection details to the debtor PSP.", "options": ["pain.001", "camt.053", "pacs.008", "pacs.003"], "question": "Which message carries the interbank direct debit collection?"}, {"answer": 2, "explanation": "Mandate status must be checked at submission time, not only at file creation. A revoked mandate must never produce a collection.", "options": ["Collect it and refund later if the customer complains", "Change the mandate reference to another customer", "Re-check mandate status at submission, exclude the revoked item, and record the exclusion", "Submit it anyway, since the file is already built"], "question": "What should happen to a collection whose mandate was revoked after the file was created?"}]}}, {"id": "INS-124", "kind": "insight", "title": "Due date versus settlement date versus debit date", "topic": "Due date versus settlement date versus debit date", "theme": "SEPA Direct Debit", "text": "Keep the three dates distinct and define their business and operational meaning.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}}, {"id": "INS-125", "kind": "insight", "title": "Four-corner model", "topic": "Four-corner model", "theme": "SEPA Direct Debit", "text": "Map creditor, creditor PSP, CSM and debtor PSP/debtor responsibilities and message path.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s2", "title": "The Four-Corner SDD Model and Mandate Flows", "url": "lessons/ch62s2"}, "case": {"status": "authored", "business_problem": "Harbour Energy collects monthly bills by SEPA Direct Debit, and a new analyst on the team cannot explain who does what when a collection fails. The creditor's billing system sends a file, the money moves, and sometimes it comes back, but the analyst cannot say which party is responsible for the mandate, which party checks the account, which party moves the funds between banks, or who the customer should call when a collection is wrong. The confusion matters because a recent failure was passed between four teams for two weeks: the creditor blamed its bank, the creditor's bank blamed the clearing system, the clearing system pointed to the debtor's bank, and the debtor's bank said the mandate was the creditor's problem. Each party was partly right, and nobody owned the end-to-end outcome.\n\nThe four-corner model gives each party a defined corner and a defined responsibility. The creditor owns the mandate, the pre-notification and the collection instruction. The creditor PSP receives the collection, validates it and submits it into the clearing system. The clearing and settlement mechanism moves the collection between the banks and settles the interbank positions. The debtor PSP receives the collection, checks the debtor account and debits it on the due date, and the debtor is the account holder whose funds are collected. A failure at any corner has a different owner, a different message and a different remedy, and the analyst must be able to map each failure to its corner.\n\nThe learning goal is practical: given a failed or disputed collection, the learner should be able to name the corner where it failed, the message that carried it there, and the party that must act. Without that map, every exception becomes a round of blame between teams that each see only their own corner.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Tell the customer to ask their bank for a refund and close the case."}, {"id": "B", "text": "Trace the collection from the creditor corner: check the mandate, the billing generation and the file sent to the creditor PSP, then follow the instruction through each corner with its references."}, {"id": "C", "text": "Ask the clearing system to reverse both collections immediately."}, {"id": "D", "text": "Assume the debtor PSP debited twice and demand it fixes the account."}], "scenario": "You are the business analyst for Harbour Energy. A customer's direct debit collection was debited twice in one month. The customer complains to Harbour Energy. The billing team blames the creditor PSP, the PSP blames the clearing system, and the debtor PSP says it only followed the instruction it received. You must decide where to start the investigation.", "why": "Option B is correct because the four-corner model makes the creditor corner the starting point: the duplicate was most likely generated in billing or in the file, and tracing the instruction reference through each corner identifies where the second collection entered. Option C asks the clearing system to fix a problem it did not create. Option A hands the customer to another party without establishing the facts. Option D blames the debtor PSP before any evidence shows it created the duplicate."}, "recommended_solution": "Teach and document the model as a responsibility map, not as a diagram to memorise. For each corner, record who the party is, what they own, which message they send and receive, and what they must do when something fails. The creditor owns the mandate, the pre-notification, the collection instruction and the billing generation, and must be able to prove the mandate and the notice. The creditor PSP owns intake validation, submission timing and the interbank message, and must check the mandate reference and the collection details before submitting. The clearing and settlement mechanism owns routing between PSPs and interbank settlement, and must be able to show whether a collection was delivered and settled. The debtor PSP owns the debtor account check, the debit on the due date and the return or refund handling, and the debtor owns the mandate consent and the right to dispute.\n\nApply the map to every exception type. A missing mandate is a creditor-corner failure. A late submission is a creditor PSP failure. A collection that never arrives is a clearing question. A debit from a closed account is a debtor PSP return. A duplicate is usually a creditor-corner generation failure, and the proof is in the file and the instruction references. For each type, define the evidence that proves the corner, the message that carries the instruction, and the remedy that belongs to that corner.\n\nFinally, make the model operational. Every collection must carry references that survive all four corners, so an investigation can follow one identifier from billing to ledger. The Operations runbook should start every investigation with the same question: which corner, which message, which reference, and which party owns the next action. Review the map whenever a new exception type appears, and add it to the runbook with its corner and remedy.", "flow_steps": [{"action": "Signs the mandate authorising Harbour Energy to collect", "actor": "Debtor (customer)", "step": 1, "system": "Mandate capture service"}, {"action": "Sends the pre-notification and generates the collection instruction", "actor": "Creditor (Harbour Energy)", "step": 2, "system": "Billing system"}, {"action": "Validates the collection and submits it to the clearing system", "actor": "Creditor PSP", "step": 3, "system": "Creditor PSP platform"}, {"action": "Routes the collection to the debtor PSP and settles the interbank position", "actor": "Clearing and settlement mechanism", "step": 4, "system": "Clearing system"}, {"action": "Checks the debtor account and debits it on the due date", "actor": "Debtor PSP", "step": 5, "system": "Debtor PSP platform"}, {"action": "Returns a status or a return where the debit cannot be made", "actor": "Debtor PSP", "step": 6, "system": "Debtor PSP platform"}, {"action": "Routes the return or status back to the creditor PSP", "actor": "Clearing and settlement mechanism", "step": 7, "system": "Clearing system"}, {"action": "Receives the outcome, reconciles it and notifies or follows up with the debtor as needed", "actor": "Creditor PSP and creditor", "step": 8, "system": "Creditor PSP platform and billing system"}], "happy_path": "The debtor signs a mandate, the creditor sends the pre-notification and generates a valid collection, the creditor PSP validates and submits it, the clearing system routes and settles it, and the debtor PSP debits the account on the due date. Each corner performs its own responsibility, the references survive the whole path, and the collection reconciles at the creditor.", "negative_paths": [{"handling": "The creditor PSP validation should block it, and the creditor must obtain or repair the mandate. The debtor PSP is not the owner of this failure.", "path": "Mandate missing at the creditor corner", "trigger": "The creditor generates a collection with no valid mandate"}, {"handling": "Trace the instruction reference through the creditor PSP submission log and the clearing receipt, and resubmit or investigate from the corner where the trail stops.", "path": "Collection never reaches the debtor PSP", "trigger": "The collection is lost or delayed between the creditor PSP and the clearing system"}, {"handling": "The debtor PSP returns the collection with the applicable reason code, the creditor PSP routes the return to the creditor, and the creditor follows up with the debtor.", "path": "Debtor account cannot be debited", "trigger": "The account is closed or has insufficient funds on the due date"}, {"handling": "Identify the duplicate by instruction reference at the creditor PSP, block the second submission, and reverse or refund the duplicate debit under the applicable process if it already settled.", "path": "Duplicate collection from the creditor corner", "trigger": "Billing generates the same collection twice"}], "technical_data": "Carry a single end-to-end reference and the mandate reference through all four corners, so any party can trace a collection from billing to ledger. Each corner must log its own receipt, validation result, submission and settlement events with timestamps, so the trail shows where the instruction stopped. Keep the mandate data with the creditor and the account data with the debtor PSP, and pass only the data each corner needs in the interbank message. Use the scheme's status and return messages to communicate outcomes between corners rather than informal emails. Design the investigation view to show all four corners for one collection on a single screen, with the status at each corner.", "messages_fields": [{"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account IBAN and name", "Instructed amount and due date"], "message": "pain.008", "purpose": "Creditor to creditor PSP collection file, from the creditor corner to its PSP"}, {"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account and instructed amount", "Due date and sequence type"], "message": "pacs.003", "purpose": "Interbank direct debit collection from creditor PSP through the clearing system to the debtor PSP"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code"], "message": "pacs.002", "purpose": "Payment status report between PSPs for acceptance or rejection"}, {"key_fields": ["Original instruction identification and return reason code", "Returned amount"], "message": "pacs.004", "purpose": "Payment return from the debtor PSP for a collection that cannot be debited"}], "accounting_operational": "Each corner posts its own accounting: the creditor PSP credits the creditor on settlement and the debtor PSP debits the debtor on the due date, with the clearing system settling the interbank positions between them. A return reverses the flow as a separate linked event at the corner that initiates it, so the original collection is never deleted. Operations at each corner works from its own worklist, but an end-to-end investigation needs the shared references to connect them. Reconciliation at the creditor matches collections, settlements and returns by instruction reference, and any collection that is missing from the clearing settlement is escalated as a break with the corner identified.", "gherkin": ["Given a collection generated by the creditor", "When it is submitted to the creditor PSP", "Then the creditor PSP validates the mandate reference before sending it to the clearing system", "Given a collection that the debtor PSP cannot debit", "When the debtor PSP returns it", "Then the return is routed through the clearing system to the creditor PSP with the applicable reason code", "Given a duplicate collection generated in billing", "When the second instruction reaches the creditor PSP", "Then it is identified by its instruction reference and blocked from submission", "Given a disputed collection", "When an investigation starts", "Then the trail shows the status at each of the four corners under one end-to-end reference"], "assessment": [{"answer": 0, "explanation": "The creditor obtains the mandate from the debtor, holds the evidence, and is responsible for validating collections against it.", "options": ["The creditor", "The debtor PSP", "The clearing system", "The debtor's employer"], "question": "Which party owns the mandate in the four-corner model?"}, {"answer": 3, "explanation": "The clearing system moves the collection between the creditor PSP and the debtor PSP and settles the interbank positions. It does not own the mandate or the customer accounts.", "options": ["The debtor's account balance", "The creditor's billing generation", "The mandate evidence", "Routing the collection between PSPs and settling the interbank positions"], "question": "What does the clearing and settlement mechanism own?"}, {"answer": 0, "explanation": "A duplicate is usually generated in billing or in the file at the creditor corner. Tracing the instruction reference from there shows where the second collection entered.", "options": ["At the creditor corner, checking billing generation and the file sent to the creditor PSP", "At the debtor PSP", "At the clearing system", "By asking the customer to prove it"], "question": "A collection is debited twice. Where should the investigation start?"}, {"answer": 2, "explanation": "pain.008 is the creditor-to-PSP file. pacs.003 is the interbank direct debit collection that travels from the creditor PSP through clearing to the debtor PSP.", "options": ["pacs.008", "pain.008", "pacs.003", "camt.053"], "question": "Which message carries the collection between the PSPs?"}, {"answer": 2, "explanation": "The debtor PSP owns the debtor account check and the debit. When the debit cannot be made, it returns the collection with the applicable reason code.", "options": ["The creditor", "The clearing system", "The debtor PSP, with the applicable return reason code", "The creditor PSP"], "question": "A debtor account is closed on the due date. Which corner returns the collection?"}]}}, {"id": "INS-126", "kind": "insight", "title": "Pre-notification versus collection submission", "topic": "Pre-notification versus collection submission", "theme": "SEPA Direct Debit", "text": "Separate customer notice timeline from creditor PSP file submission and scheme processing.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}, "case": {"status": "authored", "business_problem": "Harbour Energy sends its monthly direct debit collections on the 25th of each month, and the billing team has always assumed that generating the collection file is the same as notifying the customer. In March, a billing change moved 8,000 customers to a new tariff, changing their collection amounts, but the pre-notification emails for the new amounts were never sent because the notification job failed silently. The collections were submitted on time and debited on the due date, and hundreds of customers complained that money had been taken without warning at an amount they did not expect. Several demanded refunds, and the customer service team had no evidence that any notice had been sent.\n\nPre-notification and collection submission are two different obligations on two different timelines. Pre-notification is the creditor telling the debtor, at the latest 14 calendar days before the due date, what will be collected and when, or a different period where the mandate or agreement validly provides for one. Collection submission is the creditor PSP sending the collection into the interbank chain, and for SDD Core the submission deadline is D-1, one Inter-PSP Business Day before the due date. A file can be submitted perfectly on D-1 and still be wrong, because the debtor was never told.\n\nHarbour Energy needs to separate the two timelines in its systems and its controls: a notification step with its own content, date and delivery evidence, and a submission step with its own deadline, each checked independently before the collection proceeds. A change to the amount or the date restarts the notification question, and a missing notice must delay the collection rather than be discovered after the debit.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Submit the file on D-1 as planned and send the notices after the debit, since the submission deadline is the one that matters."}, {"id": "B", "text": "Hold the affected collections, send the pre-notifications with the correct amounts, and reschedule the collections to a due date that respects the notice period."}, {"id": "C", "text": "Submit the file without any notice and offer refunds to anyone who complains."}, {"id": "D", "text": "Submit the file and reduce the amounts back to the old tariff so the old notice still applies."}], "scenario": "You are the business analyst for Harbour Energy. A tariff change alters collection amounts for 8,000 customers, but the pre-notification emails for the new amounts were never sent because the notification job failed silently. The collection file is ready for submission on D-1. The billing manager wants to submit it on time and send the notices afterwards. What do you recommend?", "why": "Option B is correct because pre-notification is a separate obligation from submission: the debtor must be told at the latest 14 calendar days before the due date, and a changed amount needs a new notice. Submitting on D-1 does not cure a missing notice. Option A debits customers without warning. Option D changes the billing to fit a failed process. Option C collects without authority and creates refund volumes."}, "recommended_solution": "Separate the two timelines in the design, in the data and in the controls. The pre-notification step records the content, the amount, the due date, the channel, the date sent and the delivery evidence for each debtor, and it is checked against the rule that notice must be given at the latest 14 calendar days before the due date, or within any different period validly agreed in the mandate. The submission step records the file generation date, the validation result and the submission to the creditor PSP against the D-1 deadline, one Inter-PSP Business Day before the due date. Neither step may be treated as proof of the other.\n\nBuild a gate between them. A collection becomes eligible for submission only when both conditions are true: the notice for that exact amount and due date has been sent and evidenced, and the submission deadline can still be met. If the amount or the due date changes after the notice was sent, the notice is no longer valid for the changed collection and a new notice is required, unless a validly agreed arrangement covers the change. If the notification job fails, the collections it covered are held automatically, and the failure alerts Operations instead of failing silently.\n\nFinally, keep the evidence where a dispute can find it. Store the notice content, date and delivery evidence alongside the mandate and the collection, so a customer who disputes a debit can be shown exactly what they were told and when. Report monthly on notice failures, late notices and collections delayed for notice reasons, and treat a silent notification failure as an incident, with a fix and a control that proves the job ran and delivered.", "flow_steps": [{"action": "Calculates the monthly amount and due date for each customer", "actor": "Harbour Energy billing", "step": 1, "system": "Billing system"}, {"action": "Sends the pre-notification with the amount and due date at the latest 14 calendar days before the due date, and records delivery evidence", "actor": "Notification service", "step": 2, "system": "Notification service"}, {"action": "Checks that a valid notice exists for the exact amount and due date before generating the collection", "actor": "Harbour Energy billing", "step": 3, "system": "Billing system"}, {"action": "Generates the collection file for items that pass the notice and mandate checks", "actor": "Harbour Energy", "step": 4, "system": "Billing system"}, {"action": "Validates the file and submits the collections by the D-1 deadline", "actor": "Creditor PSP", "step": 5, "system": "Creditor PSP platform"}, {"action": "Routes the collections to the debtor PSPs", "actor": "Clearing system", "step": 6, "system": "Clearing system"}, {"action": "Debits the debtor account on the due date", "actor": "Debtor PSP", "step": 7, "system": "Debtor PSP platform"}, {"action": "Reconciles collections against notices, mandates and settlements", "actor": "Harbour Energy", "step": 8, "system": "Reconciliation service"}], "happy_path": "Billing calculates the amount, the pre-notification is sent at the latest 14 calendar days before the due date with the correct amount and date, and delivery evidence is recorded. The collection passes the notice and mandate checks, is submitted by D-1, and is debited on the due date. The customer recognises the amount, and the collection reconciles cleanly.", "negative_paths": [{"handling": "Hold the affected collections automatically, alert Operations, fix the job, send the notices, and reschedule the collections to a due date that respects the notice period.", "path": "Notification delivery failure", "trigger": "The notification job fails silently and notices are never sent"}, {"handling": "Treat the old notice as invalid for the changed collection, send a new notice with the new amount, and reschedule the collection if the notice period cannot be met.", "path": "Changed amount or date after notice", "trigger": "A tariff change alters the amount after the notice was sent"}, {"handling": "Produce the stored notice content, date and delivery evidence. If the evidence is missing or wrong, handle the collection under the applicable refund or return process and fix the evidence gap.", "path": "Customer disputes the notice", "trigger": "A debtor says they were not notified or were told a different amount"}, {"handling": "Move the due date rather than submitting late or skipping the notice. Tell the customer the revised due date in the notice itself.", "path": "Submission deadline missed while waiting for notice", "trigger": "The notice period pushes the due date later than planned"}], "technical_data": "Model pre-notification as its own entity linked to the mandate and the collection, with fields for content, amount, due date, channel, sent timestamp and delivery evidence. Model submission as a separate event with its own timestamp and D-1 deadline check, computed against the Inter-PSP Business Day calendar. Gate collection generation on both conditions, and never let a submission event imply a notice event. If the amount or due date changes, version the notice and require a new one for the changed collection. Monitor the notification job with a success and delivery confirmation, not just a run log, so a silent failure is detected the same day. Keep the notice, the mandate version and the collection linked by correlation IDs.", "messages_fields": [{"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account IBAN and name", "Instructed amount and due date, matching the amount and date in the pre-notification"], "message": "pain.008", "purpose": "Customer direct debit initiation file carrying the collections to the creditor PSP after the notice gate has passed"}, {"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account and instructed amount", "Due date and sequence type"], "message": "pacs.003", "purpose": "Interbank direct debit collection from the creditor PSP to the debtor PSP"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code"], "message": "pacs.002", "purpose": "Payment status report for acceptance or rejection of the collection"}], "accounting_operational": "A collection held for a missing notice never posts, so it appears in the held-items worklist rather than in the ledger, and the billing forecast must show the delayed cash separately from the collected cash. A collection debited without a valid notice may be refunded, and the refund is posted as a separate linked event with the reason recorded. Operations works from a notice-exception worklist with SLA targets for re-issue and rescheduling, and Finance tracks the value and volume of collections delayed for notice reasons each month. Customer service uses the stored notice evidence to answer disputes, and a dispute that cannot be evidenced is escalated to the mandate owner.", "gherkin": ["Given the required notice period has not elapsed for a collection", "When collection eligibility is checked", "Then the collection is delayed or handled under a documented exception", "Given a collection whose amount changed after the notice was sent", "When eligibility is checked", "Then a new pre-notification is required before the collection can proceed", "Given a notification job that fails to deliver", "When the job completes", "Then the affected collections are held and Operations is alerted the same day", "Given a collection submitted by the D-1 deadline", "When the notice evidence is checked", "Then submission alone is not accepted as proof that the debtor was notified"], "assessment": [{"answer": 1, "explanation": "Pre-notification must be given at the latest 14 calendar days before the due date, or within any different period validly agreed in the mandate. Submission timing does not replace it.", "options": ["On the due date", "At the latest 14 calendar days before the due date, unless a different period is validly agreed", "One business day before the due date", "After the collection is submitted"], "question": "What is the latest point at which pre-notification must be given for an SDD collection?"}, {"answer": 2, "explanation": "The SDD Core submission deadline is D-1, one Inter-PSP Business Day before the due date. D-2 is outdated and must not be taught.", "options": ["D-2", "The due date itself", "D-1, one Inter-PSP Business Day before the due date", "14 calendar days before the due date"], "question": "What is the SDD Core collection submission deadline?"}, {"answer": 0, "explanation": "The notice must match the collection. A changed amount needs a new notice, and the collection must be rescheduled if the notice period cannot be met.", "options": ["A new pre-notification with the new amount before the collection proceeds", "A phone call after the debit", "Nothing, the old notice still covers it", "A smaller collection to match the old notice"], "question": "A tariff change alters the collection amount after the notice was sent. What is required?"}, {"answer": 0, "explanation": "A run log proves the job started, not that notices arrived. Delivery confirmation is what detects a silent failure before collections are debited.", "options": ["Because a job can run and still fail to deliver, and a silent failure leaves customers uninformed", "Because the job is slow", "Because delivery evidence is optional", "To save storage"], "question": "Why must the notification job's delivery be monitored, not just its run?"}, {"answer": 2, "explanation": "Submission is the creditor PSP sending the collection into the interbank chain. Notification is the creditor telling the debtor. Each needs its own evidence.", "options": ["Yes, if the file was generated on time", "Yes, submission is notification", "No, submission and notification are separate obligations with separate evidence", "Only for small amounts"], "question": "Does submitting the collection file on time prove the debtor was notified?"}]}}, {"id": "INS-127", "kind": "insight", "title": "Participant calendars and TARGET/CSM closure", "topic": "Participant calendars and TARGET/CSM closure", "theme": "SEPA Direct Debit", "text": "Calculate processing using creditor PSP, debtor PSP and infrastructure business calendars.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch44s2", "title": "Cut-Off Management and Processing Calendars", "url": "lessons/ch44s2"}, "case": {"status": "authored", "business_problem": "Harbour Energy collects monthly direct debits from customers across several SEPA countries, and the billing team plans its collections on a single calendar: the creditor's own business calendar. In a recent month, a collection due on a public holiday in the debtor's country was debited a day late, and another collection due on a day the clearing system was closed was submitted on the wrong day and rejected. The billing team assumed that one calendar, the creditor's, governed every milestone. It does not. The submission deadline, the inter-PSP settlement date and the debtor debit date are each governed by a different calendar, and each participant can be closed on a different day.\n\nThe calendars in play are the creditor PSP's business calendar, the debtor PSP's business calendar, the clearing and settlement mechanism's calendar, and the TARGET calendar for euro settlement. A date that is a business day for the creditor PSP may be a holiday for the debtor PSP, and a date that is a business day for both PSPs may be a day when the clearing system is closed. SDD Core uses the Inter-PSP Business Day definition, and the submission deadline of D-1 is one Inter-PSP Business Day before the due date, so the calculation depends on which days count as business days for the participants involved.\n\nHarbour Energy needs a date-calculation service that applies the right calendar to each milestone, retains the calendar version used, and moves due dates and submission dates explicitly when a calendar makes the planned date invalid, rather than letting the payment fail at the clearing system or debit late without explanation.", "decision_exercise": {"correct_option": "D", "options": [{"id": "A", "text": "Ask the debtor PSPs to stay open on their national holidays."}, {"id": "B", "text": "Move all collections to the first business day of the month to avoid holiday calculations."}, {"id": "C", "text": "Keep using the creditor's calendar for all milestones and let any failures be handled as exceptions."}, {"id": "D", "text": "Calculate each milestone against its governing calendar, retain the calendar version used, and adjust due and submission dates explicitly where a planned date is invalid."}], "scenario": "You are the business analyst for Harbour Energy. Collections are planned on the creditor's calendar only. A collection due on a holiday in the debtor's country debited late, and another was rejected because the clearing system was closed on the planned submission day. The operations director asks for your recommendation.", "why": "Option D is correct because each milestone has its own governing calendar, and only a per-milestone calculation with a retained calendar version produces correct submission, settlement and debit dates. Option C guarantees repeat failures. Option B moves every collection and breaks the customers' billing expectations. Option A is not within the creditor's control."}, "recommended_solution": "Build a calendar service that holds separate calendars for the creditor PSP, the debtor PSP, the clearing and settlement mechanism and TARGET, each versioned with effective dates. For every collection, the service calculates each milestone against its governing calendar: the submission date from the D-1 Inter-PSP Business Day rule, the inter-PSP settlement date from the clearing calendar, and the debtor debit date from the debtor PSP calendar. The calculation records the calendar version used, so any date can be reproduced and audited later.\n\nApply explicit adjustment rules and communicate the result. When a planned due date is not a business day for the relevant participant, move the date under the scheme's adjustment rule and tell the customer the revised date in the pre-notification, so the customer is never surprised by a debit on a different day. When a calendar is updated after scheduling, recheck every scheduled collection against the new version and report what changed. Never use one generic bank-holiday calendar for the whole chain, because that is the error that caused the late debit and the rejected submission.\n\nTest the service with a calendar matrix: a collection due on a creditor holiday, a debtor holiday, a clearing closure, and a date that is valid everywhere, plus a calendar update published after scheduling. For each case, assert the submission date, the settlement date and the debit date, and assert that the customer notice and the ledger both show the adjusted dates.", "flow_steps": [{"action": "Plans the monthly collection with a planned due date", "actor": "Harbour Energy billing", "step": 1, "system": "Billing system"}, {"action": "Calculates the submission date, settlement date and debit date using the governing calendar for each milestone", "actor": "Calendar service", "step": 2, "system": "Calendar and scheduling service"}, {"action": "Adjusts the due date where the planned date is not a business day for the relevant participant", "actor": "Calendar service", "step": 3, "system": "Calendar and scheduling service"}, {"action": "Generates the collection file with the adjusted dates", "actor": "Harbour Energy", "step": 4, "system": "Billing system"}, {"action": "Validates the file and submits it by the D-1 deadline computed on the Inter-PSP Business Day calendar", "actor": "Creditor PSP", "step": 5, "system": "Creditor PSP platform"}, {"action": "Routes the collection and settles the interbank position on a day the clearing system is open", "actor": "Clearing system", "step": 6, "system": "Clearing system"}, {"action": "Debits the debtor account on the due date under the debtor PSP calendar", "actor": "Debtor PSP", "step": 7, "system": "Debtor PSP platform"}, {"action": "Reconciles collections against the adjusted dates and the calendar version used", "actor": "Harbour Energy", "step": 8, "system": "Reconciliation service"}], "happy_path": "The planned due date is checked against the creditor PSP, clearing and debtor PSP calendars, the submission date is calculated as D-1 on the Inter-PSP Business Day calendar, and the settlement and debit dates satisfy their governing calendars. The collection is submitted on time, settles on the planned day and is debited on the due date, with the calendar version used recorded for audit.", "negative_paths": [{"handling": "Recheck all scheduled collections against the new calendar, adjust the affected dates, and notify the affected customers of any revised due date.", "path": "Unexpected national holiday", "trigger": "A holiday is declared after collections have been scheduled"}, {"handling": "Store the calendar version with every calculation, and re-run the calculation when a new version is published, with a report of what changed.", "path": "Calendar update after scheduling", "trigger": "The clearing system publishes a revised calendar and previously valid dates are no longer valid"}, {"handling": "Use the governing calendar for each milestone rather than a single timezone, and state the date and the timezone in every customer-facing message.", "path": "Timezone boundary", "trigger": "A due date falls on different calendar days for participants in different timezones"}, {"handling": "Hold the collection to the next valid submission day, recalculate the due date, and tell the customer the revised date rather than submitting on a closed day.", "path": "Submission day falls on a clearing closure", "trigger": "The planned submission date is a day the clearing system is closed"}], "technical_data": "Hold each participant calendar as a versioned data set with effective dates, and never merge them into one generic holiday list. Store the calendar version alongside every date calculation so the result is reproducible. Compute dates per milestone against the governing calendar, and keep the original planned date, the adjusted date and the adjustment reason in the record. Use correlation IDs to link the calendar calculation, the collection instruction, the interbank message and the ledger entry. Schedule a recheck job that runs whenever a calendar version is published, and report the collections it changes. Test with a calendar matrix covering creditor, debtor and clearing closures, timezone boundaries and post-scheduling updates.", "messages_fields": [{"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account IBAN and name", "Instructed amount and due date, as adjusted for the governing calendars"], "message": "pain.008", "purpose": "Customer direct debit initiation file carrying the collections with the adjusted due dates"}, {"key_fields": ["Mandate identification", "Debtor account and instructed amount", "Due date and sequence type", "Interbank settlement date, computed on the clearing calendar"], "message": "pacs.003", "purpose": "Interbank direct debit collection from the creditor PSP to the debtor PSP"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code where a calendar problem causes rejection"], "message": "pacs.002", "purpose": "Payment status report for acceptance or rejection of the collection"}], "accounting_operational": "A collection whose due date is moved because of a calendar difference is value-dated on the adjusted date, and the ledger must reflect the adjusted date, not the originally planned one. Collections that cannot settle on the planned date are reported as calendar-held items, and the customer statement shows the actual debit date. Operations works from a calendar-exception worklist, and Finance tracks the value of collections rescheduled for calendar reasons each month. A settlement that was expected on a day the clearing system was closed must be reconciled against the next settlement date, with the break explained as a calendar difference rather than a missing payment.", "gherkin": ["Given different calendars for creditor PSP, clearing system and debtor PSP", "When dates are calculated", "Then each milestone uses its governing calendar", "Given a planned due date that is a holiday for the debtor PSP", "When the collection is scheduled", "Then the due date is adjusted and the customer is told the revised date", "Given a calendar update published after scheduling", "When the update is applied", "Then collections already scheduled are rechecked against the new calendar", "Given a collection whose submission date falls on a day the clearing system is closed", "When the collection is submitted", "Then it is held to the next valid submission day and the due date is recalculated"], "assessment": [{"answer": 2, "explanation": "Each milestone has its own governing calendar. The submission deadline uses the Inter-PSP Business Day definition, settlement uses the clearing system calendar, and the debit uses the debtor PSP calendar.", "options": ["The creditor's calendar for every milestone", "The debtor's calendar for every milestone", "Each milestone uses its governing calendar: submission, settlement and debit are calculated separately", "No calendar is needed, dates are always valid"], "question": "Which calendar controls submission, settlement and debtor debit?"}, {"answer": 3, "explanation": "D-1 means one Inter-PSP Business Day before the due date, so the calculation depends on which days are Inter-PSP Business Days for the participants involved.", "options": ["Two calendar days before the due date", "The due date itself", "One week before the due date", "One Inter-PSP Business Day before the due date"], "question": "How is the SDD Core submission deadline D-1 calculated?"}, {"answer": 2, "explanation": "A holiday announced after scheduling can invalidate a planned date. Scheduled collections must be rechecked so the due date and submission date are still valid.", "options": ["Collect a day early without telling anyone", "Ignore it, since the dates are already fixed", "Recheck all scheduled collections against the new calendar and adjust dates where needed", "Cancel all collections"], "question": "What should happen when a calendar is updated after collections are scheduled?"}, {"answer": 2, "explanation": "The calendar version is part of the decision record. Without it, an auditor or an investigator cannot reproduce why a date was chosen.", "options": ["It is not needed", "Because calendars change daily", "So the date calculation can be reproduced and audited later", "To save storage"], "question": "Why must the calendar version used be retained?"}, {"answer": 3, "explanation": "A date that is valid for one participant can be a non-processing day for another, and the adjustment must be explicit so the customer and the ledger show the true date.", "options": ["Debit the customer a week early", "Submit it anyway and let it fail", "Ignore the debtor calendar", "Adjust the date explicitly, tell the customer the revised date, and record the adjustment"], "question": "A due date is a business day for the creditor PSP but a holiday for the debtor PSP. What should happen?"}]}}, {"id": "INS-128", "kind": "insight", "title": "Calendar days versus banking business days", "topic": "Calendar days versus banking business days", "theme": "SEPA Direct Debit", "text": "Use the correct calendar for pre-notification, refund and scheme timelines.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}}, {"id": "INS-129", "kind": "insight", "title": "Creditor PSP closed on due date", "topic": "Creditor PSP closed on due date", "theme": "SEPA Direct Debit", "text": "Determine how creditor-side processing constraints affect the normal timeline.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}}, {"id": "INS-130", "kind": "insight", "title": "Debtor PSP closed on due date", "topic": "Debtor PSP closed on due date", "theme": "SEPA Direct Debit", "text": "Assess whether debtor account debit can occur on the intended date and what moves.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}}, {"id": "INS-131", "kind": "insight", "title": "Clearing and settlement mechanism closed", "topic": "Clearing and settlement mechanism closed", "theme": "SEPA Direct Debit", "text": "Identify impact when PSPs are open but inter-PSP infrastructure is unavailable.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch18s1", "title": "What Settlement Means After Clearing", "url": "lessons/ch18s1"}, "case": {"status": "authored", "business_problem": "Harbour Energy's monthly direct debit collections are due on a day when the creditor PSP and the debtor PSP are both open, but the clearing and settlement mechanism is closed. The billing team asks why the collections cannot simply be submitted and settled anyway, since both banks are working. The answer is that the clearing system is the infrastructure between the banks: it routes the collections from the creditor PSP to the debtor PSP and settles the interbank positions. When it is closed, the banks can accept instructions and prepare files, but the interbank movement cannot happen, and a collection that depends on that movement cannot settle on the planned date.\n\nThe distinction matters because the customer experience is misleading. The creditor PSP can accept the file, the creditor can see it as submitted, and the debtor's bank can see the collection as expected, yet no funds move. If the platform reports the collection as settled because it was accepted, the creditor's cash forecast is wrong, the debtor may be debited on a different day from the one promised, and a return or refund that depends on settlement timing is calculated against the wrong date.\n\nHarbour Energy and its PSP need a design that distinguishes PSP availability from infrastructure availability, holds collections that cannot settle, and recalculates the due and settlement dates explicitly when the clearing system is closed, rather than letting the platform imply a settlement that never happened.", "decision_exercise": {"correct_option": "B", "options": [{"id": "A", "text": "Debit the debtors directly without the clearing system and settle the interbank positions later."}, {"id": "B", "text": "Hold the collections in a pending-settlement state, recalculate the settlement and debit dates, tell the creditor and debtor the revised dates, and submit when the clearing system reopens."}, {"id": "C", "text": "Submit the collections as planned and report them as settled, since both PSPs are open."}, {"id": "D", "text": "Cancel all collections for the month and ask customers to pay by another method."}], "scenario": "You are the business analyst for Meridian Bank's clearing operations. Harbour Energy's collections are due on a day when both PSPs are open but the clearing system is closed. The billing team wants the collections submitted and reported as settled anyway. The operations director asks for your recommendation.", "why": "Option B is correct because PSP availability is not infrastructure availability: the clearing system must route and settle the collections, so they must be held, recalculated and communicated honestly. Option C reports a settlement that never happened and corrupts the cash forecast. Option D cancels a month of collections for a one-day closure. Option A bypasses the clearing system and breaks the interbank settlement model."}, "recommended_solution": "Make infrastructure availability a first-class check, separate from PSP availability. Before a collection is submitted, the platform checks the clearing and settlement mechanism's calendar for the planned settlement date, and if the system is closed, the collection enters a pending-settlement state with a revised settlement date and a revised debit date. The revised dates are calculated against the governing calendars, and the creditor and the debtor are told the revised dates, so no one plans cash against a settlement that will not happen.\n\nKeep the states honest throughout. A collection that is accepted by the creditor PSP is not settled until the clearing system confirms settlement, and the status shown to the creditor, the debtor and Operations must say so. The ledger must not show an interbank settlement that has not occurred, and any customer debit that depends on the clearing settlement must wait for the settlement confirmation or be clearly marked as provisional.\n\nBuild the recovery into the design. On reopening, the held collections are submitted in a controlled order, reconciled against the clearing settlement report, and any missing item is escalated before the next cycle. Return and reversal windows are calculated from the actual settlement date, not the planned one. Report monthly on collections held for infrastructure closures, their value and their revised dates, so the business can see how often the constraint bites and whether the billing calendar should be planned around it.", "flow_steps": [{"action": "Generates the collection file for the planned due date", "actor": "Harbour Energy billing", "step": 1, "system": "Billing system"}, {"action": "Checks the clearing system calendar and finds it closed on the planned settlement date", "actor": "Creditor PSP", "step": 2, "system": "Creditor PSP platform"}, {"action": "Holds the collections in a pending-settlement state with a revised settlement date", "actor": "Creditor PSP", "step": 3, "system": "Creditor PSP platform"}, {"action": "Tells the creditor the revised settlement and debit dates", "actor": "Creditor PSP", "step": 4, "system": "Creditor PSP platform"}, {"action": "Submits the collections when the clearing system reopens", "actor": "Creditor PSP", "step": 5, "system": "Creditor PSP platform"}, {"action": "Routes the collections and settles the interbank positions", "actor": "Clearing and settlement mechanism", "step": 6, "system": "Clearing system"}, {"action": "Debits the debtor account on the revised due date", "actor": "Debtor PSP", "step": 7, "system": "Debtor PSP platform"}, {"action": "Reconciles the held collections against the settlement report", "actor": "Operations", "step": 8, "system": "Reconciliation service"}], "happy_path": "The creditor PSP checks the clearing calendar before submission, finds the closure, holds the collections with a revised settlement and debit date, and tells the creditor and the debtor the revised dates. When the clearing system reopens, the collections are submitted, routed, settled and debited on the revised dates, and the settlement reconciles cleanly.", "negative_paths": [{"handling": "Hold the collection in a pending-settlement state, recalculate the dates, tell the creditor and debtor, and do not report it as settled.", "path": "PSPs open but clearing closed", "trigger": "The planned settlement date is a clearing closure day"}, {"handling": "Recheck every held collection against the revised calendar, adjust the dates again, and notify the affected parties of the new dates.", "path": "Closure extended after scheduling", "trigger": "The clearing system announces an extended closure after collections were rescheduled"}, {"handling": "Calculate the window from the actual settlement date, and escalate any return that falls outside it for a decision rather than applying it automatically.", "path": "Return window miscalculated", "trigger": "A return is assessed against the planned settlement date instead of the actual one"}, {"handling": "Reconcile the held population against the settlement report on reopening, and investigate any item that is missing from the report before the next cycle.", "path": "Collection lost in the held queue", "trigger": "A held collection is not submitted when the clearing system reopens"}], "technical_data": "Model infrastructure availability as a calendar service separate from PSP availability, with the clearing system's open and closed days versioned and effective-dated. Model the collection state machine with an explicit pending-settlement state that is distinct from accepted and settled, and never let a transition to settled happen without a clearing settlement confirmation. Record the planned date, the revised date and the closure reason for every held collection. Use correlation IDs to link the held collection, its resubmission, the settlement report and the ledger entry. Reconcile the held population against the settlement report automatically on reopening, and alert on any item missing from the report. Calculate return and reversal windows from the actual settlement timestamp stored in the record.", "messages_fields": [{"key_fields": ["Mandate identification", "Creditor scheme identification", "Debtor account and instructed amount", "Due date, as revised for the clearing closure"], "message": "pacs.003", "purpose": "Interbank direct debit collection submitted when the clearing system reopens"}, {"key_fields": ["Original instruction identification", "Transaction status, pending settlement while the clearing system is closed", "Status reason code where applicable"], "message": "pacs.002", "purpose": "Payment status report showing the held or settled state of the collection"}, {"key_fields": ["Original instruction identification and return reason code", "Returned amount"], "message": "pacs.004", "purpose": "Payment return where a collection is returned after settlement"}], "accounting_operational": "Collections accepted while the clearing system is closed must not be assumed settled, so they are held in a pending-settlement state and the ledger shows no interbank settlement until the clearing system reopens and the settlement is confirmed. Any customer account debit that depends on the clearing settlement must wait for the settlement confirmation, or be clearly marked as provisional. Operations works from a clearing-closure worklist that lists every held collection with its revised settlement date, and Finance reconciles the held population against the clearing system's settlement report on reopening. A collection that misses its due date because of a closure is reported to the creditor with the revised date, and the customer is told the revised debit date where the debit itself moves.", "gherkin": ["Given the clearing system is closed on the planned settlement date while both PSPs are open", "When the collection is processed", "Then it is held in a pending-settlement state and not reported as settled", "Given the clearing system reopens", "When the held collections are submitted", "Then they settle on the revised date and reconcile to the settlement report", "Given a collection held because of a closure", "When the customer is notified", "Then the revised debit date is stated, not the original planned date", "Given a return that depends on settlement timing", "When the return window is calculated", "Then it is calculated from the actual settlement date, not the planned date"], "assessment": [{"answer": 3, "explanation": "The clearing system routes collections between PSPs and settles the interbank positions. When it is closed, that movement cannot happen even though both banks are open.", "options": ["The banks can settle directly without it", "Nothing, the collection settles anyway", "The debtor is debited twice", "The interbank movement and settlement cannot happen, so the collection cannot settle on the planned date"], "question": "What happens when the clearing system is closed but both PSPs are open?"}, {"answer": 3, "explanation": "Acceptance by a PSP and settlement through the clearing system are different states. Reporting a held collection as settled misstates the cash position and the return and refund timing.", "options": ["Because it looks better", "Because customers prefer it", "Because the ledger requires it", "Because acceptance and settlement are different states, and the cash forecast and return timing depend on the real settlement date"], "question": "Why must a held collection not be reported as settled?"}, {"answer": 2, "explanation": "The revised dates are the true dates. The customer and the creditor must be told them, so nobody plans against a date that will not happen.", "options": ["Do not tell anyone", "Cancel the collections", "State the revised settlement and debit dates to the creditor and the debtor", "Keep the original dates to avoid confusion"], "question": "What should the creditor and debtor be told when a closure moves the dates?"}, {"answer": 2, "explanation": "Return and reversal windows are counted from the settlement or due date. If the real date moves, the window moves with it.", "options": ["From the file generation date", "They do not depend on dates", "From the actual settlement date", "From the planned date"], "question": "From which date should return and reversal windows be calculated after a closure?"}, {"answer": 1, "explanation": "The D-1 deadline is calculated on Inter-PSP Business Days, so a closure changes which day counts and the submission date must be recalculated.", "options": ["Submit a day early without checking", "Recalculate the submission date against the Inter-PSP Business Day calendar", "Submit on the planned date anyway", "Ignore the closure"], "question": "How does a clearing closure affect the SDD Core D-1 submission deadline?"}]}}, {"id": "INS-132", "kind": "insight", "title": "Authorised SDD Core refund window", "topic": "Authorised SDD Core refund window", "theme": "SEPA Direct Debit", "text": "Teach the stated eight-week rule with current EPC rulebook and jurisdiction caveats.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}}, {"id": "INS-133", "kind": "insight", "title": "Unauthorised SDD claim window", "topic": "Unauthorised SDD claim window", "theme": "SEPA Direct Debit", "text": "Teach the stated 13-month period with precise legal and scheme caveats and current rulebook validation.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}}, {"id": "INS-134", "kind": "insight", "title": "Return, refund and reversal distinctions", "topic": "Return, refund and reversal distinctions", "theme": "SEPA Direct Debit", "text": "Differentiate business reason, initiating party, message, timing and ledger treatment.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s5", "title": "Rejects, Returns and Refunds: pacs.002, pacs.004 and the 8 Week Rule", "url": "lessons/ch62s5"}, "case": {"status": "authored", "business_problem": "Harbour Energy's customer service team receives three kinds of money-back request and treats them as the same thing: a return, a refund and a reversal. They are not the same, and confusing them costs the company money. A return is initiated by the debtor PSP, usually because the account cannot be debited, for example because the account is closed or the funds are insufficient, and it is carried by pacs.004. A refund is initiated by the debtor, who asks their bank to give the money back for an authorised collection under the scheme refund right. A reversal is initiated by the creditor, who has discovered an error after settlement and asks for the collection to be undone. Each has a different initiating party, a different message, different timing rules and different ledger treatment.\n\nThe timing rules are where the confusion is most expensive. For SDD Core, an authorised collection can be refunded on a no-questions-asked basis within 8 weeks of the debit date, and an unauthorised collection can be claimed within 13 months. SDD B2B has no authorised refund right at all, so a B2B debtor who asks for an authorised refund must be told that the right does not exist and given the correct alternative. The return windows differ too: B2B returns within D+3 Inter-PSP Business Days against Core D+5. A reversal is only possible from the settlement date and within 5 Inter-PSP Business Days following the due date. A team that applies the Core refund window to a B2B collection, or that treats a reversal as a refund, will pay money it did not need to pay or miss a deadline it should have met.\n\nHarbour Energy needs a decision framework that asks, for every money-back case: who initiated it, which scheme applies, when was the debit, was the collection authorised, and which mechanism is available. Only then can the team give the customer the right answer and post the right ledger entry.", "decision_exercise": {"correct_option": "C", "options": [{"id": "A", "text": "Refuse every money-back request to protect revenue."}, {"id": "B", "text": "Delete the original collection from the ledger and re-collect the correct amount."}, {"id": "C", "text": "Classify the case by initiating party and scheme, check authorisation and the applicable window, and process the valid mechanism as a separate linked event with the original collection intact."}, {"id": "D", "text": "Treat all three as refunds and pay every request within 13 months."}], "scenario": "You are the business analyst for Harbour Energy. A debtor asks for a refund of an authorised SDD B2B collection, a debtor PSP returns a Core collection for a closed account, and the billing team wants to reverse a settled collection a month after the due date. Customer service treats all three as the same kind of request. What framework do you recommend?", "why": "Option C is correct because it distinguishes the three mechanisms by initiating party and scheme, applies the correct window to each, and preserves the original collection as a financial record. Option D pays refunds that do not exist, since B2B has no authorised refund right, and ignores the different windows. Option A refuses valid claims. Option B deletes a financial record, which destroys the audit trail."}, "recommended_solution": "Start with a classification table that the customer service team can use on every case. The first question is who initiated it: the debtor PSP means a return, the debtor means a refund, the creditor means a reversal. The second question is the scheme: SDD Core or SDD B2B. The third is authorisation: was the collection authorised or not. The fourth is timing: the debit date for a refund, the due date for a reversal, and the return date for a return. With those four answers, the applicable mechanism and its window follow from the rules, and the team can give the customer a correct answer instead of a guess.\n\nTeach the windows as a table and keep it current against the rulebook. For SDD Core, an authorised refund is available no-questions-asked within 8 weeks of the debit date, and an unauthorised claim within 13 months. SDD B2B has no authorised refund right. Returns are within D+3 Inter-PSP Business Days for B2B and D+5 for Core. A reversal is only possible from the settlement date and within 5 Inter-PSP Business Days following the due date. The pacs.004 message is the SDD return message used for both returns and refunds, so the team must not assume that a pacs.004 always means the same kind of event.\n\nFinally, enforce the ledger discipline. Every money-back event is a separate linked transaction against the original collection, with the original instruction reference preserved, and the original collection is never deleted or altered. Keep separate worklists for returns, refunds and reversals, because each has its own deadlines and evidence needs, and reconcile each population separately. Report monthly on how many cases were classified correctly at first contact, how many were refused for the wrong reason, and how many missed a deadline, so the framework can be improved where it fails.", "flow_steps": [{"action": "Raises a money-back request, or identifies an error after settlement", "actor": "Debtor or creditor", "step": 1, "system": "Customer service or billing system"}, {"action": "Identifies the mechanism: return, refund or reversal, based on who initiated it and the scheme", "actor": "Customer service", "step": 2, "system": "Claims and exceptions workbench"}, {"action": "Validates the scheme, the collection date, authorisation status and the applicable deadline", "actor": "Claims service", "step": 3, "system": "Claims and exceptions workbench"}, {"action": "Checks the window: 8 weeks for an authorised Core refund, 13 months for an unauthorised claim, D+3 or D+5 for returns, 5 Inter-PSP Business Days after the due date for a reversal", "actor": "Claims service", "step": 4, "system": "Claims and exceptions workbench"}, {"action": "Rejects the request with the correct explanation if the window has passed or the right does not exist", "actor": "Customer service", "step": 5, "system": "Customer service"}, {"action": "Processes the valid return, refund or reversal as a separate linked event against the original collection", "actor": "Creditor PSP or debtor PSP", "step": 6, "system": "PSP platform"}, {"action": "Posts the linked accounting entries without altering the original collection", "actor": "Ledger service", "step": 7, "system": "Core ledger"}, {"action": "Reconciles the money-back event against the original collection and the clearing report", "actor": "Operations", "step": 8, "system": "Reconciliation service"}], "happy_path": "A money-back case is classified correctly by initiating party and scheme, the applicable window is checked against the debit or due date, and the valid mechanism is processed as a separate linked event with the original collection intact. The customer receives a clear outcome, and the ledger reconciles. A case that is out of time or has no right is refused with the correct explanation and the alternative offered.", "negative_paths": [{"handling": "Apply the correct rule for that scheme. For B2B, explain that no authorised refund right exists and offer the correct alternative, such as contacting the creditor.", "path": "Authorised refund requested on a B2B collection", "trigger": "A debtor asks for a refund of an authorised SDD B2B collection"}, {"handling": "Refuse the request with the correct explanation, record the decision, and offer the alternative that applies, for example a commercial goodwill gesture or a dispute with the creditor.", "path": "Request outside the applicable window", "trigger": "A refund or reversal is requested after its deadline has passed"}, {"handling": "Treat the claim as unauthorised, apply the 13-month window, investigate the authorisation evidence, and do not apply the 8-week authorised window to it.", "path": "Authorisation disputed", "trigger": "The debtor says the collection was never authorised"}, {"handling": "Apply the closed-account policy, route the funds to the approved suspense or unclaimed-funds process, and keep the funds traceable to the original collection.", "path": "Return for a closed account", "trigger": "A return arrives after the original customer account has been closed"}, {"handling": "Reject the duplicate, link it to the first reversal, and reconcile to a single posting.", "path": "Duplicate reversal", "trigger": "The same reversal is submitted twice for one original collection"}], "technical_data": "Model each money-back event as a separate linked transaction with its own type, return, refund or reversal, its initiating party, its scheme, its window and its deadline, all linked to the original collection by instruction reference. Store the debit date, the due date and the settlement date on the original collection, because each window is counted from a different one. Enforce the window rules in the claims service with effective-dated rule configuration, and never let a window be applied from the wrong scheme. Use pacs.004 for SDD returns and refunds, and camt.056 with camt.029 where a cancellation is the applicable mechanism, keeping the cancellation request separate from the original payment. Retain the classification decision, the evidence and the customer explanation in the audit record.", "messages_fields": [{"key_fields": ["Original instruction identification and return reason code", "Returned amount", "Reference to the original collection"], "message": "pacs.004", "purpose": "Payment return carrying a return or a refund-related return between PSPs, used for both returns and refunds in SDD"}, {"key_fields": ["Original instruction identification", "Transaction status", "Status reason code"], "message": "pacs.002", "purpose": "Payment status report for the outcome of the original collection and of the money-back event"}, {"key_fields": ["Original instruction identification", "Cancellation reason", "Reference to the original collection"], "message": "camt.056", "purpose": "Cancellation request where a cancellation, rather than a return or refund, is the applicable mechanism, paired with camt.029"}, {"key_fields": ["Original instruction identification", "Resolution status, accepted or rejected", "Reason where rejected"], "message": "camt.029", "purpose": "Resolution of an investigation, confirming whether a camt.056 cancellation request was accepted or rejected"}], "accounting_operational": "A return debits the creditor and credits the debtor's bank for the returned amount, a refund credits the debtor and is recovered from the creditor, and a reversal debits the creditor and credits the debtor, each as a separate linked event against the original collection. The original collection is never deleted or altered. Operations works from separate worklists for returns, refunds and reversals, because each has its own deadlines and evidence requirements, and Finance reconciles each population separately against the clearing and ledger reports. A refund paid outside its window, or a reversal submitted after its deadline, is rejected and escalated rather than posted silently.", "gherkin": ["Given an eligible authorised Core collection refund request within 8 weeks of the debit date", "When the claim is validated", "Then the bank applies the scheme-defined refund process", "Given an authorised B2B collection refund request", "When the claim is validated", "Then it is refused because SDD B2B has no authorised refund right, and the customer is told the correct alternative", "Given a settled collection eligible for reversal within 5 Inter-PSP Business Days following the due date", "When a valid reversal is submitted", "Then the reversal is linked to the original and posted once", "Given a return received for a closed account", "When posting is attempted", "Then the closed-account policy is applied and funds remain traceable"], "assessment": [{"answer": 2, "explanation": "A return is initiated by the debtor PSP, a refund is initiated by the debtor, and a reversal is initiated by the creditor. The initiating party is the first classification question.", "options": ["The amount", "The message format", "The initiating party", "The currency"], "question": "What is the first thing that distinguishes a return, a refund and a reversal?"}, {"answer": 1, "explanation": "An authorised SDD Core collection can be refunded no-questions-asked within 8 weeks of the debit date. An unauthorised claim has a 13-month window.", "options": ["D+5", "8 weeks from the debit date", "13 months", "5 business days"], "question": "Within what period can an authorised SDD Core collection be refunded without questions?"}, {"answer": 3, "explanation": "SDD B2B has no authorised refund right. The debtor must be told this and offered the correct alternative, such as raising the matter with the creditor.", "options": ["Treat it as a reversal", "Pay it under the Core rules", "Pay it after 13 months", "Refuse it, explaining that SDD B2B has no authorised refund right, and offer the correct alternative"], "question": "A debtor asks for a refund of an authorised SDD B2B collection. What should happen?"}, {"answer": 0, "explanation": "A reversal is only possible from the settlement date and within 5 Inter-PSP Business Days following the due date. After that, the reversal mechanism is unavailable.", "options": ["5 Inter-PSP Business Days following the due date", "13 months", "8 weeks", "D+3"], "question": "Within what window can a creditor reverse a settled SDD collection?"}, {"answer": 1, "explanation": "B2B returns are within D+3 Inter-PSP Business Days, while Core returns are within D+5. Applying the Core window to a B2B collection would be wrong.", "options": ["8 weeks for both", "D+3 for B2B against D+5 for Core", "D+5 for both", "D+3 for both"], "question": "How do the return windows differ between SDD B2B and SDD Core?"}]}}, {"id": "INS-135", "kind": "insight", "title": "Why cross-border payments remain slower than domestic instant payments", "topic": "Why cross-border payments remain slower than domestic instant payments", "theme": "Cross-Border Instant", "text": "Explain multiple PSPs, FX, compliance, settlement and operating-hour dependencies.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch16s1", "title": "Why cross border payments fail", "url": "lessons/ch16s1"}}, {"id": "INS-136", "kind": "insight", "title": "Euro leg versus non-euro leg", "topic": "Euro leg versus non-euro leg", "theme": "Cross-Border Instant", "text": "Separate OCT Inst coverage and non-euro corridor responsibilities; validate current scheme scope.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch16s1", "title": "Why cross border payments fail", "url": "lessons/ch16s1"}, "case": {"status": "authored", "business_problem": "Meridian Bank offers instant cross-border payments from Europe to a customer in India. A corporate customer, Aldergrove Manufacturing, pays a supplier in India and expects the payment to arrive instantly, because the euro leg is instant. The payment is accepted, the euro leg completes in seconds, and then nothing happens for hours. The supplier has not been credited, the customer asks where the money is, and the support team cannot answer, because it has been treating the payment as one instant payment rather than as two legs with different rules.\n\nThe distinction is the EPC One-Leg-Out Instant Credit Transfer, or OCT Inst. It covers the euro leg of a cross-border instant payment where one leg sits outside SEPA. The Rulebook 2025 version 1.1 is effective 5 October 2025. The euro leg follows the instant euro rules, including the 10-second execution maximum and Verification of Payee where it applies. The non-euro leg follows the destination corridor's own rules, its own timing, its own settlement arrangement and its own confirmation, and it is not instant simply because the euro leg is. The customer promise must be built from the slower leg, and the end-to-end state must be reported only when the required leg confirmations are received.\n\nMeridian Bank needs an orchestration model that treats each leg separately, with its own state, timeout and confirmation, and that reports the overall outcome honestly: the euro leg complete, the non-euro leg pending, or the payment failed with a defined compensation. The bank must not report end-to-end completion until the required confirmations arrive, and it must not resubmit blindly when a leg times out.", "decision_exercise": {"correct_option": "C", "options": [{"id": "A", "text": "Resubmit the payment immediately so the supplier is credited faster."}, {"id": "B", "text": "Refund the sender at once and cancel the payment."}, {"id": "C", "text": "Model each leg separately with its own state, timeout and confirmation, and report the true end-to-end state, including that the euro leg is complete and the non-euro leg is pending."}, {"id": "D", "text": "Tell the customer the payment is complete because the euro leg finished in seconds."}], "scenario": "You are the business analyst for Meridian Bank. A corporate customer pays a supplier in India and expects the payment to arrive instantly because the euro leg is instant. The euro leg completes in seconds, the supplier has not been credited hours later, and support cannot explain where the money is. What model do you recommend?", "why": "Option C is correct because OCT Inst covers only the euro leg, and the non-euro leg follows the destination corridor's own rules and timing, so each leg needs its own state, timeout and confirmation. Option D misleads the customer about a payment that has not completed end to end. Option A risks a duplicate payment. Option B refunds a payment that may still complete."}, "recommended_solution": "Model the payment as an orchestration with two legs, not as a single instant payment. The euro leg is covered by OCT Inst under Rulebook 2025 version 1.1, effective 5 October 2025, and it follows the instant euro rules, including the 10-second execution maximum. The non-euro leg follows the destination corridor's own rules, its own timing, its own settlement arrangement and its own confirmation. Each leg gets its own state machine, its own timeout and its own confirmation, and the overall orchestration state is reported only from the leg states, never assumed.\n\nDefine the customer promise from the slower leg. The customer must be told that the euro leg can complete in seconds while the destination credit follows the corridor's timing, and the status shown to the customer must name each leg's state, so a payment with a complete euro leg and a pending non-euro leg is shown exactly that way. End-to-end completion is reported only when the required leg confirmations are received. If a leg times out, the payment enters an unknown or investigation state, and it is not blindly resubmitted. Compensation or return follows the defined scheme and corridor rules, with exactly-once financial effect enforced by unique financial event IDs.\n\nKeep the cover and customer legs correlated but distinct. The pacs.009 cover leg and the pacs.008 customer leg can have different states, so a cover return must trigger an investigation of both legs before any customer adjustment is posted. Use the UETR and the end-to-end reference to link the legs across the corridor, and reconcile each leg separately against its own settlement report. Test the orchestration with the hard cases: destination timeout, late success after timeout, cover return with an unclear customer leg, and duplicate callbacks, and prove that each resolves to exactly one financial effect.", "flow_steps": [{"action": "Submits an instant cross-border payment from Europe to a supplier in India", "actor": "Aldergrove Manufacturing", "step": 1, "system": "Corporate banking portal"}, {"action": "Validates the instruction and splits it into a euro leg and a non-euro leg under one orchestration reference", "actor": "Cross-border orchestration service", "step": 2, "system": "Cross-border orchestration"}, {"action": "Executes the euro leg under OCT Inst, within the 10-second execution maximum", "actor": "Payment engine", "step": 3, "system": "Payment engine"}, {"action": "Confirms the euro leg and reports its state to orchestration", "actor": "Instant euro clearing", "step": 4, "system": "Instant clearing system"}, {"action": "Applies foreign exchange and prepares the non-euro leg under the corridor arrangement", "actor": "FX and settlement service", "step": 5, "system": "FX and settlement service"}, {"action": "Sends the non-euro leg to the destination system and awaits its confirmation", "actor": "Destination connector", "step": 6, "system": "Destination rail connector"}, {"action": "Reports end-to-end completion only when the required leg confirmations are received", "actor": "Cross-border orchestration service", "step": 7, "system": "Cross-border orchestration"}, {"action": "Posts the debit, the settlement entries and the credit, and reconciles each leg", "actor": "Ledger service", "step": 8, "system": "Core ledger"}], "happy_path": "The payment is split into its euro and non-euro legs under one orchestration reference. The euro leg executes under OCT Inst within the 10-second maximum, the non-euro leg completes under the corridor arrangement, and end-to-end completion is reported only when both required confirmations are received. The customer sees the true state at each stage, and the ledger reconciles leg by leg.", "negative_paths": [{"handling": "Keep the payment in an unknown or investigation state, do not resubmit blindly, and trigger the defined investigation or compensation process only under the agreed rules.", "path": "Destination timeout", "trigger": "The non-euro leg is sent but the destination system does not confirm beneficiary credit within the timeout"}, {"handling": "Establish whether the debit is provisional, final or held, then apply the scheme and corridor rules to decide whether to await confirmation, return funds or investigate, with exactly one financial effect.", "path": "Sender debited but no beneficiary credit", "trigger": "The sender's account is debited and the receiving system reports a technical failure or no final response"}, {"handling": "Resolve the race using the leg state and the unique financial event ID, so the beneficiary is credited once and the sender is not also refunded for the same payment.", "path": "Late success after timeout", "trigger": "A success confirmation arrives after the timeout and after a compensation has been started"}, {"handling": "Correlate the cover and the customer payment by stable references, determine the customer leg's state first, and do not assume the cover return defines the customer outcome.", "path": "Cover returned while customer leg unclear", "trigger": "The cover leg is returned but the underlying customer credit transfer has a different state"}, {"handling": "Do not resubmit. Use the original idempotency key and correlation ID to check the existing state, and only a governed replay under the defined rules may re-send a leg.", "path": "Duplicate callback", "trigger": "The destination system sends the same confirmation twice"}], "technical_data": "Model the payment as an orchestration with a leg-level state machine for the euro leg and the non-euro leg, plus an overall orchestration state derived from the legs. Use a single end-to-end reference and UETR where applicable across both legs, with separate leg identifiers for tracing. Apply the OCT Inst rules to the euro leg only, including the 10-second execution budget, and apply the corridor rules to the non-euro leg. Use idempotency keys per leg so a retry or a duplicate callback cannot create a second financial effect, and use unique financial event IDs for every debit, credit, compensation and return. Keep a durable event store of leg states, timeouts and confirmations, and design the investigation view to show both legs and the orchestration state on one screen.", "messages_fields": [{"key_fields": ["End-to-end identification carried across both legs", "Creditor account and agent", "Instructed amount and currency for the euro leg"], "message": "pacs.008", "purpose": "Interbank customer credit transfer for the euro leg of the cross-border payment"}, {"key_fields": ["End-to-end identification", "Creditor account and agent", "Cover amount and settlement details"], "message": "pacs.009", "purpose": "Financial institution credit transfer for the cover leg, including the COV variant where the underlying customer payment is linked"}, {"key_fields": ["Original instruction identification", "Transaction status per leg", "Status reason code"], "message": "pacs.002", "purpose": "Payment status report confirming each leg's state"}, {"key_fields": ["Original instruction identification and return reason code", "Returned amount"], "message": "pacs.004", "purpose": "Payment return where a leg is returned, including a cover-leg return"}], "accounting_operational": "The euro leg and the non-euro leg settle under different arrangements, so each leg has its own liquidity, settlement and reconciliation treatment. The euro leg settles through the instant euro infrastructure, while the non-euro leg settles under the corridor's own arrangement, and the overall customer transaction reconciles only when both legs are confirmed or when the defined compensation has been applied. Operations works from a leg-level worklist that shows each leg's state and age, and Treasury must hold liquidity for the euro leg and manage the foreign exchange and settlement risk on the non-euro leg. A failed non-euro leg after a successful euro leg creates a defined compensation or return obligation, and the accounting must show the compensation as a separate linked event, never as a silent reversal of the euro leg.", "gherkin": ["Given the originating euro leg is accepted but destination confirmation is absent", "When the timeout threshold is reached", "Then the payment enters an unknown or investigation state and is not blindly resubmitted", "Given a euro leg that completes under OCT Inst", "When the non-euro leg is still pending", "Then the customer is told the euro leg is complete and the non-euro leg is pending, not that the payment is complete", "Given a timeout followed by a late success on the non-euro leg", "When the late event is received", "Then the system resolves the transaction without both crediting the beneficiary and refunding the sender", "Given a cover leg return", "When the underlying customer payment status is unknown", "Then the bank investigates both legs before posting a customer adjustment"], "assessment": [{"answer": 3, "explanation": "OCT Inst covers the euro leg of a cross-border instant payment where one leg sits outside SEPA. The non-euro leg follows the destination corridor's own rules.", "options": ["Only the foreign exchange conversion", "The whole payment, including the non-euro leg", "Only domestic euro payments", "Only the euro leg, where one leg sits outside SEPA"], "question": "What does EPC OCT Inst cover?"}, {"answer": 0, "explanation": "The euro leg follows the instant euro rules, but the non-euro leg follows the destination corridor's timing and settlement. The overall promise must be built from the slower leg.", "options": ["The euro leg is instant, but the non-euro leg follows its own corridor rules and timing", "The euro leg is slow", "The payment is instant in both directions", "The whole payment is instant"], "question": "Why is an instant cross-border payment not instant end to end?"}, {"answer": 3, "explanation": "Reporting completion before the destination confirms it would mislead the customer and could lead to duplicate sending. The state must stay pending or unknown until confirmation arrives.", "options": ["Refund the sender at once", "Resubmit it immediately", "Report it as complete to keep the customer happy", "Keep it in a pending or unknown state and investigate under the defined timeout rules"], "question": "The euro leg is complete but destination confirmation is absent. What should the bank report?"}, {"answer": 3, "explanation": "A late success after a compensation would double-pay. The orchestration must resolve the race so exactly one financial effect results.", "options": ["Credit the beneficiary and refund the sender", "Ignore the late success", "Send the payment again", "Resolve the race so exactly one financial effect results, using the leg state and the unique financial event ID"], "question": "A late success arrives after a timeout and a compensation. What must the system do?"}, {"answer": 1, "explanation": "The cover leg and the customer leg can have different states. Each must be checked before any customer adjustment is posted.", "options": ["Assume the customer leg failed too", "Investigate both legs separately before posting a customer adjustment", "Ignore the cover return", "Refund the customer immediately"], "question": "A cover leg is returned but the customer leg status is unclear. What should happen?"}]}}, {"id": "INS-137", "kind": "insight", "title": "Clearing, processing and settlement efficiency", "topic": "Clearing, processing and settlement efficiency", "theme": "Cross-Border Instant", "text": "Identify which steps need to be optimised for an instant end-to-end experience.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch18s1", "title": "What Settlement Means After Clearing", "url": "lessons/ch18s1"}, "case": {"status": "authored", "business_problem": "Meridian Bank, a fictional retail and corporate bank, has launched an instant euro payment service for customers sending money to beneficiaries in another SEPA country. The customer promise is simple: the beneficiary is credited within seconds and the sender sees a confirmed outcome in the app. In practice the operations team sees a different picture. A material share of payments misses the 10 second execution limit for instant euro payments under Regulation (EU) 2024/886, and the customer channel shows a vague pending status while the back office is still working through sequential checks.\n\nThe payment journey is a chain of steps: channel capture, balance and limit checks, sanctions and fraud screening, Verification of Payee, FX or routing decisions where a leg sits outside SEPA, message construction, clearing submission, and settlement confirmation. Each step was built by a different team and each adds its own queue, timeout and retry. No single owner can see the elapsed time per step, so nobody can say which step is the bottleneck on a given corridor.\n\nThe commercial risk is direct. Customers compare the service with domestic instant payments and with rival cross-border services. When a payment is slow or its outcome is unclear, the bank faces complaints, duplicate instructions from customers who retry, and manual investigation work. The bank must identify which steps genuinely need to be optimised for an instant end to end experience, and which steps must stay synchronous even if they cost time.", "decision_exercise": {"scenario": "Meridian Bank measures its instant euro corridor and finds that 18 percent of payments breach the 10 second execution limit. Screening and Verification of Payee together consume most of the elapsed time, and clearing rejections arrive after the customer has already been told the payment was accepted. As the business analyst, you must recommend where to optimise first.", "options": [{"id": "A", "text": "Tell customers the payment is complete as soon as the channel accepts it, and reconcile any clearing failure later."}, {"id": "B", "text": "Add a larger retry loop at the clearing adapter so every rejected payment is resubmitted automatically until it succeeds."}, {"id": "C", "text": "Measure elapsed time per step, run independent checks in parallel with hard decision deadlines, keep mandatory screening synchronous, and separate channel acceptance from clearing acceptance in status and accounting."}, {"id": "D", "text": "Remove synchronous screening for low value payments so the 10 second limit is met, and run the checks after settlement."}], "correct_option": "C", "why": "Option C is correct because it attacks the real bottleneck with evidence, parallelises only what can safely run in parallel, preserves mandatory controls, and stops the channel overstating the outcome. Option D is wrong because mandatory sanctions and AML screening must never be bypassed to meet a speed target. Option A is wrong because channel acceptance is not clearing acceptance or settlement, and overstating completion creates duplicate instructions and mis-selling risk. Option B is wrong because blind resubmission can duplicate a payment and hides the root cause of the rejection."}, "recommended_solution": "Start with measurement, not with new technology. Instrument every step with a timestamp and a correlation ID so the bank can see elapsed time for capture, validation, screening, Verification of Payee, routing, message build, clearing submission and confirmation. Rank steps by their contribution to breaches of the 10 second limit and by how often they cause a failure, then optimise in that order. Steps that are independent, such as balance checks, fraud scoring and Verification of Payee, should run in parallel with a single synchronous decision deadline, so the slowest check sets the time rather than the sum of all checks.\n\nKeep mandatory controls synchronous and fail closed. If a sanctions service is unavailable and policy requires fail closed processing, the payment is held or rejected under the approved procedure, never released to meet the clock. Move only work that is legally and scheme permitted to post event monitoring, and document that split with risk appetite, service level agreements and audit evidence for every control.\n\nSeparate the customer instruction status from the clearing status and from settlement. The channel may confirm receipt and validation, but it must only report completion when the required clearing or rail confirmation has arrived. Translate every clearing rejection through a scheme specific reason code map into a controlled internal reason, reverse or release any reservation exactly once, and notify the channel with a plain language explanation.\n\nFinally, treat the clearing adapter as a governed boundary. Validate messages before submission, deduplicate status reports by message identity, reconcile every sent message against its acknowledgement and ledger entry, and put unmatched or late responses on an operational worklist with an ageing alert. Optimisation then becomes a repeatable loop: measure, fix the worst step, remeasure, and prove the improvement on the next reporting period.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits an instant euro payment in the mobile app with beneficiary, amount and purpose", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction, checks balance and limits, and assigns a correlation ID", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud checks and Verification of Payee in parallel under a single decision deadline", "system": "Screening services"}, {"step": 4, "actor": "Payment engine", "action": "Selects the route and builds the ISO 20022 payment message", "system": "Routing and message builder"}, {"step": 5, "actor": "Clearing adapter", "action": "Submits the message to the instant clearing system and records the submission timestamp", "system": "Scheme adapter"}, {"step": 6, "actor": "Clearing system", "action": "Processes the payment and returns an acceptance or rejection status", "system": "Instant clearing system"}, {"step": 7, "actor": "Payment engine", "action": "Posts settlement accounting on acceptance or reverses the reservation on rejection", "system": "Core ledger"}, {"step": 8, "actor": "Payment engine", "action": "Sends the final confirmed status and notification to the customer channel", "system": "Notification service"}], "happy_path": "The customer submits a valid instant euro payment. Balance, screening and Verification of Payee all pass within the decision deadline. The message is built and submitted to clearing, the clearing system accepts it, settlement completes within the 10 second execution limit, the ledger posts the debit and the settlement entry, and the customer sees a confirmed completion with the beneficiary name as verified.", "negative_paths": [{"path": "Screening timeout", "trigger": "A sanctions or fraud service does not respond within its deadline", "handling": "Apply the approved fail open or fail closed rule for that control, hold or reject explicitly, log the decision and evidence, and alert operations if the service stays unavailable."}, {"path": "Clearing rejection after channel acceptance", "trigger": "The clearing participant rejects the interbank message for a format, limit or eligibility reason", "handling": "Map the scheme reason code to a controlled internal reason, move the payment to a rejected state, release the reservation once, and notify the customer with a clear explanation and next step."}, {"path": "Duplicate status report", "trigger": "The clearing system sends the same status report twice", "handling": "Deduplicate by message identity and transaction reference, apply the status once, and suppress any duplicate ledger posting or customer notification."}, {"path": "Late confirmation", "trigger": "No clearing response arrives within the expected window", "handling": "Hold the payment in an unknown state, run a status enquiry by correlation ID, never resubmit blindly, and escalate to investigation if the outcome cannot be confirmed."}], "technical_data": "Persist a single correlation ID across channel, engine, screening, adapter and ledger, with a timestamp at each step for elapsed time analysis. Store screening decisions, Verification of Payee outcomes and reason codes as structured audit data, not free text. Make status handling idempotent by persisting inbound message IDs and processed outcomes, and enforce a state machine so a payment cannot regress from a later state to an earlier one. Validate message fields before submission, including structured or hybrid address data with at least Town Name and Country Code where required, and reject incomplete instructions at capture rather than at clearing. Keep customer instruction status, clearing status and settlement status as separate fields with an authoritative source defined for each transition.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer instruction sent to clearing and onward to the beneficiary bank", "key_fields": ["Instruction Identification and End to End Identification for correlation", "Debtor and creditor agent BICs", "Instructed amount and currency", "Creditor name and structured or hybrid address", "Remittance information for beneficiary reconciliation"]}, {"message": "pacs.002", "purpose": "Payment status report carrying clearing acceptance or rejection", "key_fields": ["Original instruction reference for correlation", "Status code accepted or rejected", "Reason code and additional information for the rejection map"]}, {"message": "camt.054", "purpose": "Debit or credit notification where the ledger needs a formal notification record", "key_fields": ["Account identification", "Amount and currency", "Related payment reference"]}], "accounting_operational": "On acceptance, debit the customer account and credit the settlement or clearing account for the payment amount, with fees posted as a separate entry so the principal is never obscured. On a clearing rejection, release any reservation exactly once and return the funds to the customer account, leaving the original instruction record immutable with a linked rejection event. Unmatched or late confirmations go to a suspense and investigation worklist, aged by elapsed time, with reconciliation between sent messages, acknowledgements and ledger entries run intraday. Service level agreements cover screening service availability, clearing response time and investigation ageing, and breaches are reported by step so the bottleneck owner is visible.", "gherkin": ["Given a valid instant euro payment is submitted", "When screening, Verification of Payee and clearing all complete within the execution limit", "Then the payment is reported complete only after clearing acceptance and settlement posting", "And the customer notification shows the verified beneficiary name", "Given a mandatory sanctions service is unavailable", "When policy requires fail closed processing", "Then the payment is held or rejected according to the approved procedure", "And the decision and the service outage are recorded in the audit trail"], "assessment": [{"question": "What is the maximum execution time for an instant euro payment under Regulation (EU) 2024/886?", "options": ["10 seconds", "20 seconds", "One business day", "5 seconds"], "answer": 0, "explanation": "The regulation sets a maximum execution time of 10 seconds for instant euro payments."}, {"question": "Why must channel acceptance and clearing acceptance be kept as separate statuses?", "options": ["The clearing participant can still reject a message the channel accepted", "The channel never accepts a payment", "They are the same event in every scheme", "Clearing acceptance is only needed for high value payments"], "answer": 0, "explanation": "A payment platform can accept a customer instruction and still have the clearing participant reject the resulting interbank message."}, {"question": "What is the correct handling for a duplicate clearing status report?", "options": ["Resubmit the payment", "Apply the status once and suppress duplicate posting and notification", "Delete the original payment record", "Post the ledger entry again to be safe"], "answer": 1, "explanation": "Status handling must be idempotent, so one effective state transition and one financial effect occur."}, {"question": "What must never be done to meet an instant payment speed target?", "options": ["Measure elapsed time per step", "Bypass mandatory sanctions or AML screening", "Validate messages before submission", "Run independent checks in parallel"], "answer": 1, "explanation": "Mandatory screening must never be bypassed to meet speed targets; speed is achieved by parallelisation and design, not by skipping controls."}]}}, {"id": "INS-138", "kind": "insight", "title": "FX transparency for customer", "topic": "FX transparency for customer", "theme": "Cross-Border Instant", "text": "Define rate quote, fees, rate validity, customer disclosure and execution rules.", "domain": "FX & Treasury", "area": "FX & Treasury", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch15s7", "title": "A complete cross border payment: putting it together", "url": "lessons/ch15s7"}, "case": {"status": "authored", "business_problem": "Northgate Retail, a fictional retailer, pays a supplier in US dollars while its operating account is in euro. The finance manager opens the bank app, sees a rate, accepts it, and expects the supplier to receive the agreed dollar amount. Instead the supplier is credited a different amount, the finance manager cannot reconcile the invoice, and the bank receives a complaint that the rate shown was not the rate applied.\n\nThe root cause is not a single wrong rate. The quote, the fee, the rate validity window and the execution moment are held in different places, and none of them is bound to the payment as one contract. A quote can expire while screening or routing is still running, a fee can be added after the quote screen, and a future dated instruction can execute on a day when one participant is closed. The customer sees a rate; the bank executes a different economic outcome.\n\nNorthgate Retail needs the bank to define the rate quote, the fees, the rate validity, the customer disclosure and the execution rules as one transparent package, so the amount the customer accepts is the amount that executes or the payment stops and asks again.", "decision_exercise": {"scenario": "A Northgate Retail finance manager accepts a euro to US dollar quote valid for 30 seconds. Screening takes longer than expected and the payment reaches execution 90 seconds after acceptance, when the market rate has moved. The supplier invoice is for a fixed dollar amount. What should the bank do?", "options": [{"id": "A", "text": "Execute at the old rate and absorb the difference silently in a suspense account."}, {"id": "B", "text": "Cancel the supplier payment and convert the euro amount into dollars at the next available rate without consent."}, {"id": "C", "text": "Execute at the new market rate without telling the customer, since the payment was already authorised."}, {"id": "D", "text": "Stop execution, do not apply a different rate silently, and ask the customer to accept a fresh quote with the new rate, fees and final amounts disclosed before execution."}], "correct_option": "D", "why": "Option D is correct because the quote, rate, expiry and execution conditions form one contract, and a payment must not be silently executed at a different rate. Option C is wrong because it changes the agreed economics without consent. Option A is wrong because absorbing the difference hides the true cost and breaks reconciliation. Option B is wrong because it cancels and re-executes without the customer agreeing the new terms."}, "recommended_solution": "Bind the quote to the payment as a single snapshot: quote ID, currency pair, buy and sell amounts, rate, spread, each fee, the total debit, the total credit, the expiry timestamp and the execution conditions. Show the customer the full disclosure before acceptance, including the rate, the fee breakdown, the exact amount the beneficiary will receive and how long the quote is valid. Store that snapshot and the consent evidence with the payment record so any later dispute can be reconstructed exactly.\n\nRevalidate the quote at execution. If the quote has expired, if the rate or amount has moved beyond the agreed tolerance, or if liquidity for the settlement currency is not available, pause execution and obtain a fresh quote and fresh consent. Never execute at a different rate silently. If the customer declines the new quote, cancel the instruction cleanly with no debit and a clear audit record.\n\nHandle dates explicitly. Apply the scheme, currency, debtor bank, creditor bank and clearing calendars to any future dated instruction, and show the customer the calculated execution date and the rule that produced it when the requested date is not an eligible processing day. Store the requested date, the calculated date, the calendar source and version, and the timezone separately.\n\nDesign the cover and customer legs as separately tracked legs where a correspondent model is used. A cover return must not automatically change the customer leg status; correlate both legs by stable references, determine the customer leg state first, and only then decide the customer impact. That separation protects the customer from an internal settlement event they did not cause.", "flow_steps": [{"step": 1, "actor": "Finance manager", "action": "Enters supplier, dollar amount and requested date in the banking channel", "system": "Corporate banking channel"}, {"step": 2, "actor": "FX quote service", "action": "Returns a quote with rate, fees, total debit, total credit and a 30 second validity window", "system": "FX quote service"}, {"step": 3, "actor": "Finance manager", "action": "Reviews the full disclosure and accepts the quote", "system": "Corporate banking channel"}, {"step": 4, "actor": "Payment engine", "action": "Binds the quote snapshot and consent to the payment and checks calendars and limits", "system": "Payment engine"}, {"step": 5, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud screening within the execution window", "system": "Screening services"}, {"step": 6, "actor": "Payment engine", "action": "Revalidates the quote at execution and checks settlement currency liquidity", "system": "FX and liquidity service"}, {"step": 7, "actor": "Payment engine", "action": "Executes the conversion and sends the payment and any cover leg", "system": "Payment engine and correspondent network"}, {"step": 8, "actor": "Payment engine", "action": "Confirms the final amounts, rate and value date to the customer and the supplier reference", "system": "Notification service"}], "happy_path": "The finance manager accepts a quote with the rate, fees and final dollar credit fully disclosed. Screening completes inside the validity window, the quote revalidates at execution, the conversion executes at the accepted rate, the supplier receives the agreed dollar amount, and the confirmation shows the rate, fees, value date and quote ID for reconciliation.", "negative_paths": [{"path": "Quote expires before execution", "trigger": "Screening or routing delays execution beyond the quote validity window", "handling": "Pause execution, present a fresh quote with new rate and amounts, and proceed only on fresh consent or cancel cleanly with no debit."}, {"path": "Future date falls on a non processing day", "trigger": "The requested execution date is a holiday for one participant in the chain", "handling": "Apply the documented calendar adjustment rule, show the customer the calculated date and the reason, and store requested and calculated dates separately."}, {"path": "Cover leg returned while customer leg is unclear", "trigger": "A pacs.009 cover leg is returned but the customer pacs.008 leg state is not yet known", "handling": "Correlate both legs by stable references, establish the customer leg state before any customer adjustment, and investigate rather than assuming one leg defines the other."}, {"path": "FX quote service unavailable", "trigger": "No live quote can be obtained at instruction time", "handling": "Do not invent a rate or reuse a stale quote; tell the customer the service is unavailable and offer to retry or to schedule the instruction when quoting resumes."}], "technical_data": "Store the quote as an immutable snapshot with quote ID, currency pair, rate, amounts, fees, spread, expiry timestamp, tolerance and consent timestamp, linked to the payment by correlation ID. Enforce single consumption of a quote so one quote cannot fund two payments. Validate amounts and currency codes, apply rounding rules consistently between quote and execution, and record the calendar source and version used for any date adjustment. Keep customer leg and cover leg records separate with linked transaction IDs and, where applicable, the UETR, so each leg has its own state machine and audit trail. Log every revalidation, expiry and fresh consent as an event.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment initiation carrying the instruction and references", "key_fields": ["Instruction Identification", "Requested execution date", "Debtor and creditor details", "Instructed amount and currency"]}, {"message": "pacs.008", "purpose": "Customer credit transfer for the converted payment", "key_fields": ["End to End Identification", "Instructed amount and currency", "Creditor agent", "Remittance information for supplier reconciliation"]}, {"message": "pacs.009 COV", "purpose": "Cover leg for settlement through the correspondent chain where the cover model is used", "key_fields": ["Cover amount and currency", "Underlying customer payment reference", "Intermediary and creditor agents"]}, {"message": "pacs.002", "purpose": "Status report for each leg so acceptance and rejection are tracked separately", "key_fields": ["Original reference", "Status code", "Reason code where rejected"]}], "accounting_operational": "Debit the customer euro account for the total agreed debit, credit the FX conversion account at the quoted rate, and credit the settlement account for the dollar amount, with fees posted as separate entries so the principal, the rate and the fee are each reconcilable. If the quote expires and the customer declines a fresh quote, reverse any reservation exactly once and leave no partial conversion posting. A returned cover leg goes to a nostro reconciliation and investigation worklist; the customer leg is only adjusted once its own state is established. Operations monitor quote expiry rates, revalidation failures and cover return ageing as service quality measures.", "gherkin": ["Given a customer has accepted an FX quote with a defined expiry", "When execution is attempted after the quote has expired", "Then the payment is not silently executed at a different rate", "And the customer is asked to accept a fresh quote or cancel", "Given a future dated payment falls on a non processing day", "When the scheduler evaluates the requested date", "Then the documented date adjustment policy is applied", "And the customer is shown the calculated execution date"], "assessment": [{"question": "What must a payment never do when an FX quote has expired before execution?", "options": ["Show the customer the new rate", "Execute silently at a different rate", "Cancel cleanly with no debit", "Pause and seek a fresh quote and consent"], "answer": 1, "explanation": "An expired quote must not lead to silent execution at a different rate; the customer must accept fresh terms."}, {"question": "Which items should be bound to the payment as one FX quote snapshot?", "options": ["Quote ID, currency pair, amounts, rate, fees, expiry and execution conditions", "Currency pair only", "Rate only", "Fee only"], "answer": 0, "explanation": "The quote contract includes the ID, pair, amounts, rate, fees, spread, expiry and execution conditions."}, {"question": "What should happen when a cover leg is returned but the customer leg status is unclear?", "options": ["Credit the customer immediately", "Investigate both legs before posting a customer adjustment", "Delete the cover record", "Assume the customer payment failed"], "answer": 1, "explanation": "Cover and customer leg states must be modelled separately and investigated before any customer adjustment."}, {"question": "How should a future dated payment on a non processing day be handled?", "options": ["Reject it without explanation", "Execute it on the requested date anyway", "Apply the documented calendar adjustment and show the calculated date", "Move it silently to the next month"], "answer": 2, "explanation": "The correct scheme and participant calendars govern the date, and the adjustment must be transparent to the customer."}]}}, {"id": "INS-139", "kind": "insight", "title": "UETR as a tracking reference", "topic": "UETR as a tracking reference", "theme": "Cross-Border Instant", "text": "Explain UETR use for traceability and the limits of what a reference alone proves.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch15s5", "title": "UETR: the unique tracking reference", "url": "lessons/ch15s5"}}, {"id": "INS-140", "kind": "insight", "title": "Structured remittance and party data", "topic": "Structured remittance and party data", "theme": "Cross-Border Instant", "text": "Explain payer, beneficiary, purpose and remittance data for reconciliation and compliance.", "domain": "ISO 20022 & Data", "area": "ISO 20022 & Data", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch39s6", "title": "Mandatory, Optional and Conditional Fields, Schema Validation, External Code Sets, Version Management and Market Practice Rules", "url": "lessons/ch39s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank serves a corporate client, Harbourline Logistics, a fictional freight company that pays dozens of overseas suppliers each week. Every payment carries invoice numbers the supplier needs to allocate the cash, and every payment must pass compliance screening that depends on accurate payer and beneficiary data. Harbourline Logistics reports that suppliers keep calling about unallocated cash, and the bank's screening team keeps returning instructions for missing or ambiguous party data.\n\nThe problem sits in how the data travels. The channel captures a free text remittance note, a transformation layer flattens structured invoice references into a single line, and an intermediary can truncate what remains. Party addresses arrive as unstructured lines that screening cannot match reliably, and the purpose of the payment is described differently on every instruction. The money moves, but the information that makes the money usable does not.\n\nThe bank must explain payer, beneficiary, purpose and remittance data as a designed data contract, so reconciliation and compliance both work from the same structured facts, and so the data survives the full chain to the beneficiary bank.", "decision_exercise": {"scenario": "Harbourline Logistics submits a payment with three invoice references, a structured creditor address and a stated purpose of freight settlement. The downstream correspondent accepts only a shorter unstructured remittance field. As the business analyst, what do you require of the transformation?", "options": [{"id": "A", "text": "Concatenate all references into one long line and hope the intermediary preserves it."}, {"id": "B", "text": "Send the payment without remittance information and email the invoices separately."}, {"id": "C", "text": "Drop the invoice references silently so the message fits the downstream limit."}, {"id": "D", "text": "Map structured and unstructured remittance fields with explicit length, character set and preservation rules, validate truncation, and raise a controlled exception where a critical reference would be lost."}], "correct_option": "D", "why": "Option D is correct because it preserves business critical references or raises a controlled exception when preservation is impossible, with a recorded loss analysis. Option C is wrong because silently dropping references breaks supplier reconciliation. Option A is wrong because it has no length or character validation and no proof the data survives. Option B is wrong because it separates the payment from its reconciliation data and leaves the beneficiary bank with nothing to allocate against."}, "recommended_solution": "Define a canonical data model for every payment before any message is built. Payer and beneficiary each carry a legal name, a structured or hybrid address with at least Town Name and Country Code, or a BIC only where the scheme permits, plus account identification and, where the product requires it, a purpose code. Remittance information carries structured invoice references with invoice number, amount and date where the scheme supports them, and unstructured text only as a fallback with a documented length limit.\n\nMap that canonical model to each downstream format with a field level mapping table that states the source field, the target field, the maximum length, the permitted character set and the preservation rule. Test the mapping end to end, including a round trip test that proves the reference the sender entered is the reference the beneficiary bank receives. Where a downstream limit forces truncation, the rule must say which references are preserved, in what order, and when the payment must stop for repair instead of proceeding with lost data.\n\nTreat the structured address requirement as a standing rule, not a dated project. The SWIFT structured address timeline was extended in July 2026 and a new timeline was expected by December 2026, so the bank must not teach or build around 14 November 2026 as a fixed cut off. The requirement itself stands: structured or hybrid address, with the minimum Town Name and Country Code, or BIC only.\n\nGive screening and reconciliation the same source of truth. Screening matches on the structured party data, reconciliation matches on the structured remittance data, and both teams work from the canonical record rather than from a transformed copy. Data lineage is recorded for every field, so an operations analyst can trace any value on a beneficiary statement back to the field the customer entered.", "flow_steps": [{"step": 1, "actor": "Corporate customer", "action": "Enters payer, beneficiary, structured address, purpose and invoice references in the channel", "system": "Corporate banking channel"}, {"step": 2, "actor": "Payment engine", "action": "Validates the canonical data model, including address completeness and remittance structure", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Runs sanctions and AML screening on the structured party data", "system": "Screening services"}, {"step": 4, "actor": "Payment engine", "action": "Maps the canonical model to the outbound ISO 20022 message with preservation rules applied", "system": "Message transformation service"}, {"step": 5, "actor": "Payment engine", "action": "Checks that critical remittance references survive the mapping or raises a controlled exception", "system": "Message transformation service"}, {"step": 6, "actor": "Clearing adapter", "action": "Submits the pacs.008 message to clearing and onward to the beneficiary bank", "system": "Scheme adapter"}, {"step": 7, "actor": "Beneficiary bank", "action": "Receives the structured remittance data and allocates the credit against the supplier invoices", "system": "Beneficiary bank system"}, {"step": 8, "actor": "Payment engine", "action": "Confirms the payment with the remittance references as sent, for the customer record", "system": "Notification service"}], "happy_path": "Harbourline Logistics enters three invoice references, a structured creditor address and a freight settlement purpose. Validation and screening pass on the structured data, the mapping preserves every reference within the downstream limits, the beneficiary bank receives the full remittance information, the supplier allocates the cash automatically, and the customer confirmation lists the references exactly as sent.", "negative_paths": [{"path": "Remittance length overflow", "trigger": "Structured remittance data exceeds a downstream field limit", "handling": "Apply the agreed preservation or exception rule, record any loss in the lineage log, and stop for repair where a critical reference would be lost."}, {"path": "Unsupported characters", "trigger": "A reference contains characters the downstream format cannot carry", "handling": "Reject or transliterate under a documented rule, tell the customer what changed, and never silently alter an invoice number."}, {"path": "Intermediary strips data", "trigger": "An intermediary bank forwards the payment without the remittance block", "handling": "Detect the loss through reconciliation and tracker evidence, raise an investigation with the intermediary, and supply the remittance data to the beneficiary through the agreed repair channel."}, {"path": "Incomplete party address", "trigger": "The creditor address lacks Town Name or Country Code and no BIC is supplied", "handling": "Hold the instruction at capture, ask the customer for the missing structured address data, and do not submit an incomplete party record to screening or clearing."}], "technical_data": "Hold one canonical payment record with structured party, address, purpose and remittance fields, and derive every outbound message from it rather than chaining transformations. Version the field mapping table, record the mapping version used for each payment, and keep a loss analysis log for any truncation or transliteration. Validate character sets, lengths and mandatory fields at capture, and enforce idempotency so a retry does not create a second payment with a second remittance set. Store the UETR where applicable and the End to End Identification so the remittance data can be traced across intermediaries, and keep the original customer input immutable beside the transformed message.", "messages_fields": [{"message": "pain.001", "purpose": "Customer initiation carrying structured party, address, purpose and remittance data", "key_fields": ["Debtor and creditor names and structured addresses", "Purpose code or purpose text", "Structured remittance information with invoice references"]}, {"message": "pacs.008", "purpose": "Customer credit transfer carrying the remittance data to the beneficiary bank", "key_fields": ["Creditor name and structured or hybrid address", "Remittance information structured and unstructured blocks", "End to End Identification for tracing", "Purpose code"]}, {"message": "pacs.002", "purpose": "Status report confirming acceptance or reporting a data rejection", "key_fields": ["Original reference", "Status code", "Reason code for a data or format rejection"]}], "accounting_operational": "Debit the customer account and credit the settlement account for the payment amount, with the remittance references attached to the ledger record so finance can reconcile the payment to the supplier invoices. A payment held for missing party or remittance data creates no ledger posting; it sits on a data repair worklist with a service level for customer contact. Truncation or loss detected after settlement is raised as a data incident, not silently corrected, and the beneficiary bank is supplied with the full remittance set through the agreed channel. Operations track unallocated cash reports from beneficiaries as a quality measure for the remittance mapping.", "gherkin": ["Given remittance data exceeds a downstream field limit", "When transformation occurs", "Then the system follows the agreed preservation or exception rule", "And records any loss in the data lineage log", "Given a creditor address lacks Town Name or Country Code", "When no BIC is supplied", "Then the instruction is held at capture", "And the customer is asked for the missing structured address data"], "assessment": [{"question": "What is the minimum structured address data required where a BIC is not supplied?", "options": ["Street name only", "Postcode only", "Town Name and Country Code", "Country name only"], "answer": 2, "explanation": "The requirement is structured or hybrid address with minimum Town Name and Country Code, or BIC only."}, {"question": "What should happen when structured remittance data exceeds a downstream field limit?", "options": ["Concatenate everything into one line", "Drop the references silently", "Follow the agreed preservation or exception rule and record any loss", "Send the payment without remittance data"], "answer": 2, "explanation": "The mapping must have explicit preservation rules and a recorded loss analysis, never silent loss."}, {"question": "Why is a canonical data model needed before message transformation?", "options": ["So each system can invent its own fields", "So intermediaries can strip data freely", "So the channel can skip validation", "So screening, reconciliation and every outbound message work from the same structured facts"], "answer": 3, "explanation": "One canonical record gives screening and reconciliation the same source of truth and makes data lineage traceable."}, {"question": "How should the structured address timeline be treated in teaching and design?", "options": ["As a fixed cut off on 14 November 2026", "As a rule that applies only to domestic payments", "As a rule that no longer applies", "As an extended timeline with the requirement standing, not a fixed 14 November 2026 cut off"], "answer": 3, "explanation": "SWIFT extended the deadline in July 2026, so 14 November 2026 must not be taught as a fixed cut off while the structured address requirement stands."}]}}, {"id": "INS-141", "kind": "insight", "title": "Payment-system interoperability is more than an API", "topic": "Payment-system interoperability is more than an API", "theme": "Cross-Border Instant", "text": "Align message formats, scheme rules, clearing, settlement, compliance and operations.", "domain": "Payment Architecture", "area": "Payment Architecture", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch25s5", "title": "Routing, Clearing and Settlement", "url": "lessons/ch25s5"}, "case": {"status": "authored", "business_problem": "Harbourline Bank, a fictional bank, has connected its domestic instant payment service to a partner instant system in another country through an API. The integration tests pass: a message sent through the API receives a response. Yet in live operation, payments fail in ways the API tests never showed. A payment accepted by the channel is rejected by clearing, a status report arrives twice and posts twice, and a sanctions check that fits the domestic 10 second window cannot complete inside the cross-border leg timing.\n\nThe bank treated interoperability as a technical connection. In reality it is an alignment problem across message formats, scheme rules, clearing, settlement, compliance and operations. The two systems use different status meanings, different cut offs, different data requirements and different failure behaviour, and none of that is visible in an API contract alone.\n\nThe bank needs an architecture view that aligns every layer, so a payment that is technically deliverable is also scheme compliant, operationally supportable and correctly reported to the customer.", "decision_exercise": {"scenario": "Harbourline Bank connects to a new instant corridor by API. Test messages pass, but live payments show duplicate status postings, clearing rejections after channel acceptance, and screening timeouts. As the business analyst, what is the first alignment you require?", "options": [{"id": "A", "text": "Publish the API specification to the partner and ask them to adapt."}, {"id": "B", "text": "Add more API retries so every failed call is attempted again automatically."}, {"id": "C", "text": "Ship the integration and fix live defects as customers report them."}, {"id": "D", "text": "Align message formats, scheme rules, clearing and settlement, compliance placement, status semantics, idempotency and operational ownership across both systems before scaling volume."}], "correct_option": "D", "why": "Option D is correct because interoperability spans formats, scheme rules, clearing, settlement, compliance and operations, and each layer must be aligned before volume scales. Option B is wrong because blind retries duplicate financial effects. Option A is wrong because one sided publication does not align the other system's rules and timing. Option C is wrong because live customer payments are not a test environment for alignment gaps."}, "recommended_solution": "Start with a corridor alignment record that both participants sign. It covers the message formats and versions on each leg, the scheme rules that apply, the clearing and settlement arrangements, the compliance controls and where each sits in the flow, the status vocabulary and what each status means, the timeout and retry rules, the idempotency keys, and the operational owners on each side. No corridor goes live until every row has an agreed value and a test that proves it.\n\nSeparate the layers in design and in testing. Message mapping is tested with field level cases including structured addresses and remittance data. Scheme rules are tested with eligibility, limit and cut off cases. Clearing is tested with acceptance and rejection cases where the channel status, the clearing status and the ledger are checked independently. Compliance is tested with pass, match, timeout and service unavailable cases under the approved fail open or fail closed rule for each control.\n\nMake status handling idempotent by design. Deduplicate status reports by message identity and transaction reference, persist processed outcomes, and enforce a state machine that prevents regression and duplicate posting. Reconcile sent messages against acknowledgements and ledger entries, and put unmatched items on an operational worklist with ageing alerts.\n\nGive the corridor an operational owner and a joint runbook. The runbook names the owner on each side, the escalation path, the investigation service levels, the dispute process and the change process for reference data and scheme rules. Interoperability is then a maintained operating agreement, not a one off integration.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits a cross-border instant payment in the channel", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction against the corridor alignment record for format, limits and eligibility", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud checks in the agreed order with decision deadlines", "system": "Screening services"}, {"step": 4, "actor": "Payment engine", "action": "Maps the canonical payment to the outbound message format for the corridor", "system": "Message transformation service"}, {"step": 5, "actor": "Clearing adapter", "action": "Submits the message to clearing and records the submission and correlation IDs", "system": "Scheme adapter"}, {"step": 6, "actor": "Clearing system", "action": "Returns an acceptance or rejection status report", "system": "Clearing system"}, {"step": 7, "actor": "Payment engine", "action": "Deduplicates the status, updates the leg state once, and posts or reverses accounting", "system": "Payment engine and core ledger"}, {"step": 8, "actor": "Payment engine", "action": "Reports the confirmed outcome to the customer in the corridor status vocabulary", "system": "Notification service"}], "happy_path": "The customer submits a payment that passes corridor validation and screening. The message maps cleanly to the partner format, clearing accepts it, the status report is applied once, settlement posts, and the customer sees a confirmed completion with a status meaning that matches the partner system.", "negative_paths": [{"path": "Duplicate status report", "trigger": "The clearing system sends the same pacs.002 status twice", "handling": "Deduplicate by message identity, apply the status once, and suppress duplicate ledger posting and customer notification."}, {"path": "Clearing rejection after channel acceptance", "trigger": "The clearing participant rejects the interbank message", "handling": "Translate the scheme reason code, move the payment to a rejected state, reverse the reservation once, and notify the customer with a plain explanation."}, {"path": "Compliance timeout", "trigger": "A screening service exceeds the corridor decision deadline", "handling": "Apply the approved fail open or fail closed rule for that control, hold or reject explicitly, and record the decision and evidence."}, {"path": "Conflicting status sequence", "trigger": "A later status arrives before an earlier one, or two statuses disagree", "handling": "Apply event ordering rules so state never regresses, keep the full event history, and route conflicts to investigation."}], "technical_data": "Persist the corridor alignment record as versioned configuration with effective dates, and record the version used for each payment. Use a canonical payment model with a correlation ID carried across every system, and store mapping versions, screening decisions and status events as structured audit data. Make every status consumer idempotent with persisted inbound message IDs and processed outcomes, and enforce state transitions through a single state machine. Validate message fields, structured addresses and character sets before submission, and keep customer instruction status, clearing status and settlement status as separate fields with an authoritative source for each.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer sent to clearing and onward", "key_fields": ["Instruction and End to End Identification", "Debtor and creditor agents", "Instructed amount and currency", "Structured party and remittance data"]}, {"message": "pacs.002", "purpose": "Payment status report from clearing, subject to deduplication", "key_fields": ["Original instruction reference", "Message Identification for deduplication", "Status code and reason code"]}, {"message": "camt.054", "purpose": "Debit or credit notification where a formal notification record is needed", "key_fields": ["Account identification", "Amount and currency", "Related payment reference"]}], "accounting_operational": "On clearing acceptance, debit the customer account and credit the settlement account, with fees as separate entries. On rejection, release the reservation exactly once and restore the customer balance, keeping the original instruction immutable with a linked rejection event. Duplicate status reports must never create a second posting; reconciliation between sent messages, acknowledgements and ledger entries runs intraday and unmatched items age on an operations worklist. Corridor service levels cover status freshness, investigation response and change notice periods, and are reviewed jointly with the partner.", "gherkin": ["Given an identical status report is received twice", "When the second copy is processed", "Then no duplicate financial posting or state transition occurs", "And only one customer notification is sent", "Given a clearing rejection correlated to a payment", "When the response is received", "Then the payment is moved to the appropriate rejected state", "And any related accounting reservation is handled once"], "assessment": [{"question": "What does payment system interoperability require beyond an API connection?", "options": ["A single database", "Alignment of message formats, scheme rules, clearing, settlement, compliance and operations", "A shared logo", "A faster network only"], "answer": 1, "explanation": "Interoperability spans formats, scheme rules, clearing, settlement, compliance and operations, not just connectivity."}, {"question": "How should a duplicate clearing status report be handled?", "options": ["Resubmit the payment", "Deduplicate by message identity and apply the status once", "Ignore all future status reports", "Post it again"], "answer": 1, "explanation": "Status handling must be idempotent so one effective transition and one financial effect occur."}, {"question": "What is the difference between channel acceptance and clearing acceptance?", "options": ["There is no difference", "Clearing always accepts first", "The channel can accept an instruction that clearing later rejects", "The channel never accepts a payment"], "answer": 2, "explanation": "Channel acceptance confirms receipt and validation; clearing acceptance is a separate downstream decision."}, {"question": "What should a corridor alignment record cover?", "options": ["Message format only", "Marketing copy only", "Formats, scheme rules, clearing, settlement, compliance, status meanings, timeouts, idempotency and ownership", "Pricing only"], "answer": 2, "explanation": "Every layer that can diverge between participants needs an agreed value and a proving test."}]}}, {"id": "INS-142", "kind": "insight", "title": "UPI and PayNow linkage", "topic": "UPI and PayNow linkage", "theme": "Cross-Border Instant", "text": "Explain the operationalised linkage, proxy identifiers and participating institution model; validate current scope.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch16s1", "title": "Why cross border payments fail", "url": "lessons/ch16s1"}, "case": {"status": "authored", "business_problem": "Meridian Bank, a fictional bank with customers in India and Singapore, wants to offer instant person to person transfers between the two countries using the UPI and PayNow linkage. A customer in India wants to send money to a family member in Singapore using only the recipient's mobile number, and a customer in Singapore wants to send money to India using the recipient's UPI ID. Both expect the experience to feel like a domestic instant payment.\n\nThe linkage is live, but it is not a single domestic rail. It connects two domestic fast payment systems through participating institutions, proxy identifiers and a settlement arrangement, and each side has its own limits, validation and compliance checks. The UPI and PayNow linkage has been live since 21 February 2023, and the initial Indian daily limit was Rs 60,000. The bank must explain the operationalised linkage, the proxy identifiers and the participating institution model, and validate the current scope before teaching it as universal.\n\nThe risk of getting this wrong is a failed transfer after the sender is debited, a payment sent to the wrong person because a proxy was not verified, or a customer promise that the corridor cannot keep on a given day.", "decision_exercise": {"scenario": "A Meridian Bank customer in India enters a Singapore mobile number as the PayNow proxy and Rs 50,000 as the amount. The proxy resolves to a name the customer does not recognise. What should the bank do before the money moves?", "options": [{"id": "A", "text": "Convert the amount to Singapore dollars first and skip the name check to save time."}, {"id": "B", "text": "Show the resolved beneficiary name for customer confirmation, run sanctions and fraud checks, confirm the amount is within the applicable daily limit, and only then proceed on explicit confirmation."}, {"id": "C", "text": "Ask the customer to guess the correct name and proceed if the guess is close."}, {"id": "D", "text": "Send the payment anyway, since the proxy resolved to a registered account."}], "correct_option": "B", "why": "Option B is correct because proxy resolution must be confirmed by the customer, compliance checks must still run, and limits must be validated before execution. Option D is wrong because a resolved proxy is not proof the customer intended that beneficiary. Option C is wrong because guessing a beneficiary name is not a control. Option A is wrong because conversion does not replace beneficiary verification."}, "recommended_solution": "Model the linkage as two domestic legs joined by an orchestration layer, not as one domestic payment. The Indian leg runs on UPI rails and the Singapore leg runs on PayNow rails, with the originating bank, the participating institutions and the settlement arrangement each owning a defined part. The customer promise is stated per leg: the originating leg is accepted, the cross-border orchestration is confirmed, and the destination leg credit is confirmed, and the payment is only reported complete when the required confirmations have arrived.\n\nUse proxy identifiers as a lookup, never as proof. A UPI ID, a mobile number or a VPA resolves to a registered name, and the bank shows that name to the sender for explicit confirmation before the money moves. That confirmation is the control that prevents a mistyped proxy sending money to the wrong person. Record the proxy used, the resolved name, the confirmation timestamp and the consent evidence with the payment.\n\nApply limits as they stand for the corridor and the customer. The initial Indian daily limit for the linkage was Rs 60,000, and the bank must validate the current scope, the participating institutions and the applicable daily limits before promising a transfer. The wider UPI limit of INR 5 lakh applies to specified categories from December 2024 and must not be presented as the linkage limit. Validate the amount against the corridor limit, the customer limit and the destination limit, and reject or split only under a documented rule the customer can see.\n\nRun compliance and fraud checks on both the sender and the resolved beneficiary, with a synchronous decision deadline that fits the instant promise. If a leg fails after the sender is debited, hold the payment in an unknown state, establish whether the debit is provisional or final, and return or compensate funds under the defined scheme process, never by blind resubmission.", "flow_steps": [{"step": 1, "actor": "Sender", "action": "Enters the recipient proxy, either a mobile number, UPI ID or VPA, and the amount in the app", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Resolves the proxy to the registered beneficiary name through the linkage directory", "system": "Proxy resolution service"}, {"step": 3, "actor": "Sender", "action": "Confirms the resolved beneficiary name and the full disclosure of amount, fees and rate", "system": "Mobile banking"}, {"step": 4, "actor": "Payment engine", "action": "Validates corridor and customer limits and runs sanctions, AML and fraud checks", "system": "Payment engine and screening services"}, {"step": 5, "actor": "Payment engine", "action": "Debits the sender and initiates the originating domestic leg", "system": "UPI system"}, {"step": 6, "actor": "Orchestration layer", "action": "Converts and settles through the linkage settlement arrangement", "system": "Cross-border orchestration"}, {"step": 7, "actor": "Destination institution", "action": "Credits the beneficiary through the destination fast payment system", "system": "PayNow system"}, {"step": 8, "actor": "Payment engine", "action": "Confirms the destination credit to the sender with the reference and value date", "system": "Notification service"}], "happy_path": "The sender enters a mobile number proxy, the linkage resolves it to the expected beneficiary name, the sender confirms the name and the disclosed amounts, limit and compliance checks pass, the UPI leg debits the sender, the orchestration settles the transfer, the PayNow leg credits the beneficiary, and the sender receives a confirmed completion with the reference.", "negative_paths": [{"path": "Proxy resolves to an unexpected name", "trigger": "The sender does not recognise the resolved beneficiary name", "handling": "Stop the payment before any debit, let the sender correct the proxy, and log the abandoned attempt without creating a payment."}, {"path": "Destination leg timeout", "trigger": "The originating leg is accepted but no destination confirmation arrives", "handling": "Hold the payment in an unknown state, run a status enquiry by reference, never resubmit blindly, and escalate to investigation at the defined timeout."}, {"path": "Sender debited but destination fails", "trigger": "The destination system reports a technical failure after the sender debit", "handling": "Establish whether the debit is provisional or final, return or compensate funds under the defined process, and ensure exactly one financial effect."}, {"path": "Amount above the corridor limit", "trigger": "The amount exceeds the applicable daily limit for the linkage", "handling": "Reject the instruction with a clear explanation of the limit, or offer a documented alternative the customer can accept, and never split the payment silently to evade the limit."}], "technical_data": "Store the proxy type and value, the resolved beneficiary name, the confirmation timestamp and the consent evidence as structured data linked by a correlation ID across both legs. Model each leg with its own state machine and an overall orchestration state, with timestamps for leg acceptance, settlement and destination confirmation. Make all status handling idempotent so duplicate callbacks cannot double credit or double refund. Validate amounts, currencies and proxy formats at capture, and record the limit source and version used for the decision. Keep the original sender instruction immutable and link every leg event, fee and FX conversion to it for audit and reconciliation.", "messages_fields": [{"message": "UPI payment instruction", "purpose": "Originating domestic leg instruction on the UPI system", "key_fields": ["Sender UPI ID or account", "Beneficiary proxy and resolved name", "Amount in INR", "Transaction reference"]}, {"message": "PayNow payment instruction", "purpose": "Destination domestic leg instruction on the PayNow system", "key_fields": ["Beneficiary proxy, mobile number or identifier", "Amount in SGD", "Transaction reference"]}, {"message": "Status confirmation", "purpose": "Leg level confirmation that the destination credit has occurred", "key_fields": ["Transaction reference for correlation", "Leg status", "Timestamp of beneficiary credit"]}], "accounting_operational": "Debit the sender account for the agreed amount and fees, credit the linkage settlement account, and post the destination leg on confirmation, with FX conversion posted as a separate entry so the principal, the rate and the fee are each reconcilable. A failed destination leg after debit moves the funds to a suspense account and onto an investigation worklist with an ageing service level, and any return to the sender is posted as a linked reversal, never by editing the original debit. Operations reconcile originating leg debits, settlement account movements and destination confirmations daily, and report proxy mismatch rates and timeout rates as corridor quality measures.", "gherkin": ["Given the originating leg is accepted but destination confirmation is absent", "When the timeout threshold is reached", "Then the payment enters an unknown or investigation state", "And is not blindly resubmitted", "Given a proxy resolves to a beneficiary name", "When the sender does not recognise the name", "Then the payment stops before any debit", "And the sender is asked to correct the proxy"], "assessment": [{"question": "When did the UPI and PayNow linkage go live?", "options": ["9 October 2025", "27 November 2025", "21 February 2023", "5 October 2025"], "answer": 2, "explanation": "The UPI-PayNow linkage has been live since 21 February 2023."}, {"question": "What was the initial Indian daily limit for the linkage?", "options": ["Rs 60,000", "Rs 5 lakh", "Rs 2 lakh", "USD 10 million"], "answer": 0, "explanation": "The initial Indian daily limit for the linkage was Rs 60,000."}, {"question": "Which proxy identifiers can be used in the UPI and PayNow linkage?", "options": ["UPI ID, mobile number and VPA", "BIC only", "Card number only", "IBAN only"], "answer": 0, "explanation": "Proxy identifiers include UPI ID, mobile number and VPA."}, {"question": "What must happen when the originating leg is accepted but destination confirmation is absent at timeout?", "options": ["Tell the customer the payment succeeded", "Delete the payment record", "Enter an unknown or investigation state and do not blindly resubmit", "Resubmit the payment immediately"], "answer": 2, "explanation": "An unconfirmed leg must be investigated by reference, with no duplicate sending."}]}}, {"id": "INS-143", "kind": "insight", "title": "FX provider role in instant cross-border payments", "topic": "FX provider role in instant cross-border payments", "theme": "Cross-Border Instant", "text": "Define quote sourcing, rate locking, execution, liquidity and exception handling.", "domain": "FX & Treasury", "area": "FX & Treasury", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch15s7", "title": "A complete cross border payment: putting it together", "url": "lessons/ch15s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank offers instant cross-border payments but does not hold liquidity in every settlement currency its customers need. It relies on an FX provider to source quotes, lock rates, execute conversion and supply settlement currency. The arrangement works on quiet days, but on a busy morning the cracks show: a quote expires while screening runs, the provider cannot supply the settlement currency at the required time, and a payment executes at a rate the customer never accepted.\n\nThe bank and the provider each assume the other owns the risk. The bank assumes the provider guarantees the rate and the liquidity; the provider assumes the bank will only send executable instructions inside the quote window. Neither assumption is written down, so the customer bears the consequence when the two assumptions collide.\n\nThe bank must define the FX provider role precisely: quote sourcing, rate locking, execution, liquidity and exception handling, with clear ownership of the risk at each step.", "decision_exercise": {"scenario": "Meridian Bank sends an FX instruction to its provider after the quoted rate has expired, and the provider executes at the current market rate. The customer complains that the beneficiary received less than the disclosed amount. Who should have prevented this, and how?", "options": [{"id": "A", "text": "The bank, by binding the quote ID, rate, amounts and expiry to the payment, revalidating at execution, and never sending an expired quote for execution without fresh customer consent."}, {"id": "B", "text": "Nobody, because market rates always move."}, {"id": "C", "text": "The provider, by refusing to execute any instruction outside its quote window."}, {"id": "D", "text": "The customer, by accepting that any rate may apply."}], "correct_option": "A", "why": "Option A is correct because the bank owns the payment instruction and must revalidate the quote at execution and obtain fresh consent when terms change. Option C is wrong as a sole answer because the bank must not send an expired instruction in the first place, even though the provider should also reject it. Option B is wrong because rate movement is expected and must be governed by a quote contract, not accepted as an excuse. Option D is wrong because the customer accepted a specific disclosed rate, not any rate."}, "recommended_solution": "Write the FX provider role as a contract with five parts: quote sourcing, rate locking, execution, liquidity and exception handling. Quote sourcing states which currencies, which hours, which quote validity windows and which tolerances apply. Rate locking states what is locked, for how long, and what happens at expiry. Execution states the exact instruction format, the single consumption rule for a quote, and the revalidation the bank performs before sending. Liquidity states the settlement currency the provider will supply, the cut offs, and what happens when it cannot supply it. Exception handling states who notifies whom, within what time, and who bears the cost of a failed or late execution.\n\nBind every quote to the payment as an immutable snapshot with quote ID, currency pair, amounts, rate, spread, fees, expiry and execution conditions, and store the customer consent evidence beside it. Revalidate at execution and stop for a fresh quote and fresh consent when the quote has expired or the rate has moved beyond tolerance. Enforce single consumption so one quote cannot fund two payments, and reject any provider execution that does not match the locked quote.\n\nDistinguish FX conversion from settlement currency availability. A good rate does not help if the settlement currency is not available at the required time. The bank must check liquidity before promising an instant outcome, hold or queue the payment under a documented rule when liquidity is short, and never promise a settlement time the liquidity position cannot support.\n\nDesign the legs separately. The customer leg, the FX conversion and the settlement leg each have their own state, and a failure in one leg must not silently change another. If the sender is debited and the destination leg then fails, the bank establishes whether the debit is provisional or final, returns or compensates funds under the defined process, and ensures exactly one financial effect.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Requests a cross-border payment with source and destination currencies", "system": "Mobile banking"}, {"step": 2, "actor": "FX provider", "action": "Sources a quote with rate, fees, amounts and a defined validity window", "system": "FX quote service"}, {"step": 3, "actor": "Customer", "action": "Accepts the quote with the full disclosure of rate, fees and final amounts", "system": "Mobile banking"}, {"step": 4, "actor": "Payment engine", "action": "Binds the quote snapshot and consent to the payment and checks settlement currency liquidity", "system": "Payment engine"}, {"step": 5, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud screening within the quote window", "system": "Screening services"}, {"step": 6, "actor": "Payment engine", "action": "Revalidates the quote at execution and sends the execution instruction to the FX provider", "system": "FX execution service"}, {"step": 7, "actor": "FX provider", "action": "Executes the conversion and supplies the settlement currency", "system": "FX provider platform"}, {"step": 8, "actor": "Payment engine", "action": "Sends the payment onward and confirms the final rate, amounts and value date to the customer", "system": "Payment engine and notification service"}], "happy_path": "The customer accepts a quote with rate, fees and final amounts disclosed. Liquidity is confirmed, screening completes inside the validity window, the quote revalidates at execution, the provider executes at the locked rate, the settlement currency is supplied, the payment reaches the beneficiary, and the confirmation shows the quote ID, rate and value date.", "negative_paths": [{"path": "Quote expires before execution", "trigger": "Screening or routing delays execution beyond the quote validity window", "handling": "Pause execution, obtain a fresh quote, and proceed only on fresh customer consent or cancel cleanly with no debit."}, {"path": "Liquidity shortfall", "trigger": "The provider cannot supply the settlement currency at the required time", "handling": "Hold or queue the payment under the documented rule, tell the customer the realistic timing, and do not promise an instant outcome the liquidity cannot support."}, {"path": "Duplicate quote consumption", "trigger": "The same quote ID is presented for a second payment", "handling": "Reject the second use, log the attempt, and require a fresh quote for the second payment."}, {"path": "Destination failure after sender debit", "trigger": "The destination leg fails after the sender is debited and conversion has executed", "handling": "Establish whether the debit is provisional or final, return or compensate funds under the defined process, and ensure exactly one financial effect."}], "technical_data": "Store the quote snapshot immutably with quote ID, provider ID, currency pair, rate, amounts, spread, fees, expiry timestamp, tolerance, liquidity confirmation and consent timestamp, linked to the payment by correlation ID. Enforce single consumption with a unique constraint on the quote ID, and validate every provider execution response against the locked quote before posting. Record liquidity checks, revalidations and provider responses as structured events, and keep the customer leg, the conversion and the settlement leg as separate records with their own state machines. Use idempotency keys on every provider call so a retry cannot execute twice.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer for the converted payment", "key_fields": ["End to End Identification", "Instructed amount and currency", "Creditor agent", "Remittance information"]}, {"message": "pacs.009", "purpose": "Financial institution transfer for the settlement leg where the model requires it", "key_fields": ["Settlement amount and currency", "Debtor and creditor agents", "Related customer payment reference"]}, {"message": "pacs.002", "purpose": "Status report for the payment and settlement legs", "key_fields": ["Original reference", "Status code", "Reason code where rejected"]}, {"message": "FX quote contract", "purpose": "Internal contract binding the quote to the payment, not a scheme message", "key_fields": ["Quote ID and provider ID", "Currency pair, rate and amounts", "Expiry timestamp and tolerance", "Consent timestamp"]}], "accounting_operational": "Debit the customer account for the total agreed debit, credit the FX conversion account at the locked rate, and credit the settlement account for the destination amount, with fees as separate entries. If the quote expires and the customer declines a fresh quote, reverse any reservation exactly once with no conversion posting. A liquidity shortfall moves the payment to a held worklist with an ageing service level, and a provider execution that does not match the locked quote is stopped for investigation before any customer posting. Treasury monitors provider quote expiry rates, liquidity coverage by currency and corridor, and execution mismatches as provider performance measures.", "gherkin": ["Given an expired FX quote", "When execution is attempted", "Then the payment is not silently executed at a different rate", "And the customer is asked to accept a fresh quote", "Given a quote ID has already been consumed", "When the same quote ID is presented again", "Then the second use is rejected", "And a fresh quote is required"], "assessment": [{"question": "What must be bound to the payment as one FX quote contract?", "options": ["Provider name only", "Quote ID, currency pair, amounts, rate, fees, expiry and execution conditions", "Rate only", "Currency pair only"], "answer": 1, "explanation": "The quote contract includes the ID, pair, amounts, rate, fees, spread, expiry and execution conditions."}, {"question": "What is the difference between FX conversion and settlement currency availability?", "options": ["Liquidity is never a constraint", "Conversion is always instant", "A good rate does not help if the settlement currency is not available at the required time", "They are the same thing"], "answer": 2, "explanation": "Conversion sets the rate; liquidity determines whether the settlement currency can actually be supplied when needed."}, {"question": "What should happen if a quote ID is presented for a second payment?", "options": ["Reject the second use and require a fresh quote", "Accept it, since the rate is already known", "Ignore the quote ID", "Execute both payments at the same rate"], "answer": 0, "explanation": "A quote must be consumed once; a second use must be rejected."}, {"question": "Who bears FX risk between quote acceptance and settlement?", "options": ["Nobody", "Always the customer, whatever happens", "Always the provider", "The party defined by the quote contract, with the bank revalidating at execution and seeking fresh consent when terms change"], "answer": 3, "explanation": "Risk ownership is defined by the quote contract, and the bank must revalidate and obtain fresh consent when the locked terms no longer hold."}]}}, {"id": "INS-144", "kind": "insight", "title": "Currency liquidity constraint", "topic": "Currency liquidity constraint", "theme": "Cross-Border Instant", "text": "Distinguish FX conversion from availability of settlement currency at the required time.", "domain": "Liquidity & Treasury", "area": "Liquidity & Treasury", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch19s1", "title": "Why Liquidity Is the Lifeblood of Settlement", "url": "lessons/ch19s1"}, "case": {"status": "authored", "business_problem": "Crestfield Bank, a fictional bank, offers instant US dollar payments to customers in several corridors. The FX rate is competitive, the customer experience is smooth, and the marketing promises instant settlement. Yet on some mornings the payments fail or sit in a queue, and the treasury team discovers the cause only after customers complain: the bank does not hold enough US dollars in the right nostro account at the right time to settle the payments it has accepted.\n\nThe product team confuses two different things. FX conversion changes one currency into another at a rate. Liquidity is whether the settlement currency is actually available in the right account at the required time. A payment can have a perfect rate and still be unable to settle, because the dollars are in the wrong account, the correspondent is closed, or the nostro balance is committed to other payments.\n\nCrestfield Bank must distinguish FX conversion from availability of settlement currency at the required time, and design routing, liquidity checks and fallbacks so the bank only promises what its liquidity position can deliver.", "decision_exercise": {"scenario": "Crestfield Bank has accepted 200 instant US dollar payments for a corridor where the nostro balance covers only 120 of them. The FX rates are all locked and valid. What should the bank do with the remaining 80 payments?", "options": [{"id": "A", "text": "Hold or queue the remaining payments under a documented rule, tell the affected customers the realistic timing, and use an approved alternate route or liquidity source only where policy permits."}, {"id": "B", "text": "Change the FX rate on the remaining 80 to cover the shortfall."}, {"id": "C", "text": "Cancel all 200 payments and start again tomorrow."}, {"id": "D", "text": "Send all 200 anyway and hope the nostro is topped up before settlement."}], "correct_option": "A", "why": "Option A is correct because liquidity must be checked before settlement is promised, and a shortfall is handled by a governed hold, queue or approved alternate route with transparent customer communication. Option D is wrong because sending without cover creates settlement failure. Option B is wrong because changing a locked rate without consent breaks the quote contract. Option C is wrong because it penalises the 120 payments that can settle."}, "recommended_solution": "Check liquidity as a first class step in the payment flow, not as an afterthought in treasury. Before the bank promises an instant outcome, the payment engine must confirm the settlement currency balance in the correct nostro or settlement account, the correspondent availability, the cut off and the value date. That check uses live positions, not yesterday's balance, and it reserves the funds for the payment so a later payment cannot consume the same dollars.\n\nRoute with liquidity in mind. The routing service must evaluate eligibility, currency, country, service, cut off, cost and liquidity together, using current effective dated reference data. If the primary correspondent is unavailable or no longer supports the required currency or route, the engine re-evaluates against the same criteria and uses an approved alternate route only if policy permits. Otherwise it queues or rejects the payment with a transparent reason. It must never silently change the beneficiary, the settlement details or the rate to make a route fit.\n\nValidate the full correspondent chain before release. Each intermediary must support the currency, the country and the service, and each relationship must be current on the effective date. A chain with a missing or expired link is excluded, and the payment is held for repair or routed through an approved alternative. Routing decisions are recorded with the factors that produced them, so an analyst can explain why a payment took one route and not another.\n\nGive treasury a live view and the customer an honest one. Treasury monitors nostro balances, committed reservations, intraday liquidity usage and corridor demand, with alerts before a corridor runs short. The customer sees a realistic timing promise, and a payment that cannot settle instantly is held or queued with a clear status rather than shown as complete.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits an instant US dollar payment in the channel", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction and checks the FX quote and customer limits", "system": "Payment engine"}, {"step": 3, "actor": "Routing service", "action": "Evaluates eligible correspondents against currency, country, service, cut off and liquidity data", "system": "Routing service"}, {"step": 4, "actor": "Treasury service", "action": "Confirms and reserves the settlement currency in the correct nostro account", "system": "Liquidity and nostro service"}, {"step": 5, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud screening", "system": "Screening services"}, {"step": 6, "actor": "Payment engine", "action": "Builds the pacs.008 or pacs.009 message with the validated correspondent chain", "system": "Message builder"}, {"step": 7, "actor": "Clearing adapter", "action": "Submits the message through the selected correspondent and records the settlement instruction", "system": "Correspondent connector"}, {"step": 8, "actor": "Payment engine", "action": "Confirms settlement or releases the reservation and notifies the customer", "system": "Payment engine and notification service"}], "happy_path": "The customer submits a US dollar payment, routing selects an eligible correspondent with sufficient nostro liquidity, the funds are reserved, screening passes, the message is sent through the validated chain, settlement completes, the reservation converts to a final posting, and the customer sees a confirmed completion.", "negative_paths": [{"path": "Correspondent unavailable", "trigger": "The selected correspondent is temporarily unavailable or no longer supports the currency or route", "handling": "Re-evaluate routing against current data, use an approved alternate route only if policy permits, otherwise queue or reject with a transparent reason."}, {"path": "Liquidity insufficient", "trigger": "The nostro balance cannot cover the payment at the required time", "handling": "Hold or queue the payment under the documented rule, alert treasury, and tell the customer the realistic timing rather than promising instant settlement."}, {"path": "Missing or outdated correspondent data", "trigger": "The chain lacks a valid intermediary or a relationship has expired", "handling": "Exclude the invalid route, hold the payment for repair or select an approved alternative, and record the data gap for reference data governance."}, {"path": "Wrong intermediary selected", "trigger": "The payment is routed through an intermediary that cannot serve the destination or currency", "handling": "Trace the route decision, compare it with routing policy and reference data, correct the rule or the data, and hold affected payments for re-routing."}], "technical_data": "Hold nostro positions, reservations and committed amounts as live data with a correlation ID per payment, and enforce reservation as an atomic step so two payments cannot reserve the same funds. Version all routing reference data with effective dates and record the version used for each routing decision, including the factors that produced it. Validate BICs, agent sequences, currency support and country restrictions before release, and keep the routing decision, the liquidity check and the screening outcome as structured audit events. Make settlement posting idempotent so a late confirmation cannot post twice, and reconcile nostro movements against payment instructions intraday.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer where the customer leg is sent directly", "key_fields": ["End to End Identification", "Instructed amount and currency", "Debtor and creditor agents", "Intermediary agents in the validated chain"]}, {"message": "pacs.009", "purpose": "Financial institution transfer for the cover or settlement leg through the correspondent chain", "key_fields": ["Settlement amount and currency", "Debtor and creditor agents", "Underlying customer payment reference"]}, {"message": "pacs.002", "purpose": "Status report confirming acceptance or rejection of each leg", "key_fields": ["Original reference", "Status code", "Reason code where rejected"]}], "accounting_operational": "Debit the customer account and reserve the settlement currency in the nostro account at instruction time, then convert the reservation to a final nostro debit on settlement confirmation. If the payment is queued or rejected for liquidity, release the reservation exactly once and restore the customer balance where a debit was taken. Nostro reconciliation runs intraday against correspondent statements, and any break goes to a treasury worklist with an ageing service level. Treasury monitors nostro balances by currency and corridor, reservation ageing and alternate route usage, and sets intraday limits so one corridor cannot consume liquidity needed elsewhere. For context on US instant limits, FedNow and RTP each carry a USD 10 million maximum, so the constraint in this case is the bank's own nostro position, not the scheme limit.", "gherkin": ["Given an unavailable route", "When an approved alternative satisfies all routing constraints", "Then the engine selects it and records the decision factors", "And the customer is told the route that was used", "Given an expired correspondent relationship", "When routing is evaluated", "Then the route is excluded", "And an approved alternative or controlled exception is selected"], "assessment": [{"question": "What is the difference between FX conversion and settlement currency availability?", "options": ["They are the same thing", "Availability is only about the rate", "Conversion is never needed", "Conversion sets the rate; availability is whether the settlement currency is in the right account at the required time"], "answer": 3, "explanation": "A good rate does not settle a payment if the settlement currency is not available when and where it is needed."}, {"question": "What should happen when the primary correspondent is unavailable?", "options": ["Send the payment anyway", "Re-evaluate routing and use an approved alternate only if policy permits, otherwise queue or reject transparently", "Delete the payment", "Change the beneficiary to fit the route"], "answer": 1, "explanation": "Routing must be re-evaluated against current eligibility, currency, country, service, cut off, cost and liquidity data."}, {"question": "What is the FedNow maximum, effective November 2025?", "options": ["USD 1 million", "USD 10 million", "USD 100 million", "USD 100,000"], "answer": 1, "explanation": "The FedNow maximum is USD 10 million effective November 2025, with a participant default of USD 100,000."}, {"question": "Why must a routing decision record its decision factors?", "options": ["Routing decisions are never audited", "To slow the payment down", "So an analyst can explain why one route was chosen and prove it was valid for the currency and date", "For marketing"], "answer": 2, "explanation": "Explainable routing decisions with effective dated reference data are needed for control, investigation and audit."}]}}, {"id": "INS-145", "kind": "insight", "title": "AML and sanctions controls in instant payments", "topic": "AML and sanctions controls in instant payments", "theme": "Cross-Border Instant", "text": "Design fast automated controls with escalation and auditability; do not imply controls are bypassed.", "domain": "Compliance & Risk", "area": "Compliance & Risk", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch81s3", "title": "Cross-border data transfers: when a payment message leaves the region", "url": "lessons/ch81s3"}, "case": {"status": "authored", "business_problem": "Meridian Bank promises instant euro payments that complete within 10 seconds, but its compliance team knows that sanctions, AML and fraud checks can take longer than the rail allows. A payment to a newly added beneficiary, a payment with a name that partially matches a sanctions list, and a payment where the screening service is briefly unavailable all arrive on the same morning, and each one threatens the instant promise in a different way.\n\nThe tension is real and must not be resolved by cutting corners. The bank cannot bypass mandatory screening to meet a speed target, and it cannot hold every payment for manual review either, or the instant product stops being instant. Verification of Payee is mandatory for instant euro payments from 9 October 2025, so the beneficiary check is part of the synchronous flow as well.\n\nThe bank must design fast automated controls with escalation and auditability, so the great majority of payments clear automatically inside the limit, and the small number that need human judgement are held explicitly, with a clear reason and a service level.", "decision_exercise": {"scenario": "A Meridian Bank instant euro payment triggers a possible sanctions match. The 10 second execution limit is about to expire. The screening service cannot give a definitive clear or match within the window. What should the bank do?", "options": [{"id": "A", "text": "Hold the payment explicitly, tell the customer it is under review, route it to a compliance analyst with the match evidence, and record the decision and the deadline."}, {"id": "B", "text": "Tell the customer the payment succeeded while the review continues."}, {"id": "C", "text": "Release the payment to meet the 10 second limit and review it afterwards."}, {"id": "D", "text": "Reject the payment immediately without recording a reason."}], "correct_option": "A", "why": "Option A is correct because a possible sanctions match must be held for human judgement with a clear customer status, escalation and audit evidence. Option C is wrong because mandatory screening must never be bypassed to meet a speed target. Option D is wrong because a rejection without a recorded reason cannot be audited or explained. Option B is wrong because it misstates the payment status to the customer."}, "recommended_solution": "Separate controls by what must be synchronous and what may be post event, and document that split with risk appetite and legal advice. Sanctions screening of the payer, the beneficiary and the payment details, plus Verification of Payee, must be synchronous for instant euro payments. Transaction monitoring, behavioural analysis and some AML pattern detection may run post event where legally and scheme permitted, provided the post event work has a service level and a defined action when it finds something.\n\nMake the synchronous path fast by design. Use risk based orchestration so a low risk payment to a known beneficiary follows a short path, while a higher risk payment follows a longer path with more checks, and both paths share a single synchronous decision deadline. Run independent checks in parallel, cache reference data that is safe to cache, and give every screening service a hard timeout with an approved fail open or fail closed rule per control. A mandatory sanctions service that is unavailable must fail closed: the payment is held or rejected under the approved procedure, never released.\n\nTreat a potential match as a controlled hold, not as a system error. The hold carries the match evidence, the fields that matched, the screening version and the analyst queue, and the customer sees a clear under review status with a realistic next update time. False positives are recorded and fed back into tuning, so the same benign name does not hold the next payment for the same reason without review.\n\nKeep the audit trail complete. Every screening decision records the input data, the lists and versions used, the decision, the decision maker where human, the timestamp and the elapsed time. That evidence is what lets the bank prove to a regulator, an auditor or a customer that the control ran, that it ran on time, and that the outcome was the approved one.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits an instant euro payment to a beneficiary in the channel", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates the instruction and assigns a risk tier based on customer, beneficiary and amount", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Runs Verification of Payee and shows the verified beneficiary name for confirmation", "system": "Verification of Payee service"}, {"step": 4, "actor": "Screening services", "action": "Run sanctions, AML and fraud checks in parallel under a single decision deadline", "system": "Screening services"}, {"step": 5, "actor": "Payment engine", "action": "Applies the risk based decision: clear, hold for review, or reject", "system": "Payment engine"}, {"step": 6, "actor": "Compliance analyst", "action": "Reviews a held payment with the match evidence and records a clear or reject decision", "system": "Case management system"}, {"step": 7, "actor": "Clearing adapter", "action": "Submits a cleared payment to the instant clearing system", "system": "Scheme adapter"}, {"step": 8, "actor": "Payment engine", "action": "Confirms the outcome to the customer and starts post event monitoring where applicable", "system": "Notification and monitoring services"}], "happy_path": "The customer submits an instant euro payment, Verification of Payee confirms the beneficiary name, sanctions, AML and fraud checks all clear within the decision deadline, the payment is submitted to clearing, settlement completes within 10 seconds, and the customer sees a confirmed completion with the verified beneficiary name.", "negative_paths": [{"path": "Potential sanctions match", "trigger": "A name or detail partially matches a sanctions list", "handling": "Hold the payment explicitly, route it to a compliance analyst with the match evidence, and record the analyst decision and timestamp."}, {"path": "Screening service unavailable", "trigger": "A mandatory sanctions service does not respond", "handling": "Apply the approved fail closed rule, hold or reject under the procedure, and alert operations and compliance about the outage."}, {"path": "False positive", "trigger": "A benign beneficiary repeatedly triggers a low quality match", "handling": "Record the false positive, feed it into screening tuning, and keep the analyst decision on file so the next payment is handled consistently."}, {"path": "Changed beneficiary data", "trigger": "Beneficiary details change after screening has run", "handling": "Re-run the affected checks on the new data before release, and do not rely on a screening result for data that has changed."}], "technical_data": "Store the screening decision as structured data with the input fields, the list and version used, the match score and evidence, the decision, the decision maker and the timestamp, all linked by correlation ID. Give every screening call a hard timeout and a recorded fail open or fail closed outcome per control, and never allow a timeout to be treated silently as a pass. Version the risk rules and the screening configuration with effective dates, and record the version used for each payment. Keep the synchronous decision and the post event monitoring as separate records so an auditor can see what ran before settlement and what ran after. Protect the audit trail from alteration and retain it for the required period.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer submitted to clearing only after required controls pass", "key_fields": ["Debtor and creditor names and structured addresses", "Instructed amount and currency", "End to End Identification", "Purpose where required"]}, {"message": "pacs.002", "purpose": "Payment status report confirming clearing acceptance or rejection", "key_fields": ["Original reference", "Status code", "Reason code where rejected"]}, {"message": "Screening decision record", "purpose": "Internal record of each control outcome, not a scheme message", "key_fields": ["Control name and version", "Decision and match evidence", "Decision maker and timestamp", "Fail open or fail closed rule applied"]}], "accounting_operational": "No ledger posting occurs until the required controls have passed; a held payment creates a reservation only where the product design requires it, and a rejected payment releases any reservation exactly once. A payment held for compliance review sits on a compliance worklist with an ageing service level, and the customer is told it is under review rather than shown a false completion. Post event monitoring findings that require action create a linked investigation case with its own accounting treatment, never by editing the original payment record. Compliance reports screening pass rates, hold rates, false positive rates, decision times and service availability as control effectiveness measures.", "gherkin": ["Given a mandatory sanctions service is unavailable", "When policy requires fail closed processing", "Then the payment is held or rejected according to the approved procedure", "And the outage and the decision are recorded", "Given a payment triggers a possible sanctions match", "When the decision deadline expires without a definitive clear", "Then the payment is held for analyst review", "And the customer is told it is under review"], "assessment": [{"question": "What is the maximum execution time for an instant euro payment?", "options": ["5 seconds", "10 seconds", "20 seconds", "One business day"], "answer": 1, "explanation": "Regulation (EU) 2024/886 sets a maximum execution time of 10 seconds."}, {"question": "When is Verification of Payee mandatory for instant euro payments?", "options": ["From 9 October 2025", "Only for high value payments", "It is never mandatory", "From 5 October 2025"], "answer": 0, "explanation": "Verification of Payee is mandatory for instant euro payments from 9 October 2025."}, {"question": "What must happen when a mandatory sanctions service is unavailable and policy requires fail closed processing?", "options": ["Release the payment to meet the time limit", "Skip the check and review later", "Tell the customer the payment succeeded", "Hold or reject the payment under the approved procedure"], "answer": 3, "explanation": "Fail closed means the payment is held or rejected, never released to meet the clock."}, {"question": "What may run post event rather than synchronously?", "options": ["Sanctions screening of the payer", "Verification of Payee", "Transaction monitoring and pattern detection where legally and scheme permitted", "Sanctions screening of the beneficiary"], "answer": 2, "explanation": "Only work that is legally and scheme permitted may move to post event monitoring; mandatory screening and Verification of Payee stay synchronous."}]}}, {"id": "INS-146", "kind": "insight", "title": "Fraud controls in real-time payment journeys", "topic": "Fraud controls in real-time payment journeys", "theme": "Cross-Border Instant", "text": "Consider risk signals, velocity, confirmation, intervention and post-transaction monitoring.", "domain": "Fraud & Risk", "area": "Fraud & Risk", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch43s6", "title": "Fraud Controls, Monitoring and Incident Response", "url": "lessons/ch43s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank offers instant payments that settle in seconds, which is exactly what customers want and exactly what fraudsters want too. A fraudster who gains access to a customer account can move money out before the customer notices, and an authorised push payment scam can persuade the customer to send the money themselves. The bank's fraud team sees the pattern in the data: new beneficiaries, unusual amounts, high velocity across accounts, logins from new devices, and payments made under time pressure.\n\nThe challenge is to stop fraud without stopping genuine payments. A control that challenges every payment will drive customers away, and a control that challenges none will let fraud through. The bank must consider risk signals, velocity, confirmation, intervention and post transaction monitoring as one journey, so the friction lands on the risky payment and not on the routine one.\n\nThe case matters because instant payments are hard to recall. Once the money has settled, recovery depends on the beneficiary bank, the scheme rules and the speed of the fraud report, so prevention and fast intervention matter far more than after the event recovery.", "decision_exercise": {"scenario": "A Meridian Bank customer who normally sends small domestic payments suddenly sends a large instant cross-border payment to a new beneficiary, from a new device, late at night. The payment passes sanctions screening. What should the fraud control do?", "options": [{"id": "A", "text": "Block the customer account permanently without telling them why."}, {"id": "B", "text": "Let it through, since sanctions screening passed."}, {"id": "C", "text": "Split the payment into smaller amounts so it looks less risky."}, {"id": "D", "text": "Step up the journey with a strong confirmation, show the verified beneficiary name, check velocity and device signals, and hold or challenge the payment where the combined risk exceeds the approved threshold."}], "correct_option": "D", "why": "Option D is correct because the combined signals justify friction: step up authentication, confirm the beneficiary, and hold or challenge where the threshold is breached. Option B is wrong because sanctions clearance is not fraud clearance. Option A is wrong because a permanent block without explanation or a defined process is disproportionate and unauditable. Option C is wrong because splitting a payment to evade a control is itself a suspicious act."}, "recommended_solution": "Score every payment in real time from a set of signals, not from a single rule. The signals include the beneficiary history, the amount against the customer profile, velocity across the account and across the bank, device and location signals, time of day, and whether the payment follows a recent change such as a new payee or a changed contact detail. Each signal contributes to a risk score, and the score drives a proportionate response: proceed, step up with additional authentication, show the verified beneficiary name and ask for explicit confirmation, hold for analyst review, or reject.\n\nUse confirmation as a control, not as a formality. Verification of Payee, mandatory for instant euro payments from 9 October 2025, shows the customer whether the name they entered matches the account, and a mismatch or a close match must be presented clearly with a pause before the customer can proceed. Confirmation of the amount, the beneficiary and the purpose, in plain language, is the last chance to stop an authorised push payment scam, so it must never be a pre ticked box or a screen the customer can rush past.\n\nIntervene in the journey, not only after it. A payment that exceeds the risk threshold is held with a clear status and a defined review path, and the customer is contacted through a trusted channel. The hold records the signals, the score, the threshold and the decision, so the analyst can see why the payment was stopped and the customer can understand what happened.\n\nMonitor after the transaction as well. Post transaction monitoring looks for patterns a single payment cannot show, such as money moving quickly onward through several accounts, and it feeds confirmed fraud back into the scoring model and the velocity rules. A fraud report from a customer triggers a fast recall and beneficiary bank engagement process, with the original payment record preserved and every step logged.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Logs in and submits an instant payment to a beneficiary", "system": "Mobile banking"}, {"step": 2, "actor": "Fraud engine", "action": "Scores the payment from beneficiary history, amount, velocity, device and behaviour signals", "system": "Fraud detection service"}, {"step": 3, "actor": "Payment engine", "action": "Runs Verification of Payee and shows the verified beneficiary name for confirmation", "system": "Verification of Payee service"}, {"step": 4, "actor": "Customer", "action": "Confirms the beneficiary, amount and purpose, or completes step up authentication where required", "system": "Mobile banking"}, {"step": 5, "actor": "Payment engine", "action": "Applies the risk decision: proceed, hold for review, or reject", "system": "Payment engine"}, {"step": 6, "actor": "Fraud analyst", "action": "Reviews a held payment with the signals and score, and records a release or reject decision", "system": "Case management system"}, {"step": 7, "actor": "Clearing adapter", "action": "Submits a cleared payment to the instant clearing system", "system": "Scheme adapter"}, {"step": 8, "actor": "Payment engine", "action": "Confirms the outcome and starts post transaction monitoring", "system": "Notification and monitoring services"}], "happy_path": "A customer sends a routine payment to a known beneficiary. The risk score is low, Verification of Payee confirms the name, the customer confirms the amount, screening passes, the payment settles within the instant limit, and the customer sees a confirmed completion with no added friction.", "negative_paths": [{"path": "High risk new beneficiary", "trigger": "A large payment to a new beneficiary from a new device scores above the threshold", "handling": "Step up authentication, show the verified beneficiary name, and hold for analyst review where the risk remains high."}, {"path": "Authorised push payment scam", "trigger": "The customer is persuaded to send money to a fraudster and confirms the payment themselves", "handling": "Use the confirmation screen and mismatch warnings as prevention, and on report, start the fast recall process with the beneficiary bank and preserve all evidence."}, {"path": "Velocity attack", "trigger": "Many payments leave one account or many accounts in a short window", "handling": "Apply velocity limits, hold further payments, alert the fraud team, and review the accounts as a linked pattern."}, {"path": "Fraud service timeout", "trigger": "The fraud scoring service does not respond within its deadline", "handling": "Apply the approved fail open or fail closed rule for that control, hold or reject explicitly where required, and record the decision."}], "technical_data": "Store the risk score, the contributing signals, the threshold applied, the model and rule versions, the Verification of Payee outcome and the customer confirmation as structured data linked by correlation ID. Version the fraud rules and the scoring model with effective dates and record the version used for each payment. Make the decision auditable: the analyst must be able to reconstruct why a payment proceeded, was challenged or was held. Keep the synchronous fraud decision separate from post transaction monitoring, and feed confirmed fraud outcomes back into tuning with a controlled change process. Protect customer and device data under the applicable privacy rules and limit analyst access to what the case needs.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer submitted only after fraud and compliance decisions pass", "key_fields": ["Debtor and creditor names and accounts", "Instructed amount and currency", "End to End Identification", "Purpose where required"]}, {"message": "pacs.002", "purpose": "Payment status report confirming clearing acceptance or rejection", "key_fields": ["Original reference", "Status code", "Reason code where rejected"]}, {"message": "Fraud decision record", "purpose": "Internal record of the risk score, signals and decision, not a scheme message", "key_fields": ["Risk score and threshold", "Signals that contributed", "Rule and model version", "Decision maker and timestamp"]}], "accounting_operational": "No ledger posting occurs for a payment held or rejected on fraud grounds; any reservation is released exactly once. A payment released after review posts normally, with the review decision linked to the ledger record. Confirmed fraud creates a linked investigation and recovery case, with any recall or return posted as a separate linked event, never by editing the original payment. Operations monitor fraud detection rates, false positive rates, step up rates, hold ageing and recovery rates, and review thresholds regularly so genuine customers are not over challenged.", "gherkin": ["Given a payment scores above the approved fraud threshold", "When the risk decision is applied", "Then the payment is challenged or held for review", "And the signals and score are recorded", "Given Verification of Payee returns a name mismatch", "When the customer is shown the mismatch", "Then the customer must explicitly confirm before proceeding", "And the mismatch is recorded with the payment"], "assessment": [{"question": "Why is sanctions clearance not enough to clear a payment for fraud?", "options": ["Sanctions screening is slower", "Sanctions screening checks lists; fraud scoring checks behaviour, velocity, device and beneficiary signals", "Fraud checks are never needed", "Sanctions and fraud are the same check"], "answer": 1, "explanation": "Sanctions and fraud controls answer different questions and both must run."}, {"question": "What should a Verification of Payee mismatch trigger?", "options": ["Automatic cancellation of the account", "Nothing, the customer can ignore it", "A higher FX rate", "A clear warning and an explicit customer confirmation before proceeding"], "answer": 3, "explanation": "A mismatch must be presented clearly with a pause and an explicit confirmation, as the last chance to stop a misdirected or scam payment."}, {"question": "What is the right response to a velocity attack across several accounts?", "options": ["Delete the accounts", "Increase the limits", "Apply velocity limits, hold further payments and review the pattern as linked", "Let each payment through individually"], "answer": 2, "explanation": "Velocity is a pattern signal, so the response must treat the payments as linked and stop the pattern."}, {"question": "Why does post transaction monitoring matter for instant payments?", "options": ["It detects patterns a single payment cannot show, such as money moving quickly onward", "It is only for marketing", "It replaces all pre payment checks", "Instant payments can always be recalled easily"], "answer": 0, "explanation": "Once an instant payment settles, recovery is hard, so post transaction pattern detection and fast recall matter."}]}}, {"id": "INS-147", "kind": "insight", "title": "Ambiguous payment status across multiple PSPs", "topic": "Ambiguous payment status across multiple PSPs", "theme": "Cross-Border Instant", "text": "Define consistent status semantics, status enquiry, traceability and customer communication.", "domain": "Payment Status & Operations", "area": "Payment Status & Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s7", "title": "Exercise: Trace One Payment Through Every Possible Failure Scenario (one USD cross-border payment traced through reject, return, recall, duplicate, timeout and outage, with what happens at each step)", "url": "lessons/ch41s7"}, "case": {"status": "authored", "business_problem": "A customer of Meridian Bank, a fictional bank, sends a cross-border payment and then calls the contact centre. The app shows pending, the payment engine shows processed, and the ledger has no matching posting. The agent cannot tell the customer whether the money has left, whether it has arrived, or whether it is lost. The customer, understandably, assumes the worst.\n\nThe payment has travelled through several payment service providers, and each one uses its own status words. One provider calls the payment processed when it has accepted the message; another uses processed to mean settled. A cover leg has been returned, but the customer leg may have a different state, and nobody has linked the two. The tracking reference exists, but one participant has not reported a status against it.\n\nThe bank must define consistent status semantics, status enquiry, traceability and customer communication, so every system, every provider and every customer sees the same truth about the same payment.", "decision_exercise": {"scenario": "A cross-border payment shows pending in the channel, processed in the payment engine, and no posting in the ledger. The customer asks whether the money has left their account. What should the operations analyst do first?", "options": [{"id": "A", "text": "Resend the payment so the customer has a clean record."}, {"id": "B", "text": "Tell the customer the payment has failed, since the ledger has no posting."}, {"id": "C", "text": "Tell the customer the payment has settled, since the engine shows processed."}, {"id": "D", "text": "Treat the status as ambiguous, check the authoritative source for each state, correlate the records by reference and UETR, and place the item in an exception queue if the state cannot be safely inferred."}], "correct_option": "D", "why": "Option D is correct because ambiguous status must be resolved from authoritative sources and correlation, never by guessing or resending. Option C is wrong because processed in the engine does not prove settlement. Option B is wrong because a missing ledger posting may mean a lag or a missing event, not a failure. Option A is wrong because resending an uncertain payment can duplicate it."}, "recommended_solution": "Define one canonical payment state model for the whole bank and publish the status vocabulary that every system and every provider must use. The model separates instruction received, validated, screened, submitted to clearing, accepted by clearing, settled, rejected, returned and unknown, and it states which system is authoritative for each transition. Technical processing is never equated with settlement finality, and the channel may only show a status the authoritative source supports.\n\nUse a persistent end to end tracking reference, such as the UETR where applicable, and propagate it through every participating message. Each participant reports status events with a timestamp and a source institution, and the bank stores the full event history rather than overwriting it. A customer timeline then shows a coherent sequence with the source and time of each event, and a missing report from one participant is visible as a gap rather than hidden by a later status.\n\nModel the cover leg and the customer leg separately. A pacs.009 cover return does not automatically define the pacs.008 customer leg state. Correlate both legs by stable references, determine the customer leg state first, and only then decide the customer impact. That separation prevents a settlement event from being misreported as a customer failure, or a customer credit from being missed because the cover leg failed.\n\nGive ambiguous status a governed home. When systems disagree, or when an event arrives out of order, the payment goes to an exception queue with the conflicting evidence attached, an ageing service level and a named owner. A status enquiry by correlation ID or UETR returns the current known state, and a retry uses the same idempotency key so an enquiry never creates a new payment.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits a cross-border payment and receives a tracking reference", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Assigns the UETR where applicable and records the instruction state", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Submits the customer leg and, where used, the cover leg with linked references", "system": "Scheme adapter"}, {"step": 4, "actor": "Participating PSP", "action": "Reports a status event with timestamp and source institution against the tracking reference", "system": "Tracker service"}, {"step": 5, "actor": "Payment engine", "action": "Applies each status event in order to the canonical state model without overwriting history", "system": "Payment engine"}, {"step": 6, "actor": "Payment engine", "action": "Posts the ledger entry only on the authoritative settlement event", "system": "Core ledger"}, {"step": 7, "actor": "Operations analyst", "action": "Investigates any conflicting or missing status in the exception queue", "system": "Operations worklist"}, {"step": 8, "actor": "Payment engine", "action": "Shows the customer a coherent timeline with source and timestamp for each status", "system": "Customer channel"}], "happy_path": "The customer submits a payment with a UETR. Each participating institution reports its status event with a timestamp, the events apply in order to the canonical model, the ledger posts on the authoritative settlement event, and the customer sees a coherent timeline that ends in a confirmed beneficiary credit.", "negative_paths": [{"path": "Conflicting statuses", "trigger": "Two participants report different states for the same payment", "handling": "Keep both events in history, apply the authoritative source rule, and route the conflict to investigation rather than overwriting one status with the other."}, {"path": "Missing UETR or missing report", "trigger": "A participant does not report a status, or the tracking reference is absent", "handling": "Show the gap in the timeline, run a status enquiry by correlation ID, and escalate under the investigation service level."}, {"path": "Cover return with unclear customer leg", "trigger": "A cover leg is returned while the customer leg state is unknown", "handling": "Correlate both legs, establish the customer leg state first, and investigate before posting any customer adjustment."}, {"path": "Out of order events", "trigger": "An older status event arrives after a newer state has been applied", "handling": "Apply event versioning so the payment state does not regress, and record the late event in history without changing the current state."}], "technical_data": "Persist the UETR where applicable, the correlation ID, the End to End Identification and every status event with its source, timestamp and version, as an append only history. Enforce a state machine with an authoritative source per transition, and make status consumers idempotent so duplicate events cannot double post or regress state. Keep customer leg and cover leg records separate with linked IDs and their own state machines. Provide a status enquiry API that returns the current known state by reference without creating a new transaction, and reconcile the status store against the ledger and the clearing acknowledgements intraday.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer carrying the tracking reference", "key_fields": ["UETR where applicable", "End to End Identification", "Debtor and creditor agents", "Instructed amount and currency"]}, {"message": "pacs.009 COV", "purpose": "Cover leg carrying the linked customer payment reference", "key_fields": ["UETR where applicable", "Underlying customer payment reference", "Cover amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report from each participant", "key_fields": ["Original reference and UETR", "Status code", "Reason code where rejected", "Timestamp and source"]}, {"message": "camt.054", "purpose": "Debit or credit notification supporting the ledger record", "key_fields": ["Account identification", "Amount and currency", "Related payment reference"]}, {"message": "camt.053", "purpose": "Account statement supporting reconciliation of postings against status events", "key_fields": ["Account identification", "Statement entries with references", "Opening and closing balances"]}], "accounting_operational": "Ledger postings follow only the authoritative settlement event, so a channel or engine status alone never creates a posting. A payment in an unknown state holds any funds in suspense with a linked investigation case, and any later confirmed outcome posts as a linked event, never by editing the original record. Cover and customer legs reconcile separately against their own nostro and settlement accounts, and breaks age on an operations worklist with a service level for customer contact. The bank reports status freshness, missing report rates and investigation ageing as operational quality measures, and a tracking reference is never presented to a customer as proof of settlement on its own.", "gherkin": ["Given a payment with a valid tracking reference", "When a participating institution reports a new status", "Then the timeline records the event without overwriting prior history", "And the source and timestamp are shown", "Given out of order status events", "When an older event arrives after a newer state", "Then the payment state does not regress", "And the late event is recorded in history"], "assessment": [{"question": "What does a UETR provide, and what does it not prove?", "options": ["It proves settlement by itself", "It is only for domestic payments", "It replaces all status messages", "It provides end to end traceability; it does not by itself prove settlement"], "answer": 3, "explanation": "A tracking reference lets participants report against one payment, but settlement must be proven by the authoritative settlement event."}, {"question": "Which system is authoritative for settlement?", "options": ["The customer channel", "The screening service", "Whichever system reports first", "The system defined as authoritative for the settlement transition in the canonical state model"], "answer": 3, "explanation": "Each state transition has a defined authoritative source, and settlement is proven by that source, not by a channel label."}, {"question": "What should happen when the channel shows pending but the engine shows processed?", "options": ["Treat the status as ambiguous, correlate records and investigate", "Resend the payment", "Assume the payment settled", "Delete the engine record"], "answer": 0, "explanation": "Conflicting system states must be resolved from authoritative sources and correlation, with an exception queue where the state cannot be safely inferred."}, {"question": "Why must cover leg and customer leg states be modelled separately?", "options": ["Cover legs are never tracked", "Customer legs are never tracked", "They always have the same state", "One leg can be returned or rejected while the other has a different state"], "answer": 3, "explanation": "A cover return does not automatically define the customer leg outcome, so each leg needs its own state and reconciliation."}]}}, {"id": "INS-148", "kind": "insight", "title": "Interoperability as a business and operating model", "topic": "Interoperability as a business and operating model", "theme": "Cross-Border Instant", "text": "Assess governance, participant responsibilities, regulatory cooperation and dispute processes.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch83s4", "title": "Local payment methods by market: what changes when you cross a border", "url": "lessons/ch83s4"}, "case": {"status": "authored", "business_problem": "Two fictional banks, Meridian Bank and Harbourline Bank, have connected their instant payment systems and the first payments flow. Then a payment fails after the sender is debited, and neither bank can agree who should investigate, who should return the funds, or how long the customer should wait. One bank points to the API contract, the other points to its scheme rules, and the customer waits while the two banks argue.\n\nThe connection works technically, but the business and operating model does not exist. Nobody has agreed the governance, the participant responsibilities, the regulatory cooperation or the dispute process. Each bank assumed the other owned the failure, the liquidity, the compliance decision and the customer communication.\n\nThe banks need an interoperability model that is a business agreement first and a technical connection second, with governance, responsibilities, regulatory cooperation and disputes all defined before volume grows.", "decision_exercise": {"scenario": "A cross-border instant payment between Meridian Bank and Harbourline Bank fails after the sender is debited. No destination confirmation arrives. As the business analyst for Meridian Bank, what does the operating model need to say first?", "options": [{"id": "A", "text": "That the payment will be resent automatically until it succeeds."}, {"id": "B", "text": "That the model names the investigating bank, the timeout, the return or compensation rule, the customer communication owner, the dispute process and the service levels before the failure happens."}, {"id": "C", "text": "That the banks will argue about ownership after each failure."}, {"id": "D", "text": "That the customer should wait indefinitely until someone volunteers to investigate."}], "correct_option": "B", "why": "Option B is correct because an operating model must define ownership, timeouts, compensation, communication and disputes in advance. Option D is wrong because an indefinite wait is not a service level. Option C is wrong because ownership must be agreed before a failure, not negotiated during one. Option A is wrong because blind resubmission can duplicate the payment."}, "recommended_solution": "Write the interoperability agreement as a business document with a technical annex, not the other way round. The business document names the participants, the corridors, the services, the customer promise per corridor, the pricing and fee split, the liquidity and settlement arrangements, and the regulatory responsibilities of each participant. The technical annex then states the message formats, the scheme rules, the status vocabulary, the timeouts, the idempotency rules and the change process. Both documents are versioned and signed, and no corridor goes live until both are agreed.\n\nAssign a single accountable owner for each outcome. One participant owns the sender communication, one owns the investigation for a defined failure type, and one owns the return or compensation decision under the scheme rules. Ownership is defined by failure type, not by who happens to answer the phone, so a sender debit without destination confirmation always has a named investigator and a named clock.\n\nAgree the regulatory cooperation in advance. Each participant states which compliance checks it performs, which data it shares, how it handles a sanctions match, and how it cooperates with the other participant and with regulators when a payment is held. Data sharing is limited to what the investigation needs, and the audit trail is kept by each participant so the full journey can be reconstructed.\n\nDefine disputes as a process with stages and clocks. The first stage is an inter PSP investigation by reference, with a defined timeout and a status enquiry that returns the current known state. The second stage is a formal dispute with evidence, a decision owner and a resolution time. The third stage is escalation to the scheme or to the regulator where the scheme provides for it. At every stage the customer is told who is handling the case and when the next update will arrive.", "flow_steps": [{"step": 1, "actor": "Governance board", "action": "Approves the corridor, the participants, the customer promise and the service levels", "system": "Governance forum"}, {"step": 2, "actor": "Sender bank", "action": "Accepts the customer instruction and confirms the corridor terms", "system": "Payment engine"}, {"step": 3, "actor": "Sender bank", "action": "Runs its defined compliance and fraud checks and debits the sender", "system": "Screening services"}, {"step": 4, "actor": "Orchestration layer", "action": "Settles through the agreed arrangement and sends the destination leg", "system": "Cross-border orchestration"}, {"step": 5, "actor": "Destination bank", "action": "Runs its defined checks and credits the beneficiary", "system": "Destination payment system"}, {"step": 6, "actor": "Orchestration layer", "action": "Confirms the destination credit or triggers the agreed failure process at timeout", "system": "Cross-border orchestration"}, {"step": 7, "actor": "Investigating bank", "action": "Investigates by reference under the agreed timeout and service level", "system": "Inter PSP investigation service"}, {"step": 8, "actor": "Sender bank", "action": "Returns or compensates funds under the agreed rule and tells the customer the outcome", "system": "Payment engine and notification service"}], "happy_path": "The corridor operates under a signed agreement. The sender bank accepts the payment, both banks run their defined checks, the destination bank credits the beneficiary, the orchestration confirms the credit, and the customer sees a confirmed completion with the reference and value date.", "negative_paths": [{"path": "Failure after sender debit", "trigger": "The destination leg fails or times out after the sender is debited", "handling": "The named investigating bank runs a status enquiry by reference, and funds are returned or compensated under the agreed rule with exactly one financial effect."}, {"path": "Dispute over responsibility", "trigger": "The two banks disagree about which participant caused the failure", "handling": "Follow the staged dispute process with evidence, a decision owner and a resolution clock, rather than negotiating ownership during the customer wait."}, {"path": "Compliance hold by one participant", "trigger": "The destination bank holds the payment on a sanctions or AML concern", "handling": "Apply the agreed hold process, share only the data the investigation needs, and tell the customer the payment is under review with a next update time."}, {"path": "Scheme or rule change", "trigger": "A scheme rule, limit or cut off changes on one side of the corridor", "handling": "Apply the agreed change process with notice, version the change, test it, and update the customer promise before the change takes effect."}], "technical_data": "Keep the agreement, the corridor configuration and the scheme rules as versioned records with effective dates, and record the version used for each payment. Use a correlation ID and, where applicable, a UETR across both participants, with status events, investigation events and dispute events stored as an append only history. Make status and investigation handling idempotent so duplicate reports cannot double post or double refund. Define data sharing fields explicitly, limit them to the investigation need, and retain the audit trail on each side so the journey can be reconstructed jointly.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer between the participating banks", "key_fields": ["UETR where applicable", "End to End Identification", "Debtor and creditor agents", "Instructed amount and currency"]}, {"message": "pacs.002", "purpose": "Payment status report from each participant", "key_fields": ["Original reference and UETR", "Status code", "Reason code where rejected"]}, {"message": "pacs.004", "purpose": "Payment return where a settled payment must be returned under the scheme rules", "key_fields": ["Original payment reference and UETR", "Return reason code", "Returned amount and currency"]}, {"message": "Investigation record", "purpose": "Inter PSP investigation case, not a scheme message", "key_fields": ["Case reference and payment reference", "Investigating bank and timeout", "Evidence and decision", "Customer communication log"]}], "accounting_operational": "Each participant posts its own leg on its own authoritative event, and the settlement account between them reconciles daily. A failed payment after sender debit moves the funds to suspense with a linked investigation case, and any return or compensation posts as a separate linked event, never by editing the original debit. Dispute cases age on a joint worklist with service levels for investigation, decision and customer update, and the banks report failure rates, timeout rates, investigation ageing and dispute outcomes as corridor quality measures. Liquidity and settlement positions are monitored jointly so one participant's shortfall does not silently become the other's settlement failure.", "gherkin": ["Given the originating leg is accepted but destination confirmation is absent", "When the timeout threshold is reached", "Then the payment enters an unknown or investigation state", "And the named investigating bank is assigned with a service level", "Given a mandatory sanctions service is unavailable", "When policy requires fail closed processing", "Then the payment is held or rejected according to the approved procedure", "And the decision is shared with the other participant as agreed"], "assessment": [{"question": "What must an interoperability operating model define before a corridor goes live?", "options": ["The logo placement", "The API only", "Marketing copy only", "Governance, participant responsibilities, regulatory cooperation and dispute processes"], "answer": 3, "explanation": "Interoperability is a business and operating model, not just a technical connection."}, {"question": "Who should investigate a payment that fails after the sender is debited?", "options": ["The bank named as investigator for that failure type, under an agreed timeout and service level", "The customer", "Whichever bank answers the phone first", "Nobody, the customer should investigate"], "answer": 0, "explanation": "Ownership must be defined by failure type in advance, with a clock and a service level."}, {"question": "What is the first stage of a cross-border payment dispute?", "options": ["Court action", "Resending the payment", "An inter PSP investigation by reference with a defined timeout", "Deleting the payment"], "answer": 2, "explanation": "Disputes start with a structured inter PSP investigation, then a formal dispute, then escalation where the scheme provides for it."}, {"question": "How should a returned payment be recorded?", "options": ["By editing the original payment record", "As a new linked financial event with its own reference and reason, leaving the original record immutable", "By deleting the original", "By ignoring it"], "answer": 1, "explanation": "A return is a linked event, not an erasure of the original payment."}]}}, {"id": "INS-149", "kind": "insight", "title": "Customer transparency on fees and FX", "topic": "Customer transparency on fees and FX", "theme": "Cross-Border Instant", "text": "Show total cost, applied rate, fee breakdown and expected delivery status.", "domain": "Customer Experience", "area": "Customer Experience", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch15s6", "title": "Transparency: fees, rates and time in the open", "url": "lessons/ch15s6"}}, {"id": "INS-150", "kind": "insight", "title": "Failure and timeout across corridor legs", "topic": "Failure and timeout across corridor legs", "theme": "Cross-Border Instant", "text": "Handle uncertain outcome, status enquiry, no-duplicate retry and inter-PSP investigation.", "domain": "Payment Operations", "area": "Payment Operations", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch41s7", "title": "Exercise: Trace One Payment Through Every Possible Failure Scenario (one USD cross-border payment traced through reject, return, recall, duplicate, timeout and outage, with what happens at each step)", "url": "lessons/ch41s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank, a fictional bank, runs an instant cross-border corridor where the payment crosses two fast payment systems joined by an orchestration layer. A customer sends money, the app times out, and the customer taps send again. The bank now has two instructions, one debit, no destination confirmation, and a customer who does not know whether the money has gone.\n\nThe failure is not a single broken step. It is an uncertain outcome spread across corridor legs: the originating leg may have been accepted, the destination leg may have succeeded late, the response may have been lost, or the payment may never have left. Each possibility needs a different response, and the wrong response, a blind resubmission or a premature refund, creates a duplicate payment or a double compensation.\n\nThe bank must handle uncertain outcome, status enquiry, no duplicate retry and inter PSP investigation as one disciplined process, so every timeout ends in a known outcome with exactly one financial effect.", "decision_exercise": {"scenario": "A customer submits an instant cross-border payment, the channel times out with no response, and the customer retries with a new instruction. The payment engine shows one accepted payment and one duplicate instruction. What should the bank do?", "options": [{"id": "A", "text": "Treat the timeout as an unknown outcome, enquire by the original correlation ID, deduplicate the retry with the same idempotency key, and resolve the original payment before creating any new financial effect."}, {"id": "B", "text": "Refund the customer immediately and also send the payment, to be safe."}, {"id": "C", "text": "Execute both instructions, since the customer sent both."}, {"id": "D", "text": "Cancel both and tell the customer to start again tomorrow."}], "correct_option": "A", "why": "Option A is correct because a timeout is an unknown outcome, not a failure, and it must be resolved by enquiry and deduplication before any new posting. Option C is wrong because it can duplicate the payment. Option D is wrong because it discards a payment that may already have settled. Option B is wrong because it can both credit the beneficiary and refund the sender."}, "recommended_solution": "Treat every timeout as an unknown outcome, never as an automatic failure and never as an automatic success. The channel must show a pending or unknown status, not a failure, and the payment engine must hold the payment in an unknown state until an authoritative event resolves it. That discipline is what stops a customer retry from becoming a duplicate payment.\n\nResolve the unknown by enquiry, not by resubmission. The payment engine queries the orchestration layer, the destination rail and the ledger by correlation ID and, where applicable, by UETR, and compares the leg states. A retry from the channel must carry the same idempotency key as the original instruction, so the engine recognises it as the same payment and returns the current known state instead of creating a new transaction. Only when the enquiry proves the original payment did not execute may a new instruction be created, and it carries a new idempotency key.\n\nModel each corridor leg separately with an overall orchestration state. The originating leg, the settlement leg and the destination leg each have their own state machine, timeout and confirmation rule, and the overall state is unknown until the required leg confirmations have arrived or the timeout has triggered investigation. A late success after a timeout is a known race: the late event is applied to the original payment, and any refund already issued is reversed or reconciled under the defined process, so the outcome is never both a beneficiary credit and a sender refund.\n\nGive the unknown state a governed investigation path. At the defined timeout the payment moves to an inter PSP investigation with a named owner, a service level and a customer communication plan. The investigation uses status enquiry, tracker events and ledger evidence, and it closes only when the outcome is proven: settled, rejected, returned or compensated, each with its own linked accounting event.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Submits an instant cross-border payment in the channel", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Assigns a correlation ID and an idempotency key and records the instruction", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Debits the sender where the product design requires it and initiates the originating leg", "system": "Payment engine and originating rail"}, {"step": 4, "actor": "Orchestration layer", "action": "Forwards the payment through the settlement arrangement to the destination rail", "system": "Cross-border orchestration"}, {"step": 5, "actor": "Channel", "action": "Times out waiting for a response and shows the customer a pending or unknown status", "system": "Mobile banking"}, {"step": 6, "actor": "Payment engine", "action": "Runs a status enquiry by correlation ID across the legs and the ledger", "system": "Payment engine"}, {"step": 7, "actor": "Operations analyst", "action": "Investigates the unknown outcome with the destination participant where the enquiry cannot resolve it", "system": "Inter PSP investigation service"}, {"step": 8, "actor": "Payment engine", "action": "Applies the proven outcome once, posts the linked accounting, and tells the customer the final result", "system": "Payment engine and notification service"}], "happy_path": "The customer submits a payment, the originating leg is accepted, the orchestration settles it, the destination leg credits the beneficiary, the confirmation arrives within the timeout, the ledger posts once, and the customer sees a confirmed completion with the reference.", "negative_paths": [{"path": "Timeout after submission with unknown outcome", "trigger": "The channel times out and it is unclear whether the engine accepted or executed the payment", "handling": "Treat the outcome as unknown, enquire by correlation ID, expose a pending or unknown state, and retry only with the same idempotency key."}, {"path": "Late success after timeout", "trigger": "A destination success arrives after the timeout and after a refund was considered", "handling": "Apply the late event to the original payment and resolve it without both crediting the beneficiary and refunding the sender."}, {"path": "Duplicate retry", "trigger": "The customer retries the same payment with a new instruction", "handling": "Deduplicate by idempotency key, return the current known state, and create no new financial effect."}, {"path": "Return and success race", "trigger": "A return and a success event arrive for the same payment in either order", "handling": "Apply event ordering and the leg state machine, hold the payment for investigation where the race cannot be resolved safely, and post only the proven outcome."}], "technical_data": "Use a durable payment record with a correlation ID, an idempotency key and, where applicable, a UETR, and persist the state of each leg separately with timestamps and event versions. Make every consumer idempotent with persisted inbound message IDs and processed outcomes, and enforce a state machine that prevents regression and duplicate posting. Use outbox and inbox patterns so a status event is never lost between systems, and provide a status enquiry API that returns the current known state by reference without creating a transaction. Log every enquiry, retry, timeout and investigation event as structured audit data, and reconcile the status store against the ledger and the clearing acknowledgements intraday.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment initiation carrying the idempotency key and references", "key_fields": ["Instruction Identification", "Idempotency key", "Requested execution date", "Debtor and creditor details"]}, {"message": "pacs.008", "purpose": "Customer credit transfer for the payment leg", "key_fields": ["UETR where applicable", "End to End Identification", "Instructed amount and currency", "Creditor agent"]}, {"message": "pacs.002", "purpose": "Payment status report resolving the leg outcome", "key_fields": ["Original reference and UETR", "Status code", "Reason code where rejected"]}, {"message": "pacs.004", "purpose": "Payment return where a settled payment must be returned", "key_fields": ["Original payment reference and UETR", "Return reason code", "Returned amount and currency"]}, {"message": "camt.056", "purpose": "Cancellation request only where a valid cancellation process is initiated, with acceptance not guaranteed", "key_fields": ["Original payment reference", "Cancellation reason", "Requestor identification"]}], "accounting_operational": "A payment in an unknown state holds its funds in suspense with a linked investigation case, and no second posting is made until the outcome is proven. A proven success posts the beneficiary credit and settlement entries once; a proven failure releases the reservation once and restores the sender balance; a proven return posts as a linked pacs.004 event, never by editing the original debit. A late success that arrives after a refund triggers a reconciliation case to recover the duplicate effect under the defined process. Operations monitor timeout rates, unknown state ageing, duplicate retry rates and investigation resolution times as corridor quality measures, with ageing alerts so no unknown payment sits unresolved.", "gherkin": ["Given a submission timeout", "When the client enquires using the original reference", "Then the platform returns the current known state", "And does not create a new transaction", "Given a timeout followed by a late success", "When the late event is received", "Then the system resolves the transaction without both crediting the beneficiary and refunding the sender", "And the investigation case is closed with the proven outcome"], "assessment": [{"question": "What does a submission timeout mean?", "options": ["The outcome is unknown until an enquiry resolves it", "The payment was never received", "The payment definitely failed", "The payment definitely succeeded"], "answer": 0, "explanation": "A timeout means the outcome is unknown, not a failure or a success."}, {"question": "How should a retry after a timeout be sent?", "options": ["Without any key", "With the same idempotency key as the original instruction", "As a completely new payment with a different amount", "With a new idempotency key every time"], "answer": 1, "explanation": "A retry must reuse the same idempotency key so it is recognised as the same payment."}, {"question": "What must not happen when a late success arrives after a timeout?", "options": ["Both crediting the beneficiary and refunding the sender", "The late event is applied to the original payment", "The customer is told the final outcome", "The investigation case is closed"], "answer": 0, "explanation": "Exactly one financial effect must occur, so a late success must not combine with a refund."}, {"question": "When may camt.056 be used?", "options": ["To confirm a payment", "To replace a status enquiry", "Only where a valid cancellation process is initiated, with acceptance not guaranteed", "To cancel any payment at any time with guaranteed acceptance"], "answer": 2, "explanation": "Cancellation via camt.056 is a request process, and acceptance is not guaranteed."}]}}, {"id": "INS-151", "kind": "insight", "title": "Richer data to support AML/FT and reconciliation", "topic": "Richer data to support AML/FT and reconciliation", "theme": "Cross-Border Instant", "text": "Assess structured purpose/remittance data quality, mapping and downstream consumption.", "domain": "ISO 20022 & Compliance", "area": "ISO 20022 & Compliance", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch81s3", "title": "Cross-border data transfers: when a payment message leaves the region", "url": "lessons/ch81s3"}}, {"id": "INS-152", "kind": "insight", "title": "Instant payment does not mean instant settlement everywhere", "topic": "Instant payment does not mean instant settlement everywhere", "theme": "Cross-Border Instant", "text": "Explain the distinction between customer experience, scheme processing and settlement finality.", "domain": "Clearing & Settlement", "area": "Clearing & Settlement", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch18s7", "title": "Settlement Finality and Legal Certainty", "url": "lessons/ch18s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank has launched instant euro payments for its small business customers. A furniture exporter, Aldergrove Interiors, pays a supplier in another SEPA country on a Friday afternoon and the mobile app immediately shows the payment as sent. The supplier checks its own account, sees no credit, and threatens to hold the shipment. Aldergrove Interiors calls Meridian Bank and asks whether the money has settled, and the frontline agent cannot answer with confidence because the app, the payment engine and the settlement account all show different states.\n\nThe confusion is commercial as well as technical. Aldergrove Interiors has promised its supplier same-day value, and the supplier treats the app confirmation as proof of settlement. In reality the customer experience, the scheme processing and the settlement finality are three different events that happen at different times and are confirmed by different systems. When the bank conflates them in its screens and its agent scripts, every delay looks like a lost payment and every investigation starts from the wrong assumption.\n\nMeridian Bank needs a design that keeps these three layers separate in its data, its customer messages and its operations. The customer leg may be accepted in seconds under the SCT Inst 10-second maximum execution rule, while the interbank settlement and any cross-border cover leg follow their own timelines and confirmation rules. The case asks the learner to design statuses, controls and communications that stay truthful at each layer.", "decision_exercise": {"scenario": "Aldergrove Interiors has sent an instant euro payment. The app shows Sent, the payment engine shows Accepted, and the beneficiary bank has not yet confirmed credit. The supplier is demanding proof of settlement. The learner must decide what Meridian Bank should tell the customer and record internally.", "options": [{"id": "A", "text": "Reverse the payment immediately so the customer can send it again by a slower rail."}, {"id": "B", "text": "Explain that acceptance is confirmed, beneficiary credit and settlement finality are still pending, and give the customer the tracking reference and the expected confirmation window."}, {"id": "C", "text": "Tell the customer the payment has settled because the app shows Sent, and close the enquiry."}, {"id": "D", "text": "Wait silently until the beneficiary bank confirms, and only contact the customer if the payment fails."}], "correct_option": "B", "why": "Option B is correct because it keeps acceptance, execution and settlement finality separate and gives the customer a verifiable reference and a next step. Option C is wrong because Sent describes the customer instruction, not settlement finality, and it misleads the supplier. Option A is wrong because reversing an accepted instant payment without a scheme basis creates a duplicate payment risk and a reconciliation break. Option D is wrong because silence leaves the customer unable to manage the supplier relationship and hides a case that operations should already be tracking."}, "recommended_solution": "Meridian Bank should model the payment as three linked but independent states: customer instruction state, scheme processing state, and settlement state. The channel shows Accepted once the payment engine has validated and released the instruction. It shows Beneficiary credited only when the beneficiary PSP confirmation or the scheme settlement confirmation arrives. It never shows Settled on the basis of acceptance alone. Each state transition is driven by an authoritative event, not by a timer or by another system's status.\n\nFor cross-border legs that use a cover model, the customer leg (pacs.008) and the cover leg (pacs.009 COV) must be tracked separately with a shared correlation key. A cover return (pacs.004) does not by itself prove the customer leg failed, and a customer credit does not by itself prove the cover settled. Operations investigates both legs before posting any customer adjustment, using the UETR where applicable and the linked transaction identifiers.\n\nCompliance and fraud screening must sit inside the execution window without being bypassed to meet a speed target. Where a mandatory check cannot complete in time, the payment is held or rejected under an explicit, auditable rule, never silently released. FX, where the payment involves a currency conversion, is bound to a quote with an expiry, and an expired quote blocks execution until a fresh quote and consent are obtained.\n\nFinally, the bank should publish a plain-language status glossary for agents and customers: Accepted means the bank has taken the instruction, In progress means scheme processing or settlement is pending, Credited means the beneficiary PSP has confirmed credit, and Failed means a definitive reject or return was received. Unknown is a legitimate status that triggers investigation rather than a retry.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Enters beneficiary, amount and payment purpose in mobile banking and confirms the payment.", "system": "Mobile banking"}, {"step": 2, "actor": "Payment engine", "action": "Validates account, balance, beneficiary data and scheme eligibility, and runs Verification of Payee.", "system": "Payment engine"}, {"step": 3, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud screening within the execution window and records each decision.", "system": "Screening services"}, {"step": 4, "actor": "Payment engine", "action": "Accepts the instruction, debits or earmarks the customer account, and sends the payment message to the clearing mechanism.", "system": "Payment engine"}, {"step": 5, "actor": "Clearing mechanism", "action": "Processes the instruction under SCT Inst rules within the 10-second maximum execution window.", "system": "Instant clearing and settlement mechanism"}, {"step": 6, "actor": "Beneficiary PSP", "action": "Validates the instruction, credits the beneficiary account, and returns a positive or negative confirmation.", "system": "Beneficiary PSP"}, {"step": 7, "actor": "Payment engine", "action": "Receives the confirmation, updates the scheme processing state and the settlement state separately, and releases any earmark.", "system": "Payment engine"}, {"step": 8, "actor": "Channel", "action": "Shows the customer the updated status with the tracking reference and the time of beneficiary credit.", "system": "Mobile banking"}], "happy_path": "The customer submits a valid instant payment. Verification of Payee passes, screening clears, and the payment engine accepts the instruction within seconds. The clearing mechanism processes it inside the 10-second maximum execution window. The beneficiary PSP credits the beneficiary and returns a positive confirmation. The payment engine records acceptance, execution and settlement as three separate confirmed events, updates the customer status to Credited with the confirmation time, and reconciliation matches the customer debit to the settlement account movement without exception.", "negative_paths": [{"path": "Beneficiary PSP rejects after acceptance", "trigger": "The beneficiary account is closed or the beneficiary data fails validation at the beneficiary PSP.", "handling": "Record the pacs.002 reject, reverse the customer earmark or debit under a linked reversal event, notify the customer with the reason, and do not retry automatically without fresh customer instruction."}, {"path": "Cover leg returned while customer leg is unclear", "trigger": "A pacs.004 return arrives for the cover leg but the customer leg has no final status.", "handling": "Hold any customer adjustment, correlate both legs by UETR and linked references, determine whether the customer leg was delivered, held or rejected, and only then decide the customer impact with operations sign-off."}, {"path": "Screening cannot complete in the window", "trigger": "A mandatory sanctions or fraud service times out or returns a potential match.", "handling": "Apply the approved fail-closed rule for mandatory controls, place the payment in a held state with a clear reason, escalate to the screening queue within its SLA, and never release the payment to meet the speed target."}, {"path": "FX quote expires before execution", "trigger": "Processing delay pushes execution past the accepted FX quote validity window.", "handling": "Block execution at the expired quote, request a fresh quote, and obtain fresh customer consent if the rate or amount changes beyond the agreed tolerance. Never execute silently at a different rate."}], "technical_data": "Store three state machines with separate authoritative events: instruction state, scheme processing state and settlement state. Use a unique instruction ID, end-to-end ID and UETR where applicable, and propagate them unchanged through every leg and message. Make all financial postings idempotent on the instruction ID so a duplicate confirmation or a retried callback cannot double-post. Keep screening decisions, quote snapshots, consent evidence and confirmation timestamps in the audit trail with source system and event time. Validate beneficiary data, including structured or hybrid address with Town Name and Country Code as a minimum where required, and never fabricate a value missing from the source message. Enforce the SCT Inst 10-second maximum execution window with sub-timelines of 5, 7 and 9 seconds monitored as operational thresholds, and treat a timeout as an unknown state that requires investigation, not as a success or a failure.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer instruction, including the customer leg of a cross-border payment.", "key_fields": ["Instruction ID and End-to-End ID for correlation", "Debtor and creditor agent BICs", "Creditor account and structured or hybrid address", "Amount, currency and settlement date", "UETR where applicable"]}, {"message": "pacs.009 COV", "purpose": "Cover leg for settlement between financial institutions where a cover model is used.", "key_fields": ["Cover amount and currency", "Underlying customer payment reference for linkage", "Settlement account details", "UETR where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance, rejection or execution outcome.", "key_fields": ["Original instruction reference", "Status code and reason code", "Status timestamp and reporting agent"]}, {"message": "pacs.004", "purpose": "Return of a payment leg, used to reverse funds for a defined reason.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and value date"]}], "accounting_operational": "On acceptance, debit the customer account or post an earmark with a linked pending settlement entry, so the customer balance and the settlement account never diverge silently. On beneficiary confirmation, clear the pending entry against the settlement account movement. On a reject or return, post a linked reversal that references the original instruction and reason, never delete the original posting. Where a cover leg is involved, reconcile the customer leg and the cover leg separately against the nostro account, and park any unmatched leg in a suspense worklist with an owner and an SLA. Operations monitors three queues: unconfirmed executions past the scheme window, cover returns without a matched customer leg outcome, and screening holds. Each queue has a defined escalation time and a rule that no item is auto-retried without a fresh decision.", "gherkin": ["Given an instant payment has been accepted by the payment engine", "When the beneficiary PSP confirmation has not yet arrived", "Then the customer status shows Accepted and In progress, not Settled", "And the settlement state remains Pending until the confirmation event is recorded", "Given a cover leg return has been received", "When the underlying customer payment status is unknown", "Then the bank investigates both legs before posting any customer adjustment", "And no automatic customer debit or credit is raised from the cover return alone"], "assessment": [{"question": "What is the maximum execution time for an SCT Inst payment under Regulation (EU) 2024/886?", "options": ["60 seconds", "One business day", "20 seconds", "10 seconds"], "answer": 3, "explanation": "The maximum execution time is 10 seconds, with monitored sub-timelines of 5, 7 and 9 seconds."}, {"question": "A cover leg is returned but the customer leg status is unknown. What should the bank do first?", "options": ["Refund the customer immediately", "Resend the cover leg automatically", "Investigate both legs and determine the customer leg outcome before adjusting the customer account", "Tell the customer the payment failed"], "answer": 2, "explanation": "The two legs have independent states, so the bank must establish the customer leg outcome before deciding customer impact."}, {"question": "Which statement about the SCT Inst scheme maximum amount is correct under the EPC SCT Inst Rulebook 2025?", "options": ["There is no scheme-level maximum now", "Each bank sets the scheme maximum", "The EUR 100,000 maximum still applies", "The maximum is EUR 50,000"], "answer": 0, "explanation": "The EUR 100,000 scheme maximum was removed by the EPC SCT Inst Rulebook 2025, effective 5 October 2025."}, {"question": "A mandatory sanctions check times out during an instant payment. What is the correct approach?", "options": ["Apply the approved fail-closed rule and hold or reject under the documented procedure", "Release the payment to meet the speed target", "Retry the payment until the check passes", "Skip the check and monitor afterwards"], "answer": 0, "explanation": "Mandatory screening must never be bypassed for speed. The approved fail-closed procedure applies and the hold is auditable."}]}}, {"id": "INS-153", "kind": "insight", "title": "India-Europe payment bridge design", "topic": "India-Europe payment bridge design", "theme": "Cross-Border Instant", "text": "Map corridor-specific currency, scheme, compliance, data, FX and settlement dependencies.", "domain": "Cross-Border Architecture", "area": "Cross-Border Architecture", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch33s7", "title": "Cross-Border Payments from India: SWIFT, Nostro, Vostro and a Worked Example", "url": "lessons/ch33s7"}, "case": {"status": "authored", "business_problem": "Meridian Bank wants to offer a corridor for small exporters who sell from India to buyers in Europe. Today a payment from a European buyer to an Indian exporter travels through a chain of correspondents, takes days, and gives neither side a reliable status. The exporter, Kaveri Textiles, ships fabric to a buyer in the Netherlands and waits for euros to arrive before it can pay its own suppliers in rupees. The buyer wants to pay instantly in euros, the exporter wants rupees quickly, and both want to know where the money is at every step.\n\nThe corridor has to join two very different domestic worlds. On the India side the domestic legs run on rails that operate 24x7x365: UPI for small instant transfers, IMPS for instant bank transfers typically capped by banks around Rs 5 lakh, NEFT in half-hourly batches, and RTGS for individual real-time settlement with a minimum of Rs 2 lakh and no RBI maximum. On the Europe side the euro leg can run as an SCT Inst payment with a 10-second maximum execution window and no scheme-level maximum, or as a One-Leg-Out Instant Credit Transfer where one leg sits outside SEPA.\n\nBetween the two domestic systems sit currency conversion, compliance screening, data translation, liquidity and settlement. No single rail covers the whole journey, so the bank must design a bridge that orchestrates the legs, owns the FX risk window, and gives the customer one truthful status instead of a patchwork of local confirmations.", "decision_exercise": {"scenario": "Kaveri Textiles is expecting EUR 40,000 from a Dutch buyer. The euro leg is accepted instantly, but the INR leg has not yet been confirmed and the FX quote is close to expiry. The learner must decide how the bridge should behave.", "options": [{"id": "A", "text": "Report the payment as complete because the euro leg was accepted."}, {"id": "B", "text": "Hold the end-to-end status at In progress, keep each leg state separate, and revalidate the FX quote before releasing the INR leg."}, {"id": "C", "text": "Cancel the euro leg and ask the buyer to send the payment again by correspondent banking."}, {"id": "D", "text": "Execute the INR leg at whatever rate applies when it is processed, without telling the customer."}], "correct_option": "B", "why": "Option B is correct because the corridor is only complete when every leg confirms, and an FX quote must be revalidated at execution. Option A is wrong because euro acceptance does not prove INR credit. Option D is wrong because executing at an unagreed rate breaks the quote contract and the consent evidence. Option C is wrong because cancelling a successfully accepted leg without a scheme basis creates unnecessary cost and delay."}, "recommended_solution": "Design the corridor as an orchestration layer over independent legs, not as a single payment. The euro leg, the bridge settlement leg and the INR leg each have their own state machine, timeout and confirmation rule, and the orchestration state only moves to Complete when the required leg confirmations have all arrived. The euro leg uses SCT Inst inside SEPA or the EPC One-Leg-Out Instant Credit Transfer where one leg sits outside SEPA, under the Rulebook 2025 version 1.1 effective 5 October 2025. The INR leg uses the rail that fits the amount and urgency: UPI for small instant transfers within its limits, IMPS for instant bank transfers, NEFT for batched settlement, or RTGS for large individual real-time settlement from Rs 2 lakh.\n\nBind every payment to an FX quote contract that records the quote ID, currency pair, amount, rate, expiry and tolerance. Revalidate the quote at execution, and if the rate or amount has moved beyond tolerance, pause for a fresh quote and fresh customer consent. Store the quote snapshot and the consent evidence with the payment record so any later dispute can be reconstructed.\n\nCompliance is designed into the corridor, not added after it. Sanctions, AML and fraud screening run with synchronous decision deadlines, and the corridor defines which checks are mandatory before release and which monitoring may follow the payment where the rules permit. Routing is validated against current, effective-dated reference data for correspondents, currencies, cut-offs and liquidity, and an approved alternate route is used only when policy permits it. Data is translated through a canonical model that preserves the structured or hybrid address, the purpose code and the identifier semantics of each rail, so nothing needed downstream is lost in translation.", "flow_steps": [{"step": 1, "actor": "Buyer", "action": "Instructs a EUR payment to Kaveri Textiles from European online banking, with invoice reference and purpose.", "system": "European online banking"}, {"step": 2, "actor": "Meridian Bank", "action": "Validates the instruction, runs Verification of Payee on the euro leg, and obtains an FX quote for EUR to INR.", "system": "Payment engine and FX service"}, {"step": 3, "actor": "Buyer", "action": "Accepts the FX quote, rate and expiry, and confirms the payment.", "system": "European online banking"}, {"step": 4, "actor": "Payment engine", "action": "Runs sanctions, AML and fraud screening with synchronous decision deadlines and records each outcome.", "system": "Screening services"}, {"step": 5, "actor": "Payment engine", "action": "Releases the euro leg as an SCT Inst or One-Leg-Out instant payment and awaits the beneficiary PSP confirmation.", "system": "Instant clearing mechanism"}, {"step": 6, "actor": "Bridge operator", "action": "On euro confirmation, revalidates the FX quote and confirms settlement liquidity for the INR leg.", "system": "Corridor orchestration"}, {"step": 7, "actor": "Indian partner bank", "action": "Executes the INR leg on the selected domestic rail and confirms credit to the exporter account.", "system": "Indian domestic rail"}, {"step": 8, "actor": "Corridor orchestration", "action": "Matches all leg confirmations, updates the end-to-end status to Complete, and issues a single customer timeline.", "system": "Corridor orchestration"}, {"step": 9, "actor": "Customer", "action": "Views the completed payment with the applied FX rate, fees and confirmation time for each leg.", "system": "Mobile and online banking"}], "happy_path": "The buyer accepts the FX quote and confirms the payment. Screening clears within its deadlines, the euro leg is accepted and confirmed inside the 10-second SCT Inst execution window, and the bridge revalidates the quote while it is still valid. The Indian partner bank executes the INR leg on the selected domestic rail and confirms credit to Kaveri Textiles. The orchestration layer matches the euro confirmation, the FX execution and the INR credit, marks the corridor payment Complete, and both customers see one coherent timeline with the applied rate, the fees and the time of each leg.", "negative_paths": [{"path": "Correspondent or route unavailable", "trigger": "The selected route is temporarily unavailable or no longer supports the currency or corridor.", "handling": "Re-evaluate routing against current effective-dated reference data, use an approved alternate route only if policy permits, otherwise queue or reject with a transparent reason and never silently change settlement details."}, {"path": "FX quote expires before execution", "trigger": "A delay pushes execution past the quote validity window.", "handling": "Block execution at the expired quote, obtain a fresh quote, and seek fresh consent if the rate or amount moves beyond tolerance. Record the expired quote and the new consent as separate audit events."}, {"path": "Compliance screening threatens the instant SLA", "trigger": "A mandatory check cannot complete inside the rail processing window.", "handling": "Apply the approved fail-closed rule for mandatory controls, hold the payment with a clear reason, escalate within the screening SLA, and never bypass screening to protect the speed target."}, {"path": "INR leg confirms late or not at all", "trigger": "The euro leg is confirmed but the domestic INR confirmation is delayed or missing.", "handling": "Keep the end-to-end status at In progress or Unknown, do not report completion, place the item in the corridor investigation queue, and resolve it through leg-level reconciliation before any compensation or retry."}], "technical_data": "Build a canonical payment model that carries the instruction ID, end-to-end ID and UETR where applicable unchanged across the corridor, with separate fields for each rail reference so identifiers are never collapsed into one generic field. Preserve the structured or hybrid address with Town Name and Country Code as a minimum, and never teach a fixed structured-address cut-off date, since the timeline was extended and a new timeline was expected by December 2026. Keep FX quote, consent, screening decision and leg confirmation as separate durable events with timestamps and source systems. Make the INR leg posting idempotent on the corridor transaction ID so a duplicate callback cannot double-credit the exporter. Version all routing and reference data with effective dates, and record the route decision factors for every payment. Note that PSD2 remains the law in force; PSD3 and the Payment Services Regulation are not law, with full application only around 2028, so corridor compliance must be built on PSD2.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer for the euro customer leg and for onward customer payment instructions.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor and creditor agent BICs", "Creditor account and structured or hybrid address", "Amount, currency and remittance information", "UETR where applicable"]}, {"message": "pacs.009", "purpose": "Financial institution transfer and cover leg for settlement between banks on the bridge.", "key_fields": ["Settlement amount and currency", "Underlying customer reference for linkage", "Settlement account and value date", "UETR where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report for acceptance, rejection and execution outcomes on each leg.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}, {"message": "pain.001", "purpose": "Customer payment initiation carrying the buyer instruction into the payment engine.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor account and creditor details", "Amount, currency and requested execution date", "Remittance information and purpose"]}], "accounting_operational": "Each leg posts its own linked accounting entries so the euro receipt, the FX conversion, the bridge settlement and the INR payout reconcile independently and in total. The euro leg credits a corridor settlement account on confirmation, the FX execution posts the conversion at the agreed rate with any spread recorded separately, and the INR leg debits the settlement account and credits the exporter. Any leg that confirms without its counterpart goes to a corridor suspense worklist with an owner and an SLA, and no compensation is posted until the leg states are established. Operations monitors quote expiries, route failures, screening holds and unmatched leg confirmations as separate queues, and nostro and settlement account reconciliation runs on the bridge accounts daily with same-day break ageing. Fees are disclosed per leg and posted as separate entries so the customer can see what each stage cost.", "gherkin": ["Given a corridor payment with an accepted FX quote", "When execution is attempted after the quote has expired", "Then the payment is not executed at a different rate", "And a fresh quote and fresh consent are requested before execution", "Given the euro leg is confirmed but the INR leg confirmation is absent", "When the corridor timeout threshold is reached", "Then the end-to-end status moves to Unknown and enters investigation", "And the payment is not reported as Complete and is not blindly resubmitted"], "assessment": [{"question": "Which euro mechanism covers the euro leg of a cross-border instant payment where one leg sits outside SEPA?", "options": ["SCT Core", "NEFT", "EPC One-Leg-Out Instant Credit Transfer", "SDD Core"], "answer": 2, "explanation": "The EPC One-Leg-Out Instant Credit Transfer covers the euro leg where one leg sits outside SEPA, under Rulebook 2025 version 1.1 effective 5 October 2025."}, {"question": "What is the minimum amount for an RTGS payment in India?", "options": ["Rs 50,000", "Rs 2 lakh", "Rs 10,000", "Rs 10 lakh"], "answer": 1, "explanation": "RTGS settles individually in real time with a minimum of Rs 2 lakh and no RBI maximum."}, {"question": "What is the current legal status of PSD3?", "options": ["It is law and PSD2 is repealed", "It is not law; PSD2 remains in force", "It applies only to instant payments", "It was withdrawn in 2025"], "answer": 1, "explanation": "PSD3 and the Payment Services Regulation are not law. PSD2 remains in force, with full application of PSD3 only around 2028."}, {"question": "How should the corridor report a payment whose euro leg is confirmed but whose INR leg is not?", "options": ["Credit the exporter from the suspense account", "Report it as Complete", "Cancel the euro leg automatically", "Report it as In progress or Unknown until the INR leg confirms"], "answer": 3, "explanation": "End-to-end completion requires all required leg confirmations. Until then the status stays In progress or Unknown and the item is investigated."}]}}, {"id": "INS-154", "kind": "insight", "title": "Mandate setup before first collection", "topic": "Mandate setup before first collection", "theme": "SEPA Direct Debit", "text": "Identify mandate data, creditor/debtor roles, authorisation evidence and downstream reference handling.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s2", "title": "The Four-Corner SDD Model and Mandate Flows", "url": "lessons/ch62s2"}}, {"id": "INS-155", "kind": "insight", "title": "Mandate reference and lifecycle maintenance", "topic": "Mandate reference and lifecycle maintenance", "theme": "SEPA Direct Debit", "text": "Define reference generation, amendment, cancellation and audit history requirements.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s3", "title": "e-Mandate Service and Its ISO 20022 Messages", "url": "lessons/ch62s3"}}, {"id": "INS-156", "kind": "insight", "title": "First versus recurring collection", "topic": "First versus recurring collection", "theme": "SEPA Direct Debit", "text": "Determine how collection sequence and mandate state influence processing and scheme data.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}}, {"id": "INS-157", "kind": "insight", "title": "Creditor pre-notification agreement", "topic": "Creditor pre-notification agreement", "theme": "SEPA Direct Debit", "text": "Define the standard notice expectation and how an agreed alternative timeline is evidenced.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}}, {"id": "INS-158", "kind": "insight", "title": "Collection file creation and submission", "topic": "Collection file creation and submission", "theme": "SEPA Direct Debit", "text": "Map creditor file preparation, validation, creditor PSP acceptance and scheme submission.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s4", "title": "Collections: pain.008 and pacs.003 Step by Step", "url": "lessons/ch62s4"}, "case": {"status": "authored", "business_problem": "Brightfield Energy supplies electricity to 40,000 households and collects monthly bills by SEPA Direct Debit. Each month its billing team builds a collection file, and each month something goes wrong: a customer who cancelled is still collected, an amount changed after the file was built, or a collection is submitted after the scheme deadline and is rejected by the creditor PSP. The billing team treats the file as a spreadsheet task, while the bank treats it as a regulated scheme submission, and the gap between those views creates refunds, complaints and rework.\n\nThe discipline sits in the sequence. A collection is only valid if a live mandate supports it, the debtor was pre-notified at the latest 14 calendar days before the due date or within an agreed alternative period, the amount and date match the notice, and the file reaches the creditor PSP in time for the D-1 submission deadline, which is one Inter-PSP Business Day before the due date. A file that is built correctly but submitted late is not a minor delay; it is a scheme breach that can invalidate the whole batch.\n\nBrightfield Energy needs a controlled file creation and submission process with validation at each gate, a clear cut-off after which a collection can no longer be edited, and an audit trail that proves what was notified, what mandate supported each collection, and when the file was accepted by the creditor PSP.", "decision_exercise": {"scenario": "Brightfield Energy has built its monthly collection file for a due date in three days. During a final check, the team finds 120 collections where the mandate reference does not match the mandate store, and 40 collections where the pre-notification was sent only 5 days before the due date with no agreed shorter period. The file submission deadline is tomorrow. The learner must decide what to do with the file.", "options": [{"id": "A", "text": "Submit the file late after correcting everything, and accept the late submission."}, {"id": "B", "text": "Collect the affected 160 by card payment instead, without telling the customers."}, {"id": "C", "text": "Remove the 160 affected collections from the file, submit only the validated collections on time, and handle the removed ones through a corrected re-issue."}, {"id": "D", "text": "Submit the whole file as built and fix the mandate and notice problems after the collections settle."}], "correct_option": "C", "why": "Option C is correct because only collections with a valid mandate and valid pre-notification may be submitted, and the valid majority should still meet the D-1 deadline. Option D is wrong because submitting collections without a valid mandate or notice exposes the creditor to returns and refunds and breaches scheme rules. Option A is wrong because a late submission misses the D-1 deadline and risks rejection of the whole file. Option B is wrong because changing the collection method without customer agreement is not a valid substitute."}, "recommended_solution": "Build the collection process as a gated pipeline with four gates that cannot be skipped. Gate one validates the mandate: it must exist, be active, match the creditor identifier and debtor account, and not have been unused for 36 months, since a mandate unused for that long must not be used. Gate two validates pre-notification: the notice content, amount, date and delivery evidence must be on file, sent at the latest 14 calendar days before the due date unless a valid agreed alternative period applies. Gate three validates the collection itself: amount, due date, mandate reference, creditor identifier and debtor IBAN must match the mandate and the notice exactly. Gate four is the submission control: the file is generated once, control totals are reconciled, and the file is transmitted to the creditor PSP before the D-1 deadline.\n\nOnce the file is generated, collections move from editable to locked. Any change after that point requires a formal revocation of the item from the file and a new collection in a later file, never a silent edit to the generated file. Duplicate prevention runs on mandate reference, due date and amount so a re-run of billing cannot create a second collection for the same period.\n\nThe creditor PSP acceptance is recorded as its own event with a timestamp and a file reference. A pain.008 that has not yet been submitted can still be revoked by the creditor; once submitted, stopping it needs a different mechanism. The process therefore keeps a clear record of which collections were submitted, which were revoked before submission, and which were excluded at validation, with a reason for every exclusion.", "flow_steps": [{"step": 1, "actor": "Billing team", "action": "Generates monthly bills and identifies the collections due, with amount and due date for each debtor.", "system": "Billing system"}, {"step": 2, "actor": "Billing system", "action": "Sends pre-notification to each debtor at the latest 14 calendar days before the due date and stores delivery evidence.", "system": "Notification service"}, {"step": 3, "actor": "Collection service", "action": "Validates each collection against the mandate store, checking mandate status, creditor identifier and debtor account.", "system": "Mandate and collection service"}, {"step": 4, "actor": "Collection service", "action": "Matches amount and due date against the pre-notification and excludes any collection that fails validation, with a recorded reason.", "system": "Mandate and collection service"}, {"step": 5, "actor": "Collection service", "action": "Generates the pain.008 file for the validated collections, reconciles control totals, and locks the file.", "system": "Collection service"}, {"step": 6, "actor": "Creditor PSP", "action": "Receives the file, validates it, and returns an acceptance or rejection for the file and its items.", "system": "Creditor PSP"}, {"step": 7, "actor": "Creditor PSP", "action": "Submits the accepted collections into clearing as pacs.003 instructions by the D-1 deadline.", "system": "Clearing mechanism"}, {"step": 8, "actor": "Debtor PSP", "action": "Processes each collection, debits the debtor account where valid, and reports returns or rejects.", "system": "Debtor PSP"}], "happy_path": "Billing generates the monthly amounts and pre-notification is sent at the latest 14 calendar days before the due date with delivery evidence stored. Every collection passes mandate, notice and amount validation. The pain.008 file is generated once, its control totals reconcile to the billing run, and the creditor PSP accepts it before the D-1 deadline. The collections are submitted as pacs.003 instructions, debtor PSPs debit the valid accounts on the due date, and the creditor receives the settled funds with an item-level reconciliation that matches every collection to a mandate, a notice and a settlement entry.", "negative_paths": [{"path": "Mandate missing or invalid", "trigger": "A collection has no active mandate, a mismatched mandate reference, or a mandate unused for 36 months.", "handling": "Exclude the collection at validation, record the reason, route it to mandate repair, and never submit it. Re-issue only after a valid mandate is in place."}, {"path": "Pre-notification sent late", "trigger": "The debtor was not notified within the required period and no agreed alternative period applies.", "handling": "Delay the collection to a later due date that satisfies the notice period, or handle it under a documented agreed exception. Do not treat file submission as notification."}, {"path": "File already generated when an error is found", "trigger": "An incorrect amount is found after the pain.008 file has been generated but before submission.", "handling": "Revoke the affected item from the file through the creditor-side revocation process, regenerate or correct the file before submission, and preserve the audit evidence for the change."}, {"path": "Creditor PSP rejects the file", "trigger": "The file fails format, total or deadline validation at the creditor PSP.", "handling": "Log the rejection with its reason codes, correct the file or its items, revalidate control totals, and resubmit only if the D-1 deadline can still be met."}], "technical_data": "Keep the mandate as a versioned record with status, creditor identifier, debtor IBAN, mandate reference, signature or consent evidence, and last-used date, so the 36-month non-use rule can be enforced automatically. Store pre-notification content, send date, delivery evidence and any agreed notice period with the collection, and validate the 14-calendar-day rule from those stored facts rather than from a billing date. Generate the pain.008 with a unique file and message ID, control totals for count and amount, and an idempotency key so a re-transmission cannot double-submit the batch. Lock generated files against silent edits and record every revocation, exclusion and resubmission as a separate audit event with actor and timestamp. Validate the D-1 submission deadline in Inter-PSP Business Days, not calendar days, and reject any file that cannot meet it before transmission.", "messages_fields": [{"message": "pain.008", "purpose": "Customer direct debit initiation carrying the creditor collection file to the creditor PSP.", "key_fields": ["Mandate reference and creditor identifier", "Debtor IBAN and debtor agent", "Collection amount, currency and due date", "Sequence type: first, recurring, final or one-off", "Pre-notification evidence reference"]}, {"message": "pacs.003", "purpose": "Direct debit collection instruction submitted into clearing by the creditor PSP.", "key_fields": ["Mandate reference and creditor identifier", "Debtor and creditor agent BICs", "Amount, currency and due date", "Instruction ID and End-to-End ID"]}, {"message": "pacs.002", "purpose": "Payment status report for acceptance or rejection of collections.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}], "accounting_operational": "On submission, post the expected collections to a collections-in-transit control account so the billing total, the file total and the expected settlement can be reconciled at each stage. On settlement, credit the creditor operating account and clear the in-transit entries item by item. Returns and rejects arrive as pacs.004 events and are posted as separate linked entries against the original collection, never by deleting it, with the return reason driving the next action: re-present where the scheme permits, contact the debtor, or write the item to a collections exception worklist. Operations works a daily queue of validation exclusions, PSP rejections and unmatched settlements, with an SLA tied to the next D-1 deadline so excluded customers are re-issued correctly rather than silently dropped.", "gherkin": ["Given a collection with no active mandate", "When validation runs before file generation", "Then the collection is excluded from the file and a clear reason is recorded", "And the file control totals exclude that collection", "Given a collection whose pre-notification was sent less than 14 calendar days before the due date with no agreed alternative period", "When collection eligibility is checked", "Then the collection is delayed to a due date that satisfies the notice period", "And the delay and its reason are recorded in the audit trail"], "assessment": [{"question": "What is the SDD Core collection submission deadline?", "options": ["D-1, one Inter-PSP Business Day before the due date", "D-2, two Inter-PSP Business Days before the due date", "Five business days before the due date", "On the due date itself"], "answer": 0, "explanation": "The SDD Core submission deadline is D-1, one Inter-PSP Business Day before the due date, not D-2."}, {"question": "By when must pre-notification normally be sent?", "options": ["After the collection settles", "On the due date", "One business day before submission", "At the latest 14 calendar days before the due date"], "answer": 3, "explanation": "Pre-notification is required at the latest 14 calendar days before the due date, unless a valid agreed alternative period applies."}, {"question": "A mandate has not been used for 36 months. What should happen?", "options": ["It must not be used; a new mandate is needed", "Use it only for small amounts", "Use it once more before it lapses", "Renew it automatically at collection"], "answer": 0, "explanation": "A mandate unused for 36 months must not be used."}, {"question": "Which message carries the creditor collection file to the creditor PSP?", "options": ["camt.056", "pacs.008", "pacs.003", "pain.008"], "answer": 3, "explanation": "The pain.008 customer direct debit initiation carries the collection file; pacs.003 is the interbank collection instruction."}]}}, {"id": "INS-159", "kind": "insight", "title": "Creditor-side collection cancellation", "topic": "Creditor-side collection cancellation", "theme": "SEPA Direct Debit", "text": "Distinguish cancellation before submission/processing from downstream return or refund events.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s6", "title": "Reversals: pain.007, pacs.007 and Reason Codes AM05, MS02, MS03", "url": "lessons/ch62s6"}, "case": {"status": "authored", "business_problem": "Brightfield Energy discovers on a Tuesday that its billing run used last month's tariff for 800 customers. The collections are due on Friday and the file has already been submitted to the creditor PSP. The billing manager asks the team to cancel the collections, and two different people give two different answers: one says the collections can simply be deleted from the file, the other says nothing can be done until the money is collected and refunded. Both answers are wrong, and the difference between them is worth 800 customer complaints.\n\nThe error sits at a precise point in the lifecycle. Before submission, the creditor can revoke a collection from its own file. After submission, the collection belongs to the payment chain, and stopping it needs a request for cancellation through the scheme channel, which may be accepted or rejected, and which does not guarantee the collection will stop. After settlement, cancellation is no longer available at all, and the remedy becomes a reversal or a refund through a different mechanism.\n\nBrightfield Energy needs a cancellation playbook that starts from the collection state, not from the billing error, so every team member takes the same action for the same state and the customer is told the truth about what can and cannot still be stopped.", "decision_exercise": {"scenario": "Brightfield Energy submitted a collection file yesterday for a due date in three days. Today it finds the amounts are wrong. The learner must decide the correct action.", "options": [{"id": "A", "text": "Wait until after settlement and then ask each debtor to claim a refund from their own bank."}, {"id": "B", "text": "Submit a request for cancellation through the scheme channel, track acceptance or rejection, and prepare a reversal or refund plan in case the original still settles."}, {"id": "C", "text": "Send a second corrected collection for the same due date and let the debtor bank sort out the duplicate."}, {"id": "D", "text": "Delete the collections from the local billing file and assume the submitted file is also cancelled."}], "correct_option": "B", "why": "Option B is correct because a submitted collection can only be stopped through a scheme cancellation request, whose acceptance is not guaranteed, so a fallback plan is needed. Option D is wrong because deleting a local copy does not cancel a submitted instruction. Option A is wrong because it leaves wrong collections to settle and pushes the remedy onto debtors. Option C is wrong because it creates duplicate collections for the same period."}, "recommended_solution": "Teach cancellation as a state-driven decision tree with three branches. Branch one, before submission: the creditor revokes the collection from its own file or collection service. The item is marked revoked, excluded from generation, and preserved in the audit trail with the actor, the reason and the timestamp. No scheme message is needed because the instruction has not left the creditor's control.\n\nBranch two, after submission but before settlement: the creditor PSP sends a request for cancellation, using camt.056 where applicable, with a camt.029 response recording acceptance or rejection. The original collection and the cancellation request are tracked as separate records with separate states. The team must not tell the customer the collection is cancelled until the acceptance arrives, because the request itself does not stop settlement and the original can still settle while the request is in flight.\n\nBranch three, after settlement: cancellation is closed. The remedy is a reversal initiated by the creditor within the scheme window, or a debtor refund claim handled under the Core or B2B rules. The playbook therefore pairs every cancellation request with a contingency: if the original settles, the creditor reverses it or refunds it promptly, notifies the debtor, and records the linkage between the original, the cancellation request and the reversal so reconciliation stays clean.", "flow_steps": [{"step": 1, "actor": "Billing team", "action": "Discovers the tariff error and identifies the 800 affected collections with their mandate references and amounts.", "system": "Billing system"}, {"step": 2, "actor": "Collection service", "action": "Checks the state of each collection: not submitted, submitted, or settled.", "system": "Collection service"}, {"step": 3, "actor": "Collection service", "action": "Revokes any collections still within creditor control and excludes them from any pending file.", "system": "Collection service"}, {"step": 4, "actor": "Creditor PSP", "action": "Sends a camt.056 request for cancellation for each submitted collection, with the original instruction reference.", "system": "Creditor PSP"}, {"step": 5, "actor": "Counterparty PSP", "action": "Evaluates the request against the collection state and scheme rules, and returns a camt.029 acceptance or rejection.", "system": "Debtor PSP"}, {"step": 6, "actor": "Collection service", "action": "Records the camt.029 outcome against the original collection and updates its state.", "system": "Collection service"}, {"step": 7, "actor": "Billing team", "action": "For any original that still settles, initiates a reversal or refund and notifies the affected debtors.", "system": "Billing system"}, {"step": 8, "actor": "Operations", "action": "Reconciles the originals, the cancellation requests and the reversals, and closes the incident with a full audit trail.", "system": "Reconciliation service"}], "happy_path": "The error is found while most collections are still within creditor control, so those are revoked from the file before submission. For the submitted remainder, the creditor PSP sends camt.056 requests promptly and the counterparty PSP accepts them before settlement. The accepted cancellations stop the collections, no debtor is debited, and the billing team re-issues corrected collections with fresh pre-notification for a later due date. Every original, request and outcome is linked in the audit trail and the incident closes with no customer complaint.", "negative_paths": [{"path": "Cancellation arrives too late", "trigger": "The request reaches the counterparty after the collection has passed the point where cancellation is possible.", "handling": "Record the rejection, let the original follow its normal course, and trigger the reversal or refund contingency with debtor notification."}, {"path": "Counterparty rejects the request", "trigger": "The counterparty PSP rejects the camt.056 for a scheme or state reason.", "handling": "Log the camt.029 rejection reason, do not resend the same request without a changed basis, and move the item to the reversal or refund plan."}, {"path": "Original settles while the request is in flight", "trigger": "Settlement and the cancellation request race, and the original settles first.", "handling": "Treat the settlement as valid, initiate a reversal within the scheme window where eligible, link it to the original and the cancellation request, and notify the debtor of the correction."}, {"path": "Duplicate corrected collection", "trigger": "A corrected collection is issued for the same period while the original is still live.", "handling": "Block the corrected collection until the original is cancelled, reversed or confirmed settled, using mandate reference, due date and amount as duplicate keys."}], "technical_data": "Model the original collection and the cancellation request as separate records with their own IDs, states and timestamps, linked by the original instruction ID and end-to-end ID. Make the camt.056 idempotent on its own request ID so a retry cannot create a second cancellation for the same original. Record the camt.029 outcome as the authoritative decision, and never infer cancellation from the sending of the request. Enforce state transitions so a settled collection cannot move to cancelled, only to reversed or refunded. Keep the actor, reason and timestamp for every revocation, request and outcome, and surface the race condition in testing: a cancellation that arrives in the same processing window as settlement must resolve to exactly one financial outcome.", "messages_fields": [{"message": "camt.056", "purpose": "Request for cancellation of a submitted payment instruction.", "key_fields": ["Original instruction ID and End-to-End ID", "Cancellation reason", "Requester identification and request timestamp"]}, {"message": "camt.029", "purpose": "Resolution of investigation, reporting acceptance or rejection of the cancellation request.", "key_fields": ["Original cancellation request reference", "Resolution status: accepted or rejected", "Rejection reason code where applicable"]}, {"message": "pacs.004", "purpose": "Return or reversal of a collection that has settled, where the scheme permits it.", "key_fields": ["Original instruction reference", "Return or reversal reason code", "Returned amount and value date"]}, {"message": "pain.008", "purpose": "Collection file instruction before submission, revocable by the creditor while still in creditor control.", "key_fields": ["Mandate reference and creditor identifier", "Collection amount and due date", "Instruction ID for linkage to any later cancellation"]}], "accounting_operational": "A revoked pre-submission collection never reaches the ledger, so no accounting entry is needed beyond the audit record of the revocation. An accepted cancellation leaves the expected collection in the in-transit control account to be cleared without a settlement entry, with the cancellation outcome as the clearing evidence. A collection that settles despite the request posts normally, then the reversal posts as a separate linked entry that debits the creditor and credits the debtor, preserving the original settlement record. Operations works a cancellation queue that separates awaiting response, accepted, rejected and settled-despite-request, each with its own next action and SLA, and reconciles the queue daily against the clearing reports so no item is left in an assumed state.", "gherkin": ["Given a collection that has been submitted but not yet settled", "When a valid cancellation request is accepted", "Then the original collection follows the scheme cancellation outcome", "And the customer is told the collection is cancelled only after acceptance is recorded", "Given a cancellation request is sent for a submitted collection", "When the original settles before the response arrives", "Then the settlement stands and a linked reversal or refund is initiated", "And the original, the request and the reversal remain linked in the audit trail"], "assessment": [{"question": "A collection has been submitted but not yet settled. How can the creditor try to stop it?", "options": ["Ask the debtor to block it at their bank", "Send a request for cancellation through the scheme channel, such as camt.056", "Delete it from the local billing file", "Wait for it to be returned automatically"], "answer": 1, "explanation": "After submission the creditor must use a scheme cancellation request, and acceptance is not guaranteed."}, {"question": "What does sending a camt.056 guarantee?", "options": ["That the original is deleted", "Nothing; acceptance depends on the counterparty and the collection state", "An immediate refund to the debtor", "The collection will definitely stop"], "answer": 1, "explanation": "A cancellation request does not itself stop settlement. The camt.029 response records acceptance or rejection."}, {"question": "A collection is still in the creditor file and has not been submitted. What is the correct action to stop it?", "options": ["Creditor-side revocation from the file", "A camt.056 request", "A pacs.004 return", "A debtor refund claim"], "answer": 0, "explanation": "While the collection remains within creditor control, the creditor revokes it from the file or collection service."}, {"question": "After a collection has settled, which remedy applies?", "options": ["Reversal or refund under the applicable scheme rules", "Cancellation", "Revocation", "Deleting the settlement entry"], "answer": 0, "explanation": "Cancellation is closed after settlement. The remedy is a reversal or a refund, posted as a separate linked transaction."}]}}, {"id": "INS-160", "kind": "insight", "title": "Request for cancellation versus revocation", "topic": "Request for cancellation versus revocation", "theme": "SEPA Direct Debit", "text": "Clarify which party initiates the request, timing, processing state and scheme message/operational handling.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s6", "title": "Reversals: pain.007, pacs.007 and Reason Codes AM05, MS02, MS03", "url": "lessons/ch62s6"}, "case": {"status": "authored", "business_problem": "Aster Leisure Group runs monthly gym memberships collected by SEPA Direct Debit. Its support team keeps using the words cancellation and revocation as if they meant the same thing, and the confusion has real consequences. A member who cancels a membership expects no further collection, a billing clerk who revokes a collection expects it never to leave the building, and a creditor PSP that receives a cancellation request expects a scheme message with a response. When the team picks the wrong mechanism for the collection state, the member is debited anyway or the bank rejects the request, and the complaint lands with the same team that chose the wrong word.\n\nThe distinction turns on three facts: who initiates the action, what state the collection is in, and which channel carries it. Revocation is a creditor-side action taken while the collection is still within the creditor's control, before submission. A request for cancellation is a scheme action taken after submission, carried by camt.056 with a camt.029 response, and it can be accepted or rejected. A debtor refund is a third thing entirely, initiated by the debtor through the debtor PSP after the collection, and it follows refund rights rather than cancellation logic.\n\nAster Leisure Group needs a single page its support and billing teams can use without guessing: for each collection state, the correct mechanism, the correct initiator, the correct message, and the correct customer wording.", "decision_exercise": {"scenario": "A member cancels their Aster Leisure membership on Monday. The next monthly collection is in the pain.008 file that has been generated but not yet submitted to the creditor PSP. A second member cancelled last month, but their collection was already submitted yesterday for a due date in three days. The learner must choose the correct mechanism for each member.", "options": [{"id": "A", "text": "Revoke the first member's collection from the file, and send a camt.056 request for cancellation for the second member."}, {"id": "B", "text": "Revoke both collections from the local file and assume both are stopped."}, {"id": "C", "text": "Tell both members to claim a refund from their own banks after the collections settle."}, {"id": "D", "text": "Send a camt.056 for both members."}], "correct_option": "A", "why": "Option A is correct because the mechanism follows the collection state: revocation while still in creditor control, and a scheme cancellation request after submission. Option D is wrong because a camt.056 is not the mechanism for an unsubmitted collection. Option B is wrong because revoking a local copy does not cancel a submitted instruction. Option C is wrong because a refund claim is a post-settlement debtor remedy, not a way to stop a collection that can still be cancelled."}, "recommended_solution": "Build the decision around a state table that the team consults before acting. State one, collection created but not submitted: the initiator is the creditor, the mechanism is revocation, the channel is the creditor's own collection service or file, and the outcome is immediate exclusion from the submission set with an audit record. No scheme message is sent and no counterparty response is needed.\n\nState two, collection submitted but not settled: the initiator is the creditor through the creditor PSP, the mechanism is a request for cancellation, the channel is camt.056, and the outcome depends on the camt.029 response. The team records the request, waits for the response, and tells the customer the collection is cancelled only after acceptance. If the request is rejected or the original settles first, the team moves to the reversal or refund branch.\n\nState three, collection settled: neither revocation nor cancellation applies. The creditor remedy is a reversal where the scheme permits it, and the debtor remedy is a refund claim under the Core or B2B rules. The team must also distinguish a membership cancellation from a collection cancellation: ending a membership stops future collections by cancelling or ending the mandate, while stopping a single collection that is already in flight needs the mechanism above. Both actions should be recorded so a cancelled member is never collected again in a later billing run.", "flow_steps": [{"step": 1, "actor": "Member", "action": "Cancels membership through the app or by phone, giving the effective date.", "system": "Membership system"}, {"step": 2, "actor": "Billing team", "action": "Locates the next collection and checks its state: created, submitted or settled.", "system": "Collection service"}, {"step": 3, "actor": "Billing team", "action": "For a created but unsubmitted collection, revokes it from the file and marks it revoked with reason and actor.", "system": "Collection service"}, {"step": 4, "actor": "Creditor PSP", "action": "For a submitted collection, sends a camt.056 request for cancellation with the original instruction reference.", "system": "Creditor PSP"}, {"step": 5, "actor": "Counterparty PSP", "action": "Evaluates the request and returns a camt.029 acceptance or rejection.", "system": "Debtor PSP"}, {"step": 6, "actor": "Collection service", "action": "Records the camt.029 outcome against the original collection and updates its state.", "system": "Collection service"}, {"step": 7, "actor": "Support team", "action": "Notifies the member of the outcome using wording that matches the actual state, and confirms no further collections will be raised.", "system": "Customer service system"}, {"step": 8, "actor": "Billing team", "action": "Ends or cancels the mandate for future periods so the member is not collected again.", "system": "Mandate service"}], "happy_path": "Both members are handled by state. The first member's unsubmitted collection is revoked from the file before submission, so no instruction ever leaves the creditor. The second member's submitted collection is stopped by an accepted camt.056, confirmed by a camt.029, before settlement. Both members receive accurate confirmation, their mandates are ended so no future collection is raised, and the audit trail shows the revocation, the request, the acceptance and the mandate end as separate linked events.", "negative_paths": [{"path": "Revocation attempted after submission", "trigger": "A clerk tries to revoke a collection from the local file after it has already been submitted.", "handling": "Detect the state mismatch from the collection record, block the local revocation, and route the item to the camt.056 cancellation path with an explanation to the clerk."}, {"path": "Cancellation request rejected", "trigger": "The counterparty PSP rejects the camt.056 because the collection has passed the cancellable point.", "handling": "Record the camt.029 rejection, tell the member the collection could not be stopped, and prepare a reversal or refund with a clear date."}, {"path": "Membership cancelled but mandate left live", "trigger": "The collection is stopped for one month but the mandate remains active, so the next billing run collects again.", "handling": "Treat mandate end as a mandatory step in the membership cancellation checklist, and add a control that flags any collection raised against an ended membership before file generation."}, {"path": "Batch booking hides a single-item outcome", "trigger": "A batch posts as one aggregate entry, so a single cancelled collection inside it is hard to trace.", "handling": "Retain item-level references linked to the aggregate posting, so each collection, revocation and cancellation can be reconciled individually against the batch total."}], "technical_data": "Store the collection state as an explicit field with allowed transitions, and enforce the mechanism by state in the application so a revocation cannot be recorded for a submitted collection and a camt.056 cannot be created for an unsubmitted one. Keep the revocation, the cancellation request and the camt.029 response as separate records linked by the original instruction ID, each with its own ID, actor, timestamp and reason. Make the camt.056 idempotent on its request ID. Link the mandate end to the membership cancellation so future billing runs exclude the member automatically, and validate that linkage before every file generation. For batch booking, keep the aggregate ledger entry linked to its item-level records with control totals, so a single-item return or cancellation reconciles without reversing the successful items in the batch.", "messages_fields": [{"message": "pain.008", "purpose": "Collection instruction before submission, revocable by the creditor while still in creditor control.", "key_fields": ["Mandate reference and creditor identifier", "Collection amount and due date", "Instruction ID and collection state"]}, {"message": "camt.056", "purpose": "Request for cancellation of a submitted instruction.", "key_fields": ["Original instruction ID and End-to-End ID", "Cancellation reason", "Requester identification and request timestamp"]}, {"message": "camt.029", "purpose": "Resolution of investigation, reporting acceptance or rejection of the cancellation request.", "key_fields": ["Original cancellation request reference", "Resolution status: accepted or rejected", "Rejection reason code where applicable"]}, {"message": "pacs.004", "purpose": "Return or reversal where a settled collection must be corrected.", "key_fields": ["Original instruction reference", "Return or reversal reason code", "Returned amount and value date"]}], "accounting_operational": "A revoked collection never enters the in-transit control account, so the billing total and the file total reconcile with the revocation listed as an exclusion. An accepted cancellation clears the expected in-transit entry without a settlement posting, using the camt.029 as clearing evidence. A rejected cancellation that settles posts normally and is then corrected by a linked reversal entry, so the original settlement record stays intact. Where a batch is booked as one aggregate entry, the item-level records carry the individual outcomes and the aggregate reconciles to the sum of its items, including the cancelled and reversed ones. Operations reviews a daily queue of state mismatches, rejected cancellations and mandates left live after membership cancellation, with an SLA that clears each item before the next billing run.", "gherkin": ["Given a collection that has not yet been submitted to the PSP", "When an authorised creditor revokes it", "Then it is excluded from submission and marked revoked", "And no scheme cancellation message is sent for it", "Given a collection that has been submitted but not yet settled", "When a valid cancellation request is accepted", "Then the original collection follows the scheme cancellation outcome", "And the member is notified only after the acceptance is recorded"], "assessment": [{"question": "Who initiates a revocation, and when is it available?", "options": ["The debtor, before the due date", "The clearing mechanism, at any time", "The debtor PSP, after settlement", "The creditor, while the collection is still within creditor control before submission"], "answer": 3, "explanation": "Revocation is a creditor-side action available while the collection has not yet been submitted."}, {"question": "What message carries a request for cancellation after submission?", "options": ["pacs.003", "pacs.008", "camt.056", "pain.008"], "answer": 2, "explanation": "The camt.056 carries the request for cancellation, and the camt.029 reports acceptance or rejection."}, {"question": "A cancellation request has been sent. What should the team tell the customer?", "options": ["That the collection is cancelled, immediately", "That a refund is on its way", "That a cancellation has been requested and the outcome will be confirmed once the response arrives", "Nothing until the next billing run"], "answer": 2, "explanation": "The request itself does not stop settlement, so the customer must be told the outcome only after the acceptance is recorded."}, {"question": "A member cancels their membership. What else must happen to prevent future collections?", "options": ["The creditor PSP must be told verbally", "The next collection must be revoked each month", "The mandate must be ended or cancelled so later billing runs exclude the member", "Nothing, the membership system handles it"], "answer": 2, "explanation": "Ending the mandate is the control that stops future collections. Without it, the next billing run can collect again."}]}}, {"id": "INS-161", "kind": "insight", "title": "Reversal after collection", "topic": "Reversal after collection", "theme": "SEPA Direct Debit", "text": "Define when a reversal is appropriate, who initiates it, references and accounting treatment; validate scheme rules.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s6", "title": "Reversals: pain.007, pacs.007 and Reason Codes AM05, MS02, MS03", "url": "lessons/ch62s6"}, "case": {"status": "authored", "business_problem": "Brightfield Energy has collected the same monthly bill twice from 300 customers after a billing re-run duplicated a batch. The money has already settled, so the collections cannot be cancelled or revoked. Customers are calling, the support team is offering to delete the duplicate collections from the system, and finance is worried that deleting settled entries will break reconciliation. Everyone agrees the customers must be paid back, but nobody agrees on the mechanism that does it correctly.\n\nA reversal is not a deletion and it is not a refund claim by the debtor. It is a separate, linked transaction initiated by the creditor after settlement, within a defined scheme window, for a defined reason, for the same or a corrected amount. It leaves the original settlement record intact and creates its own audit trail, so the duplicate can be traced from the billing error through the reversal to the customer account.\n\nBrightfield Energy needs a reversal process that checks eligibility first, creates exactly one reversal per original, posts it correctly, and tells the customer precisely what was reversed and when the money will be back.", "decision_exercise": {"scenario": "Brightfield Energy duplicated 300 collections and they have settled. The duplicate amounts are identical to the originals and the due date was four Inter-PSP Business Days ago. The learner must decide the correct remedy.", "options": [{"id": "A", "text": "Initiate a linked reversal for each duplicate collection within the scheme window, using pacs.004, and notify each debtor."}, {"id": "B", "text": "Delete the duplicate collection records from the billing system so they disappear."}, {"id": "C", "text": "Send a camt.056 cancellation request for each duplicate collection."}, {"id": "D", "text": "Ask each of the 300 debtors to claim an authorised refund from their own bank."}], "correct_option": "A", "why": "Option A is correct because a settled duplicate is corrected by a creditor-initiated reversal, linked to the original, within the scheme window. Option B is wrong because deleting a settled record destroys the audit trail and breaks reconciliation. Option D is wrong because it pushes a creditor error onto debtors and uses the wrong mechanism. Option C is wrong because cancellation applies before settlement, not after it."}, "recommended_solution": "Treat reversal as a controlled financial event with four checks before it is created. Check one, eligibility: the collection has settled, the reversal is initiated by the creditor, and the reason is one the scheme permits, such as a duplicate collection or an incorrect amount. Check two, timing: a reversal is only available from the settlement date and within 5 Inter-PSP Business Days following the due date, so the team must confirm the window is still open before promising the customer a reversal. Check three, linkage: the reversal references the original instruction ID, mandate reference and amount, and carries a reason code that explains the error. Check four, uniqueness: the system blocks a second reversal for the same original unless a partial reversal is explicitly permitted and recorded.\n\nThe reversal is posted as a separate transaction, normally carried by pacs.004, and the original settlement entry is never edited or deleted. The debtor is notified with the original amount, the reversed amount, the reason and the expected value date. Where the window has already closed, the team does not force a reversal through; it uses the available alternative, such as a separate creditor-to-debtor credit transfer or a commercial refund, and records why the scheme reversal was not available.\n\nThe process also distinguishes a reversal from a debtor refund. A refund is claimed by the debtor through the debtor PSP under the Core or B2B refund rights, with the Core authorised refund available within 8 weeks of the debit date and an unauthorised claim within 13 months, while B2B has no authorised refund right. A reversal is initiated by the creditor. Mixing the two up sends the customer to the wrong channel and delays the correction.", "flow_steps": [{"step": 1, "actor": "Billing team", "action": "Discovers the duplicate billing run and identifies the 300 duplicate collections with their original references.", "system": "Billing system"}, {"step": 2, "actor": "Collection service", "action": "Confirms each duplicate has settled and checks the reversal window: from settlement date and within 5 Inter-PSP Business Days following the due date.", "system": "Collection service"}, {"step": 3, "actor": "Collection service", "action": "Creates one linked reversal per duplicate, with the original instruction reference, amount and reason code.", "system": "Collection service"}, {"step": 4, "actor": "Creditor PSP", "action": "Submits the reversals as pacs.004 instructions into clearing.", "system": "Creditor PSP"}, {"step": 5, "actor": "Debtor PSP", "action": "Receives each reversal, validates the linkage, and credits the debtor account.", "system": "Debtor PSP"}, {"step": 6, "actor": "Collection service", "action": "Matches each reversal to its original and updates both records as a linked pair.", "system": "Collection service"}, {"step": 7, "actor": "Billing team", "action": "Notifies each debtor of the duplicate, the reversed amount and the expected value date.", "system": "Notification service"}, {"step": 8, "actor": "Operations", "action": "Reconciles originals against reversals and closes the incident with a full audit trail.", "system": "Reconciliation service"}], "happy_path": "The duplicate is found inside the reversal window. The team creates exactly one linked pacs.004 reversal per duplicate, each referencing its original instruction and carrying the duplicate reason code. The debtor PSPs credit the 300 debtors, the reversals match their originals one to one, and the customers receive a clear notice stating the duplicate amount and the value date. The original settlement records remain intact, the incident closes with no second reversal and no debtor refund claim, and the billing re-run control is fixed so the duplicate cannot recur.", "negative_paths": [{"path": "Reversal deadline missed", "trigger": "The error is found after 5 Inter-PSP Business Days following the due date.", "handling": "Do not force a scheme reversal. Use the available alternative, such as a separate creditor credit transfer, record why the reversal window had closed, and notify the debtor of the corrected route and date."}, {"path": "Duplicate reversal", "trigger": "A re-run of the reversal job creates a second reversal for the same original.", "handling": "Block the second reversal on the original instruction ID, quarantine the duplicate request, and reconcile the reversal count against the original count before any further submission."}, {"path": "Original already refunded", "trigger": "A debtor has already claimed a refund for the same collection before the reversal is sent.", "handling": "Detect the existing refund by the original reference, stop the reversal to avoid double repayment, and reconcile the refund as the correcting event with a linked record."}, {"path": "Partial reversal amount dispute", "trigger": "Only part of the collected amount was wrong, and the reversal amount does not match the error.", "handling": "Reverse only the incorrect portion where the scheme permits a partial reversal, state the partial amount and reason clearly, and keep the correct portion settled with its own linked record."}], "technical_data": "Model the reversal as a separate transaction with its own instruction ID, linked to the original by the original instruction ID and end-to-end ID, and enforce a uniqueness constraint so one original can have only the permitted number of reversals. Validate the reversal window in Inter-PSP Business Days from the settlement date and the due date before the reversal is created, and record the window check as an audit event. Carry the mandate reference, amount, currency, value date and reason code in the pacs.004, and never edit the original settlement record. Make the reversal posting idempotent on its own instruction ID so a retried submission cannot double-credit the debtor. Keep the reversal distinct from a debtor refund in the data model, with separate reason codes, initiators and status flows, so reporting never conflates the two.", "messages_fields": [{"message": "pacs.004", "purpose": "Payment return and reversal message carrying the creditor-initiated reversal to the debtor PSP.", "key_fields": ["Original instruction ID and End-to-End ID", "Reversal reason code", "Reversed amount, currency and value date", "Mandate reference and creditor identifier"]}, {"message": "pacs.003", "purpose": "Original direct debit collection instruction that the reversal corrects.", "key_fields": ["Instruction ID and End-to-End ID", "Mandate reference and creditor identifier", "Amount, currency and due date"]}, {"message": "pacs.002", "purpose": "Payment status report confirming acceptance or rejection of the reversal.", "key_fields": ["Original reversal reference", "Status and reason code", "Status timestamp and reporting agent"]}], "accounting_operational": "The original collection stays posted as a settled credit to the creditor and a debit to the debtor. The reversal posts as a separate linked entry that debits the creditor operating account and credits the debtor, so the ledger shows both the error and the correction. The in-transit and settlement control accounts reconcile the reversal total against the duplicate total, and any unmatched reversal goes to an exception worklist with an owner and an SLA. Where a reversal is not possible because the window has closed, the alternative credit transfer is posted from a separate corrections account with its own reference, so it is never mixed into the scheme reversal totals. Operations reports reversal volumes, reasons and window breaches weekly, because a rising reversal rate is a billing control failure, not a normal cost of business.", "gherkin": ["Given a settled collection eligible for reversal", "When a valid reversal is submitted within the scheme window", "Then the reversal is linked to the original and posted once", "And the original settlement record remains unchanged", "Given a reversal request for an original that has already been refunded", "When the duplicate correction is detected", "Then the second correction is blocked", "And the existing refund is recorded as the correcting event"], "assessment": [{"question": "Within what window is an SDD reversal available?", "options": ["Within 8 weeks of the debit date", "Any time after the due date", "Only from the settlement date and within 5 Inter-PSP Business Days following the due date", "Within 13 months of the debit date"], "answer": 2, "explanation": "A reversal is only available from the settlement date and within 5 Inter-PSP Business Days following the due date."}, {"question": "How should a reversal be recorded?", "options": ["By deleting the original settlement entry", "As a debtor refund claim", "As a separate linked transaction that leaves the original intact", "By editing the original amount"], "answer": 2, "explanation": "A reversal is a separate linked transaction. The original settlement record remains intact."}, {"question": "Who initiates an SDD reversal?", "options": ["The debtor PSP", "The debtor through their bank", "The creditor", "The clearing mechanism automatically"], "answer": 2, "explanation": "A reversal is initiated by the creditor, unlike a refund claim which is initiated by the debtor."}, {"question": "What is the Core authorised refund period for a debtor?", "options": ["36 months", "14 calendar days", "5 Inter-PSP Business Days", "8 weeks from the debit date"], "answer": 3, "explanation": "An authorised SDD Core refund is available within 8 weeks of the debit date, with no questions asked. An unauthorised claim runs to 13 months."}]}}, {"id": "INS-162", "kind": "insight", "title": "Return reason and timeline handling", "topic": "Return reason and timeline handling", "theme": "SEPA Direct Debit", "text": "Map return reasons, message path, scheme timeline and customer/creditor notification.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch62s6", "title": "Reversals: pain.007, pacs.007 and Reason Codes AM05, MS02, MS03", "url": "lessons/ch62s6"}, "case": {"status": "authored", "business_problem": "Meridian Bank acts as debtor PSP for thousands of SDD collections each month. Its returns team receives pacs.004 returns with reason codes it does not consistently interpret, and creditors complain that they learn about a return days after the debtor was debited, with no clear explanation of what went wrong or whether the collection can be re-presented. A return for insufficient funds is treated the same as a return for a closed account, and a return inside the scheme window is treated the same as one that arrives late.\n\nThe cost of that confusion is concrete. A creditor that does not know the reason cannot fix the mandate, the account or the amount, so it re-presents a collection that will fail again. A debtor that is not told why a collection was returned cannot correct the underlying problem. And a bank that does not enforce the return timeline, Core D+5 Inter-PSP Business Days and B2B D+3 Inter-PSP Business Days, cannot tell a valid return from a late one.\n\nMeridian Bank needs a return handling playbook that starts from the reason code, applies the scheme timeline for the correct scheme, notifies both sides in plain language, and records whether the collection may be re-presented or must be repaired first.", "decision_exercise": {"scenario": "A Core collection is returned on D+4 with a reason code for insufficient funds. A second Core collection is returned on D+6 with a reason code for a closed account. The learner must decide how Meridian Bank should handle each return.", "options": [{"id": "A", "text": "Accept the D+4 return as inside the Core D+5 window and allow a corrected re-presentation; treat the D+6 return as outside the window, escalate it, and block re-presentation of the closed-account collection until the account is repaired."}, {"id": "B", "text": "Refund both debtors and ignore the reason codes."}, {"id": "C", "text": "Reject both returns because the debtor account was debited."}, {"id": "D", "text": "Treat both returns the same: notify the creditor and allow re-presentation of both."}], "correct_option": "A", "why": "Option A is correct because it applies the Core D+5 timeline to each return separately and uses the reason code to decide re-presentation. Option D is wrong because a late return and a closed account need different handling from a timely insufficient-funds return. Option C is wrong because a valid return inside the window must be honoured. Option B is wrong because a return is not a refund claim and the reason code drives the next action."}, "recommended_solution": "Handle every return through four steps in order: identify the reason, check the timeline, notify, then decide on re-presentation. The reason code is the primary fact. Insufficient funds, account closed, mandate invalid, account number invalid and debtor deceased each point to a different next action, and the team must map each code to a named action rather than to a generic returned label. The timeline check uses the scheme: a Core return must arrive within D+5 Inter-PSP Business Days and a B2B return within D+3 Inter-PSP Business Days. A return outside its window is escalated as a late return and is not treated as a routine event.\n\nNotification goes to both sides with the same facts but different wording. The creditor receives the original reference, the return reason, the return date and whether re-presentation is permitted. The debtor receives a plain-language explanation of what happened to their account and what they need to do, such as fund the account or update the mandate. The pacs.004 is the message that carries the return, and its reason code is preserved unchanged through every system so the creditor and the debtor see the same reason.\n\nRe-presentation is a decision, not a default. An insufficient-funds return may be re-presented where the scheme and the creditor agreement permit it, after the debtor has had a chance to fund the account. A closed-account or invalid-mandate return must not be re-presented until the account or mandate is repaired, and a duplicate re-presentation is blocked by the original instruction reference. Every return, notification and re-presentation decision is recorded against the original collection so the full history can be reconstructed.", "flow_steps": [{"step": 1, "actor": "Debtor PSP", "action": "Detects that a collection cannot be honoured, for example insufficient funds or a closed account.", "system": "Debtor PSP"}, {"step": 2, "actor": "Debtor PSP", "action": "Creates a pacs.004 return with the original instruction reference and the scheme reason code.", "system": "Debtor PSP"}, {"step": 3, "actor": "Clearing mechanism", "action": "Routes the return to the creditor PSP and records the return date for timeline checking.", "system": "Clearing mechanism"}, {"step": 4, "actor": "Creditor PSP", "action": "Validates the return against the scheme timeline, Core D+5 or B2B D+3 Inter-PSP Business Days.", "system": "Creditor PSP"}, {"step": 5, "actor": "Creditor", "action": "Receives the return with its reason code and updates the customer record and the collection status.", "system": "Creditor system"}, {"step": 6, "actor": "Creditor", "action": "Notifies the debtor in plain language and, where permitted, agrees a corrected re-presentation date.", "system": "Notification service"}, {"step": 7, "actor": "Collection service", "action": "Decides whether re-presentation is permitted and, if so, creates a new collection linked to the original.", "system": "Collection service"}, {"step": 8, "actor": "Operations", "action": "Reconciles the return against the original collection and closes the item or places it in the repair queue.", "system": "Reconciliation service"}], "happy_path": "A Core collection is returned on D+2 for insufficient funds. The pacs.004 carries the correct reason code and the original reference. The creditor PSP validates it as inside the D+5 window, the creditor notifies the debtor the same day, the debtor funds the account, and the creditor re-presents the collection on the agreed date with a link to the original. The re-presented collection settles, the return and the re-presentation reconcile as a linked pair, and no further action is needed.", "negative_paths": [{"path": "Late return", "trigger": "A Core return arrives on D+6, outside the D+5 window.", "handling": "Escalate the late return as an exception, do not treat it as a routine return, and resolve it through the agreed late-return procedure with the counterparty rather than by silent acceptance."}, {"path": "Mandate invalid return", "trigger": "The return reason shows the mandate is missing, revoked or mismatched.", "handling": "Block re-presentation, route the item to mandate repair, obtain a valid mandate with evidence before any new collection, and notify the debtor of what needs to be corrected."}, {"path": "Account closed return", "trigger": "The return reason shows the debtor account is closed.", "handling": "Stop all further collections for that account, contact the debtor for a new account and a new mandate, and never re-present to the closed account."}, {"path": "Pre-notification failure behind the return", "trigger": "The debtor disputes the collection because the pre-notification was late or never received.", "handling": "Check the stored notice evidence and its date, accept that the collection should not have proceeded if the notice failed, and handle the item as a notice failure rather than as a routine return."}], "technical_data": "Store the return as a separate event linked to the original by instruction ID and end-to-end ID, carrying the pacs.004 reason code unchanged from receipt to creditor notification. Validate the return date against the scheme timeline in Inter-PSP Business Days, using D+5 for Core and D+3 for B2B, and flag late returns automatically. Keep the mandate, account and pre-notification evidence linked to the original so the reason can be investigated without searching across systems. Block duplicate re-presentation on the original instruction reference plus the new due date, and require a repair flag to be cleared before a mandate-invalid or closed-account collection can be re-presented. Record every notification with its content, channel and timestamp, and keep the return, the notification and the re-presentation decision in one audit chain.", "messages_fields": [{"message": "pacs.004", "purpose": "Payment return carrying the return reason and the link to the original collection.", "key_fields": ["Original instruction ID and End-to-End ID", "Return reason code", "Returned amount, currency and value date", "Return date for timeline validation"]}, {"message": "pacs.003", "purpose": "Original direct debit collection instruction that was returned.", "key_fields": ["Instruction ID and End-to-End ID", "Mandate reference and creditor identifier", "Amount, currency and due date"]}, {"message": "pacs.002", "purpose": "Payment status report for acceptance or rejection of the return or any re-presentation.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}], "accounting_operational": "A return reverses the original settlement as a separate linked entry: the debtor is credited and the creditor is debited for the returned amount, with the reason code attached to the entry. The in-transit and settlement control accounts clear the original against the return, and any return without a matching original goes to a suspense worklist the same day. A re-presentation creates a new collection with its own accounting entries linked to the original, so the ledger shows the failed attempt and the successful retry as separate events. Operations monitors returns by reason code, scheme and lateness, with daily ageing on late returns and on mandate-invalid returns awaiting repair, and reports the return rate by creditor so a creditor with a rising return rate is contacted before the problem grows.", "gherkin": ["Given a Core collection returned within D+5 Inter-PSP Business Days for insufficient funds", "When the creditor is notified with the reason code", "Then re-presentation is permitted where the scheme and agreement allow it", "And the re-presentation is linked to the original collection", "Given a Core collection returned on D+6", "When the timeline check runs", "Then the return is flagged as late and escalated as an exception", "And it is not processed as a routine return"], "assessment": [{"question": "What is the return window for an SDD Core collection?", "options": ["13 months", "D+5 Inter-PSP Business Days", "D+3 Inter-PSP Business Days", "8 weeks"], "answer": 1, "explanation": "The Core return window is D+5 Inter-PSP Business Days. B2B is D+3."}, {"question": "What is the return window for an SDD B2B collection?", "options": ["36 months", "8 weeks", "D+5 Inter-PSP Business Days", "D+3 Inter-PSP Business Days"], "answer": 3, "explanation": "The B2B return window is D+3 Inter-PSP Business Days, shorter than the Core D+5 window."}, {"question": "Which message carries an SDD return?", "options": ["pain.001", "pacs.004", "pacs.008", "camt.056"], "answer": 1, "explanation": "The pacs.004 is the SDD return message, used for both returns and refunds."}, {"question": "A collection is returned because the mandate is invalid. What should happen before any re-presentation?", "options": ["Re-present immediately with the same mandate", "Repair or replace the mandate with valid evidence first", "Ask the debtor to pay by card instead", "Change the amount and re-present"], "answer": 1, "explanation": "A mandate-invalid return must not be re-presented until the mandate is repaired with valid evidence."}]}}, {"id": "INS-163", "kind": "insight", "title": "Core versus B2B scheme differences", "topic": "Core versus B2B scheme differences", "theme": "SEPA Direct Debit", "text": "Compare mandate, refund rights, eligibility and processing requirements using current EPC rulebooks.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch62s1", "title": "SDD Core and B2B: Two Schemes, Two Risk Profiles", "url": "lessons/ch62s1"}, "case": {"status": "authored", "business_problem": "Vantage Manufacturing sells components to other businesses and also sells spare parts directly to consumers. Its finance team wants one direct debit process for everyone, and it has been collecting from business customers under the Core scheme because that is the scheme it already uses for consumers. The result is a set of quiet risks: business debtors have a refund right the team assumes they do not have, or the team assumes a right that does not exist, and nobody can say which scheme each mandate belongs to without opening the individual mandate file.\n\nCore and B2B differ on the points that matter most when something goes wrong. Under Core, a debtor may claim a refund of an authorised collection within 8 weeks of the debit date with no questions asked, and may claim an unauthorised collection within 13 months. Under B2B there is no authorised refund right at all, which is why B2B debtors must be businesses, why the debtor PSP must support B2B, and why the debtor must actively authorise the mandate with its bank before the first collection. The return windows differ too: Core D+5 Inter-PSP Business Days against B2B D+3.\n\nVantage Manufacturing needs a scheme decision that is made once per customer type, recorded on the mandate, and enforced by the system, so a business customer is never collected under Core by accident and a consumer is never collected under B2B.", "decision_exercise": {"scenario": "Vantage Manufacturing signs a new business customer that wants to pay by direct debit. The customer is a registered company, its bank supports B2B, and it has agreed in writing that it will not have an authorised refund right. The learner must decide which scheme to use and what must happen before the first collection.", "options": [{"id": "A", "text": "Collect under Core for the first collection and switch to B2B later without telling the debtor."}, {"id": "B", "text": "Collect under B2B, after the debtor has authorised the mandate with its own bank and the mandate is recorded as B2B."}, {"id": "C", "text": "Collect under Core, because Core is simpler and the customer can claim a refund within 8 weeks if needed."}, {"id": "D", "text": "Collect under B2B without debtor bank authorisation, since the customer signed the mandate."}], "correct_option": "B", "why": "Option B is correct because B2B requires a business debtor, a supporting debtor PSP, and debtor authorisation of the mandate with its bank before collection, and it correctly reflects that B2B has no authorised refund right. Option C is wrong because it gives the business debtor a Core refund right the parties did not agree and misstates the scheme. Option D is wrong because B2B collection without debtor bank authorisation is not valid. Option A is wrong because switching schemes without agreement and without a new mandate basis breaches the scheme rules."}, "recommended_solution": "Decide the scheme from the debtor type and record it as a controlled field on the mandate, not as a free-text note. Core is for any debtor, including consumers, and carries the authorised refund right of 8 weeks and the unauthorised claim period of 13 months. B2B is only for business debtors, requires the debtor PSP to support B2B, requires the debtor to authorise the mandate with its bank before the first collection, and carries no authorised refund right. The system must enforce those rules: a B2B collection for a consumer debtor is blocked, a B2B collection without recorded debtor bank authorisation is blocked, and a Core collection for a business debtor is allowed only where the parties have deliberately chosen Core.\n\nThe operational differences follow the scheme. Pre-notification, the D-1 submission deadline and the mandate evidence rules apply under both schemes, but the return windows differ, Core D+5 against B2B D+3 Inter-PSP Business Days, and the refund handling differs completely. Support scripts must therefore ask which scheme the collection belongs to before answering any refund question, and the refund workflow must branch on the scheme: a Core authorised refund is processed within its 8-week window, an unauthorised claim is investigated within its 13-month window, and a B2B authorised refund request is declined with a clear explanation and an offer of a commercial resolution where appropriate.\n\nMigration between schemes is a new mandate exercise, not a field edit. Moving a debtor from Core to B2B needs a new B2B mandate, debtor bank authorisation, and a fresh pre-notification cycle. The curriculum should teach learners to verify the current EPC rulebook and the local implementation before configuring any timeline, because scheme details are set by the rulebook and can change.", "flow_steps": [{"step": 1, "actor": "Sales team", "action": "Identifies the customer as a business or a consumer and records the debtor type.", "system": "Customer system"}, {"step": 2, "actor": "Finance team", "action": "Selects Core or B2B from the debtor type and records the scheme on the mandate as a controlled field.", "system": "Mandate service"}, {"step": 3, "actor": "Debtor", "action": "Signs the mandate. For B2B, the debtor also authorises the mandate with its own bank before the first collection.", "system": "Mandate service"}, {"step": 4, "actor": "Creditor", "action": "Sends pre-notification at the latest 14 calendar days before the due date and stores delivery evidence.", "system": "Notification service"}, {"step": 5, "actor": "Collection service", "action": "Validates the mandate, scheme, debtor type and authorisation before file generation.", "system": "Collection service"}, {"step": 6, "actor": "Creditor PSP", "action": "Submits the collection by the D-1 deadline under the selected scheme.", "system": "Creditor PSP"}, {"step": 7, "actor": "Debtor PSP", "action": "Processes the collection under the scheme rules, including the scheme return window.", "system": "Debtor PSP"}, {"step": 8, "actor": "Support team", "action": "Handles any refund or return question by first confirming the scheme, then applying the scheme refund and return rules.", "system": "Customer service system"}], "happy_path": "The business customer is correctly identified, the mandate is recorded as B2B, and the debtor authorises it with its bank before the first collection. Pre-notification is sent on time, the collection is submitted by D-1, and it settles on the due date. When the customer later asks about refunds, support confirms the scheme is B2B, explains there is no authorised refund right, and resolves the underlying billing query commercially. Consumer customers continue under Core with their 8-week authorised refund right intact, and no customer is ever collected under the wrong scheme.", "negative_paths": [{"path": "B2B collection without debtor bank authorisation", "trigger": "A B2B collection is submitted before the debtor has authorised the mandate with its bank.", "handling": "Block the collection at validation, obtain the debtor bank authorisation with evidence, and only then re-issue the collection for a later due date."}, {"path": "Consumer collected under B2B", "trigger": "A consumer debtor is recorded under a B2B mandate by error.", "handling": "Stop the collection, replace the mandate with a Core mandate, and notify the debtor that the scheme has been corrected before any further collection."}, {"path": "B2B authorised refund requested", "trigger": "A B2B debtor asks for an authorised refund within 8 weeks, assuming the Core right applies.", "handling": "Explain that B2B has no authorised refund right, investigate whether the collection was unauthorised, and offer a commercial resolution where the creditor accepts the billing was wrong."}, {"path": "Return window applied to the wrong scheme", "trigger": "Operations applies the Core D+5 window to a B2B return that is already on D+4.", "handling": "Correct the timeline to B2B D+3, escalate the return as late, and fix the scheme flag on the collection so the error does not repeat."}], "technical_data": "Store the scheme as a controlled field on the mandate with the values Core and B2B, together with the debtor type, the debtor PSP B2B support flag, and the debtor bank authorisation status and date for B2B. Enforce validation rules by scheme: B2B requires a business debtor, a supporting debtor PSP and recorded authorisation before the first collection. Keep the refund and return rules as scheme-driven configuration, Core D+5 and 8-week authorised refund with 13-month unauthorised claim, B2B D+3 and no authorised refund right, so a support agent cannot apply the wrong timeline by mistake. Record the scheme on every collection, return and refund event, and verify the current EPC rulebook before any timeline change is configured. A mandate unused for 36 months must not be used under either scheme.", "messages_fields": [{"message": "pain.008", "purpose": "Collection file carrying the scheme, mandate reference and debtor details to the creditor PSP.", "key_fields": ["Scheme indicator: Core or B2B", "Mandate reference and creditor identifier", "Debtor IBAN and debtor agent", "Collection amount, currency and due date"]}, {"message": "pacs.003", "purpose": "Direct debit collection instruction submitted into clearing under the selected scheme.", "key_fields": ["Scheme indicator", "Mandate reference and creditor identifier", "Amount, currency and due date", "Instruction ID and End-to-End ID"]}, {"message": "pacs.004", "purpose": "Return or refund of a collection, with the reason and timeline governed by the scheme.", "key_fields": ["Original instruction reference", "Return or refund reason code", "Returned amount and value date", "Scheme indicator for timeline validation"]}], "accounting_operational": "Core and B2B collections are accounted through the same in-transit and settlement control accounts, but their exception handling diverges. Core refunds post as linked refund entries within the 8-week window, with unauthorised claims tracked separately up to 13 months. B2B authorised refund requests are not posted as scheme refunds; where the creditor agrees a commercial correction, it is posted as a separate creditor credit transfer from a corrections account so it is never counted as a scheme refund. Returns are aged against their scheme window, Core D+5 and B2B D+3, and late returns are escalated by scheme. Operations reports refund and return rates separately for Core and B2B, because a single blended rate would hide a scheme-specific control failure.", "gherkin": ["Given a B2B mandate without recorded debtor bank authorisation", "When collection validation runs", "Then the collection is blocked and routed to authorisation", "And no collection is submitted until the authorisation is recorded", "Given a Core authorised collection refund request within 8 weeks of the debit date", "When the claim is validated", "Then the bank applies the scheme-defined Core refund process", "And a B2B authorised refund request is handled under the B2B rule, with no authorised refund right"], "assessment": [{"question": "What is the authorised refund right under SDD Core?", "options": ["Refund within 5 business days", "Refund within 8 weeks of the debit date, no questions asked", "Refund within 36 months", "No authorised refund right"], "answer": 1, "explanation": "Core gives an authorised refund within 8 weeks of the debit date, no questions asked. An unauthorised claim runs to 13 months."}, {"question": "What is the authorised refund right under SDD B2B?", "options": ["Refund within 8 weeks", "No authorised refund right", "Refund within 3 business days", "Refund within 13 months"], "answer": 1, "explanation": "B2B has no authorised refund right, which is why debtor bank authorisation before the first collection matters."}, {"question": "What is the B2B return window?", "options": ["D+3 Inter-PSP Business Days", "14 calendar days", "8 weeks", "D+5 Inter-PSP Business Days"], "answer": 0, "explanation": "B2B returns must arrive within D+3 Inter-PSP Business Days, against Core D+5."}, {"question": "Can a consumer debtor be collected under SDD B2B?", "options": ["Yes, B2B is open to all debtors", "Yes, with a Core mandate", "Yes, if the amount is small", "No, B2B is only for business debtors"], "answer": 3, "explanation": "B2B is only for business debtors, and the debtor PSP must support B2B."}]}}, {"id": "INS-164", "kind": "insight", "title": "India-to-Europe corridor operating model", "topic": "India-to-Europe corridor operating model", "theme": "Cross-Border Instant", "text": "Identify participants, domestic rail legs, cross-border bridge, FX, settlement and compliance responsibilities.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch33s7", "title": "Cross-Border Payments from India: SWIFT, Nostro, Vostro and a Worked Example", "url": "lessons/ch33s7"}, "case": {"status": "authored", "business_problem": "Kaveri Textiles exports fabric from India to buyers in Europe, and its finance director has a simple complaint: the money leaves the buyer quickly and arrives in India slowly, and nobody can say who owns each part of the journey. The European buyer pays in euros, the Indian exporter needs rupees, the payment crosses a domestic euro rail, a cross-border bridge, an FX conversion and a domestic Indian rail, and each participant reports only its own leg. When a payment is late, the exporter calls the buyer, the buyer calls its bank, and the bank calls the bridge operator, and the answer is always that the other party holds the money.\n\nThe operating model has to name every participant and give each one a single responsibility. The originating bank owns the euro leg and the customer instruction. The bridge operator owns the orchestration, the FX execution and the end-to-end state. The Indian partner bank owns the INR leg and the credit to the exporter. Compliance screening, liquidity and settlement are owned explicitly, not shared vaguely, so a failure has one owner and one escalation path.\n\nThe model must also be honest about timing. A domestic euro leg can complete inside the 10-second SCT Inst window, and a domestic Indian leg can complete instantly on UPI or IMPS, but the end-to-end payment is only complete when every leg confirms. The customer promise must reflect that, not the speed of the fastest leg.", "decision_exercise": {"scenario": "A EUR 25,000 payment from a European buyer to Kaveri Textiles has been debited from the buyer, the euro leg is confirmed, but the INR leg has produced no confirmation after the corridor timeout. The learner must decide who owns the next action and what the customer should be told.", "options": [{"id": "A", "text": "Credit the exporter from the bridge suspense account so the exporter is not kept waiting."}, {"id": "B", "text": "Place the payment in the bridge investigation state, owned by the bridge operator, tell both customers the INR leg is unconfirmed, and resolve it through leg reconciliation before any retry or compensation."}, {"id": "C", "text": "Tell the exporter the payment is complete because the buyer was debited."}, {"id": "D", "text": "Ask the buyer to send the payment again immediately."}], "correct_option": "B", "why": "Option B is correct because the bridge operator owns the end-to-end state, an unconfirmed leg is an investigation case, and no retry or compensation happens before the leg states are established. Option C is wrong because a sender debit does not prove beneficiary credit. Option D is wrong because a blind resend risks a duplicate payment. Option A is wrong because crediting from suspense before the leg outcome is known creates a double-payment risk."}, "recommended_solution": "Define the operating model as a table of participants, responsibilities and handoffs. The originating bank validates the instruction, runs Verification of Payee on the euro leg, screens the payment, and releases the euro leg as SCT Inst or as a One-Leg-Out Instant Credit Transfer where one leg sits outside SEPA. The bridge operator receives the euro confirmation, revalidates the FX quote, checks settlement liquidity, and instructs the INR leg. The Indian partner bank executes the INR leg on the rail that fits the amount and urgency, UPI for small instant transfers within its limits, IMPS for instant bank transfers typically capped by banks around Rs 5 lakh, NEFT in half-hourly batches, or RTGS for individual real-time settlement from Rs 2 lakh, and confirms the credit.\n\nCompliance is split by ownership: the originating bank owns sanctions, AML and fraud screening on the euro side, the bridge operator owns corridor-level screening and sanctions list currency, and the Indian partner bank owns local regulatory checks on the INR leg. No participant may bypass a mandatory check to protect a speed target, and each check has a synchronous decision deadline and a fail-closed rule.\n\nSettlement and liquidity are owned by the bridge operator, which holds the corridor settlement accounts, funds them to the agreed level, and reconciles them daily. FX risk sits with the party named in the quote contract, and the quote expiry is enforced at execution. The end-to-end state is owned by the bridge operator and is the only status shown to the customer as the corridor status; leg statuses are shown as supporting detail, never as the headline. A failure after sender debit follows a defined path: establish whether the debit is provisional, final or held, await or request the missing confirmation, and only then return funds or compensate, with exactly one financial effect.", "flow_steps": [{"step": 1, "actor": "Buyer", "action": "Instructs a EUR payment to Kaveri Textiles with invoice reference and purpose.", "system": "European online banking"}, {"step": 2, "actor": "Originating bank", "action": "Validates the instruction, runs Verification of Payee and screening, and obtains an FX quote.", "system": "Payment engine"}, {"step": 3, "actor": "Buyer", "action": "Accepts the FX quote and confirms the payment.", "system": "European online banking"}, {"step": 4, "actor": "Originating bank", "action": "Releases the euro leg and confirms it through the instant clearing mechanism.", "system": "Instant clearing mechanism"}, {"step": 5, "actor": "Bridge operator", "action": "Receives the euro confirmation, revalidates the FX quote and checks settlement liquidity.", "system": "Corridor orchestration"}, {"step": 6, "actor": "Bridge operator", "action": "Executes the FX conversion at the agreed rate and instructs the INR leg to the Indian partner bank.", "system": "Corridor orchestration"}, {"step": 7, "actor": "Indian partner bank", "action": "Runs local compliance checks and executes the INR leg on the selected domestic rail.", "system": "Indian domestic rail"}, {"step": 8, "actor": "Indian partner bank", "action": "Credits Kaveri Textiles and returns the confirmation with the credit timestamp.", "system": "Core banking"}, {"step": 9, "actor": "Bridge operator", "action": "Matches all leg confirmations, marks the corridor payment Complete, and publishes one customer timeline.", "system": "Corridor orchestration"}], "happy_path": "The buyer accepts the FX quote, screening clears, and the euro leg confirms inside the SCT Inst 10-second window. The bridge operator revalidates the quote while it is still valid, executes the conversion, and instructs the INR leg. The Indian partner bank runs its local checks and credits Kaveri Textiles on the selected domestic rail. The bridge operator matches the euro confirmation, the FX execution and the INR credit, marks the payment Complete, and both customers see a single timeline with the applied rate, the fees and the confirmation time for each leg.", "negative_paths": [{"path": "Asynchronous legs with no destination confirmation", "trigger": "The euro leg is accepted but the destination system has not confirmed beneficiary credit.", "handling": "Model each leg separately with an overall orchestration state, apply the scheme timeout, enter an investigation state when the threshold is reached, and do not blindly resubmit."}, {"path": "Payment fails after sender debit", "trigger": "The sender is debited but the receiving system reports a technical failure or no final response.", "handling": "Establish whether the debit is provisional, final or held, use scheme rules and leg status to decide whether to await confirmation, return funds or investigate, and ensure exactly one financial effect."}, {"path": "Compliance screening threatens the instant SLA", "trigger": "A mandatory check cannot complete inside the rail processing window.", "handling": "Apply the approved fail-closed rule, hold or reject under the documented procedure, escalate within the screening SLA, and never bypass screening for speed."}, {"path": "Duplicate callback or late success", "trigger": "A late success arrives after a timeout, or a confirmation callback is delivered twice.", "handling": "Resolve the transaction from durable leg state and unique financial event IDs, so a late success and a refund cannot both take effect, and a duplicate callback cannot double-post."}], "technical_data": "Give every corridor payment a single orchestration ID plus a leg ID for each leg, and propagate the instruction ID, end-to-end ID and UETR where applicable unchanged across all legs. Keep a durable leg-level state machine for the euro leg, the bridge settlement leg and the INR leg, with an overall orchestration state that only moves to Complete on the required confirmations. Make every financial posting idempotent on its financial event ID, and store FX quote, consent, screening decision and leg confirmation as separate audit events with source and timestamp. Translate data through a canonical model that preserves the structured or hybrid address, the purpose code and the rail-specific references, and never fabricate a value missing from the source message. Define the corridor timeout, the investigation trigger and the compensation rules in configuration, and test the race between a late success and a return so exactly one outcome is possible.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer for the euro customer leg.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor and creditor agent BICs", "Creditor account and structured or hybrid address", "Amount, currency and remittance information", "UETR where applicable"]}, {"message": "pacs.009", "purpose": "Financial institution transfer and cover leg for bridge settlement.", "key_fields": ["Settlement amount and currency", "Underlying customer reference for linkage", "Settlement account and value date", "UETR where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report for each leg, carrying acceptance, rejection and execution outcomes.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}, {"message": "pacs.004", "purpose": "Return of a leg where a return is required under the scheme rules.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and value date"]}], "accounting_operational": "Each leg posts its own linked entries: the euro receipt credits a corridor settlement account, the FX execution posts the conversion at the agreed rate with the spread recorded separately, and the INR leg debits the settlement account and credits the exporter. A leg that confirms without its counterpart is parked in a corridor suspense worklist with the bridge operator as owner and a defined SLA, and no compensation is posted until the leg states are established. Nostro and settlement account reconciliation runs daily on the bridge accounts with same-day break ageing, and fees are posted per leg so the customer can see the cost of each stage. Operations works four queues: unconfirmed legs past timeout, screening holds, quote expiries and unmatched settlements, each with its own escalation time and a rule that no item is retried without a fresh decision.", "gherkin": ["Given the originating leg is accepted but destination confirmation is absent", "When the timeout threshold is reached", "Then the payment enters an unknown or investigation state", "And it is not blindly resubmitted", "Given a timeout followed by a late success", "When the late event is received", "Then the system resolves the transaction without both crediting the beneficiary and refunding the sender", "And exactly one financial effect is recorded"], "assessment": [{"question": "Who owns the end-to-end state of a corridor payment?", "options": ["The bridge operator, as the orchestrator", "The Indian partner bank alone", "The clearing mechanism", "The buyer"], "answer": 0, "explanation": "The bridge operator owns orchestration and the end-to-end state. Each participant owns its own leg."}, {"question": "Which Indian rail settles individually in real time with a minimum of Rs 2 lakh?", "options": ["RTGS", "IMPS", "NEFT", "UPI"], "answer": 0, "explanation": "RTGS settles individually in real time, minimum Rs 2 lakh, with no RBI maximum."}, {"question": "A sender is debited but the destination reports no final response. What must the bank establish first?", "options": ["Whether the FX rate moved", "Whether to resend immediately", "Whether the customer will complain", "Whether the debit is provisional, final or held"], "answer": 3, "explanation": "The debit character determines whether to await confirmation, return funds or investigate, and it protects exactly-once financial effect."}, {"question": "How is NEFT settlement organised?", "options": ["In half-hourly batches", "Individually in real time", "Once a day", "Only on business days"], "answer": 0, "explanation": "NEFT settles in half-hourly batches and operates 24x7x365, as do RTGS and IMPS."}]}}, {"id": "INS-165", "kind": "insight", "title": "France-to-Algeria fee transparency example", "topic": "France-to-Algeria fee transparency example", "theme": "Cross-Border Instant", "text": "Use the cited \u20ac140 transfer and 11.39% fee as a prompt to analyse corridor cost components; revalidate the original post and figures before publishing.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Source URL pending verification", "messages": "", "lesson": {"id": "ch15s6", "title": "Transparency: fees, rates and time in the open", "url": "lessons/ch15s6"}}, {"id": "INS-166", "kind": "insight", "title": "Domestic instant payment system interoperability", "topic": "Domestic instant payment system interoperability", "theme": "Cross-Border Instant", "text": "Compare technical connectivity with alignment of scheme rules, participants, operating hours and dispute processes.", "domain": "Payment Architecture", "area": "Payment Architecture", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch74s1", "title": "NPP: Australia instant payments and PayID", "url": "lessons/ch74s1"}, "case": {"status": "authored", "business_problem": "Meridian Bank wants to connect its customers to instant payment systems in three markets: UPI in India, SCT Inst in Europe, and FedNow and RTP in the United States. Its engineers have shown that the technical connection is feasible, and its product team has assumed that a technical connection means the systems will behave the same way. That assumption breaks on the first cross-border payment, because the systems differ on the points that decide the customer promise: maximum amounts, execution windows, operating hours, confirmation rules and dispute processes.\n\nThe numbers make the point. SCT Inst has no scheme-level maximum and a 10-second maximum execution window. FedNow has a maximum of USD 10 million with a participant default of USD 100,000, and RTP has a limit of USD 10 million. UPI has a limit of INR 5 lakh for specified categories. The Indian rails operate 24x7x365, while other systems have their own operating models and cut-offs. A payment that is instant on one system and batched on another cannot be sold as instant end to end.\n\nMeridian Bank needs an interoperability design that compares technical connectivity with scheme rule alignment, and that only promises what the slowest aligned rule permits. The design must also say what happens when the rules do not align, because that is the normal case, not the exception.", "decision_exercise": {"scenario": "Meridian Bank plans a corridor between UPI in India and SCT Inst in Europe. The technical teams confirm both systems can exchange messages. The product team wants to advertise the corridor as instant end to end with a single 10-second promise. The learner must decide what promise the bank can honestly make.", "options": [{"id": "A", "text": "Drop the corridor because the two systems have different limits."}, {"id": "B", "text": "Advertise a 10-second end-to-end promise, because SCT Inst executes in 10 seconds."}, {"id": "C", "text": "Advertise the corridor as instant and handle any delay as a customer complaint."}, {"id": "D", "text": "Promise only what the aligned rules permit: instant domestic legs with an end-to-end confirmation that depends on both legs, FX and screening, and publish the leg-level timings."}], "correct_option": "D", "why": "Option D is correct because interoperability requires alignment of scheme rules, limits, hours and dispute processes, not just technical connectivity, and the customer promise must reflect the slowest aligned rule. Option B is wrong because the SCT Inst window governs only the euro leg. Option C is wrong because it sells a promise the corridor cannot keep. Option A is wrong because different limits can be managed with routing and disclosure rather than by abandoning the corridor."}, "recommended_solution": "Assess interoperability on four layers and require alignment on each before a customer promise is made. Layer one is technical connectivity: message formats, APIs, identifiers and character sets. Layer two is scheme rules: maximum amounts, execution windows, finality, return and refund rights, and timeout behaviour. Layer three is operating model: operating hours, cut-offs, liquidity arrangements and settlement cycles. Layer four is dispute and exception handling: who investigates, what evidence is needed, and what the customer is owed when a leg fails.\n\nWhere the layers do not align, the corridor design must say so explicitly and choose a handling rule. If the limits differ, the corridor applies the lower effective limit for the corridor and discloses it before the customer confirms. If the execution windows differ, the end-to-end promise is the sum of the aligned windows plus FX and screening time, not the fastest leg. If the dispute processes differ, the corridor names a single investigation owner and a single customer SLA, and the participants agree the evidence each will supply.\n\nThe bridge between two domestic systems is an orchestration layer, not a passthrough. It translates data through a canonical model, enforces the corridor limits, binds the FX quote, runs the corridor screening, and holds the end-to-end state. It reports leg confirmations separately and only reports completion when the required confirmations arrive. A leg that is instant and a leg that is batched are both shown truthfully, so a customer who pays on a UPI leg that confirms in seconds and an onward leg that settles in a batch understands the journey before they pay.", "flow_steps": [{"step": 1, "actor": "Product team", "action": "Maps the scheme rules of each domestic system: limits, execution windows, hours, finality and dispute rules.", "system": "Scheme rule register"}, {"step": 2, "actor": "Architecture team", "action": "Designs the canonical model and the translation rules for identifiers, addresses and purpose codes.", "system": "Integration platform"}, {"step": 3, "actor": "Customer", "action": "Instructs a cross-border instant payment and sees the corridor limit and the expected leg timings before confirming.", "system": "Mobile banking"}, {"step": 4, "actor": "Payment engine", "action": "Validates the instruction against the corridor limit and runs screening with synchronous decision deadlines.", "system": "Payment engine"}, {"step": 5, "actor": "Originating domestic system", "action": "Executes the domestic leg under its own scheme rules and returns its confirmation.", "system": "Domestic instant system"}, {"step": 6, "actor": "Bridge operator", "action": "Revalidates the FX quote, checks liquidity, and instructs the destination domestic leg.", "system": "Corridor orchestration"}, {"step": 7, "actor": "Destination domestic system", "action": "Executes the destination leg under its own scheme rules and returns its confirmation.", "system": "Domestic instant system"}, {"step": 8, "actor": "Bridge operator", "action": "Matches both leg confirmations and publishes the end-to-end status with leg-level detail.", "system": "Corridor orchestration"}], "happy_path": "The corridor is designed with aligned rules: the corridor limit is set at the lower effective limit, the end-to-end timing is published as the sum of the leg windows plus FX and screening, and a single investigation owner is named. A customer payment passes screening, the originating leg confirms, the bridge revalidates the FX quote, the destination leg confirms, and the customer sees a complete timeline with the time of each leg. Reconciliation matches both legs to the corridor settlement account without exception.", "negative_paths": [{"path": "Limit mismatch blocks the payment", "trigger": "The payment amount fits the originating system limit but exceeds the destination system limit.", "handling": "Block the payment before debit with a clear limit message, offer to split the payment only where the customer agrees and the scheme permits it, and never silently reduce the amount."}, {"path": "Asynchronous legs with no destination confirmation", "trigger": "The originating leg confirms but the destination leg produces no confirmation within the corridor timeout.", "handling": "Enter the investigation state, keep the end-to-end status unconfirmed, and resolve through leg reconciliation before any retry or compensation."}, {"path": "Dispute process mismatch", "trigger": "The two systems have different investigation evidence and timelines, so neither side accepts the other's evidence.", "handling": "Apply the corridor dispute agreement, with the named investigation owner collecting the agreed evidence set from both sides and owning the customer communication."}, {"path": "Screening delay breaks the instant window", "trigger": "A mandatory check on one leg cannot complete inside that leg's processing window.", "handling": "Apply the fail-closed rule for that leg, hold the payment with a clear reason, and never release it to protect the corridor speed promise."}], "technical_data": "Maintain a scheme rule register that records, for each domestic system, the maximum amount, the execution window, the operating hours, the finality rule, the return and refund rights, and the dispute process, with effective dates and a named owner for each entry. Build the canonical model to preserve the instruction ID, end-to-end ID and UETR where applicable, plus the structured or hybrid address and the purpose code, across the translation. Enforce the corridor limit as the lower effective limit of the aligned systems, and validate it before debit. Make every leg posting idempotent on its leg ID, keep leg states durable and separate from the orchestration state, and record the translation decisions so a field that cannot be mapped is flagged rather than dropped. Note the current figures in the register: SCT Inst has no scheme maximum and a 10-second window, FedNow has a maximum of USD 10 million with a participant default of USD 100,000, RTP has a limit of USD 10 million, and UPI has a limit of INR 5 lakh for specified categories.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer for the customer leg on the euro side of the corridor.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor and creditor agent BICs", "Creditor account and structured or hybrid address", "Amount, currency and remittance information", "UETR where applicable"]}, {"message": "pacs.009", "purpose": "Financial institution transfer for settlement between the corridor participants.", "key_fields": ["Settlement amount and currency", "Underlying customer reference for linkage", "Settlement account and value date"]}, {"message": "pacs.002", "purpose": "Payment status report for each domestic leg.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}, {"message": "pain.001", "purpose": "Customer payment initiation carrying the corridor instruction into the payment engine.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor account and creditor details", "Amount, currency and requested execution date"]}], "accounting_operational": "Each domestic leg posts its own linked entries against a corridor settlement account, so the originating receipt, the FX conversion and the destination payout reconcile independently and in total. A leg that confirms without its counterpart is parked in a corridor suspense worklist owned by the bridge operator, and no compensation is posted until the leg states are established. Daily reconciliation covers the corridor settlement account, the FX execution account and the domestic leg control accounts, with same-day break ageing. Operations monitors limit breaches, leg timeouts, screening holds and dispute cases as separate queues, and the corridor limit and timing promise are reviewed whenever any participating scheme changes its rules, so a rule change on one side cannot silently invalidate the customer promise.", "gherkin": ["Given a corridor payment that exceeds the destination system limit", "When validation runs before debit", "Then the payment is blocked with a clear limit message", "And the amount is not silently reduced or split without customer agreement", "Given the originating leg is confirmed but the destination confirmation is absent", "When the corridor timeout is reached", "Then the payment enters the investigation state", "And the end-to-end status is not reported as Complete"], "assessment": [{"question": "What is the FedNow maximum transaction value?", "options": ["USD 100,000", "USD 10 million", "No maximum", "USD 1 million"], "answer": 1, "explanation": "FedNow has a maximum of USD 10 million, effective November 2025, with a participant default of USD 100,000."}, {"question": "What is the RTP limit?", "options": ["USD 10 million from 9 February 2025", "USD 100,000", "INR 5 lakh", "USD 1 million"], "answer": 0, "explanation": "The RTP limit is USD 10 million from 9 February 2025."}, {"question": "What is the UPI limit for specified categories?", "options": ["INR 5 lakh", "INR 50,000", "INR 1 lakh", "No limit"], "answer": 0, "explanation": "The UPI limit is INR 5 lakh for specified categories from December 2024."}, {"question": "Technical connectivity alone proves two instant systems are interoperable. True or false?", "options": ["False", "True"], "answer": 0, "explanation": "False. Interoperability also needs alignment of scheme rules, limits, operating hours, finality and dispute processes."}]}}, {"id": "INS-167", "kind": "insight", "title": "Payment message standards and APIs across corridors", "topic": "Payment message standards and APIs across corridors", "theme": "Cross-Border Instant", "text": "Define common data model, translation, validation and error semantics across different domestic rails.", "domain": "ISO 20022 & APIs", "area": "ISO 20022 & APIs", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch26s3", "title": "ISO 20022 APIs", "url": "lessons/ch26s3"}, "case": {"status": "authored", "business_problem": "Meridian Bank runs payment APIs for corporate customers, a mobile channel for retail customers, and a set of correspondent connections for cross-border payments. Each channel sends similar but non-identical payment fields, and the bank's canonical payment model collapses the differences into one generic set of fields. The result is a series of small data losses that become large operational problems: an instruction ID is mistaken for an end-to-end reference, a structured address is flattened into a single free-text line, and a purpose code that one rail requires is dropped because another rail does not use it.\n\nThe damage shows up downstream. A payment that cannot be correlated to its original instruction cannot be investigated. A payment whose address was flattened fails validation at the next bank. A payment whose purpose code was dropped is held for compliance review. Each failure looks like a rail problem, but the cause is the translation layer.\n\nMeridian Bank needs a common data model that preserves business semantics, source provenance and scheme-specific extensions, with translation rules that are documented, versioned and tested, so a payment can travel across corridors without losing the information its destination needs.", "decision_exercise": {"scenario": "A corporate customer sends a payment through the Meridian Bank API with an instruction ID, an end-to-end ID and a structured address. The payment must travel as a pacs.008 to Europe and then as a domestic instruction in India. The learner must decide how the canonical model should carry these fields.", "options": [{"id": "A", "text": "Keep the instruction ID, end-to-end ID and UETR as separate fields, preserve the structured address, and record the source provenance and mapping rules."}, {"id": "B", "text": "Map both IDs into one generic reference field and flatten the address into a single text line, to keep the model simple."}, {"id": "C", "text": "Drop the end-to-end ID because the domestic rail does not use it."}, {"id": "D", "text": "Generate a new instruction ID at each hop so every system has a fresh reference."}], "correct_option": "A", "why": "Option A is correct because identifiers have distinct semantics and lifecycles, and the structured address and purpose data must survive translation. Option B is wrong because collapsing distinct identifiers into one field destroys correlation and investigation. Option C is wrong because dropping the end-to-end ID breaks the customer tracking chain. Option D is wrong because regenerating identifiers at each hop breaks linkage between the original instruction and its downstream legs."}, "recommended_solution": "Define the canonical model as a governed contract, not as a developer convenience. It carries separate fields for the internal transaction ID, the instruction ID, the end-to-end ID, the transaction ID, the UETR where applicable, and the clearing references, each with a documented meaning, uniqueness scope, generation rule and propagation matrix. A mapping that places an internal ID into an end-to-end field is a defect, not a shortcut, and the mapping rules must say so explicitly.\n\nAddress data is preserved in structured or hybrid form with Town Name and Country Code as a minimum, or a BIC only where the scheme permits it. The team must not teach a fixed structured-address cut-off date, since the timeline was extended in July 2026 and a new timeline was expected by December 2026. Where a destination rail cannot carry a structured address, the translation records what was carried, what was dropped, and why, and the payment is flagged for review rather than sent with fabricated data. A mandatory value missing from the source message is never invented.\n\nEvery translation is versioned with the message version, the mapping version and the effective date, and every payment carries lineage: the source channel, the source message, the mapping version and the target message. Round-trip testing proves that a payment mapped from the source to the canonical model and back to the source format returns the same business meaning. Error semantics are standardised across the APIs: validation errors, business rejects and technical failures each have their own code set, so a channel can tell the customer whether to correct the data, wait, or contact the bank.", "flow_steps": [{"step": 1, "actor": "Corporate customer", "action": "Submits a payment through the API with instruction ID, end-to-end ID, structured address and purpose code.", "system": "Corporate API"}, {"step": 2, "actor": "Channel adapter", "action": "Validates the API payload against the API schema and records the source provenance.", "system": "Integration platform"}, {"step": 3, "actor": "Canonical service", "action": "Maps the payload to the canonical model, preserving each identifier in its own field and the structured address intact.", "system": "Canonical payment service"}, {"step": 4, "actor": "Payment engine", "action": "Validates the canonical payment against scheme rules, limits and screening requirements.", "system": "Payment engine"}, {"step": 5, "actor": "Message mapper", "action": "Translates the canonical payment to a pacs.008 for the euro leg, carrying the identifiers and address correctly.", "system": "Message mapper"}, {"step": 6, "actor": "Clearing mechanism", "action": "Processes the pacs.008 and returns a pacs.002 status with the original references.", "system": "Clearing mechanism"}, {"step": 7, "actor": "Message mapper", "action": "Translates the confirmed payment to the destination domestic format, preserving the end-to-end ID for tracking.", "system": "Message mapper"}, {"step": 8, "actor": "Status service", "action": "Correlates the status events by the stable identifiers and publishes one customer timeline.", "system": "Status service"}], "happy_path": "The corporate customer submits a complete API instruction. The channel adapter validates it, the canonical service maps each identifier to its own field and preserves the structured address, and the payment engine validates it against the scheme rules. The message mapper produces a correct pacs.008, the clearing mechanism returns a pacs.002 that correlates by the original references, and the destination mapper carries the end-to-end ID into the domestic instruction. Every status event correlates to the original instruction, the customer sees one coherent timeline, and a round-trip test would return the same business meaning.", "negative_paths": [{"path": "Canonical model loses source semantics", "trigger": "Two source fields with different business meaning are mapped into one generic canonical field.", "handling": "Reject the mapping at design review, split the canonical fields, document the distinction, and add a round-trip test that proves the semantics survive."}, {"path": "Identifier reused with different meanings", "trigger": "An internal transaction ID is mistakenly mapped to an end-to-end reference or an instruction ID.", "handling": "Block the mapping by the identifier catalogue, correct the propagation matrix, and quarantine any payment already sent with the wrong identifier for investigation."}, {"path": "Unsupported scheme extension dropped", "trigger": "A purpose code or address element required by the destination rail has no field in the canonical model.", "handling": "Flag the payment for review, extend the canonical model with a documented extension field, and do not send the payment with the data silently dropped."}, {"path": "Structured address flattened", "trigger": "A structured address is converted to a single free-text line and fails validation at the next bank.", "handling": "Restore the structured or hybrid address from the source record, revalidate it against the scheme minimum of Town Name and Country Code, and fix the mapper so the structure is preserved."}], "technical_data": "Own the canonical model with a field dictionary that records each field, its meaning, cardinality, owner, source, target mappings and version. Keep separate fields for the internal ID, instruction ID, end-to-end ID, transaction ID, UETR and clearing references, with a propagation matrix that says which identifier travels where and which stays internal. Version the model and every mapping with effective dates, and record the mapping version on each payment so a defect can be traced to a mapping release. Preserve the structured or hybrid address and never fabricate a missing mandatory value. Standardise API error semantics so validation, business and technical failures are distinguishable, and make status correlation idempotent on the stable identifiers so duplicate events cannot regress the payment state. Remember the message lineage: MT103 maps to pacs.008 and MT202 COV maps to pacs.009, with pacs.008 as the customer leg and pacs.009 as the FI-to-FI and cover leg, and SWIFT is the network and messaging service while ISO 20022 is the message standard.", "messages_fields": [{"message": "pain.001", "purpose": "Customer payment initiation from the corporate API or channel into the payment engine.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor account and creditor details", "Amount, currency and requested execution date", "Remittance information and purpose"]}, {"message": "pacs.008", "purpose": "Customer credit transfer for the onward customer leg.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor and creditor agent BICs", "Creditor account and structured or hybrid address", "Amount, currency and remittance information", "UETR where applicable"]}, {"message": "pacs.009", "purpose": "Financial institution transfer and cover leg for settlement between banks.", "key_fields": ["Settlement amount and currency", "Underlying customer reference for linkage", "Settlement account and value date", "UETR where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report that correlates back to the original instruction by its stable identifiers.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}], "accounting_operational": "The canonical model carries the accounting references as well as the payment references, so each leg posts against the correct control account and the reconciliation can match the API instruction to the clearing entry by the stable identifiers. A payment whose identifiers were mistranslated goes to a data exception worklist, not to suspense, because the financial effect may be correct while the correlation is broken, and fixing the correlation is a data repair with its own sign-off. Operations monitors mapping failures, dropped extensions and identifier collisions as data quality metrics, with a daily report by channel and mapping version, so a mapping release that degrades data quality is rolled back rather than left to generate investigations. Fees and FX postings are linked to the canonical payment ID, so the customer statement, the ledger and the tracking timeline all agree on one payment.", "gherkin": ["Given two source fields with different business meaning", "When they are mapped to the canonical model", "Then their semantics remain distinguishable", "And a round-trip mapping returns the same business meaning", "Given an instruction ID and an end-to-end ID are both supplied", "When the payment is mapped", "Then each is placed in its correct semantic field", "And neither is overwritten by the internal transaction ID"], "assessment": [{"question": "Which ISO 20022 message does an MT103 map to?", "options": ["pacs.008", "camt.056", "pacs.004", "pacs.009"], "answer": 0, "explanation": "MT103 maps to pacs.008, the customer credit transfer. MT202 COV maps to pacs.009."}, {"question": "What is the minimum content for a structured or hybrid address?", "options": ["Full free-text address", "Street name only", "Postcode only", "Town Name and Country Code, or a BIC only"], "answer": 3, "explanation": "The requirement is a structured or hybrid address with a minimum of Town Name and Country Code, or a BIC only."}, {"question": "An internal transaction ID is mapped to the end-to-end reference. What is the correct response?", "options": ["Drop the internal ID", "Accept it, the values are similar", "Block it, because identifiers have distinct semantics and must stay in their own fields", "Generate a new end-to-end ID"], "answer": 2, "explanation": "Identifiers have distinct meanings and lifecycles. The identifier catalogue and propagation matrix prevent one being substituted for another."}, {"question": "What is the relationship between SWIFT and ISO 20022?", "options": ["They are the same thing", "SWIFT is a message standard and ISO 20022 is a network", "SWIFT is the network and messaging service; ISO 20022 is the message standard", "ISO 20022 is a SWIFT product only"], "answer": 2, "explanation": "SWIFT is a network and messaging service. ISO 20022 is the message standard carried over it and other networks."}]}}, {"id": "INS-168", "kind": "insight", "title": "G20 cross-border payment objectives", "topic": "G20 cross-border payment objectives", "theme": "Cross-Border Instant", "text": "Connect speed, cost, transparency and access goals to concrete product and operational measures; cite official targets separately.", "domain": "Cross-Border Strategy", "area": "Cross-Border Strategy", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch83s4", "title": "Local payment methods by market: what changes when you cross a border", "url": "lessons/ch83s4"}}, {"id": "INS-169", "kind": "insight", "title": "Beneficiary identifier and proxy resolution", "topic": "Beneficiary identifier and proxy resolution", "theme": "Cross-Border Instant", "text": "Assess mobile number, UPI ID/VPA or account-based beneficiary resolution in a linked payment ecosystem.", "domain": "Cross-Border Payments", "area": "Cross-Border Payments", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Public post", "messages": "", "lesson": {"id": "ch74s1", "title": "NPP: Australia instant payments and PayID", "url": "lessons/ch74s1"}}, {"id": "INS-170", "kind": "insight", "title": "Customer visibility across multiple payment systems", "topic": "Customer visibility across multiple payment systems", "theme": "Cross-Border Instant", "text": "Define customer-facing statuses that remain accurate while intermediary processing and settlement are pending.", "domain": "Customer Experience & Status", "area": "Customer Experience & Status", "depth": 3, "depth_name": "Deep-dive case", "difficulty": "Advanced", "evidence": "Public post", "messages": "", "lesson": {"id": "ch15s4", "title": "SWIFT gpi: what it is and how it changed tracking", "url": "lessons/ch15s4"}, "case": {"status": "authored", "business_problem": "Northgate Retail pays an overseas supplier every week. The payment travels through Northgate Retail's bank, a correspondent, and the supplier's bank, and the accounts payable clerk can see only one status in the online banking screen: Pending. The supplier says it has not been paid, the clerk cannot say where the money is, and the bank's contact centre gives a different answer each time because each agent reads a different system. The clerk ends up paying the supplier twice on one occasion, once by the original payment that arrived late and once by a replacement payment sent in panic.\n\nThe problem is not a missing tracking number. It is a missing status model. The channel shows Pending, the payment engine shows Processed, and the ledger has no matching posting, and nobody can say which system is authoritative for which state. A tracking reference does not by itself prove settlement, and a status that says Completed before the beneficiary is credited is a promise the bank cannot keep.\n\nNorthgate Retail needs a customer timeline that is accurate while intermediary processing and settlement are still pending: a coherent sequence of events with a source and a timestamp for each, a clear distinction between accepted, in progress, credited and failed, and an explicit Unknown state that triggers investigation instead of a second payment.", "decision_exercise": {"scenario": "Northgate Retail sent a cross-border payment yesterday. The channel shows Pending, the payment engine shows Processed, and the ledger has no matching posting. The supplier is pressing for payment and the clerk wants to send a replacement. The learner must decide what the bank should show and do.", "options": [{"id": "A", "text": "Show the payment as Completed because the engine shows Processed, and advise the clerk to wait."}, {"id": "B", "text": "Show the payment as Unknown with the last confirmed event and its timestamp, place it in investigation, and advise the clerk not to send a replacement until the state is resolved."}, {"id": "C", "text": "Advise the clerk to send a replacement payment immediately and reconcile later."}, {"id": "D", "text": "Hide the payment from the timeline until a final status arrives."}], "correct_option": "B", "why": "Option B is correct because conflicting system states mean the true state is unknown, and an unknown payment must be investigated rather than retried or reported as complete. Option A is wrong because Processed in the engine does not prove beneficiary credit or settlement. Option C is wrong because a replacement risks a duplicate payment. Option D is wrong because hiding the payment removes the only evidence the customer has."}, "recommended_solution": "Define a canonical payment state model with one authoritative source for each transition. The channel is authoritative for the customer instruction. The payment engine is authoritative for acceptance and release. The clearing mechanism or the beneficiary PSP is authoritative for execution and credit. The ledger is authoritative for the financial posting. No system may infer another system's state, and no status may move backwards: an older event arriving after a newer state is recorded as history but does not regress the current state.\n\nThe customer timeline is built from status events, each with a source institution, a timestamp and a meaning in plain language. A persistent end-to-end tracking reference, such as the UETR where applicable, is propagated through the participating messages so events from different banks correlate to the same payment. The timeline shows Accepted, In progress, Credited, Failed and Unknown as distinct states, and it never shows Settled or Completed on the basis of acceptance alone. Where a leg is pending, the timeline says which leg is pending and what the next expected event is, with the time it is expected.\n\nFor cover payments, the customer leg and the cover leg are shown as separate lines under one payment, because a cover return does not by itself prove the customer leg failed. Operations owns an investigation queue for payments in Unknown, with an SLA and a rule that no item is auto-retried. The contact centre script follows the same timeline the customer sees, so the agent and the customer are never reading different truths.", "flow_steps": [{"step": 1, "actor": "Customer", "action": "Instructs a cross-border payment and receives a tracking reference.", "system": "Online banking"}, {"step": 2, "actor": "Payment engine", "action": "Accepts the instruction, records the acceptance event with a timestamp, and releases the payment.", "system": "Payment engine"}, {"step": 3, "actor": "Originating bank", "action": "Sends the payment message with the tracking reference to the next institution.", "system": "Payment engine"}, {"step": 4, "actor": "Intermediary bank", "action": "Reports its status event with its own timestamp and source identification.", "system": "Correspondent bank"}, {"step": 5, "actor": "Beneficiary bank", "action": "Credits the beneficiary and returns a confirmation event.", "system": "Beneficiary bank"}, {"step": 6, "actor": "Status service", "action": "Correlates all events by the tracking reference and appends each to the timeline without overwriting history.", "system": "Status service"}, {"step": 7, "actor": "Channel", "action": "Shows the customer the timeline with the source and timestamp of each event.", "system": "Online banking"}, {"step": 8, "actor": "Operations", "action": "Monitors payments with no new event inside the expected window and moves them to investigation.", "system": "Operations console"}], "happy_path": "Northgate Retail instructs the payment and receives a tracking reference. The payment engine records acceptance, the intermediary reports its handling, and the beneficiary bank confirms credit, each as a separate event with a source and a timestamp. The status service correlates the events by the tracking reference and the channel shows a coherent timeline: Accepted, In progress, Credited, with the time of each step. Reconciliation matches the customer debit to the settlement entries, and the supplier confirms receipt against the same timeline the clerk sees.", "negative_paths": [{"path": "Ambiguous status across systems", "trigger": "The channel shows Pending, the engine shows Processed, and the ledger has no matching posting.", "handling": "Apply the canonical state model, identify the missing event, place the payment in the Unknown state and the exception queue, and do not infer a state from another system."}, {"path": "Cover return while customer status is unclear", "trigger": "A pacs.004 return arrives for the cover leg but the customer leg has no final status.", "handling": "Investigate both legs separately by their linked references, determine whether the customer leg was delivered, held or rejected, and only then decide the customer impact."}, {"path": "Missing or unreported tracking reference", "trigger": "An institution in the chain does not report status or does not propagate the tracking reference.", "handling": "Show the gap explicitly in the timeline as Awaiting update from the next institution, escalate to the investigation queue, and do not fill the gap with an assumed status."}, {"path": "Out-of-order or duplicate status events", "trigger": "An older event arrives after a newer state, or the same event is delivered twice.", "handling": "Record the event as history without regressing the current state, deduplicate on the event ID, and keep the timeline ordered by event time."}], "technical_data": "Build the status service as an append-only event log keyed by the tracking reference, with each event carrying a source institution, an event type, a timestamp and a version. Use the UETR where applicable as the persistent end-to-end tracking reference and propagate it through the participating messages. Define the canonical state model with allowed transitions and the authoritative source for each, and enforce it so a stale or out-of-order event cannot regress the state. Make event consumers idempotent on the event ID so duplicate deliveries are harmless. Keep the channel status as a read model derived from the event log, never as a separate writable state, so the customer and the contact centre always read the same timeline. Record the freshness of each event and the expected next event, so a payment with no update inside its window is flagged automatically.", "messages_fields": [{"message": "pacs.008", "purpose": "Customer credit transfer carrying the tracking reference through the payment chain.", "key_fields": ["Instruction ID and End-to-End ID", "Debtor and creditor agent BICs", "Creditor account and remittance information", "UETR where applicable"]}, {"message": "pacs.009 COV", "purpose": "Cover leg for settlement, tracked separately from the customer leg under the same payment.", "key_fields": ["Cover amount and currency", "Underlying customer payment reference for linkage", "Settlement account details", "UETR where applicable"]}, {"message": "pacs.002", "purpose": "Payment status report carrying acceptance, rejection and execution outcomes from each institution.", "key_fields": ["Original instruction reference", "Status and reason code", "Status timestamp and reporting agent"]}, {"message": "pacs.004", "purpose": "Return of a leg, reported as its own timeline event with its reason.", "key_fields": ["Original instruction reference", "Return reason code", "Returned amount and value date"]}], "accounting_operational": "The ledger is the authoritative source for the financial posting, and the status service never posts. On acceptance, the customer debit or earmark is posted with the tracking reference, and on beneficiary confirmation the settlement entries clear against it. A payment in Unknown stays in a reconciliation worklist with the debit or earmark visible, so finance can see the funds are held and not assume they have settled. A cover return is reconciled against the cover leg only, and any customer adjustment waits for the customer leg outcome. Operations works an investigation queue with an SLA tied to the scheme and corridor timeouts, and the queue is aged daily so no payment sits in Unknown without an owner. Duplicate payment risk is controlled by blocking a replacement instruction while the original is in Unknown, unless operations releases it with a documented decision.", "gherkin": ["Given a payment with a valid tracking reference", "When a participating institution reports a new status", "Then the timeline records the event without overwriting prior history", "And the event shows its source institution and timestamp", "Given out-of-order status events", "When an older event arrives after a newer state", "Then the payment state does not regress", "And the older event is recorded as history only"], "assessment": [{"question": "What does a UETR provide?", "options": ["Proof of settlement", "A guarantee of beneficiary credit", "A persistent end-to-end tracking reference that correlates status events across institutions", "A replacement for the instruction ID"], "answer": 2, "explanation": "A tracking reference correlates events across the chain. It does not by itself prove settlement."}, {"question": "The channel shows Pending, the engine shows Processed, and the ledger has no posting. What is the correct state?", "options": ["Settled", "Completed", "Failed", "Unknown, requiring investigation"], "answer": 3, "explanation": "Conflicting states with a missing event mean the true state is unknown. It must be investigated, not inferred."}, {"question": "What should happen when an older status event arrives after a newer state?", "options": ["The payment is cancelled", "The timeline is cleared", "The older event is recorded as history and the state does not regress", "The state regresses to the older event"], "answer": 2, "explanation": "Status is append-only history. An older event never moves the current state backwards."}, {"question": "A cover leg is returned. What does that prove about the customer leg?", "options": ["Nothing by itself; the customer leg must be checked separately", "The customer has been refunded", "The customer leg also failed", "The payment settled"], "answer": 0, "explanation": "Cover and customer legs have independent states. The customer leg outcome must be established before any customer adjustment."}]}}], "scenarios": [{"id": "PAY-001", "kind": "scenario", "title": "Duplicate payment instruction", "topic": "Payment processing", "theme": "", "text": "A corporate customer submits the same payment instruction twice after a slow channel response. Both requests reach the payment platform.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.008; pacs.002 where applicable", "flow": "Channel/API \u2192 idempotency check \u2192 payment intake \u2192 validation \u2192 processing \u2192 status response", "solution": "Use an idempotency key scoped to the initiating party and instruction. Persist the first accepted request and return its existing reference for retries. Apply duplicate-detection rules using stable business identifiers, but do not rely on amount and beneficiary alone. If two legitimate identical payments are possible, route uncertain matches for review.", "lesson": null}, {"id": "PAY-002", "kind": "scenario", "title": "Timeout after submission with unknown outcome", "topic": "Payment processing", "theme": "", "text": "The channel times out after submitting a payment. It is unclear whether the payment engine accepted or executed it.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.002; camt.056 only if a valid cancellation process is initiated", "flow": "Channel \u2192 API gateway \u2192 payment engine \u2192 status store \u2192 clearing connector", "solution": "Treat timeout as an unknown outcome, not an automatic failure. Query by correlation/reference ID, reconcile with the payment engine and downstream status, and expose a pending/unknown state until confirmed. Retry only with the same idempotency key.", "lesson": null}, {"id": "PAY-003", "kind": "scenario", "title": "Insufficient funds at execution time", "topic": "Payment processing", "theme": "", "text": "A future-dated payment was accepted when submitted, but the account has insufficient available funds on execution date.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.002; account reporting messages as applicable", "flow": "Scheduling service \u2192 account/balance service \u2192 payment engine \u2192 status/notification", "solution": "Separate instruction acceptance from execution eligibility. Recheck available balance and applicable overdraft rules at execution. Apply configured retry, reject or expiry policy and notify the customer with a meaningful reason.", "lesson": null}, {"id": "PAY-004", "kind": "scenario", "title": "Payment accepted but downstream clearing rejects it", "topic": "Payment processing", "theme": "", "text": "The payment platform accepts a customer instruction, but the clearing participant rejects the resulting interbank message.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008; pacs.002; camt.054 where relevant", "flow": "Payment engine \u2192 scheme adapter \u2192 clearing system \u2192 response handler \u2192 ledger/notification", "solution": "Keep customer instruction status distinct from clearing status. Translate the external rejection into a controlled internal reason, update the payment state, reverse or release any reservation as required, and notify the channel.", "lesson": null}, {"id": "PAY-005", "kind": "scenario", "title": "Payment cancellation requested after processing has started", "topic": "Payment processing", "theme": "", "text": "A customer requests cancellation after the instruction has left the bank's payment engine.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.056; camt.029; pacs.004 if a separate return occurs", "flow": "Channel \u2192 payment state service \u2192 scheme adapter \u2192 counterparty \u2192 investigation queue", "solution": "Check the payment's durable state and scheme rules before deciding whether cancellation is possible. If eligible, initiate the appropriate cancellation request and await the counterparty response. Never promise cancellation or reverse funds solely because a request was sent.", "lesson": null}, {"id": "PAY-006", "kind": "scenario", "title": "Payment return after original settlement", "topic": "Payment processing", "theme": "", "text": "A beneficiary-side institution returns a payment after the original transfer has settled.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.004; original pacs.008 references", "flow": "Receiving bank/clearing \u2192 return handler \u2192 payment engine \u2192 ledger \u2192 reconciliation", "solution": "Treat the return as a new linked financial event, not as erasure of the original payment. Validate return reason, amount, currency and original references; post the return entry; update customer status and reconcile both legs.", "lesson": null}, {"id": "PAY-007", "kind": "scenario", "title": "Payment routed to an unavailable correspondent", "topic": "Payment processing", "theme": "", "text": "A cross-border payment selects a correspondent that is temporarily unavailable or no longer supports the required currency/route.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008 or pacs.009 depending on customer/cover model", "flow": "Payment engine \u2192 routing service \u2192 reference data \u2192 correspondent connector", "solution": "Re-evaluate routing against current eligibility, currency, country, service, cut-off, cost and liquidity data. Use an approved alternate route only if policy permits; otherwise queue or reject with a transparent reason.", "lesson": null}, {"id": "PAY-008", "kind": "scenario", "title": "Ambiguous payment status across systems", "topic": "Payment processing", "theme": "", "text": "The channel shows pending, the payment engine shows processed, and the ledger has no matching posting.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002; camt.054; camt.053; internal events", "flow": "Channel \u2192 orchestration \u2192 payment engine \u2192 clearing \u2192 ledger \u2192 status API", "solution": "Define a canonical payment state model and authoritative source for each state transition. Correlate records across systems, identify the missing event, and place the item in an exception queue if state cannot be safely inferred.", "lesson": null}, {"id": "PAY-009", "kind": "scenario", "title": "Partial batch failure", "topic": "Payment processing", "theme": "", "text": "A file contains hundreds of transactions. Some pass validation while others fail due to invalid beneficiary or account data.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pain.002; pacs.008 per transaction", "flow": "File intake \u2192 schema validation \u2192 transaction validation \u2192 payment engine \u2192 reporting", "solution": "Define file-level and transaction-level acceptance separately. Validate each transaction, apply the agreed all-or-nothing or partial-processing rule, return itemised outcomes and ensure accepted items are not resubmitted when rejected items are repaired.", "lesson": null}, {"id": "PAY-010", "kind": "scenario", "title": "Future-dated payment falls on a non-processing day", "topic": "Payment processing", "theme": "", "text": "A customer selects an execution date that is a bank holiday for one participant in the payment chain.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.002", "flow": "Channel \u2192 calendar service \u2192 scheduler \u2192 payment engine \u2192 clearing", "solution": "Apply the correct scheme, currency, debtor bank, creditor bank and clearing calendars. Determine whether to move execution to the previous or next eligible business day, reject, or retain the requested date according to product rules.", "lesson": null}, {"id": "PAY-011", "kind": "scenario", "title": "Payment cut-off extension request", "topic": "Payment processing", "theme": "", "text": "A corporate client asks the bank to extend its same-day payment cut-off by one hour.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific payment messages", "flow": "Channel \u2192 payment engine \u2192 screening \u2192 routing \u2192 clearing \u2192 Treasury \u2192 ledger", "solution": "Run an impact assessment across channel availability, validation, fraud/sanctions, engine capacity, scheme deadlines, correspondent cut-offs, liquidity, settlement, operations, support and reconciliation. Approve only if end-to-end controls remain achievable.", "lesson": null}, {"id": "PAY-012", "kind": "scenario", "title": "Peak volume growth threatens throughput", "topic": "Payment processing", "theme": "", "text": "New customers are forecast to increase daily volume and peak TPS materially.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Not message-specific; include rail-specific payloads", "flow": "Channel \u2192 gateway \u2192 orchestration \u2192 screening \u2192 engine \u2192 connectors \u2192 ledger", "solution": "Build a capacity model using average, peak and burst volumes, payload sizes, dependency latency and retry amplification. Load-test the complete chain and define scaling thresholds and degradation behaviour.", "lesson": null}, {"id": "PAY-013", "kind": "scenario", "title": "High repair rate in a remittance file", "topic": "Payment processing", "theme": "", "text": "Most transactions in a remittance file require manual repair because key data is missing or inconsistent.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pain.002; pacs.008; remittance information fields", "flow": "File intake \u2192 validation \u2192 enrichment \u2192 repair workbench \u2192 payment engine", "solution": "Segment defects by root cause and source. Improve upstream validation and enrichment, provide actionable repair guidance, prioritise by SLA and prevent repaired items from losing original traceability.", "lesson": null}, {"id": "PAY-014", "kind": "scenario", "title": "Optional field required by downstream reporting", "topic": "Payment processing", "theme": "", "text": "A message field is optional under the message schema, but a regulatory or management report needs the information.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Relevant pain/pacs message and reporting schema", "flow": "Channel \u2192 canonical model \u2192 enrichment \u2192 message mapping \u2192 reporting", "solution": "Distinguish scheme-level optionality from product, regulatory and internal data requirements. Define source, derivation, validation, defaulting and exception policy; do not invent values to satisfy reporting.", "lesson": null}, {"id": "PAY-015", "kind": "scenario", "title": "Country-specific reject reason and privacy", "topic": "Payment processing", "theme": "", "text": "A reject reason must be configured differently by country because the bank must not expose sensitive account information.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002; pain.002; scheme-specific codes", "flow": "Payment engine \u2192 reason-code mapping \u2192 notification/API \u2192 operations reporting", "solution": "Maintain internal diagnostic detail separately from customer-visible reason text. Apply jurisdiction-specific disclosure rules, localised descriptions and consistent mapping to external scheme codes.", "lesson": null}, {"id": "PAY-016", "kind": "scenario", "title": "Batch booking versus individual booking", "topic": "Payment processing", "theme": "", "text": "A corporate customer wants one account debit for a batch, while Operations needs transaction-level traceability.", "domain": "Payment processing", "area": "Payment processing", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001 batch indicators; camt.053; camt.054", "flow": "Payment engine \u2192 accounting interface \u2192 core ledger \u2192 statement/reporting", "solution": "Clarify product, accounting, statement and reconciliation needs. Define whether the ledger posts one aggregate entry, individual entries or both through linked accounting events. Ensure totals and transaction references reconcile.", "lesson": null}, {"id": "PAY-017", "kind": "scenario", "title": "Correspondent chain has missing or outdated data", "topic": "Cross-border", "theme": "", "text": "A cross-border instruction lacks a valid intermediary or correspondent relationship for the selected currency.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008; pacs.009 COV where cover settlement is used", "flow": "Payment engine \u2192 routing/reference-data service \u2192 correspondent network", "solution": "Validate the full correspondent chain against approved, effective-dated reference data. Determine whether data can be derived safely from an authorised source; otherwise repair or reject before release.", "lesson": null}, {"id": "PAY-018", "kind": "scenario", "title": "Cover payment return while customer payment status is unclear", "topic": "Cross-border", "theme": "", "text": "A cover leg is returned, but the related underlying customer credit transfer may have a different processing state.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008; pacs.009 COV; pacs.004; pacs.002", "flow": "Originating bank \u2192 correspondent chain \u2192 beneficiary bank; parallel customer and cover legs", "solution": "Correlate the cover and underlying customer payment using stable references. Determine whether the customer leg was delivered, held or rejected before deciding customer impact. Do not assume one leg's status automatically defines the other.", "lesson": null}, {"id": "PAY-019", "kind": "scenario", "title": "Intermediary bank selected incorrectly", "topic": "Cross-border", "theme": "", "text": "A payment is routed through an intermediary that cannot serve the destination or currency.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008; pacs.009", "flow": "Payment engine \u2192 routing rules \u2192 correspondent master \u2192 SWIFT connector", "solution": "Trace the route decision and compare the selected intermediary with the bank's routing policy, currency capability, country restrictions, settlement relationship and effective-dated reference data.", "lesson": null}, {"id": "PAY-020", "kind": "scenario", "title": "Cross-border payment tracking across multiple banks", "topic": "Cross-border", "theme": "", "text": "A customer cannot determine where a payment is while it travels through multiple institutions.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "UETR in relevant SWIFT payment messages; pacs.002 and tracker events", "flow": "Originating bank \u2192 intermediaries \u2192 beneficiary bank \u2192 tracking/status service", "solution": "Use a persistent end-to-end tracking reference such as UETR where applicable, propagate it through participating messages and maintain status events with timestamps and source institutions.", "lesson": null}, {"id": "PAY-021", "kind": "scenario", "title": "FX quote expires before execution", "topic": "Cross-border", "theme": "", "text": "A customer accepts an FX quote but payment processing is delayed beyond the quote validity window.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Payment messages plus internal FX quote contract", "flow": "Channel \u2192 FX quote service \u2192 payment engine \u2192 liquidity/settlement", "solution": "Bind quote ID, currency pair, amount, rate, expiry and execution conditions to the payment. Revalidate at execution and obtain fresh customer consent if the rate or amount changes beyond agreed tolerance.", "lesson": null}, {"id": "PAY-022", "kind": "scenario", "title": "Instant cross-border payment has asynchronous legs", "topic": "Cross-border", "theme": "", "text": "The domestic leg is accepted, but the destination system has not yet confirmed beneficiary credit.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific instant messages; status/confirmation messages", "flow": "Originating FPS \u2192 cross-border orchestration \u2192 FX/settlement arrangement \u2192 destination FPS", "solution": "Model each rail leg separately with an overall orchestration state. Apply scheme-specific timeout and confirmation rules, avoid duplicate sending, and trigger investigation/compensation only under defined rules.", "lesson": null}, {"id": "PAY-023", "kind": "scenario", "title": "Cross-border instant payment fails after sender debit", "topic": "Cross-border", "theme": "", "text": "The sender's account is debited, but the receiving system reports a technical failure or no final response.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Scheme-specific payment and status messages", "flow": "Originating bank ledger \u2192 orchestration \u2192 destination rail \u2192 response handler", "solution": "Establish whether the debit is provisional, final or held. Use scheme rules and leg status to determine whether to await confirmation, return funds or initiate a controlled investigation. Ensure exactly-once financial effect.", "lesson": null}, {"id": "PAY-024", "kind": "scenario", "title": "Compliance screening threatens instant payment SLA", "topic": "Cross-border", "theme": "", "text": "Sanctions, AML or fraud checks may take longer than the rail's processing window.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Payment message plus internal screening decision", "flow": "Payment engine \u2192 sanctions/AML/fraud services \u2192 routing \u2192 clearing", "solution": "Separate pre-payment controls from post-event monitoring where legally and scheme-permitted. Use risk-based orchestration, synchronous decision deadlines, controlled holds and clear reject/timeout behaviour. Never bypass mandatory screening to meet speed targets.", "lesson": null}, {"id": "PAY-025", "kind": "scenario", "title": "Remittance information is lost during transformation", "topic": "Cross-border", "theme": "", "text": "Structured remittance details are truncated or flattened when translating between payment formats or intermediaries.", "domain": "Cross-border", "area": "Cross-border", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.008; remittance information structures", "flow": "Channel \u2192 canonical model \u2192 transformation \u2192 correspondent/clearing \u2192 beneficiary bank", "solution": "Map structured and unstructured remittance fields with explicit length, character-set and preservation rules. Validate truncation and ensure critical references survive the full chain.", "lesson": null}, {"id": "PAY-026", "kind": "scenario", "title": "Mandate missing or invalid", "topic": "SEPA Direct Debit", "theme": "", "text": "A creditor submits a collection without a valid mandate or with mismatched mandate details.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.008; pacs.003; pacs.002/pacs.004 depending on flow and scheme", "flow": "Creditor platform \u2192 Creditor PSP \u2192 clearing \u2192 Debtor PSP", "solution": "Validate mandate existence, status, creditor identifier, debtor account, signature/consent evidence and scheme-specific requirements before collection submission. Route invalid mandates to repair or reject.", "lesson": null}, {"id": "PAY-027", "kind": "scenario", "title": "Creditor pre-notification sent late", "topic": "SEPA Direct Debit", "theme": "", "text": "A creditor intends to collect on a planned date but the debtor was not notified within the agreed or scheme-required timeframe.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.008; mandate/pre-notification evidence", "flow": "Creditor billing \u2192 notification service \u2192 Creditor PSP \u2192 clearing", "solution": "Validate pre-notification timing against the mandate, scheme rules and any agreed alternative period. Reschedule or obtain valid agreement where permitted; do not assume file submission itself is notification.", "lesson": null}, {"id": "PAY-028", "kind": "scenario", "title": "Creditor wants to stop a collection before submission", "topic": "SEPA Direct Debit", "theme": "", "text": "A creditor identifies an incorrect collection before it has been submitted to its PSP.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.008 not yet submitted; internal mandate/collection records", "flow": "Creditor billing \u2192 collection management \u2192 file generation", "solution": "Use the creditor-side revocation process while the collection remains within the creditor's control. Cancel the instruction, preserve audit evidence and prevent file generation or resubmission.", "lesson": null}, {"id": "PAY-029", "kind": "scenario", "title": "Cancellation requested after submission but before settlement", "topic": "SEPA Direct Debit", "theme": "", "text": "The creditor discovers an error after the collection has been submitted into the payment chain.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.056; camt.029 where applicable", "flow": "Creditor PSP \u2192 clearing/counterparty PSP \u2192 response handling", "solution": "Check scheme rules and current state. Submit a request for cancellation through the appropriate channel if still eligible, track acceptance/rejection, and do not assume the request itself stops settlement.", "lesson": null}, {"id": "PAY-030", "kind": "scenario", "title": "Collection reversal after settlement", "topic": "SEPA Direct Debit", "theme": "", "text": "A creditor identifies an error after a Direct Debit has already settled.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.004 or scheme-specific reversal flow", "flow": "Creditor PSP \u2192 clearing \u2192 Debtor PSP \u2192 ledger", "solution": "Use the applicable reversal mechanism within scheme rules and deadlines. Create a linked reversal transaction, validate amount/reason and ensure the original settlement record remains intact.", "lesson": null}, {"id": "PAY-031", "kind": "scenario", "title": "Debtor requests refund for an authorised collection", "topic": "SEPA Direct Debit", "theme": "", "text": "A debtor asks their bank to refund an authorised SDD Core collection within the applicable scheme period.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.056/camt.029 or scheme-specific refund/return flow; pacs.004 where applicable", "flow": "Debtor PSP \u2192 account/claims service \u2192 ledger \u2192 interbank recovery as applicable", "solution": "Validate scheme, collection date, authorisation status and request timeframe. Apply the relevant refund right and bank process, then reconcile the refund separately from the original collection.", "lesson": null}, {"id": "PAY-032", "kind": "scenario", "title": "Debtor claims an unauthorised collection", "topic": "SEPA Direct Debit", "theme": "", "text": "A debtor disputes a collection as lacking valid authorisation.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Scheme-specific refund/claim messages", "flow": "Debtor PSP \u2192 claims/investigation \u2192 Creditor PSP \u2192 ledger", "solution": "Capture the claim, investigate mandate evidence and apply the applicable scheme/legal timeframe and burden-of-proof process. Protect the customer while retaining a complete audit trail.", "lesson": null}, {"id": "PAY-033", "kind": "scenario", "title": "Different participant calendars produce conflicting dates", "topic": "SEPA Direct Debit", "theme": "", "text": "A collection's due date is a business day for one participant but a non-processing day for another.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.008; scheme calendar configuration", "flow": "Creditor PSP \u2192 CSM \u2192 Debtor PSP \u2192 scheduler/calendar service", "solution": "Calculate each milestone against the relevant participant and scheme calendar. Apply scheme-specific business-day definitions and date adjustment rules, and retain the calendar version used.", "lesson": null}, {"id": "PAY-034", "kind": "scenario", "title": "Collection rejected, returned or refused", "topic": "SEPA Direct Debit", "theme": "", "text": "A collection does not complete and stakeholders use the terms reject, return and refusal interchangeably.", "domain": "SEPA Direct Debit", "area": "SEPA Direct Debit", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002; pacs.004; scheme-specific SDD messages", "flow": "Creditor PSP / CSM / Debtor PSP \u2192 exception handler \u2192 ledger/reporting", "solution": "Classify the event by initiator, lifecycle stage and scheme definition. Map each event to its correct status, reason code, accounting action and customer/creditor notification.", "lesson": null}, {"id": "PAY-035", "kind": "scenario", "title": "MT-to-MX transformation needs a value not present in source", "topic": "Architecture and data", "theme": "", "text": "A legacy MT message lacks an explicit value required by the target ISO 20022 message.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "MT103/MT202 COV to pacs.008/pacs.009 as applicable", "flow": "Legacy adapter \u2192 canonical model \u2192 reference data/enrichment \u2192 MX mapper", "solution": "Do not fabricate a value. Identify whether the target value can be derived from trusted contextual data, such as settlement arrangement or correspondent relationship. Document derivation rules, confidence and exception handling.", "lesson": null}, {"id": "PAY-036", "kind": "scenario", "title": "HTTP 200 returned but payment not completed", "topic": "Architecture and data", "theme": "", "text": "A client interprets an HTTP 200 response as proof that the payment has settled.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "OpenAPI contract; payment messages downstream", "flow": "API gateway \u2192 payment orchestration \u2192 status API/webhook \u2192 client", "solution": "Define API response semantics precisely. A synchronous 200 may mean request accepted or resource created, not final payment completion. Return a payment resource/reference and status; use asynchronous status events or enquiry for later lifecycle updates.", "lesson": null}, {"id": "PAY-037", "kind": "scenario", "title": "Sequential versus parallel payment controls", "topic": "Architecture and data", "theme": "", "text": "A payment passes through several checks, and the team wants to reduce latency without weakening controls.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal orchestration/API events", "flow": "Payment orchestration \u2192 account, fraud, AML, sanctions, limits and routing services", "solution": "Map dependencies and data requirements. Run independent checks in parallel where safe; retain mandatory sequencing where one result or enrichment is needed by another. Define aggregation and fail policy.", "lesson": null}, {"id": "PAY-038", "kind": "scenario", "title": "Canonical model loses source semantics", "topic": "Architecture and data", "theme": "", "text": "Different channels send similar but non-identical payment fields and the canonical model collapses meaningful distinctions.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.008; pacs.009; internal API schema", "flow": "Channel adapters \u2192 canonical payment model \u2192 orchestration \u2192 rail-specific mapper", "solution": "Define a canonical model that preserves business semantics, source provenance and scheme-specific extensions. Avoid mapping distinct identifiers into one generic field without documented rules.", "lesson": null}, {"id": "PAY-039", "kind": "scenario", "title": "Payment event arrives twice or out of order", "topic": "Architecture and data", "theme": "", "text": "A message broker redelivers an event or delivers status updates out of order.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal event schema; pacs.002/status events", "flow": "Event bus \u2192 payment status consumer \u2192 state store \u2192 downstream notifications", "solution": "Make consumers idempotent and state transitions version-aware. Store event IDs, aggregate sequence/version and processed outcome. Ignore duplicates and prevent older events from overwriting newer state.", "lesson": null}, {"id": "PAY-040", "kind": "scenario", "title": "Reconciliation finds unmatched debit and clearing record", "topic": "Architecture and data", "theme": "", "text": "The bank's ledger contains a debit but no corresponding clearing confirmation, or vice versa.", "domain": "Architecture and data", "area": "Architecture and data", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.053; camt.054; camt.056/pacs.004 as relevant", "flow": "Payment engine \u2194 clearing reports \u2194 nostro/settlement \u2194 core ledger", "solution": "Reconcile using stable identifiers, amount, currency, date and participant references. Classify timing differences versus true breaks, age exceptions and prevent duplicate financial correction.", "lesson": null}, {"id": "PAY-041", "kind": "scenario", "title": "Requirement says 'make payments faster'", "topic": "Product and BA", "theme": "", "text": "A stakeholder asks for faster payments without specifying customer outcome, scope or measurable target.", "domain": "Product and BA", "area": "Product and BA", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Not message-specific", "flow": "Discovery \u2192 journey mapping \u2192 requirements \u2192 architecture \u2192 delivery", "solution": "Clarify the business problem, user journey, baseline, target SLA, eligible rails, volumes, risk controls and dependencies. Convert the goal into measurable functional and non-functional requirements.", "lesson": null}, {"id": "PAY-042", "kind": "scenario", "title": "New regulatory limit changes product routing", "topic": "Product and BA", "theme": "", "text": "A regulatory or scheme rule changes a transaction limit, but the bank also has customer-specific limits and risk controls.", "domain": "Product and BA", "area": "Product and BA", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific message and rule configuration", "flow": "Product configuration \u2192 limits service \u2192 payment engine \u2192 channel/API", "solution": "Separate scheme maximum, regulatory obligation, bank product limit and customer-level risk limit. Determine precedence, effective date, grandfathering, channels, currencies and exception handling. Validate against official current rules.", "lesson": null}, {"id": "PAY-043", "kind": "scenario", "title": "Vendor says a feature is supported", "topic": "Product and BA", "theme": "", "text": "A vendor demo shows a capability, but it may not cover the bank's exact use case, jurisdiction or exception path.", "domain": "Product and BA", "area": "Product and BA", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Depends on feature", "flow": "Vendor product \u2192 bank configuration \u2192 integration \u2192 operations", "solution": "Translate the requirement into demonstrable acceptance scenarios. Ask the vendor to show configuration, negative paths, audit, volume, resilience, support model and upgrade impact. Record gaps and workarounds.", "lesson": null}, {"id": "PAY-044", "kind": "scenario", "title": "Mobile channel submits incomplete beneficiary data", "topic": "Payment initiation & channels", "theme": "", "text": "A retail customer initiates a payment but the channel omits a beneficiary address required for a particular destination or payment type.", "domain": "Payment initiation & channels", "area": "Payment initiation & channels", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Channel API; pain.001 or rail-specific instruction", "flow": "Mobile/web channel \u2192 API validation \u2192 beneficiary service \u2192 payment intake", "solution": "Validate requirements by rail, destination and product. Use trusted beneficiary data only where policy permits; otherwise request correction before submission. Return field-specific guidance and preserve the draft.", "lesson": null}, {"id": "PAY-045", "kind": "scenario", "title": "Customer changes beneficiary after payment authorisation", "topic": "Payment initiation & channels", "theme": "", "text": "A user edits beneficiary details after a payment has been authorised but before release.", "domain": "Payment initiation & channels", "area": "Payment initiation & channels", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "API contract; rail-specific payment message", "flow": "Channel \u2192 authorisation service \u2192 payment engine \u2192 screening", "solution": "Treat material changes as a change to the authorised payment intent. Re-run risk and validation checks and obtain re-authorisation where required. Record before/after values and prevent unauthorised mutation.", "lesson": null}, {"id": "PAY-046", "kind": "scenario", "title": "Corporate file uploaded twice with different file names", "topic": "Payment initiation & channels", "theme": "", "text": "A corporate user uploads the same payment file twice, but the filenames differ.", "domain": "Payment initiation & channels", "area": "Payment initiation & channels", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pain.002", "flow": "Corporate channel \u2192 file gateway \u2192 duplicate control \u2192 file processing", "solution": "Use business-level duplicate detection based on file identity, control totals, transaction identifiers and customer policy. Do not rely only on filename. Quarantine ambiguous duplicates for review.", "lesson": null}, {"id": "PAY-047", "kind": "scenario", "title": "Payment approval limit differs from execution limit", "topic": "Payment initiation & channels", "theme": "", "text": "A corporate payment is approved under a user entitlement, but the account or product limit is lower.", "domain": "Payment initiation & channels", "area": "Payment initiation & channels", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "API; payment initiation message", "flow": "Channel \u2192 entitlement service \u2192 limits service \u2192 payment engine", "solution": "Evaluate user authority, account limits, product limits, channel limits and scheme limits independently. Apply the strictest relevant constraint and explain the failed control.", "lesson": null}, {"id": "PAY-048", "kind": "scenario", "title": "Beneficiary account format is valid but account is closed", "topic": "Payment validation & enrichment", "theme": "", "text": "A payment passes structural validation, but the beneficiary account is no longer able to receive funds.", "domain": "Payment validation & enrichment", "area": "Payment validation & enrichment", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific message; pacs.002/pacs.004 depending on outcome", "flow": "Payment engine \u2192 beneficiary/account verification where available \u2192 routing \u2192 clearing", "solution": "Separate format validation from account/service eligibility. Use available account verification or scheme response, and handle closure through the relevant reject/return process rather than treating syntax as proof of reachability.", "lesson": null}, {"id": "PAY-049", "kind": "scenario", "title": "Name-check result is inconclusive", "topic": "Payment validation & enrichment", "theme": "", "text": "A beneficiary name check returns a close match rather than a clear match or mismatch.", "domain": "Payment validation & enrichment", "area": "Payment validation & enrichment", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "API/name-check response; payment message", "flow": "Channel \u2192 name-check service \u2192 payment initiation \u2192 audit", "solution": "Apply the jurisdiction's and product's confirmation-of-payee policy. Present clear customer choices where permitted, retain evidence and avoid silently changing beneficiary details.", "lesson": null}, {"id": "PAY-050", "kind": "scenario", "title": "Fraud engine returns a high-risk score after payment approval", "topic": "Fraud & financial crime", "theme": "", "text": "A payment is approved by the customer but a later fraud signal raises its risk before release.", "domain": "Fraud & financial crime", "area": "Fraud & financial crime", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal risk decision; rail-specific payment message", "flow": "Payment orchestration \u2192 fraud engine \u2192 authentication \u2192 release control", "solution": "Bind risk decisions to the payment version and execution stage. Apply hold, step-up authentication, reject or release policy. Reassess if material payment attributes change.", "lesson": null}, {"id": "PAY-051", "kind": "scenario", "title": "Potential sanctions match requires investigation", "topic": "Fraud & financial crime", "theme": "", "text": "A screening engine identifies a possible match against a sanctions list.", "domain": "Fraud & financial crime", "area": "Fraud & financial crime", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal screening event; payment status response", "flow": "Payment engine \u2192 sanctions screening \u2192 case management \u2192 release/reject", "solution": "Place the payment into a controlled hold, route it to authorised investigators and preserve screening evidence. Release only after a documented disposition and required approvals.", "lesson": null}, {"id": "PAY-052", "kind": "scenario", "title": "Screening service is unavailable", "topic": "Fraud & financial crime", "theme": "", "text": "A mandatory screening dependency is unavailable during payment processing.", "domain": "Fraud & financial crime", "area": "Fraud & financial crime", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal service/API events", "flow": "Payment orchestration \u2192 screening service \u2192 queue/exception handling", "solution": "Apply the control-specific fail-open/fail-closed policy. Queue or reject affected payments safely, alert Operations and prevent un-screened release where prohibited.", "lesson": null}, {"id": "PAY-053", "kind": "scenario", "title": "Clearing acknowledgement is delayed beyond expected window", "topic": "Clearing & settlement", "theme": "", "text": "The bank submits a payment but receives no acknowledgement within the expected service window.", "domain": "Clearing & settlement", "area": "Clearing & settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008; pacs.002 or scheme-specific acknowledgement", "flow": "Payment engine \u2192 clearing connector \u2192 acknowledgement handler \u2192 status service", "solution": "Retain a submitted/awaiting-response state, correlate by message and transaction references, perform status enquiry or operational investigation, and avoid blind resubmission.", "lesson": null}, {"id": "PAY-054", "kind": "scenario", "title": "Settlement amount differs from submitted payment amount", "topic": "Clearing & settlement", "theme": "", "text": "A settlement report contains an amount that differs from the expected payment or batch total.", "domain": "Clearing & settlement", "area": "Clearing & settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.053; camt.054; scheme settlement reports", "flow": "Payment engine \u2192 clearing/settlement report \u2192 nostro/ledger reconciliation", "solution": "Identify whether the difference is caused by fees, FX, partial settlement, netting or an error. Reconcile at the correct level and post adjustments only under approved accounting rules.", "lesson": null}, {"id": "PAY-055", "kind": "scenario", "title": "Clearing system sends duplicate status reports", "topic": "Clearing & settlement", "theme": "", "text": "A scheme adapter receives the same status message more than once.", "domain": "Clearing & settlement", "area": "Clearing & settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002 or rail-specific status report", "flow": "Clearing connector \u2192 message validation \u2192 status processor \u2192 ledger/notification", "solution": "Deduplicate by message/event identity and transaction reference. Make status handling idempotent and ensure no repeated ledger posting or customer notification.", "lesson": null}, {"id": "PAY-056", "kind": "scenario", "title": "Net settlement position creates a liquidity shortfall", "topic": "Clearing & settlement", "theme": "", "text": "The bank's projected net debit position exceeds available settlement liquidity.", "domain": "Clearing & settlement", "area": "Clearing & settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Settlement reports; internal liquidity events", "flow": "Payment queue \u2192 liquidity management \u2192 settlement account \u2192 Treasury operations", "solution": "Forecast position using payment queues, expected inflows/outflows, settlement cycles and available funding. Apply liquidity alerts, prioritisation and contingency funding under Treasury policy.", "lesson": null}, {"id": "PAY-057", "kind": "scenario", "title": "Settlement calendar differs from customer-facing date", "topic": "Clearing & settlement", "theme": "", "text": "A customer is shown an execution date that differs from the interbank settlement date.", "domain": "Clearing & settlement", "area": "Clearing & settlement", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific messages and calendar rules", "flow": "Channel \u2192 scheduler \u2192 payment engine \u2192 clearing \u2192 status/notification", "solution": "Represent requested execution, bank processing, clearing settlement and beneficiary availability as separate concepts. Display the correct customer promise for the product and rail.", "lesson": null}, {"id": "PAY-058", "kind": "scenario", "title": "Return message has no usable original reference", "topic": "Returns & investigations", "theme": "", "text": "A returned payment arrives but its original transaction reference is missing or malformed.", "domain": "Returns & investigations", "area": "Returns & investigations", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.004; original pacs.008 identifiers", "flow": "Return intake \u2192 matching service \u2192 investigation queue \u2192 ledger", "solution": "Attempt controlled matching using approved secondary attributes, confidence thresholds and time windows. Do not auto-match ambiguous cases; route them to investigation and suspense handling.", "lesson": null}, {"id": "PAY-059", "kind": "scenario", "title": "Customer disputes a payment they do not recognise", "topic": "Returns & investigations", "theme": "", "text": "A customer reports an unfamiliar debit that may be a card, direct debit, standing order or credit transfer.", "domain": "Returns & investigations", "area": "Returns & investigations", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Instrument-specific; camt.053/camt.054 may support identification", "flow": "Customer service \u2192 transaction identification \u2192 claims/fraud \u2192 payment operations", "solution": "Identify the payment instrument and transaction type first. Apply the correct dispute, recall, refund or fraud process; secure evidence and explain the next steps.", "lesson": null}, {"id": "PAY-060", "kind": "scenario", "title": "Cancellation request and return arrive close together", "topic": "Returns & investigations", "theme": "", "text": "A payment cancellation request is in flight when a return is independently received.", "domain": "Returns & investigations", "area": "Returns & investigations", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.056; camt.029; pacs.004", "flow": "Investigation service \u2192 payment state store \u2192 return handler \u2192 ledger", "solution": "Correlate both events to the original payment and apply a deterministic state model. Prevent duplicate customer credits and reconcile the cancellation outcome with the return financial event.", "lesson": null}, {"id": "PAY-061", "kind": "scenario", "title": "Ledger posting succeeds but payment status update fails", "topic": "Reconciliation & accounting", "theme": "", "text": "The core ledger records a debit, but the payment platform remains in an earlier state because the status event failed.", "domain": "Reconciliation & accounting", "area": "Reconciliation & accounting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal accounting event; camt.053/camt.054 for external evidence", "flow": "Payment engine \u2192 ledger adapter \u2192 event/outbox \u2192 status store", "solution": "Use durable posting references and recoverable event publication. Reconcile ledger and payment state, replay the missing event idempotently and alert on aged inconsistency.", "lesson": null}, {"id": "PAY-062", "kind": "scenario", "title": "Nostro statement contains an unexplained debit", "topic": "Reconciliation & accounting", "theme": "", "text": "Treasury receives a correspondent statement entry that cannot be matched to an expected payment or fee.", "domain": "Reconciliation & accounting", "area": "Reconciliation & accounting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "camt.053; MT940 in legacy contexts; camt.054 where applicable", "flow": "Nostro statement ingestion \u2192 reconciliation \u2192 payment/fee records \u2192 investigation", "solution": "Parse the statement, match against expected settlement and fee records, classify unmatched items, and investigate with the correspondent. Do not create an assumed payment record to force a match.", "lesson": null}, {"id": "PAY-063", "kind": "scenario", "title": "Payment is returned after customer account has closed", "topic": "Reconciliation & accounting", "theme": "", "text": "A valid return is received after the original customer account has been closed.", "domain": "Reconciliation & accounting", "area": "Reconciliation & accounting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.004; ledger/accounting events", "flow": "Return handler \u2192 customer/account service \u2192 ledger \u2192 suspense/unclaimed funds", "solution": "Apply the bank's closed-account return policy and legal/accounting controls. Route funds to an approved suspense or unclaimed-funds process where appropriate, notify relevant teams and preserve traceability.", "lesson": null}, {"id": "PAY-064", "kind": "scenario", "title": "API schema changes introduce a breaking field rename", "topic": "Data & integration", "theme": "", "text": "A downstream consumer expects an existing field name, but a new API version changes it.", "domain": "Data & integration", "area": "Data & integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "OpenAPI/JSON schema; internal events", "flow": "API gateway \u2192 service contract \u2192 consumers \u2192 monitoring", "solution": "Use explicit API versioning and compatibility policy. Prefer additive evolution; provide deprecation period, consumer impact assessment, contract tests and migration plan.", "lesson": null}, {"id": "PAY-065", "kind": "scenario", "title": "Character encoding changes beneficiary name", "topic": "Data & integration", "theme": "", "text": "A beneficiary name contains characters not supported by a downstream rail or legacy interface.", "domain": "Data & integration", "area": "Data & integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "ISO 20022 text fields; rail-specific character rules", "flow": "Channel \u2192 canonical model \u2192 character-set validation \u2192 rail mapper", "solution": "Apply documented character-set rules and transliteration only where permitted. Preserve the original customer-provided value, record transformed value and ensure the transformation does not change identity meaning.", "lesson": null}, {"id": "PAY-066", "kind": "scenario", "title": "Payment identifier is reused across systems with different meanings", "topic": "Data & integration", "theme": "", "text": "An internal transaction ID is mistakenly mapped to an end-to-end reference or instruction ID.", "domain": "Data & integration", "area": "Data & integration", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.008; pacs.009; UETR where applicable", "flow": "Channel \u2192 canonical model \u2192 message mapper \u2192 clearing \u2192 tracking", "solution": "Define identifier semantics and lifecycle clearly. Maintain separate fields for internal ID, instruction ID, end-to-end ID, transaction ID, UETR and clearing references; map only according to standards and use case.", "lesson": null}, {"id": "PAY-067", "kind": "scenario", "title": "New scheme rule changes mandatory data and validation", "topic": "Product & regulatory change", "theme": "", "text": "A payment scheme publishes a rulebook update that changes a required field or processing deadline.", "domain": "Product & regulatory change", "area": "Product & regulatory change", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Scheme-specific message version and rulebook", "flow": "Regulatory change \u2192 product/rule engine \u2192 channel \u2192 payment engine \u2192 scheme adapter", "solution": "Perform rule impact analysis across channels, canonical model, validation, mapping, clearing adapters, operations, customer terms and reporting. Implement effective-dated rules and parallel testing.", "lesson": null}, {"id": "PAY-068", "kind": "scenario", "title": "Bank introduces a new instant payment product", "topic": "Product & regulatory change", "theme": "", "text": "A bank wants to launch an instant payment service with 24/7 availability and customer-facing confirmation.", "domain": "Product & regulatory change", "area": "Product & regulatory change", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific instant payment messages", "flow": "Product discovery \u2192 channel \u2192 payment engine \u2192 scheme connectivity \u2192 Treasury/Ops", "solution": "Define supported segments, rails, limits, liquidity, fraud controls, uptime, cut-offs, customer journey, dispute handling and operating model. Validate scheme participation and end-to-end readiness before launch.", "lesson": null}, {"id": "PAY-069", "kind": "scenario", "title": "Customer requests a payment limit increase", "topic": "Product & regulatory change", "theme": "", "text": "A customer requests a higher daily payment limit for a new business need.", "domain": "Product & regulatory change", "area": "Product & regulatory change", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal servicing/API event", "flow": "Customer channel \u2192 servicing workflow \u2192 risk/limits service \u2192 payment engine", "solution": "Assess customer segment, risk profile, authentication, fraud controls, regulatory constraints, account mandate and operational capacity. Apply a controlled, effective-dated limit change with approval and monitoring.", "lesson": null}, {"id": "PAY-070", "kind": "scenario", "title": "Payment queue grows during downstream outage", "topic": "Operations & resilience", "theme": "", "text": "A clearing connector outage causes payment backlog and threatens cut-off deadlines.", "domain": "Operations & resilience", "area": "Operations & resilience", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Rail-specific messages; internal queue events", "flow": "Payment engine \u2192 durable queue \u2192 connector \u2192 recovery/replay \u2192 clearing", "solution": "Apply queue prioritisation, back-pressure and controlled recovery. Identify payments at risk of missing cut-off, communicate impact, prevent retry storms and reconcile all queued items after restoration.", "lesson": null}, {"id": "PAY-071", "kind": "scenario", "title": "Disaster recovery switches payment processing to secondary site", "topic": "Operations & resilience", "theme": "", "text": "A primary data centre fails while payments are in-flight.", "domain": "Operations & resilience", "area": "Operations & resilience", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "All relevant messages and internal events", "flow": "Primary platform \u2192 DR environment \u2192 state replication \u2192 connector recovery \u2192 reconciliation", "solution": "Fail over using tested recovery procedures that preserve durable state, sequence, idempotency keys, message acknowledgements and ledger consistency. Reconcile in-flight items before resuming full throughput.", "lesson": null}, {"id": "PAY-072", "kind": "scenario", "title": "Manual repair changes beneficiary account details", "topic": "Operations & resilience", "theme": "", "text": "An operator corrects an account number in a payment repair queue.", "domain": "Operations & resilience", "area": "Operations & resilience", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal repair event; downstream payment message", "flow": "Repair workbench \u2192 validation \u2192 screening \u2192 payment engine", "solution": "Apply role-based access, maker-checker for sensitive fields, validation, reason capture and full before/after audit. Re-run screening and routing after any material beneficiary change.", "lesson": null}, {"id": "PAY-073", "kind": "scenario", "title": "Customer receives contradictory notifications", "topic": "Customer experience & reporting", "theme": "", "text": "The customer receives a payment-success notification followed by a rejection notification due to asynchronous event ordering.", "domain": "Customer experience & reporting", "area": "Customer experience & reporting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal status events; customer API", "flow": "Payment state service \u2192 notification orchestrator \u2192 email/SMS/push", "solution": "Define notification eligibility by authoritative payment state and event version. Suppress stale or contradictory messages, correct the customer promptly and retain notification history.", "lesson": null}, {"id": "PAY-074", "kind": "scenario", "title": "Customer asks for proof of payment", "topic": "Customer experience & reporting", "theme": "", "text": "A corporate customer needs evidence that a payment was processed, but the bank's portal only shows a generic completed status.", "domain": "Customer experience & reporting", "area": "Customer experience & reporting", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002; camt.054; tracking data where available", "flow": "Payment status service \u2192 evidence/document service \u2192 corporate channel", "solution": "Define evidence levels: instruction received, accepted, sent, clearing accepted, settled, beneficiary credited where known. Provide an appropriate confirmation document/status with timestamp and reference, without overstating what the bank can prove.", "lesson": null}, {"id": "PAY-075", "kind": "scenario", "title": "Intraday liquidity forecast ignores queued outgoing payments", "topic": "Liquidity & Treasury", "theme": "", "text": "Treasury's forecast uses settled balances but does not include payments waiting in the release queue.", "domain": "Liquidity & Treasury", "area": "Liquidity & Treasury", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Internal payment/settlement events", "flow": "Payment queue \u2192 liquidity forecast \u2192 Treasury dashboard \u2192 funding actions", "solution": "Incorporate committed, queued, expected and settled flows with confidence categories. Model release scenarios and refresh forecasts as queue priority or status changes.", "lesson": null}, {"id": "PAY-076", "kind": "scenario", "title": "Correspondent imposes a new intraday credit limit", "topic": "Liquidity & Treasury", "theme": "", "text": "A correspondent reduces the bank's available intraday credit, potentially constraining payment routing.", "domain": "Liquidity & Treasury", "area": "Liquidity & Treasury", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.008/pacs.009 as applicable; liquidity data", "flow": "Treasury \u2192 correspondent limits/reference data \u2192 routing engine \u2192 payment queue", "solution": "Update liquidity and route eligibility controls, quantify affected corridors and currencies, assess alternative correspondents and prioritise critical payments under policy.", "lesson": null}, {"id": "PAY-077", "kind": "scenario", "title": "Structured address migration affects payment validation", "topic": "ISO 20022 & standards", "theme": "", "text": "A scheme or bank adopts structured or hybrid postal-address requirements and legacy customer records are incomplete.", "domain": "ISO 20022 & standards", "area": "ISO 20022 & standards", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Relevant pacs/pain message version and address structures", "flow": "Customer master \u2192 channel \u2192 canonical model \u2192 MX mapper \u2192 clearing", "solution": "Assess data capture, cleansing, enrichment, message version, validation, downstream storage and customer remediation. Do not fabricate address components; define transition and exception rules.", "lesson": null}, {"id": "PAY-078", "kind": "scenario", "title": "Remittance information exceeds message limits", "topic": "ISO 20022 & standards", "theme": "", "text": "A corporate payment includes extensive invoice details that exceed the receiving rail's supported remittance capacity.", "domain": "ISO 20022 & standards", "area": "ISO 20022 & standards", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pain.001; pacs.008 remittance information", "flow": "Corporate channel \u2192 canonical model \u2192 message mapper \u2192 rail adapter", "solution": "Determine required business references, supported structured/unstructured elements and truncation rules. Preserve essential data through approved supplementary channels or references, and alert the customer when information cannot be carried.", "lesson": null}, {"id": "PAY-079", "kind": "scenario", "title": "Payment status mapping differs between scheme and bank model", "topic": "ISO 20022 & standards", "theme": "", "text": "A scheme uses status and reason combinations that do not map one-to-one to the bank's internal status model.", "domain": "ISO 20022 & standards", "area": "ISO 20022 & standards", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "pacs.002; pain.002; rail-specific statuses", "flow": "Scheme adapter \u2192 status mapper \u2192 canonical state model \u2192 channel/operations", "solution": "Create a governed mapping matrix by message, status, reason, transaction scope and lifecycle stage. Preserve raw scheme values alongside normalised internal values.", "lesson": null}, {"id": "PAY-080", "kind": "scenario", "title": "Major requirement change after most of the sprint is complete", "topic": "Professional Masterclass / Agile Delivery", "theme": "", "text": "A business owner requests a material change after most of the sprint work has been developed and tested.", "domain": "Professional Masterclass / Agile Delivery", "area": "Professional Masterclass / Agile Delivery", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "User story; acceptance criteria; change request; API/data contracts where impacted", "flow": "Stakeholder request \u2192 BA clarification \u2192 impact assessment \u2192 PO decision \u2192 backlog/release plan \u2192 delivery and regression testing", "solution": "Clarify the business driver, urgency and whether the request is a defect, regulatory obligation or new scope. Map impacts to stories, APIs, data, downstream systems, test coverage, dependencies and sprint goal. Present options to the Product Owner: defer, swap scope, split a safe increment, or re-plan the sprint/release. Obtain an explicit decision and update backlog, traceability and stakeholders.", "lesson": null}, {"id": "PAY-081", "kind": "scenario", "title": "Two senior stakeholders demand mutually exclusive outcomes", "topic": "Professional Masterclass / Stakeholder Management", "theme": "", "text": "Two senior business owners insist that opposite behaviours are both essential for the same feature.", "domain": "Professional Masterclass / Stakeholder Management", "area": "Professional Masterclass / Stakeholder Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Decision record; process model; prioritisation matrix; acceptance criteria", "flow": "Stakeholder interviews \u2192 outcome comparison \u2192 options analysis \u2192 decision forum \u2192 signed decision log", "solution": "Understand the outcome each stakeholder is trying to achieve. Make the conflict explicit, quantify customer, regulatory, operational and revenue impact, assess effort and dependencies, and facilitate a decision using agreed product objectives and decision rights. Escalate unresolved trade-offs to the accountable sponsor rather than choosing by hierarchy.", "lesson": null}, {"id": "PAY-082", "kind": "scenario", "title": "Everything in the backlog is labelled high priority", "topic": "Professional Masterclass / Prioritisation", "theme": "", "text": "A backlog contains many items all marked high, making sprint selection impossible.", "domain": "Professional Masterclass / Prioritisation", "area": "Professional Masterclass / Prioritisation", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Product backlog; WSJF or agreed scoring model; dependency map", "flow": "Backlog review \u2192 value/risk scoring \u2192 dependency mapping \u2192 sequencing \u2192 sprint planning", "solution": "Re-establish prioritisation criteria: regulatory deadline, customer impact, risk reduction, revenue, strategic alignment, dependency criticality, effort and cost of delay. Use a transparent scoring method and validate sequencing with the PO and stakeholders.", "lesson": null}, {"id": "PAY-083", "kind": "scenario", "title": "Stakeholders cannot articulate what they need", "topic": "Professional Masterclass / Requirements Engineering", "theme": "", "text": "A sponsor asks for a digital capability but describes only a desired screen or solution, not the business problem.", "domain": "Professional Masterclass / Requirements Engineering", "area": "Professional Masterclass / Requirements Engineering", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Problem statement; process map; business rules; user stories; acceptance criteria", "flow": "Discovery \u2192 interviews/workshops \u2192 process/data analysis \u2192 options \u2192 validation \u2192 requirements baseline", "solution": "Start with outcomes and current pain points. Interview users, observe the process, review data and policies, map AS-IS and TO-BE, identify actors, rules, exceptions, controls and measures of success. Validate the proposed solution with prototypes or examples before writing requirements.", "lesson": null}, {"id": "PAY-084", "kind": "scenario", "title": "Developer says an approved requirement is technically infeasible", "topic": "Professional Masterclass / Feasibility & Solution Design", "theme": "", "text": "A delivery team challenges a signed-off requirement because of platform constraints or a dependency limitation.", "domain": "Professional Masterclass / Feasibility & Solution Design", "area": "Professional Masterclass / Feasibility & Solution Design", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "NFRs; interface contract; architecture decision record; revised acceptance criteria", "flow": "Requirement review \u2192 technical spike \u2192 options assessment \u2192 stakeholder decision \u2192 revised design/backlog", "solution": "Ask for the specific constraint and evidence. Work with architecture, engineering and business to identify alternatives, trade-offs, phased delivery or process changes. Compare each option against the original outcome, risk, cost, performance and compliance. Rebaseline only after accountable approval.", "lesson": null}, {"id": "PAY-085", "kind": "scenario", "title": "Delivered feature works as documented but fails business expectations", "topic": "Professional Masterclass / UAT & Acceptance", "theme": "", "text": "UAT users reject a feature even though development followed the approved story and acceptance criteria.", "domain": "Professional Masterclass / UAT & Acceptance", "area": "Professional Masterclass / UAT & Acceptance", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "User story; acceptance criteria; RTM; defect/change record", "flow": "UAT observation \u2192 requirement traceability \u2192 gap classification \u2192 decision \u2192 fix/change \u2192 retest", "solution": "Compare the original business objective, approved requirements, acceptance criteria, process model and actual behaviour. Classify the gap as implementation defect, ambiguous requirement, missed exception, changed expectation or new scope. Agree severity and release decision, then update tests and traceability.", "lesson": null}, {"id": "PAY-086", "kind": "scenario", "title": "New requirement arrives after UAT sign-off, immediately before release", "topic": "Professional Masterclass / Scope & Change Control", "theme": "", "text": "A previously unrecorded requirement is raised on the eve of deployment.", "domain": "Professional Masterclass / Scope & Change Control", "area": "Professional Masterclass / Scope & Change Control", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Change request; defect record; release checklist; regression evidence", "flow": "Change intake \u2192 criticality triage \u2192 impact assessment \u2192 release authority decision \u2192 release/defer", "solution": "Triage whether it is a defect, safety/compliance issue or new scope. Assess customer impact, regulatory necessity, data migration, regression scope, rollback and deployment risk. Present go/no-go options to the release authority. Defer non-critical scope; postpone or hotfix only with evidence and governance.", "lesson": null}, {"id": "PAY-087", "kind": "scenario", "title": "UAT feedback mixes defects, usability preferences and new features", "topic": "Professional Masterclass / Defect Management", "theme": "", "text": "Testers submit many comments, including broken functionality, cosmetic preferences and new capability requests.", "domain": "Professional Masterclass / Defect Management", "area": "Professional Masterclass / Defect Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Defect taxonomy; acceptance criteria; UAT log", "flow": "UAT feedback \u2192 triage workshop \u2192 defect/enhancement classification \u2192 backlog/release decision", "solution": "Define classification criteria and review each item with business, QA and product. Defects are failures against agreed requirements; enhancements change scope; usability issues are assessed against usability standards and impact. Prioritise by severity, user impact and release risk.", "lesson": null}, {"id": "PAY-088", "kind": "scenario", "title": "API returns success but downstream business transaction is incomplete", "topic": "APIs & Integration / Production Support", "theme": "", "text": "A payment API returns a successful HTTP response, but a downstream order, account or case record is not created.", "domain": "APIs & Integration / Production Support", "area": "APIs & Integration / Production Support", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "OpenAPI contract; request/response; webhook/event; payment status messages where applicable", "flow": "Client \u2192 API gateway \u2192 payment service \u2192 event/callback \u2192 downstream system \u2192 database/ledger", "solution": "Determine what the response contract promises: receipt, validation, acceptance or completion. Trace correlation IDs across gateway, service, event bus, downstream consumer and database. Inspect payload, response body, webhook delivery, retries, dead-letter queues and persistence. Reconcile financial effects before retrying.", "lesson": null}, {"id": "PAY-089", "kind": "scenario", "title": "Integration passes in test but fails in production", "topic": "APIs & Integration / Environment Management", "theme": "", "text": "An API integration behaves correctly in SIT/UAT but fails after production deployment.", "domain": "APIs & Integration / Environment Management", "area": "APIs & Integration / Environment Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "OpenAPI; OAuth2/mTLS; logs and distributed traces", "flow": "Client \u2192 gateway \u2192 service \u2192 downstream API \u2192 production monitoring", "solution": "Compare environment configuration, endpoint, credentials, certificates, firewall/network routes, scopes, payload versions, feature flags, data quality, rate limits and downstream versions. Use production-safe telemetry and a controlled reproduction. Assess rollback/containment before making changes.", "lesson": null}, {"id": "PAY-090", "kind": "scenario", "title": "Data differs between UI, API payload and database", "topic": "APIs & Integration / Data Mapping", "theme": "", "text": "A user sees one value in the UI, the API transmits another, and the persisted record contains a third.", "domain": "APIs & Integration / Data Mapping", "area": "APIs & Integration / Data Mapping", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "JSON schema; field mapping; SQL evidence; audit events", "flow": "UI \u2192 API \u2192 transformation/business service \u2192 database \u2192 read model/report", "solution": "Trace one affected record using a stable identifier. Compare UI state, request payload, API transformation, validation/defaulting, service logs, database write and read model/cache. Check timezone, decimal precision, encoding, mapping, stale cache and transaction boundaries.", "lesson": null}, {"id": "PAY-091", "kind": "scenario", "title": "Source data is correct but management report is wrong", "topic": "Data & Reporting / Reconciliation", "theme": "", "text": "Operational screens show correct transactions, but a downstream report has missing or incorrect totals.", "domain": "Data & Reporting / Reconciliation", "area": "Data & Reporting / Reconciliation", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Data dictionary; SQL; ETL mappings; report specification", "flow": "Source system \u2192 ETL/stream \u2192 data warehouse \u2192 semantic layer \u2192 report", "solution": "Trace lineage from source event through extraction, transformation, aggregation, joins, filters, time windows and report refresh. Reconcile record counts and control totals at each stage. Identify whether the issue is late data, transformation logic or report definition.", "lesson": null}, {"id": "PAY-092", "kind": "scenario", "title": "Critical production incident: rollback versus hotfix", "topic": "Professional Masterclass / Production Incident", "theme": "", "text": "A live service is failing and technology recommends rollback while the business wants service restored immediately.", "domain": "Professional Masterclass / Production Incident", "area": "Professional Masterclass / Production Incident", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Incident record; transaction logs; deployment/change record; reconciliation evidence", "flow": "Incident detection \u2192 containment \u2192 impact assessment \u2192 decision \u2192 recovery \u2192 reconciliation \u2192 RCA", "solution": "Stabilise first: assess customer, financial, operational, security and regulatory impact; stop or limit harmful processing if necessary; preserve evidence; identify decision owner. Compare rollback, feature disablement, traffic diversion and hotfix based on data integrity, reversibility, validation and recovery time. Communicate status and maintain incident log.", "lesson": null}, {"id": "PAY-093", "kind": "scenario", "title": "Customer funds are affected but root cause is unknown", "topic": "Professional Masterclass / Incident & RCA", "theme": "", "text": "Customers report debits or credits that do not match displayed payment status, while the technical cause is not yet known.", "domain": "Professional Masterclass / Incident & RCA", "area": "Professional Masterclass / Incident & RCA", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Payment references; ledger entries; scheme statuses; incident evidence", "flow": "Incident bridge \u2192 impact quantification \u2192 payment/ledger reconciliation \u2192 containment \u2192 remediation \u2192 RCA", "solution": "Prioritise customer and financial containment. Identify affected population and value, stop duplicate or unsafe processing, preserve transaction evidence, reconcile ledger and external payment records, arrange approved customer remediation and run parallel technical RCA.", "lesson": null}, {"id": "PAY-094", "kind": "scenario", "title": "Pre-production data mismatch appears shortly before go-live", "topic": "Professional Masterclass / Release Management", "theme": "", "text": "SIT and UAT passed, but pre-production testing reveals a data mismatch close to release approval.", "domain": "Professional Masterclass / Release Management", "area": "Professional Masterclass / Release Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Test evidence; SQL reconciliation; data mapping; release checklist", "flow": "Pre-prod test \u2192 data comparison \u2192 impact assessment \u2192 release governance \u2192 remediation/retest", "solution": "Assess whether the mismatch is representative, reproducible and release-critical. Compare environment data, mappings, reference data, migration scripts and configuration. Quantify affected journeys and records. Delay or proceed only through formal risk acceptance with a safe mitigation and rollback plan.", "lesson": null}, {"id": "PAY-095", "kind": "scenario", "title": "QA capacity is insufficient for a fixed release date", "topic": "Professional Masterclass / Quality & Test Strategy", "theme": "", "text": "The release date is fixed but QA resources cannot execute the full planned test suite.", "domain": "Professional Masterclass / Quality & Test Strategy", "area": "Professional Masterclass / Quality & Test Strategy", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Test strategy; RTM; defect severity model; release checklist", "flow": "Scope review \u2192 risk assessment \u2192 test prioritisation \u2192 execution plan \u2192 go/no-go", "solution": "Reassess risk-based coverage with QA and product. Protect critical payment, security, regulatory, data integrity and regression paths. Identify automation, parallel execution, scope reduction or release phasing. Make residual risk explicit to release authority.", "lesson": null}, {"id": "PAY-096", "kind": "scenario", "title": "Stories repeatedly spill over into the next sprint", "topic": "Professional Masterclass / Backlog Management", "theme": "", "text": "Multiple user stories remain unfinished at sprint end because they are too large, unclear or dependency-heavy.", "domain": "Professional Masterclass / Backlog Management", "area": "Professional Masterclass / Backlog Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "User stories; estimation; DoR/DoD; dependency board", "flow": "Backlog refinement \u2192 dependency analysis \u2192 story slicing \u2192 sprint planning \u2192 review", "solution": "Review historical spillover causes, story size, acceptance clarity, external dependencies, team capacity and hidden work. Split vertically into independently testable value increments, refine definition of ready/done and forecast using actual throughput.", "lesson": null}, {"id": "PAY-097", "kind": "scenario", "title": "Team delivers every sprint but business outcomes do not improve", "topic": "Professional Masterclass / Product Outcomes", "theme": "", "text": "Delivery metrics show completed stories, but customer conversion, processing time or operational workload remains unchanged.", "domain": "Professional Masterclass / Product Outcomes", "area": "Professional Masterclass / Product Outcomes", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Product KPI tree; analytics events; process metrics; user feedback", "flow": "Product objective \u2192 discovery \u2192 delivery \u2192 adoption \u2192 outcome measurement", "solution": "Reconnect backlog items to the product outcome and baseline metrics. Validate whether the problem was correctly defined, adoption barriers exist, process changes were omitted or the delivered capability misses the user need. Reprioritise based on measured outcomes.", "lesson": null}, {"id": "PAY-098", "kind": "scenario", "title": "Business requests a shortcut that conflicts with a control", "topic": "Professional Masterclass / Governance & Compliance", "theme": "", "text": "A stakeholder asks to bypass a validation or approval to meet a deadline, but the control is required by policy or regulation.", "domain": "Professional Masterclass / Governance & Compliance", "area": "Professional Masterclass / Governance & Compliance", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Control matrix; policy; regulatory requirement; audit record", "flow": "Request \u2192 control analysis \u2192 alternative options \u2192 risk/compliance decision \u2192 implementation", "solution": "Identify the exact control obligation and risk owner. Explain the consequence, explore compliant alternatives such as controlled manual review or limited scope, and escalate to Compliance/Risk where interpretation is needed. Record the decision and prohibit unauthorised bypass.", "lesson": null}, {"id": "PAY-099", "kind": "scenario", "title": "Regulatory requirement arrives after development is well advanced", "topic": "Professional Masterclass / Regulatory Change", "theme": "", "text": "A new regulatory obligation is published or interpreted while a release is already in progress.", "domain": "Professional Masterclass / Regulatory Change", "area": "Professional Masterclass / Regulatory Change", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Regulatory obligation register; control mapping; user stories; RTM", "flow": "Regulatory intake \u2192 compliance interpretation \u2192 impact assessment \u2192 backlog/release plan \u2192 evidence", "solution": "Confirm applicability, legal interpretation, effective date and affected entities/products. Perform gap and impact analysis across process, data, controls, messages, reporting, customer terms and operations. Prioritise mandatory compliance, identify interim controls if legally acceptable and re-plan with governance.", "lesson": null}, {"id": "PAY-100", "kind": "scenario", "title": "Client escalates angrily that the delivered process has disrupted operations", "topic": "Professional Masterclass / Stakeholder Communication", "theme": "", "text": "A client reports that a change has made a critical operational process harder or impossible.", "domain": "Professional Masterclass / Stakeholder Communication", "area": "Professional Masterclass / Stakeholder Communication", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Incident/change record; process map; communications log", "flow": "Client escalation \u2192 impact triage \u2192 workaround \u2192 evidence gathering \u2192 recovery plan \u2192 review", "solution": "Acknowledge impact without defensiveness, establish facts and immediate workaround, capture affected users/processes, compare before/after workflow and approved requirements, agree recovery owner and update cadence. Follow with root-cause and prevention actions.", "lesson": null}, {"id": "PAY-101", "kind": "scenario", "title": "Project handover occurs without adequate knowledge transfer", "topic": "Professional Masterclass / Knowledge Management", "theme": "", "text": "A new BA or support team inherits a payment process with incomplete documentation and unavailable subject-matter experts.", "domain": "Professional Masterclass / Knowledge Management", "area": "Professional Masterclass / Knowledge Management", "depth": 2, "depth_name": "Applied scenario", "difficulty": "Intermediate", "evidence": "Independently authored practice scenario", "messages": "Runbooks; process maps; interface catalogue; decision log; support matrix", "flow": "Handover intake \u2192 artefact review \u2192 SME sessions \u2192 reverse-shadowing \u2192 readiness sign-off", "solution": "Establish service boundaries, process flows, system/context diagrams, data dictionary, known issues, operational runbooks, contacts, controls, SLAs and open decisions. Validate through reverse-shadowing and scenario walkthroughs; record gaps and risk owners.", "lesson": null}], "generated": "Payments Training Hub Excel integration"};
